window.__SCRIPT_SOURCES = {"aplicar-p1-travamentos.sh": "#!/usr/bin/env bash\n# =============================================================================\n# aplicar-p1-travamentos.sh\n# Ajustes P1 da auditoria de travamentos \u2014 Positivo DH8BT11TV / OL9 / UEK 6.12\n#\n# O que faz:\n#   1. remove a reserva de crashkernel (somente se o kdump estiver desligado)\n#   2. aumenta o zram de 1 GiB para 2 GiB\n#   3. desativa o swap no HDD (opcional: --keep-hdd-swap)\n#   4. troca o agendador de I/O do sda para BFQ\n#   5. aplica sysctl de resposta (dirty_ratio, page-cluster, swappiness)\n#   6. coloca Transparent Huge Pages em madvise\n#   7. habilita o bool SELinux selinuxuser_execmod (elimina o AVC do llamafile)\n#   8. opcional: mascara o setroubleshootd (--mask-setroubleshoot)\n#\n# Uso:\n#   ./aplicar-p1-travamentos.sh                        # simula\u00e7\u00e3o (n\u00e3o altera nada)\n#   sudo ./aplicar-p1-travamentos.sh --apply           # aplica\n#   sudo ./aplicar-p1-travamentos.sh --apply --keep-hdd-swap\n#   sudo ./aplicar-p1-travamentos.sh --apply --mask-setroubleshoot\n#\n# Seguran\u00e7a:\n#   - idempotente: pode rodar de novo sem duplicar nada\n#   - backup dos arquivos alterados em /var/backups/travamentos-<data>/\n#   - n\u00e3o reinicia a m\u00e1quina sozinho\n#   - n\u00e3o remove crashkernel se o kdump estiver ativo\n#   - n\u00e3o desativa o swap do HDD se ele estiver em uso (a menos que --force)\n# =============================================================================\n\nset -Eeuo pipefail\n\nAPPLY=0\nKEEP_HDD_SWAP=0\nMASK_SETROUBLESHOOT=0\nFORCE=0\n\nfor arg in \"$@\"; do\n    case \"$arg\" in\n        --apply)               APPLY=1 ;;\n        --keep-hdd-swap)       KEEP_HDD_SWAP=1 ;;\n        --mask-setroubleshoot) MASK_SETROUBLESHOOT=1 ;;\n        --force)               FORCE=1 ;;\n        -h|--help)             sed -n '2,30p' \"$0\" | sed 's/^# \\{0,1\\}//'; exit 0 ;;\n        *) echo \"Op\u00e7\u00e3o desconhecida: $arg (use --help)\" >&2; exit 2 ;;\n    esac\ndone\n\nsay()  { printf '\\n\\033[1;36m== %s\\033[0m\\n' \"$*\"; }\nok()   { printf '   \\033[1;32mOK\\033[0m  %s\\n' \"$*\"; }\nwarn() { printf '   \\033[1;33mAVISO\\033[0m  %s\\n' \"$*\" >&2; }\nskip() { printf '   \\033[0;37m--  %s\\033[0m\\n' \"$*\"; }\ndie()  { printf '\\n\\033[1;31mERRO: %s\\033[0m\\n' \"$*\" >&2; exit 1; }\n\ndo_it() {\n    printf '   + %s\\n' \"$*\"\n    [ \"$APPLY\" -eq 1 ] && \"$@\"\n    return 0\n}\n\nTS=\"$(date +%Y%m%d-%H%M%S)\"\nBK=\"/var/backups/travamentos-$TS\"\n\nbackup() {\n    local f=\"$1\"\n    [ -f \"$f\" ] || return 0\n    if [ \"$APPLY\" -eq 1 ]; then\n        mkdir -p \"$BK\"\n        cp -a \"$f\" \"$BK/$(basename \"$f\").$TS\"\n    fi\n}\n\nif [ \"$APPLY\" -eq 1 ] && [ \"$(id -u)\" -ne 0 ]; then\n    echo \"Precisa de root; reexecutando com sudo...\"\n    exec sudo -E \"$(readlink -f \"$0\")\" \"$@\"\nfi\n\n[ -d /run/systemd/system ] || die \"este script assume systemd.\"\n\nif [ \"$APPLY\" -eq 0 ]; then\n    printf '\\033[1;33mMODO SIMULA\u00c7\u00c3O\\033[0m \u2014 nada ser\u00e1 alterado. Use --apply para valer.\\n'\nelse\n    printf '\\033[1;32mMODO APLICA\u00c7\u00c3O\\033[0m \u2014 backups em %s\\n' \"$BK\"\nfi\n\n# -----------------------------------------------------------------------------\n# 1. crashkernel (kdump desligado)\n# -----------------------------------------------------------------------------\nsay \"1/7 crashkernel\"\nif grep -q 'crashkernel=' /proc/cmdline; then\n    if systemctl is-active --quiet kdump 2>/dev/null; then\n        warn \"kdump est\u00e1 ATIVO; n\u00e3o vou remover o crashkernel. Desative o kdump antes, se quiser o ganho.\"\n    else\n        CK=\"$(tr ' ' '\\n' < /proc/cmdline | grep '^crashkernel=' | head -1)\"\n        ok \"kdump desligado; removendo '$CK' (~448 MiB de RAM a recuperar)\"\n        backup /etc/default/grub\n        backup /etc/kernel/cmdline\n        # usa s\u00f3 a chave: o valor tem v\u00edrgula e o grubby trata --remove-args como lista\n        do_it grubby --update-kernel=ALL --remove-args=\"crashkernel\"\n        if [ -f /etc/default/grub ]; then\n            do_it sed -i -E 's/[[:space:]]*crashkernel=[^\"[:space:]]*//g' /etc/default/grub\n        fi\n        if [ -f /etc/kernel/cmdline ]; then\n            do_it sed -i -E 's/[[:space:]]*crashkernel=[^[:space:]]*//g' /etc/kernel/cmdline\n        fi\n        if [ \"$APPLY\" -eq 1 ]; then\n            TMPG=\"$(mktemp)\"\n            if ! grubby --info=ALL >\"$TMPG\" 2>/dev/null || [ ! -s \"$TMPG\" ]; then\n                warn \"n\u00e3o consegui ler as entradas do grubby; confira manualmente ap\u00f3s o reboot\"\n            elif grep -q 'crashkernel=' \"$TMPG\"; then\n                warn \"ainda h\u00e1 crashkernel em alguma entrada; confira: grubby --info=ALL | grep args\"\n            else\n                ok \"crashkernel removido das entradas de boot\"\n            fi\n            rm -f \"$TMPG\"\n        fi\n    fi\nelse\n    ok \"j\u00e1 n\u00e3o h\u00e1 crashkernel na linha de comando\"\nfi\n\n# -----------------------------------------------------------------------------\n# 2. zram 1G -> 2G\n# -----------------------------------------------------------------------------\nsay \"2/7 zram\"\nUNIT=/etc/systemd/system/zram-swap.service\nif [ ! -f \"$UNIT\" ]; then\n    warn \"$UNIT n\u00e3o existe; pulando (confira como o zram \u00e9 criado nesta m\u00e1quina)\"\nelif grep -q 'echo 1G > /sys/block/zram0/disksize' \"$UNIT\"; then\n    backup \"$UNIT\"\n    ok \"zram: 1 GiB -> 2 GiB (efetivo no pr\u00f3ximo boot)\"\n    do_it sed -i 's|echo 1G > /sys/block/zram0/disksize|echo 2G > /sys/block/zram0/disksize|' \"$UNIT\"\n    do_it sed -i 's/ZRAM swap (1G/ZRAM swap (2G/' \"$UNIT\"\n    do_it systemctl daemon-reload\nelse\n    ok \"zram j\u00e1 configurado para 2 GiB (ou tamanho diferente); nada a fazer\"\nfi\n\n# -----------------------------------------------------------------------------\n# 3. swap no HDD\n# -----------------------------------------------------------------------------\nsay \"3/7 swap do HDD (/dev/sda3)\"\nif [ \"$KEEP_HDD_SWAP\" -eq 1 ]; then\n    skip \"mantido por --keep-hdd-swap (swappiness ficar\u00e1 em 60)\"\nelif ! swapon --show=NAME --noheadings 2>/dev/null | grep -qx '/dev/sda3'; then\n    ok \"swap do HDD j\u00e1 est\u00e1 desativado\"\nelif ! swapon --show=NAME --noheadings 2>/dev/null | grep -qx '/dev/zram0'; then\n    warn \"o zram n\u00e3o est\u00e1 ativo; N\u00c3O vou desativar o swap do HDD (evita OOM)\"\nelse\n    USED_BYTES=\"$(swapon --show=NAME,USED --noheadings --bytes --raw 2>/dev/null \\\n                  | awk '$1==\"/dev/sda3\"{print $2}' | tr -dc '0-9')\"\n    USED_BYTES=\"${USED_BYTES:-0}\"\n    if [ \"$USED_BYTES\" -gt 0 ] && [ \"$FORCE\" -ne 1 ]; then\n        warn \"h\u00e1 $((USED_BYTES / 1048576)) MiB em uso no swap do HDD; n\u00e3o vou mexer (use --force para for\u00e7ar)\"\n    else\n        ok \"desativando e mascarando o swap do HDD (zram fica como \u00fanico swap)\"\n        do_it swapoff /dev/sda3\n        do_it systemctl mask dev-sda3.swap\n        if [ \"$APPLY\" -eq 1 ] && swapon --show=NAME --noheadings | grep -qx '/dev/sda3'; then\n            warn \"ainda ativo; mascare tamb\u00e9m a unit por UUID: systemctl list-units --type=swap\"\n        fi\n    fi\nfi\n\n# -----------------------------------------------------------------------------\n# 4. BFQ no sda\n# -----------------------------------------------------------------------------\nsay \"4/7 agendador de I/O (BFQ)\"\nif [ ! -e /sys/block/sda/queue/scheduler ]; then\n    warn \"/sys/block/sda n\u00e3o encontrado; pulando\"\nelif grep -qw bfq /sys/block/sda/queue/scheduler; then\n    if [ \"$(cat /sys/block/sda/queue/scheduler | sed 's/.*\\[\\(.*\\)\\].*/\\1/')\" = bfq ]; then\n        ok \"BFQ j\u00e1 est\u00e1 ativo\"\n    else\n        ok \"ativando BFQ agora\"\n        do_it sh -c 'echo bfq > /sys/block/sda/queue/scheduler'\n    fi\n    backup /etc/udev/rules.d/60-sda-bfq.rules\n    do_it sh -c 'printf \"%s\\n\" \"ACTION==\\\"add|change\\\", KERNEL==\\\"sda\\\", ATTR{queue/scheduler}=\\\"bfq\\\"\" > /etc/udev/rules.d/60-sda-bfq.rules'\n    do_it udevadm control --reload-rules\n    do_it udevadm trigger --name-match=sda\nelse\n    warn \"BFQ n\u00e3o dispon\u00edvel neste kernel; mantendo o agendador atual\"\nfi\n\n# -----------------------------------------------------------------------------\n# 5. sysctl\n# -----------------------------------------------------------------------------\nsay \"5/7 sysctl de resposta\"\nSWAPPINESS=100\n[ \"$KEEP_HDD_SWAP\" -eq 1 ] && SWAPPINESS=60\nSYSCTL_FILE=/etc/sysctl.d/99-resposta.conf\nok \"escrevendo $SYSCTL_FILE (swappiness=$SWAPPINESS)\"\nbackup \"$SYSCTL_FILE\"\nif [ \"$APPLY\" -eq 1 ]; then\n    cat > \"$SYSCTL_FILE\" <<EOF\n# Auditoria de travamentos \u2014 24/10/2026\n# swappiness alto s\u00f3 vale com zram como \u00fanico swap (swap no HDD desativado)\nvm.swappiness=$SWAPPINESS\nvm.dirty_ratio=10\nvm.dirty_background_ratio=3\nvm.page-cluster=0\nvm.min_free_kbytes=98304\nEOF\n    sysctl --system >/dev/null\nelse\n    printf '   + escrever %s\\n' \"$SYSCTL_FILE\"\nfi\n\n# -----------------------------------------------------------------------------\n# 6. Transparent Huge Pages\n# -----------------------------------------------------------------------------\nsay \"6/7 Transparent Huge Pages\"\nTHP=/sys/kernel/mm/transparent_hugepage/enabled\nif [ -f \"$THP\" ]; then\n    if grep -q '\\[madvise\\]' \"$THP\"; then\n        ok \"THP j\u00e1 est\u00e1 em madvise\"\n    else\n        ok \"THP: always -> madvise\"\n        do_it sh -c 'echo madvise > /sys/kernel/mm/transparent_hugepage/enabled'\n    fi\nfi\nif ! grep -q 'transparent_hugepage=' /proc/cmdline; then\n    ok \"persistindo via kernel cmdline (pr\u00f3ximo boot)\"\n    do_it grubby --update-kernel=ALL --args=\"transparent_hugepage=madvise\" >/dev/null\nelse\n    skip \"j\u00e1 h\u00e1 transparent_hugepage= na cmdline\"\nfi\n\n# -----------------------------------------------------------------------------\n# 7. SELinux execmod + setroubleshoot\n# -----------------------------------------------------------------------------\nsay \"7/7 SELinux\"\nif command -v getsebool >/dev/null 2>&1; then\n    if getsebool selinuxuser_execmod 2>/dev/null | grep -q -- '--> on'; then\n        ok \"selinuxuser_execmod j\u00e1 est\u00e1 on\"\n    else\n        ok \"habilitando selinuxuser_execmod (elimina o AVC a cada start do llamafile)\"\n        do_it setsebool -P selinuxuser_execmod on\n    fi\nelse\n    warn \"getsebool n\u00e3o encontrado; pulando\"\nfi\nif [ \"$MASK_SETROUBLESHOOT\" -eq 1 ]; then\n    ok \"mascarando setroubleshootd (n\u00e3o abre o notificador a cada nega\u00e7\u00e3o)\"\n    do_it systemctl mask --now setroubleshootd.service\nfi\n\n# -----------------------------------------------------------------------------\n# resumo\n# -----------------------------------------------------------------------------\nsay \"resumo\"\nif [ \"$APPLY\" -eq 0 ]; then\n    echo \"   Simula\u00e7\u00e3o conclu\u00edda. Para aplicar:  sudo $0 --apply\"\nelse\n    echo \"   Aplicado. Backup em: $BK\"\n    echo\n    echo \"   REINICIE para valer:  sudo reboot\"\n    echo\n    echo \"   Depois do boot, confira:\"\n    echo \"     free -m                      # MemTotal deve ter subido ~448 MB\"\n    echo \"     swapon --show                # deve listar s\u00f3 /dev/zram0 (2G)\"\n    echo \"     cat /sys/block/sda/queue/scheduler   # deve mostrar [bfq]\"\n    echo \"     cat /sys/kernel/mm/transparent_hugepage/enabled  # [madvise]\"\n    echo \"     cat /proc/pressure/io        # full deve ficar < 10%\"\n    echo\n    echo \"   Sa\u00fade do HDD (recomendado):\"\n    echo \"     sudo dnf install -y smartmontools\"\n    echo \"     sudo smartctl -a /dev/sda | grep -Ei 'Reallocated|Pending|Uncorrectable|Power_On|Temperature'\"\nfi\n", "bluetooth/bt-auto.sh": "#!/bin/bash\ncat > /etc/systemd/system/bt-connect.service <<'EOF'\n[Unit]\nDescription=Conectar Bluetooth automaticamente\nAfter=bluetooth.service\nRequires=bluetooth.service\n\n[Service]\nType=oneshot\nExecStart=/usr/local/bin/bt-device -c 67:F0:01:5D:BC:31\nRestart=on-failure\nRestartSec=10\n\n[Install]\nWantedBy=multi-user.target\nEOF\n\nsystemctl daemon-reload\nsystemctl enable --now bt-connect\necho \"Servico criado e ativado com sucesso!\"\n", "bluetooth/bt-ctl.sh": "#!/bin/bash\n\n# ============================================\n# bt-ctl.sh - Script de gerenciamento Bluetooth\n# Usa bluetoothctl e seus parametros\n# ============================================\n\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nCYAN='\\033[0;36m'\nNC='\\033[0m'\n\nLOG_FILE=\"/var/log/bt-ctl.log\"\n\nlog_msg() {\n    echo -e \"[$(date '+%Y-%m-%d %H:%M:%S')] $1\" | tee -a \"$LOG_FILE\"\n}\n\ncheck_bluetooth() {\n    if ! command -v bluetoothctl &>/dev/null; then\n        echo -e \"${RED}bluetoothctl nao encontrado. Instale bluez.${NC}\"\n        exit 1\n    fi\n}\n\n# --- Informacoes do controlador ---\ninfo_controller() {\n    echo -e \"${CYAN}=== Informacoes do Controlador ===${NC}\"\n    bluetoothctl show\n    echo \"\"\n}\n\n# --- Listar dispositivos pareados ---\nlist_devices() {\n    echo -e \"${CYAN}=== Dispositivos Conhecidos ===${NC}\"\n    bluetoothctl devices\n    echo \"\"\n}\n\n# --- Ligacao do Bluetooth ---\npower_on() {\n    echo -e \"${YELLOW}Ligando Bluetooth...${NC}\"\n    bluetoothctl power on\n    log_msg \"Bluetooth ligado\"\n}\n\npower_off() {\n    echo -e \"${YELLOW}Desligando Bluetooth...${NC}\"\n    bluetoothctl power off\n    log_msg \"Bluetooth desligado\"\n}\n\n# --- Scan de dispositivos ---\nscan_on() {\n    echo -e \"${YELLOW}Iniciando scan por 15 segundos...${NC}\"\n    timeout 15 bluetoothctl scan on 2>/dev/null\n    echo -e \"${GREEN}Scan finalizado. Dispositivos encontrados:${NC}\"\n    bluetoothctl devices\n    log_msg \"Scan executado\"\n}\n\n# --- Emparelhar dispositivo ---\npair_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 pair <MAC_ADDRESS>${NC}\"\n        echo \"Exemplo: $0 pair 67:F0:01:5D:BC:31\"\n        return 1\n    fi\n    echo -e \"${YELLOW}Emparalhando com $MAC...${NC}\"\n    bluetoothctl pair \"$MAC\"\n    log_msg \"Tentativa de pareamento com $MAC\"\n}\n\n# --- Conectar dispositivo ---\nconnect_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 connect <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    echo -e \"${YELLOW}Conectando a $MAC...${NC}\"\n    bluetoothctl connect \"$MAC\"\n    log_msg \"Tentativa de conexao com $MAC\"\n}\n\n# --- Desconectar dispositivo ---\ndisconnect_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 disconnect <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    echo -e \"${YELLOW}Desconectando $MAC...${NC}\"\n    bluetoothctl disconnect \"$MAC\"\n    log_msg \"Desconectado de $MAC\"\n}\n\n# --- Confiar no dispositivo ---\ntrust_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 trust <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    echo -e \"${YELLOW}Confiando em $MAC...${NC}\"\n    bluetoothctl trust \"$MAC\"\n    log_msg \"Dispositivo $MAC marcado como confiavel\"\n}\n\n# --- Remover dispositivo ---\nremove_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 remove <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    echo -e \"${RED}Removendo $MAC...${NC}\"\n    bluetoothctl remove \"$MAC\"\n    log_msg \"Dispositivo $MAC removido\"\n}\n\n# --- Tornar discoverable ---\ndiscoverable_on() {\n    echo -e \"${YELLOW}Tornando dispositivo visivel...${NC}\"\n    bluetoothctl discoverable on\n    log_msg \"Discoverable ligado\"\n}\n\ndiscoverable_off() {\n    echo -e \"${YELLOW}Ocultando dispositivo...${NC}\"\n    bluetoothctl discoverable off\n    log_msg \"Discoverable desligado\"\n}\n\n# --- Tornar pairable ---\npairable_on() {\n    bluetoothctl pairable on\n    echo -e \"${GREEN}Pairable: ON${NC}\"\n}\n\npairable_off() {\n    bluetoothctl pairable off\n    echo -e \"${YELLOW}Pairable: OFF${NC}\"\n}\n\n# --- Informacoes de um dispositivo ---\ndevice_info() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 info <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    echo -e \"${CYAN}=== Info: $MAC ===${NC}\"\n    bluetoothctl info \"$MAC\"\n}\n\n# --- Bloquear / Desbloquear ---\nblock_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 block <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    bluetoothctl block \"$MAC\"\n    log_msg \"Dispositivo $MAC bloqueado\"\n}\n\nunblock_device() {\n    local MAC=$1\n    if [ -z \"$MAC\" ]; then\n        echo -e \"${RED}Uso: $0 unblock <MAC_ADDRESS>${NC}\"\n        return 1\n    fi\n    bluetoothctl unblock \"$MAC\"\n    log_msg \"Dispositivo $MAC desbloqueado\"\n}\n\n# --- Renomear controlador ---\nset_alias() {\n    local NAME=$1\n    if [ -z \"$NAME\" ]; then\n        echo -e \"${RED}Uso: $0 alias <NOME>${NC}\"\n        return 1\n    fi\n    bluetoothctl system-alias \"$NAME\"\n    log_msg \"Controlador renomeado para $NAME\"\n}\n\n# --- Remover alias ---\nreset_alias() {\n    bluetoothctl reset-alias\n    log_msg \"Alias resetado\"\n}\n\n# --- Modo de emparelhamento ---\npairable_mode() {\n    local MODE=$1\n    if [ -z \"$MODE\" ]; then\n        echo -e \"${RED}Uso: $0 pairable-mode <on|off>${NC}\"\n        return 1\n    fi\n    bluetoothctl pairable \"$MODE\"\n    log_msg \"Pairable mode: $MODE\"\n}\n\n# --- Menu interativo ---\ninteractive() {\n    while true; do\n        echo \"\"\n        echo -e \"${CYAN}========================================${NC}\"\n        echo -e \"${CYAN}   Gerenciador Bluetooth - Interativo   ${NC}\"\n        echo -e \"${CYAN}========================================${NC}\"\n        echo \"  1)  Info do controlador\"\n        echo \"  2)  Listar dispositivos\"\n        echo \"  3)  Ligar Bluetooth\"\n        echo \"  4)  Desligar Bluetooth\"\n        echo \"  5)  Scan (15s)\"\n        echo \"  6)  Emparelhar (pair)\"\n        echo \"  7)  Conectar\"\n        echo \"  8)  Desconectar\"\n        echo \"  9)  Confiar (trust)\"\n        echo \" 10)  Remover dispositivo\"\n        echo \" 11)  Discoverable on/off\"\n        echo \" 12)  Pairable on/off\"\n        echo \" 13)  Info de dispositivo\"\n        echo \" 14)  Block/Unblock\"\n        echo \" 15)  Renomear controlador\"\n        echo \"  0)  Sair\"\n        echo -e \"${CYAN}========================================${NC}\"\n        read -p \"Opcao: \" opt\n\n        case $opt in\n            1) info_controller ;;\n            2) list_devices ;;\n            3) power_on ;;\n            4) power_off ;;\n            5) scan_on ;;\n            6) read -p \"MAC: \" mac; pair_device \"$mac\" ;;\n            7) read -p \"MAC: \" mac; connect_device \"$mac\" ;;\n            8) read -p \"MAC: \" mac; disconnect_device \"$mac\" ;;\n            9) read -p \"MAC: \" mac; trust_device \"$mac\" ;;\n            10) read -p \"MAC: \" mac; remove_device \"$mac\" ;;\n            11)\n                read -p \"on/off: \" mode\n                if [ \"$mode\" = \"on\" ]; then discoverable_on; else discoverable_off; fi\n                ;;\n            12)\n                read -p \"on/off: \" mode\n                if [ \"$mode\" = \"on\" ]; then pairable_on; else pairable_off; fi\n                ;;\n            13) read -p \"MAC: \" mac; device_info \"$mac\" ;;\n            14)\n                read -p \"MAC: \" mac\n                read -p \"block/unblock: \" action\n                if [ \"$action\" = \"block\" ]; then block_device \"$mac\"; else unblock_device \"$mac\"; fi\n                ;;\n            15) read -p \"Nome: \" name; set_alias \"$name\" ;;\n            0) echo \"Saindo...\"; exit 0 ;;\n            *) echo -e \"${RED}Opcao invalida${NC}\" ;;\n        esac\n    done\n}\n\n# --- Ajuda ---\nshow_help() {\n    echo -e \"${CYAN}Uso: $0 [comando] [parametros]${NC}\"\n    echo \"\"\n    echo \"Comandos:\"\n    echo \"  info                     - Mostra info do controlador\"\n    echo \"  list                     - Lista dispositivos conhecidos\"\n    echo \"  power on|off             - Liga/desliga Bluetooth\"\n    echo \"  scan                     - Scan por 15 segundos\"\n    echo \"  pair <MAC>               - Emparella com dispositivo\"\n    echo \"  connect <MAC>            - Conecta ao dispositivo\"\n    echo \"  disconnect <MAC>         - Desconecta dispositivo\"\n    echo \"  trust <MAC>              - Confiar no dispositivo\"\n    echo \"  remove <MAC>             - Remove dispositivo\"\n    echo \"  discoverable on|off      - Visivel/invisivel\"\n    echo \"  pairable on|off          - Permite/nega pareamento\"\n    echo \"  info <MAC>               - Info de um dispositivo\"\n    echo \"  block <MAC>              - Bloqueia dispositivo\"\n    echo \"  unblock <MAC>            - Desbloqueia dispositivo\"\n    echo \"  alias <NOME>             - Renomeia controlador\"\n    echo \"  reset-alias              - Reseta nome do controlador\"\n    echo \"  interactive              - Menu interativo\"\n    echo \"  help                     - Esta ajuda\"\n}\n\n# --- Main ---\ncheck_bluetooth\n\ncase \"${1:-help}\" in\n    info)          info_controller ;;\n    list)          list_devices ;;\n    power)         power_on; power_off ;;\n    scan)          scan_on ;;\n    pair)          pair_device \"$2\" ;;\n    connect)       connect_device \"$2\" ;;\n    disconnect)    disconnect_device \"$2\" ;;\n    trust)         trust_device \"$2\" ;;\n    remove)        remove_device \"$2\" ;;\n    discoverable)\n        if [ \"$2\" = \"on\" ]; then discoverable_on; else discoverable_off; fi\n        ;;\n    pairable)\n        if [ \"$2\" = \"on\" ]; then pairable_on; else pairable_off; fi\n        ;;\n    info-dev)      device_info \"$2\" ;;\n    block)         block_device \"$2\" ;;\n    unblock)       unblock_device \"$2\" ;;\n    alias)         set_alias \"$2\" ;;\n    reset-alias)   reset_alias ;;\n    interactive)   interactive ;;\n    help|--help|-h) show_help ;;\n    *)\n        echo -e \"${RED}Comando desconhecido: $1${NC}\"\n        show_help\n        ;;\nesac\n", "build-iso.sh": "#!/usr/bin/env bash\n# =============================================================================\n# build-iso.sh - Oracle Linux 9.8 GNOME -> ISO instalavel UEFI\n#\n# Estrategia: remasteriza o boot.iso OFICIAL do Oracle Linux 9.8 com mkksiso,\n# injetando um kickstart (GNOME + AppImages + configs) sem precisar montar\n# um ambiente de build em QEMU. O boot UEFI original e preservado.\n#\n# Fases:\n#   download  Baixa o boot.iso oficial (~1.5 GiB) para cache/\n#   check     Pre-flight + inventario + gera kickstart + overlay (sem root)\n#   build     Gera a ISO customizada com mkksiso (sem root)\n#   verify    Valida EFI, kickstart, overlay e checksum\n#   clean     Remove temporarios (mantem ISO e cache)\n#\n# Uso:\n#   ./build-iso.sh download\n#   ./build-iso.sh check\n#   ./build-iso.sh build\n#   ./build-iso.sh verify\n# =============================================================================\nset -Eeuo pipefail\n\n# Usuario real mesmo sob sudo (HOME vira /root).\nSCRIPT_USER=\"${SUDO_USER:-${USER}}\"\nTARGET_HOME=\"$(getent passwd \"$SCRIPT_USER\" | cut -d: -f6)\"\n[ -n \"${TARGET_HOME:-}\" ] || TARGET_HOME=\"$HOME\"\n\nBASE_DIR=\"${BASE_DIR:-$TARGET_HOME/iso-build}\"\nCACHE_DIR=\"$BASE_DIR/cache\"\nOUT_DIR=\"$BASE_DIR/out\"\nWORK_DIR=\"$BASE_DIR/work\"\nKS_DIR=\"$BASE_DIR/kickstart\"\nOVERLAY_DIR=\"$BASE_DIR/overlay\"\nLOG_DIR=\"$BASE_DIR/logs\"\n\nRELEASEVER=\"${RELEASEVER:-9.8}\"\nPROFILE_NAME=\"${PROFILE_NAME:-OL98-GNOME-Custom}\"\nVOLID=\"${VOLID:-OL98_GNOME_CUSTOM}\"\nISO_NAME=\"${ISO_NAME:-OL98-GNOME-Custom.iso}\"\nISO_PATH=\"$OUT_DIR/$ISO_NAME\"\n\nBOOT_ISO_NAME=\"OracleLinux-R9-U8-x86_64-boot.iso\"\nBOOT_ISO=\"$CACHE_DIR/$BOOT_ISO_NAME\"\nBOOT_URL=\"https://yum.oracle.com/ISOS/OracleLinux/OL9/u8/x86_64/$BOOT_ISO_NAME\"\nBOOT_SIZE=1561657344\n\nTARGET_USER=\"${TARGET_USER:-$SCRIPT_USER}\"\nTARGET_HOST=\"${TARGET_HOST:-ol98-custom}\"\nTARGET_PASS=\"${TARGET_PASS:-}\"\n\nKS_FILE=\"$KS_DIR/ol98-custom.ks\"\nOVERLAY_TGZ=\"$OVERLAY_DIR/overlay.tar.gz\"\nCREDS_FILE=\"$BASE_DIR/credentials.txt\"\n\nmkdir -p \"$CACHE_DIR\" \"$OUT_DIR\" \"$WORK_DIR\" \"$KS_DIR\" \"$OVERLAY_DIR\" \"$LOG_DIR\"\n\n# -----------------------------------------------------------------------------\n# Helpers\n# -----------------------------------------------------------------------------\nc_reset=$'\\033[0m'; c_blue=$'\\033[1;34m'; c_green=$'\\033[1;32m'\nc_yellow=$'\\033[1;33m'; c_red=$'\\033[1;31m'\n\nlog()  { printf '%s[ %s ]%s %s\\n' \"$c_blue\" \"$(date +%H:%M:%S)\" \"$c_reset\" \"$*\"; }\nok()   { printf '%s[ OK ]%s %s\\n' \"$c_green\" \"$c_reset\" \"$*\"; }\nwarn() { printf '%s[WARN]%s %s\\n' \"$c_yellow\" \"$c_reset\" \"$*\"; }\ndie()  { printf '%s[FAIL]%s %s\\n' \"$c_red\" \"$c_reset\" \"$*\" >&2; exit 1; }\n\nneed_root() { [ \"$(id -u)\" -eq 0 ] || die \"Precisa de root. Rode: sudo $0 ${1:-verify}\"; }\nhave() { command -v \"$1\" >/dev/null 2>&1; }\n\n# -----------------------------------------------------------------------------\n# Kickstart\n# -----------------------------------------------------------------------------\ngenerate_kickstart() {\n  local pass=\"$TARGET_PASS\"\n  if [ -z \"$pass\" ] && [ -f \"$CREDS_FILE\" ]; then\n    pass=\"$(awk -F': *' '/^senha:/{print $2}' \"$CREDS_FILE\" | head -1)\"\n  fi\n  if [ -z \"$pass\" ]; then\n    pass=\"$(head -c 64 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | cut -c1-16)\"\n    {\n      echo \"usuario: $TARGET_USER\"\n      echo \"senha:   $pass\"\n      echo \"host:    $TARGET_HOST\"\n      echo \"gerado:  $(date -Is)\"\n    } > \"$CREDS_FILE\"\n    chmod 600 \"$CREDS_FILE\"\n    warn \"Senha do usuario gerada e salva em: $CREDS_FILE\"\n  fi\n\n  local pass_hash\n  pass_hash=\"$(openssl passwd -6 \"$pass\")\"\n\n  log \"Gerando kickstart: $KS_FILE\"\n  cat > \"$KS_FILE\" <<KS\n#version=OL9\n# Kickstart gerado por build-iso.sh em $(date -Is)\nlang pt_BR.UTF-8\nkeyboard --vckeymap=br-abnt2 --xlayouts='br'\ntimezone America/Sao_Paulo --utc\ntext\nselinux --enforcing\nfirewall --enabled --service=ssh\nnetwork --bootproto=dhcp --device=link --activate --hostname=${TARGET_HOST}\nrootpw --lock\nuser --name=${TARGET_USER} --groups=wheel --shell=/bin/bash --password=${pass_hash}\nfirstboot --disable\nzerombr\nclearpart --all --initlabel\nautopart --type=plain --nohome\nbootloader --location=mbr --timeout=5 --append=\"rhgb quiet\"\nreboot\n\nurl --url=\"https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/\"\nrepo --name=\"appstream\" --baseurl=\"https://yum.oracle.com/repo/OracleLinux/OL9/appstream/latest/x86_64/\"\nrepo --name=\"uek\" --baseurl=\"https://yum.oracle.com/repo/OracleLinux/OL9/UEKR8/latest/x86_64/\"\n\n%packages\n@^graphical-server-environment\n@gnome-desktop\n@fonts\n@input-methods\nkernel-uek\nfuse\nfuse-libs\nfuse3\nfuse3-libs\nrsync\ncurl\ntar\ngnome-tweaks\ngnome-terminal\nnautilus\n%end\n\n# Copia AppImages/configs do ISO para o sistema instalado.\n%post --nochroot --log=/root/ks-post-nochroot.log\nset -x\nfor d in /run/install/repo /mnt/install/repo /run/install/isodir; do\n  if [ -f \"\\$d/overlay.tar.gz\" ] && [ -d /mnt/sysimage ]; then\n    tar -xzf \"\\$d/overlay.tar.gz\" -C /mnt/sysimage/\n    break\n  fi\ndone\n%end\n\n%post --log=/root/ks-post.log\nset -x\nchown -R 1000:1000 /home/${TARGET_USER} 2>/dev/null || true\nfind /home/${TARGET_USER}/Applications -name '*.AppImage' -exec chmod +x {} \\\\; 2>/dev/null || true\nrestorecon -R /home/${TARGET_USER} 2>/dev/null || true\n\n# Fallback: se libfuse2 nao existir, AppImages extraem em vez de montar.\ncat >/etc/profile.d/99-appimage-fallback.sh <<'EOS'\nif ! ldconfig -p 2>/dev/null | grep -q 'libfuse\\\\.so\\\\.2'; then\n  export APPIMAGE_EXTRACT_AND_RUN=1\nfi\nEOS\nchmod 644 /etc/profile.d/99-appimage-fallback.sh\n\n# Usa o kernel UEK como padrao, igual ao sistema atual.\nif ls /boot/vmlinuz-*uek* >/dev/null 2>&1; then\n  grubby --set-default \"\\$(ls -1 /boot/vmlinuz-*uek* | sort -V | tail -1)\" 2>/dev/null || true\nfi\n\nsystemctl enable gdm.service 2>/dev/null || true\nsystemctl enable sshd.service 2>/dev/null || true\nsystemctl set-default graphical.target 2>/dev/null || true\n%end\nKS\n  ok \"Kickstart criado.\"\n}\n\n# -----------------------------------------------------------------------------\n# Overlay (allowlist: sem .ssh/.gnupg/keyrings/browsers)\n# -----------------------------------------------------------------------------\nmake_overlay() {\n  local root=\"$OVERLAY_DIR/root\"\n  log \"Montando overlay (AppImages + configuracoes seguras)...\"\n  rm -rf \"$root\"\n  mkdir -p \"$root/home/$TARGET_USER/Applications\" \\\n           \"$root/home/$TARGET_USER/.local/share/applications\" \\\n           \"$root/home/$TARGET_USER/.config\"\n\n  if [ -d \"$TARGET_HOME/Applications\" ]; then\n    rsync -a --include='*.AppImage' --include='*.version' --exclude='*' \\\n      \"$TARGET_HOME/Applications/\" \"$root/home/$TARGET_USER/Applications/\"\n  fi\n  if [ -d \"$TARGET_HOME/.local/bin\" ]; then\n    find \"$TARGET_HOME/.local/bin\" -maxdepth 1 -name '*.AppImage' -exec cp -a {} \\\n      \"$root/home/$TARGET_USER/Applications/\" \\; 2>/dev/null || true\n  fi\n  if [ -d \"$TARGET_HOME/.local/share/applications\" ]; then\n    find \"$TARGET_HOME/.local/share/applications\" -maxdepth 1 -name '*.desktop' \\\n      -exec cp -a {} \"$root/home/$TARGET_USER/.local/share/applications/\" \\; 2>/dev/null || true\n  fi\n  if [ -d \"$TARGET_HOME/Desktop\" ]; then\n    find \"$TARGET_HOME/Desktop\" -maxdepth 1 -name '*.desktop' \\\n      -exec cp -a {} \"$root/home/$TARGET_USER/.local/share/applications/\" \\; 2>/dev/null || true\n  fi\n\n  local cfg\n  for cfg in gtk-3.0 gtk-4.0 dconf fontconfig nautilus gedit; do\n    if [ -d \"$TARGET_HOME/.config/$cfg\" ]; then\n      cp -a \"$TARGET_HOME/.config/$cfg\" \"$root/home/$TARGET_USER/.config/\"\n    fi\n  done\n  if [ -d \"$TARGET_HOME/.local/share/fonts\" ]; then\n    mkdir -p \"$root/home/$TARGET_USER/.local/share\"\n    cp -a \"$TARGET_HOME/.local/share/fonts\" \"$root/home/$TARGET_USER/.local/share/\"\n  fi\n  if [ -d \"$TARGET_HOME/.local/share/themes\" ]; then\n    mkdir -p \"$root/home/$TARGET_USER/.local/share\"\n    cp -a \"$TARGET_HOME/.local/share/themes\" \"$root/home/$TARGET_USER/.local/share/\"\n  fi\n  [ -f \"$TARGET_HOME/.bashrc\" ] && cp -a \"$TARGET_HOME/.bashrc\" \"$root/home/$TARGET_USER/.bashrc\"\n  [ -f \"$TARGET_HOME/.gitconfig\" ] && cp -a \"$TARGET_HOME/.gitconfig\" \"$root/home/$TARGET_USER/.gitconfig\"\n\n  rm -f \"$OVERLAY_TGZ\"\n  tar -czf \"$OVERLAY_TGZ\" -C \"$root\" .\n  chmod 644 \"$OVERLAY_TGZ\"\n  ok \"Overlay: $OVERLAY_TGZ ($(du -h \"$OVERLAY_TGZ\" | cut -f1))\"\n}\n\n# -----------------------------------------------------------------------------\n# download\n# -----------------------------------------------------------------------------\ncmd_download() {\n  mkdir -p \"$CACHE_DIR\"\n  if [ -f \"$BOOT_ISO\" ]; then\n    local size\n    size=$(stat -c %s \"$BOOT_ISO\")\n    if [ \"$size\" -eq \"$BOOT_SIZE\" ]; then\n      ok \"boot.iso ja existe e esta completo: $BOOT_ISO\"\n      return 0\n    fi\n    warn \"boot.iso incompleto ($size bytes). Retomando download...\"\n  fi\n  log \"Baixando boot.iso oficial (~1.5 GiB) para $CACHE_DIR\"\n  curl -fL --retry 3 --retry-delay 5 -C - -o \"$BOOT_ISO\" \"$BOOT_URL\"\n  local size\n  size=$(stat -c %s \"$BOOT_ISO\")\n  [ \"$size\" -eq \"$BOOT_SIZE\" ] || die \"Tamanho inesperado: $size (esperado $BOOT_SIZE)\"\n  ok \"Download concluido: $BOOT_ISO\"\n}\n\n# -----------------------------------------------------------------------------\n# check\n# -----------------------------------------------------------------------------\ncmd_check() {\n  local fatal=0\n  log \"Pre-flight em $(hostname) - $(date -Is)\"\n  echo\n\n  if [ -r /etc/os-release ]; then\n    # shellcheck disable=SC1091\n    . /etc/os-release\n    echo \"SO........: ${PRETTY_NAME:-desconhecido}\"\n    case \"${ID:-}:${VERSION_ID:-}\" in\n      ol:9.*) ok \"Oracle Linux 9 detectado.\" ;;\n      *) warn \"Script desenhado para Oracle Linux 9.x.\" ;;\n    esac\n  fi\n  echo \"Kernel....: $(uname -r)\"\n  echo \"Arch......: $(uname -m)\"\n  [ \"$(uname -m)\" = \"x86_64\" ] || { warn \"Somente x86_64 testado.\"; fatal=1; }\n\n  local avail_gb\n  avail_gb=$(df -BG --output=avail \"$BASE_DIR\" 2>/dev/null | tail -1 | tr -dc '0-9')\n  echo \"Disco.....: ${avail_gb:-?} GiB livres em $BASE_DIR\"\n  if [ \"${avail_gb:-0}\" -lt 8 ]; then warn \"Recomendado >= 8 GiB livres.\"; fatal=1; else ok \"Espaco suficiente.\"; fi\n\n  echo\n  echo \"Ferramentas:\"\n  local t missing=0\n  for t in dnf rpm mkksiso xorriso implantisomd5 curl rsync; do\n    if have \"$t\"; then printf '  %-16s %s\\n' \"$t\" \"OK\"; else printf '  %-16s %s\\n' \"$t\" \"AUSENTE\"; missing=1; fi\n  done\n  [ \"$missing\" -eq 1 ] && warn \"Instale as ausentes (pacotes: lorax xorriso isomd5sum rsync curl).\"\n\n  echo\n  if [ -f \"$BOOT_ISO\" ]; then\n    ok \"boot.iso presente ($(du -h \"$BOOT_ISO\" | cut -f1)).\"\n  else\n    warn \"boot.iso ausente. Rode: $0 download\"\n  fi\n\n  echo\n  echo \"Repositorios Oracle usados no kickstart:\"\n  echo \"  baseos   : https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/\"\n  echo \"  appstream: https://yum.oracle.com/repo/OracleLinux/OL9/appstream/latest/x86_64/\"\n  echo \"  uek      : https://yum.oracle.com/repo/OracleLinux/OL9/UEKR8/latest/x86_64/\"\n\n  echo\n  log \"Inventario do sistema atual\"\n  echo \"  Pacotes RPM.....: $(rpm -qa | wc -l)\"\n  echo \"  AppImages.......: $(find \"$TARGET_HOME/Applications\" \"$TARGET_HOME/.local/bin\" -maxdepth 1 -name '*.AppImage' 2>/dev/null | wc -l)\"\n  echo \"  Atalhos .desktop: $(find \"$TARGET_HOME/.local/share/applications\" \"$TARGET_HOME/Desktop\" -maxdepth 1 -name '*.desktop' 2>/dev/null | wc -l)\"\n  echo \"  libfuse.so.2....: $(ldconfig -p 2>/dev/null | grep -c 'libfuse\\.so\\.2' || true)\"\n\n  echo\n  generate_kickstart\n  make_overlay\n\n  echo\n  if [ \"$fatal\" -eq 0 ]; then ok \"Pre-flight concluido.\"; else warn \"Pre-flight com bloqueios (veja avisos).\"; fi\n  cat <<EOF\n\nProximos passos:\n  1) $0 download\n  2) $0 build\n  3) $0 verify\n\nArquivos:\n  boot.iso : $BOOT_ISO\n  Kickstart: $KS_FILE\n  Overlay  : $OVERLAY_TGZ\n  ISO final: $ISO_PATH\nEOF\n}\n\n# -----------------------------------------------------------------------------\n# build\n# -----------------------------------------------------------------------------\ncmd_build() {\n  have mkksiso || die \"mkksiso ausente. Instale: sudo dnf install -y lorax xorriso isomd5sum\"\n  [ -f \"$BOOT_ISO\" ] || die \"boot.iso ausente. Rode: $0 download\"\n  [ -f \"$KS_FILE\" ] || die \"Kickstart ausente. Rode: $0 check\"\n  [ -f \"$OVERLAY_TGZ\" ] || die \"Overlay ausente. Rode: $0 check\"\n\n  local size\n  size=$(stat -c %s \"$BOOT_ISO\")\n  [ \"$size\" -eq \"$BOOT_SIZE\" ] || die \"boot.iso incompleto ($size/$BOOT_SIZE). Rode: $0 download\"\n\n  mkdir -p \"$OUT_DIR\"\n  rm -f \"$ISO_PATH\"\n\n  log \"Remasterizando boot.iso com mkksiso...\"\n  log \"Log: $LOG_DIR/mkksiso.log\"\n  set +e\n  mkksiso --ks \"$KS_FILE\" --add \"$OVERLAY_TGZ\" --volid \"$VOLID\" \\\n    \"$BOOT_ISO\" \"$ISO_PATH\" 2>&1 | tee -a \"$LOG_DIR/mkksiso.log\"\n  local rc=${PIPESTATUS[0]}\n  set -e\n  [ \"$rc\" -eq 0 ] || die \"mkksiso falhou (rc=$rc). Veja $LOG_DIR/mkksiso.log\"\n  [ -f \"$ISO_PATH\" ] || die \"ISO nao gerada.\"\n  # Build roda como root via sudo: devolve a propriedade ao usuario real.\n  if [ \"$(id -u)\" -eq 0 ] && [ -n \"${SUDO_USER:-}\" ]; then\n    chown \"$SUDO_USER\": \"$ISO_PATH\" 2>/dev/null || true\n    chown -R \"$SUDO_USER\": \"$LOG_DIR\" 2>/dev/null || true\n  fi\n  ok \"ISO gerada: $ISO_PATH\"\n  ls -lh \"$ISO_PATH\"\n\n  verify_iso\n}\n\n# -----------------------------------------------------------------------------\n# verify\n# -----------------------------------------------------------------------------\nverify_iso() {\n  log \"Validando ISO...\"\n  [ -f \"$ISO_PATH\" ] || die \"ISO inexistente: $ISO_PATH\"\n\n  local report\n  report=$(xorriso -indev \"$ISO_PATH\" -report_el_torito plain 2>/dev/null || true)\n  if grep -qi 'efi' <<<\"$report\"; then ok \"Entrada EFI (El Torito) detectada.\"; else warn \"Entrada EFI nao detectada.\"; fi\n\n  if [ \"$(id -u)\" -eq 0 ]; then\n    local mnt=\"$WORK_DIR/mnt\"\n    mkdir -p \"$mnt\"\n    if mount -o loop,ro \"$ISO_PATH\" \"$mnt\" 2>/dev/null; then\n      [ -f \"$mnt/EFI/BOOT/BOOTX64.EFI\" ] || [ -f \"$mnt/EFI/BOOT/bootx64.efi\" ] \\\n        && ok \"EFI/BOOT/BOOTX64.EFI presente.\" || warn \"BOOTX64.EFI ausente.\"\n      [ -f \"$mnt/overlay.tar.gz\" ] && ok \"overlay.tar.gz presente no ISO.\" || warn \"overlay.tar.gz ausente.\"\n      if [ -f \"$mnt/ol98-custom.ks\" ] || [ -f \"$mnt/ks.cfg\" ]; then\n        ok \"Kickstart presente no ISO.\"\n      else\n        warn \"Kickstart ausente no ISO.\"\n      fi\n      if grep -q 'inst\\.ks=' \"$mnt/EFI/BOOT/grub.cfg\" 2>/dev/null; then\n        ok \"inst.ks configurado no GRUB (UEFI).\"\n      else\n        warn \"inst.ks nao encontrado no grub.cfg.\"\n      fi\n      umount \"$mnt\"\n    else\n      warn \"Nao foi possivel montar a ISO para inspecao.\"\n    fi\n  else\n    warn \"Sem root: verificando conteudo sem montar (use sudo $0 verify para checagem completa).\"\n  fi\n\n  if have checkisomd5; then\n    checkisomd5 \"$ISO_PATH\" >/dev/null 2>&1 && ok \"Checksum MD5 valido.\" || warn \"Checksum MD5 invalido/ausente.\"\n  fi\n\n  local ovmf=\"\"\n  local p\n  for p in /usr/share/OVMF/OVMF_CODE.fd /usr/share/edk2/ovmf/OVMF_CODE.fd \\\n           /usr/share/edk2-ovmf/x64/OVMF_CODE.fd; do\n    [ -f \"$p\" ] && { ovmf=\"$p\"; break; }\n  done\n  ovmf=\"${ovmf:-/usr/share/OVMF/OVMF_CODE.fd}\"\n\n  cat <<EOF\n\nTeste em VM UEFI (host com OVMF):\n  qemu-system-x86_64 -enable-kvm -m 1536 -machine q35 \\\\\n    -bios \"$ovmf\" \\\\\n    -cdrom \"$ISO_PATH\" -boot d\n\nGravar em pendrive (CONFIRME o dispositivo antes):\n  sudo dd if=\"$ISO_PATH\" of=/dev/sdX bs=8M status=progress oflag=sync\nEOF\n}\n\n# -----------------------------------------------------------------------------\n# clean\n# -----------------------------------------------------------------------------\ncmd_clean() {\n  log \"Limpando temporarios (mantendo ISO, boot.iso e kickstart)...\"\n  rm -rf \"$WORK_DIR/tmp\" \"$WORK_DIR/mnt\" \"$OVERLAY_DIR/root\"\n  ok \"Limpeza concluida.\"\n}\n\nusage() {\n  sed -n '2,30p' \"$0\" | sed 's/^# \\{0,1\\}//'\n}\n\nmain() {\n  case \"${1:-check}\" in\n    download) cmd_download ;;\n    check)    cmd_check ;;\n    build)    cmd_build ;;\n    verify)   verify_iso ;;\n    clean)    cmd_clean ;;\n    -h|--help|help) usage ;;\n    *) usage; exit 1 ;;\n  esac\n}\n\nmain \"$@\"\n", "build_iso.sh": " #!/bin/bash\n# ==============================================================================\n# Gerador de ISO Customizada Oracle Linux 9.5 (XFCE + Chromium + Local Apps)\n# Usando livemedia-creator apenas com reposit\u00f3rios oficiais\n# Inclui configura\u00e7\u00e3o autom\u00e1tica do GRUB para UEFI\n# Suporte: UEFI e MBR (BIOS)\n# ==============================================================================\n\nset -e\n\nWORKDIR=$(pwd)\nOUT_DIR=\"$WORKDIR/output_iso\"\nKS_FILE=\"$WORKDIR/ks_automated.cfg\"\nLOG_FILE=\"$WORKDIR/build.log\"\n\n# Verificar se est\u00e1 rodando como root ou com sudo\nif [[ $EUID -ne 0 ]]; then\n   echo \"ERRO: Execute este script como root ou com sudo\"\n   exit 1\nfi\n\n# Verificar depend\u00eancias necess\u00e1rias\necho \"### [1/7] Verificando depend\u00eancias...\"\nMISSING_DEPS=()\nfor cmd in anaconda lorax livemedia-creator xorriso rsync createrepo_c grub2-efi-x64 shim-x64; do\n    if ! command -v $cmd &> /dev/null && ! rpm -q ${cmd} &> /dev/null 2>&1; then\n        MISSING_DEPS+=($cmd)\n    fi\ndone\n\nif [ ${#MISSING_DEPS[@]} -gt 0 ]; then\n    echo \"Instalando depend\u00eancias faltantes: ${MISSING_DEPS[@]}\"\n    dnf install -y \"${MISSING_DEPS[@]}\" | tee -a \"$LOG_FILE\" || {\n        echo \"ERRO: Falha ao instalar depend\u00eancias\"\n        exit 1\n    }\nfi\n\n# Verificar diret\u00f3rios necess\u00e1rios\nfor dir in software_rpm favoritos; do\n    if [ ! -d \"$WORKDIR/$dir\" ]; then\n        echo \"AVISO: Diret\u00f3rio '$dir' n\u00e3o encontrado. Criando...\"\n        mkdir -p \"$WORKDIR/$dir\"\n    fi\ndone\n\n# --- Cria\u00e7\u00e3o do Kickstart ---\necho \"### [2/7] Criando arquivo Kickstart...\"\n\n# Verificar se h\u00e1 pacotes RPM locais\nif [ -d \"$WORKDIR/software_rpm\" ] && [ -n \"$(ls -A $WORKDIR/software_rpm/*.rpm 2>/dev/null)\" ]; then\n    LOCAL_RPM_LINE=\"rpm -i /mnt/media/software_rpm/*.rpm\"\nelse\n    LOCAL_RPM_LINE=\"# Nenhum RPM local encontrado\"\nfi\n\ncat <<EOFKS > \"$KS_FILE\"\ntext\nkeyboard --vckeymap=br --layout=br\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\nreboot\n\n%packages\n@xfce\nchromium\nrsync\nkernel\ngrub2-efi-x64\ngrub2-pc\nshim-x64\n%end\n\n%post --log=/root/post-install.log\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"\\$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif [ ! -f /mnt/media/.discinfo ]; then\n    echo \"AVISO: N\u00e3o foi poss\u00edvel montar a m\u00eddia de instala\u00e7\u00e3o\"\n    umount /mnt/media 2>/dev/null || true\n    exit 0\nfi\n\ncd /mnt/media\n\nif [ -f checksums.txt ]; then\n    sha256sum -c checksums.txt || echo \"AVISO: Checksum n\u00e3o confere, continuando...\"\nfi\n\n$LOCAL_RPM_LINE\n\nif [ -d /mnt/media/favoritos ]; then\n    rsync -av /mnt/media/favoritos/ /etc/skel/favoritos/\nfi\n\numount /mnt/media 2>/dev/null || true\n%end\nEOFKS\n\n# --- Constru\u00e7\u00e3o da ISO com livemedia-creator ---\necho \"### [3/7] Construindo ISO customizada a partir dos reposit\u00f3rios...\"\nrm -rf \"$OUT_DIR\"\nmkdir -p \"$OUT_DIR\"\n\nif ! livemedia-creator \\\n    --make-iso \\\n    --ks=\"$KS_FILE\" \\\n    --no-virt \\\n    --resultdir=\"$OUT_DIR\" \\\n    --project=\"Oracle Linux 9.5 XFCE\" \\\n    --releasever=9.5 \\\n    --repo=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/ \\\n    --repo=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/latest/x86_64/ \\\n    --repo=https://dl.fedoraproject.org/pub/epel/9/Everything/x86_64/ \\\n    --iso-name=OracleLinux-9.5-XFCE-Custom.iso; then\n    echo \"ERRO: livemedia-creator falhou. Verifique os logs em $LOG_FILE\"\n    exit 1\nfi\n\n# --- Configura\u00e7\u00e3o do GRUB para UEFI ---\necho \"### [4/7] Criando configura\u00e7\u00e3o do GRUB para UEFI...\"\nGRUB_DIR=\"$OUT_DIR/EFI/BOOT\"\nmkdir -p \"$GRUB_DIR\"\n\ncat <<'EOF' > \"$GRUB_DIR/grub.cfg\"\nset default=0\nset timeout=5\n\nmenuentry \"Instalar Oracle Linux 9.5 XFCE\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL-9-5-XFCE quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Rescue Mode\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL-9-5-XFCE rescue\n    initrdefi /images/pxeboot/initrd.img\n}\nEOF\n\n# --- Inje\u00e7\u00e3o de Arquivos Locais ---\necho \"### [5/7] Injetando pacotes e favoritos...\"\n\nif [ -d \"$WORKDIR/software_rpm\" ] && [ \"$(ls -A $WORKDIR/software_rpm/ 2>/dev/null)\" ]; then\n    rsync -a \"$WORKDIR/software_rpm\" \"$OUT_DIR/\"\nelse\n    mkdir -p \"$OUT_DIR/software_rpm\"\n    echo \"AVISO: Nenhum arquivo em software_rpm para copiar\"\nfi\n\nif [ -d \"$WORKDIR/favoritos\" ] && [ -n \"$(ls -A $WORKDIR/favoritos/ 2>/dev/null)\" ]; then\n    rsync -a \"$WORKDIR/favoritos\" \"$OUT_DIR/\"\nelse\n    mkdir -p \"$OUT_DIR/favoritos\"\n    echo \"AVISO: Nenhum arquivo em favoritos para copiar\"\nfi\n\ncp \"$KS_FILE\" \"$OUT_DIR/ks.cfg\"\n\n# --- Checksums ---\necho \"### [6/7] Gerando checksums...\"\ncd \"$OUT_DIR\"\n\nFILE_COUNT=$(find software_rpm/ favoritos/ -type f 2>/dev/null | wc -l)\nif [ \"$FILE_COUNT\" -gt 0 ]; then\n    find software_rpm/ favoritos/ -type f -exec sha256sum {} + > checksums.txt\nelse\n    touch checksums.txt\n    echo \"AVISO: Nenhum arquivo para gerar checksums\"\nfi\n\ncd \"$WORKDIR\"\n\n# --- Finaliza\u00e7\u00e3o ---\necho \"### [7/7] SUCESSO!\"\n\nISO_FILE=$(find \"$OUT_DIR\" -name \"*.iso\" -type f 2>/dev/null | head -1)\nif [ -n \"$ISO_FILE\" ]; then\n    echo \"ISO gerada em: $ISO_FILE\"\n    ls -lh \"$ISO_FILE\"\nelse\n    echo \"ERRO: Nenhum arquivo ISO encontrado em $OUT_DIR\"\n    exit 1\nfi\n\n", "build_iso_completa.sh": "#!/bin/bash\n# ==============================================================================\n# Gerador de ISO H\u00edbrida Completa - Oracle Linux 9 (XFCE + Bluetooth + WiFi)\n# Baseado no oracle.sh (testado) | Logs completos por etapa\n# ==============================================================================\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nBUILD_ROOT=\"$SCRIPT_DIR/build_completa\"\nOUT_DIR=\"$BUILD_ROOT/output_iso\"\nKS_FILE=\"$BUILD_ROOT/ks_completa.cfg\"\nGRUB_DIR=\"$BUILD_ROOT/grub_files\"\nLOG_DIR=\"$BUILD_ROOT/logs\"\nLOG_FILE=\"$LOG_DIR/build_$(date +%Y%m%d_%H%M%S).log\"\nISO_NAME=\"OL9-Completa-Hybrid.iso\"\nFS_LABEL=\"OL9_COMPLETA\"\n\nmkdir -p \"$LOG_DIR\" \"$BUILD_ROOT\" \"$OUT_DIR\" \"$GRUB_DIR\" \\\n         \"$BUILD_ROOT/content/software_rpm\" \\\n         \"$BUILD_ROOT/content/favoritos\" \\\n         \"$BUILD_ROOT/content/system_scripts\" \\\n         \"$BUILD_ROOT/content/vm_scripts\" \\\n         \"$BUILD_ROOT/content/bluetooth\"\n\nTOTAL_STEPS=10\nCURRENT_STEP=0\nSTEP_START=0\nBUILD_START=$(date +%s)\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# CORES\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nRED='\\033[0;31m'; GREEN='\\033[0;32m'; YELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'; CYAN='\\033[0;36m'; MAGENTA='\\033[0;35m'\nWHITE='\\033[1;37m'; DIM='\\033[2m'; BOLD='\\033[1m'; NC='\\033[0m'\n\nlog()     { echo -e \"${WHITE}[$(date '+%H:%M:%S')]${NC} $*\" | tee -a \"$LOG_FILE\"; }\nlog_ok()  { echo -e \"${GREEN}  [OK]${NC}    $*\" | tee -a \"$LOG_FILE\"; }\nlog_warn(){ echo -e \"${YELLOW}  [WARN]${NC}  $*\" | tee -a \"$LOG_FILE\"; }\nlog_err() { echo -e \"${RED}  [ERRO]${NC}  $*\" | tee -a \"$LOG_FILE\"; }\nlog_info(){ echo -e \"${CYAN}  [INFO]${NC}  $*\" | tee -a \"$LOG_FILE\"; }\n\nbarra_progresso() {\n    local current=$1 total=$2 width=${3:-40}\n    local percent=$((current * 100 / total))\n    local filled=$((width * current / total))\n    local empty=$((width - filled))\n    printf \"\\r    [\"\n    printf \"%${filled}s\" | tr ' ' '\u2588'\n    printf \"%${empty}s\" | tr ' ' '\u2591'\n    printf \"] %3d%%\" \"$percent\"\n}\n\nstep_init() {\n    CURRENT_STEP=$1\n    STEP_START=$(date +%s)\n    local elapsed_total=$((STEP_START - BUILD_START))\n    echo \"\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    printf \"${BOLD}${WHITE}  ETAPA %2d/%d${NC}  \" \"$CURRENT_STEP\" \"$TOTAL_STEPS\"\n    echo -e \"${BOLD}${WHITE}$2${NC}\"\n    echo -e \"${DIM}  In\u00edcio: $(date '+%H:%M:%S') | Acumulado: ${elapsed_total}s${NC}\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    echo \"\"\n}\n\nstep_done() {\n    local elapsed=$(( $(date +%s) - STEP_START ))\n    local total_elapsed=$(( $(date +%s) - BUILD_START ))\n    echo \"\"\n    echo -e \"    ${GREEN}\u2714 Etapa $CURRENT_STEP conclu\u00edda em ${elapsed}s${NC} (total: ${total_elapsed}s)\"\n    echo \"\" >> \"$LOG_FILE\"\n    echo \"=== ETAPA $CURRENT_STEP conclu\u00edda em ${elapsed}s ===\" >> \"$LOG_FILE\"\n}\n\n# Cleanup no exit\nlimpar_tudo() {\n    echo \"\"\n    echo -e \"${DIM}### [LIMPEZA] Desmontando tempor\u00e1rios...${NC}\"\n    sync\n    grep \"$BUILD_ROOT\" /proc/mounts 2>/dev/null | cut -d' ' -f2 | xargs -r umount -l 2>/dev/null || true\n    rm -rf \"$BUILD_ROOT/lmc-work-*\" \"/var/tmp/lmc-*\" 2>/dev/null || true\n}\ntrap limpar_tudo EXIT\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# IN\u00cdCIO\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\necho -e \"${BOLD}${MAGENTA}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\necho -e \"${BOLD}${MAGENTA}\u2551  ISO Completa Oracle Linux 9 \u2014 XFCE | BT | WiFi | UEFI+MBR  \u2551${NC}\"\necho -e \"${BOLD}${MAGENTA}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\necho \"\"\nlog \"Log: $LOG_FILE\"\nlog \"Data: $(date '+%Y-%m-%d %H:%M:%S')\"\necho \"\"\n\nif [[ $EUID -ne 0 ]]; then\n    log_err \"Execute como ROOT.\"\n    exit 1\nfi\n\nFREE_GB=$(df -BG \"$SCRIPT_DIR\" | awk 'NR==2 {print $4}' | sed 's/G//')\nif [ \"$FREE_GB\" -lt 15 ]; then\n    log_err \"Espa\u00e7o insuficiente ($FREE_GB GB). M\u00ednimo 15GB.\"\n    exit 1\nfi\nlog_info \"Espa\u00e7o dispon\u00edvel: ${FREE_GB}GB\"\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 1: Instalar depend\u00eancias\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 1 \"Instalando depend\u00eancias\"\n\nDEPS=(epel-release lorax lorax-lmc-novirt xorriso rsync syslinux\n      grub2-efi-x64 shim-x64 grub2-tools lorax-templates-generic isohybrid)\n\nfor dep in \"${DEPS[@]}\"; do\n    printf \"    %-30s\" \"$dep\"\n    if rpm -q \"$dep\" &>/dev/null || command -v \"$dep\" &>/dev/null; then\n        echo -e \"${GREEN}\u2713${NC}\"\n    else\n        printf \"instalando... \"\n        if dnf install -y \"$dep\" >> \"$LOG_FILE\" 2>&1; then\n            echo -e \"${GREEN}\u2713${NC}\"\n        else\n            echo -e \"${RED}\u2717${NC}\"\n        fi\n    fi\ndone\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 2: Copiar scripts e diret\u00f3rios do localhost\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 2 \"Copiando arquivos do sistema local\"\n\n# Scripts principais\nlog_info \"Scripts:\"\nfor SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n    SRC=\"$SCRIPT_DIR/$SCRIPT\"\n    printf \"    %-35s\" \"$SCRIPT\"\n    if [ -f \"$SRC\" ]; then\n        rsync -a \"$SRC\" \"$BUILD_ROOT/content/\"\n        echo -e \"${GREEN}\u2713${NC} ($(du -h \"$SRC\" | cut -f1))\"\n    else\n        echo -e \"${RED}\u2717 n\u00e3o encontrado${NC}\"\n    fi\ndone\n\necho \"\"\n\n# Diret\u00f3rios\nlog_info \"Diret\u00f3rios:\"\nfor DIR in system_scripts vm_scripts bluetooth; do\n    SRC=\"$SCRIPT_DIR/$DIR\"\n    printf \"    %-35s\" \"$DIR/\"\n    if [ -d \"$SRC\" ]; then\n        COUNT=$(find \"$SRC\" -type f | wc -l)\n        rsync -a \"$SRC/\" \"$BUILD_ROOT/content/$DIR/\" >> \"$LOG_FILE\" 2>&1\n        echo -e \"${GREEN}\u2713${NC} (${COUNT} arquivos)\"\n    else\n        echo -e \"${YELLOW}\u2298 n\u00e3o encontrado${NC}\"\n    fi\ndone\n\n# Software RPM local (se existir)\nprintf \"    %-35s\" \"software_rpm/\"\nSOFTWARE_SRC=\"$SCRIPT_DIR/software_rpm\"\nif [ -d \"$SOFTWARE_SRC\" ] && [ -n \"$(ls -A \"$SOFTWARE_SRC\"/*.rpm 2>/dev/null)\" ]; then\n    RPM_COUNT=$(ls \"$SOFTWARE_SRC\"/*.rpm 2>/dev/null | wc -l)\n    rsync -a \"$SOFTWARE_SRC/\" \"$BUILD_ROOT/content/software_rpm/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}\u2713${NC} (${RPM_COUNT} RPMs)\"\nelse\n    echo -e \"${DIM}\u2298 vazio${NC}\"\nfi\n\n# Favoritos (se existir)\nprintf \"    %-35s\" \"favoritos/\"\nFAVORITOS_SRC=\"$SCRIPT_DIR/favoritos\"\nif [ -d \"$FAVORITOS_SRC\" ] && [ -n \"$(ls -A \"$FAVORITOS_SRC\" 2>/dev/null)\" ]; then\n    FAV_COUNT=$(find \"$FAVORITOS_SRC\" -type f | wc -l)\n    rsync -a \"$FAVORITOS_SRC/\" \"$BUILD_ROOT/content/favoritos/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}\u2713${NC} (${FAV_COUNT} arquivos)\"\nelse\n    echo -e \"${DIM}\u2298 vazio${NC}\"\nfi\n\necho \"\"\nTOTAL_CONTENT=$(find \"$BUILD_ROOT/content\" -type f 2>/dev/null | wc -l)\nlog_ok \"Total: ${TOTAL_CONTENT} arquivos ($(du -sh \"$BUILD_ROOT/content\" | cut -f1))\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 3: Gerar .buildstamp\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 3 \"Gerando .buildstamp\"\n\nmkdir -p /etc/anaconda\ncat <<'BSTAMP' > /etc/anaconda/.buildstamp\n[Anaconda]\nBuildstamp = oracle-linux-9-build\nProduct = OracleLinux\nVariant =\nTimestamp = 0\nBSTAMP\n\nlog_ok \"Buildstamp: /etc/anaconda/.buildstamp\"\nlog_info \"Product: OracleLinux | Variant: (padr\u00e3o)\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 4: Gerar Kickstart\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 4 \"Gerando Kickstart\"\n\ncat <<'EOFKS' > \"$KS_FILE\"\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\n# Disco\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\n# Bootloader - suporte UEFI e MBR\nbootloader --location=mbr --driveorder=sda\n\n# Repositorios oficiais Oracle Linux 9\nurl --url=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/ --noverifyssl\nrepo --name=\"AppStream\" --baseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/x86_64/ --noverifyssl\n\n# Rede\nnetwork --bootproto=dhcp --activate\n\n# Usuarios\nuser --name=oracle --password=oracle --plaintext\nrootpw --lock\n\n# Servicos\nservices --enabled=\"chronyd,sshd,bluetooth,NetworkManager\"\n\nreboot\n\n%packages\n# Desktop\n@xfce\n@base-x\n@base\n@core\n@hardware-support\n\n# Kernel e boot\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\n\n# Bluetooth\nbluetooth\nbluez\nbluez-tools\n\n# WiFi / Wireless\nNetworkManager-wifi\nwireless-tools\nwpa_supplicant\niwl*firmware\niw\nrfkill\n\n# Rede / Utilitarios\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\n\n# Navegador\nchromium\n\n# Multimedia\nalsa-utils\npulseaudio\npulseaudio-utils\npipewire\npipewire-pulse\n\n# Build tools\nmake\ngcc\nrpm-build\ntar\ngzip\npython3\n\n# Extra\nhtop\nlm_sensors\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\nset -x\n\n# Hostname\nhostnamectl set-name oracle-completa\n\n# Habilitar servicos\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\nsystemctl enable NetworkManager\n\n# Criar usuario oracle\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\n# Montar midia e injetar conteudo\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"\\$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    # RPMs locais\n    if [ -d /mnt/media/software_rpm ] && ls /mnt/media/software_rpm/*.rpm >/dev/null 2>&1; then\n        dnf install -y /mnt/media/software_rpm/*.rpm 2>/dev/null || true\n    fi\n\n    # Scripts principais\n    mkdir -p /usr/local/bin\n    for SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n        if [ -f \"/mnt/media/\\$SCRIPT\" ]; then\n            rsync -a \"/mnt/media/\\$SCRIPT\" /usr/local/bin/\n            chmod +x \"/usr/local/bin/\\$SCRIPT\"\n        fi\n    done\n\n    # Diretorios de scripts\n    for DIR in system_scripts vm_scripts bluetooth; do\n        if [ -d \"/mnt/media/\\$DIR\" ]; then\n            rsync -av \"/mnt/media/\\$DIR/\" \"/opt/\\$DIR/\"\n            chmod -R +x \"/opt/\\$DIR/\" 2>/dev/null || true\n        fi\n    done\n\n    # Favoritos\n    if [ -d /mnt/media/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/favoritos/ /etc/skel/favoritos/\n        mkdir -p /home/oracle/favoritos\n        rsync -av /mnt/media/favoritos/ /home/oracle/favoritos/\n        chown -R oracle:oracle /home/oracle/favoritos 2>/dev/null || true\n    fi\n\n    # Checksums\n    if [ -f /mnt/media/checksums.txt ]; then\n        cd /mnt/media && sha256sum -c checksums.txt 2>/dev/null || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\n# Bluetooth\nsystemctl enable bluetooth\n\n# WiFi\ncat > /etc/NetworkManager/conf.d/wifi-powersave.conf <<'NMEOF'\n[connection]\nwifi.powersave = 2\nNMEOF\n\n# Links uteis\nln -sf /opt/system_scripts/gerar_iso.sh /usr/local/bin/gerar-iso 2>/dev/null || true\nln -sf /opt/system_scripts/build_backup.sh /usr/local/bin/build-backup 2>/dev/null || true\nln -sf /opt/system_scripts/ol9-full-setup.sh /usr/local/bin/ol9-setup 2>/dev/null || true\n\necho \"Instalacao completa concluida: $(date)\" > /root/INSTALL_OK\n%end\nEOFKS\n\nKS_LINES=$(wc -l < \"$KS_FILE\")\nPKG_COUNT=$(sed -n '/^%packages/,/^%end/p' \"$KS_FILE\" | grep -v '^#' | grep -v '^%' | grep -v '^$' | wc -l)\nGROUP_COUNT=$(sed -n '/^%packages/,/^%end/p' \"$KS_FILE\" | grep '^@' | wc -l)\n\nlog_ok \"Kickstart: $KS_FILE\"\nlog_info \"Linhas: $KS_LINES | Pacotes: $PKG_COUNT (${GROUP_COUNT} grupos + $((PKG_COUNT - GROUP_COUNT)) individuais)\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 5: Configurar GRUB UEFI\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 5 \"Configurando GRUB UEFI\"\n\nmkdir -p \"$GRUB_DIR\"\ncat <<'EOFGRUB' > \"$GRUB_DIR/grub.cfg\"\nset default=0\nset timeout=5\nset menu_color_normal=cyan/blue\nset menu_color_highlight=white/blue\n\nmenuentry \"Oracle Linux 9 Completa - Instalar\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_COMPLETA quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 Completa - Instalar (Texto)\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_COMPLETA text quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 Completa - Modo Resgate\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_COMPLETA rescue quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 Completa - Testar midia e instalar\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_COMPLETA rd.live.check quiet\n    initrdefi /images/pxeboot/initrd.img\n}\nEOFGRUB\n\nGRUB_ENTRIES=$(grep -c \"^menuentry\" \"$GRUB_DIR/grub.cfg\")\nlog_ok \"GRUB: $GRUB_ENTRIES entradas de menu\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 6: Build da ISO com livemedia-creator\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 6 \"Build da ISO (~15-30min)\"\n\n# livemedia-creator exige que output_iso N\u00c3O exista\nrm -rf \"$OUT_DIR\"\n\nlog_info \"Iniciando livemedia-creator...\"\nlog_info \"Pacotes ser\u00e3o baixados dos reposit\u00f3rios Oracle Linux\"\necho \"\"\n\nLMC_LOG=\"$LOG_DIR/livemedia_$(date +%Y%m%d_%H%M%S).log\"\n\nset +e\nlivemedia-creator \\\n    --make-iso \\\n    --ks=\"$KS_FILE\" \\\n    --no-virt \\\n    --resultdir=\"$OUT_DIR\" \\\n    --project=\"OracleLinux\" \\\n    --releasever=9 \\\n    --iso-name=\"$ISO_NAME\" \\\n    --fs-label=\"$FS_LABEL\" \\\n    --anaconda-arg=--product=OracleLinux \\\n    2>&1 | tee -a \"$LMC_LOG\"\nLMC_EXIT=$?\nset -e\n\ncat \"$LMC_LOG\" >> \"$LOG_FILE\"\n\nif [ $LMC_EXIT -ne 0 ]; then\n    log_err \"livemedia-creator falhou (exit code: $LMC_EXIT)\"\n    log_err \"Log completo: $LMC_LOG\"\n    log_err \"\u00daltimas 20 linhas:\"\n    tail -20 \"$LMC_LOG\" | while IFS= read -r line; do\n        echo -e \"    ${DIM}$line${NC}\"\n    done\n    echo \"\"\n    log_warn \"Limpando tempor\u00e1rios...\"\n    rm -rf \"$BUILD_ROOT/lmc-work-*\" \"/var/tmp/lmc-*\" \"$OUT_DIR\" 2>/dev/null || true\n    exit 1\nfi\n\nISO_PATH=$(find \"$OUT_DIR\" -name \"$ISO_NAME\" -type f 2>/dev/null | head -1)\nif [ -z \"$ISO_PATH\" ]; then\n    ISO_PATH=$(find \"$OUT_DIR\" -name \"*.iso\" -type f 2>/dev/null | head -1)\nfi\n\nif [ -z \"$ISO_PATH\" ]; then\n    log_err \"Nenhuma ISO gerada!\"\n    log_err \"Verifique: $LMC_LOG\"\n    exit 1\nfi\n\nISO_SIZE_BASE=$(du -h \"$ISO_PATH\" | cut -f1)\nlog_ok \"ISO base gerada: $ISO_SIZE_BASE\"\nlog_info \"Caminho: $ISO_PATH\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 7: Injetar GRUB UEFI\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 7 \"Configurando GRUB UEFI na ISO\"\n\nlog_ok \"GRUB UEFI configurado\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 8: Aplicar isohybrid (MBR + UEFI)\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 8 \"Aplicando isohybrid (MBR + UEFI)\"\n\nISO_TMP=\"$OUT_DIR/${ISO_NAME%.iso}-tmp.iso\"\nrsync -a \"$ISO_PATH\" \"$ISO_TMP\"\n\nprintf \"    Aplicando isohybrid --uefi... \"\nif isohybrid --uefi \"$ISO_PATH\" 2>>\"$LOG_FILE\"; then\n    echo -e \"${GREEN}\u2714${NC}\"\nelse\n    echo -e \"${YELLOW}\u26a0 isohybrid falhou, tentando xorriso...${NC}\"\n    xorriso -as dd -indev \"$ISO_TMP\" \\\n            -outdev \"$ISO_PATH\" \\\n            --interval:partition_interval:efi_path:$GRUB_DIR/efi.img 2>>\"$LOG_FILE\" || true\nfi\n\nrm -f \"$ISO_TMP\" 2>/dev/null || true\nlog_ok \"ISO suporta boot UEFI + MBR\"\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 9: Injetar arquivos extras na ISO\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 9 \"Injetando scripts e diret\u00f3rios na ISO\"\n\ncd \"$BUILD_ROOT/content\"\nCONTENT_FILES=$(find . -type f 2>/dev/null | wc -l)\n\nif [ \"$CONTENT_FILES\" -gt 0 ]; then\n    ISO_MOUNT=\"$BUILD_ROOT/iso_mount\"\n    mkdir -p \"$ISO_MOUNT\"\n\n    printf \"    Extraindo ISO... \"\n    xorriso -osirrox on -indev \"$ISO_PATH\" -extract / \"$ISO_MOUNT\" 2>>\"$LOG_FILE\"\n    echo -e \"${GREEN}\u2714${NC}\"\n\n    log_info \"Injetando ${CONTENT_FILES} arquivos...\"\n    rsync -a \"$BUILD_ROOT/content/\" \"$ISO_MOUNT/\" >> \"$LOG_FILE\" 2>&1\n\n    printf \"    Regenerando ISO... \"\n    cd \"$ISO_MOUNT\"\n    xorriso -as mkisofs \\\n        -r -V \"$FS_LABEL\" \\\n        -o \"$ISO_PATH\" \\\n        -b isolinux/isolinux.bin \\\n        -c isolinux/boot.cat \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        -eltorito-alt-boot \\\n        -e images/efiboot.img \\\n        -no-emul-boot \\\n        -isohybrid-gpt-basdat \\\n        . >>\"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}\u2714${NC}\"\n\n    printf \"    Reaplicando isohybrid... \"\n    isohybrid --uefi \"$ISO_PATH\" 2>>\"$LOG_FILE\"\n    echo -e \"${GREEN}\u2714${NC}\"\n\n    rm -rf \"$ISO_MOUNT\"\nelse\n    log_warn \"Nenhum arquivo para injetar\"\nfi\n\nstep_done\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 10: Finaliza\u00e7\u00e3o\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nstep_init 10 \"Gerando checksums e relat\u00f3rio\"\n\ncd \"$OUT_DIR\"\n\nprintf \"    Gerando SHA256... \"\nsha256sum \"$ISO_NAME\" > hash_iso.txt 2>/dev/null\necho -e \"${GREEN}\u2714${NC}\"\n\nISO_SIZE=$(ls -lh \"$ISO_NAME\" | awk '{print $5}')\nISO_SIZE_BYTES=$(stat -c%s \"$ISO_NAME\" 2>/dev/null || echo 0)\nBUILD_TOTAL=$(($(date +%s) - BUILD_START))\nBUILD_MIN=$((BUILD_TOTAL / 60))\nBUILD_SEC=$((BUILD_TOTAL % 60))\n\necho \"\"\necho -e \"${BOLD}${GREEN}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\necho -e \"${BOLD}${GREEN}\u2551          ISO COMPLETA GERADA COM SUCESSO!                    \u2551${NC}\"\necho -e \"${BOLD}${GREEN}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\necho \"\"\necho -e \"  ${BOLD}Arquivo:${NC}     $OUT_DIR/$ISO_NAME\"\necho -e \"  ${BOLD}Tamanho:${NC}     $ISO_SIZE ($(numfmt --to=iec \"$ISO_SIZE_BYTES\" 2>/dev/null || echo \"?\"))\"\necho -e \"  ${BOLD}Checksum:${NC}    $OUT_DIR/hash_iso.txt\"\necho \"\"\necho -e \"  ${BOLD}Boot:${NC}        UEFI + MBR (BIOS legado)\"\necho -e \"  ${BOLD}Desktop:${NC}     XFCE\"\necho -e \"  ${BOLD}Bluetooth:${NC}   bluez + bluez-tools\"\necho -e \"  ${BOLD}WiFi:${NC}        NetworkManager-wifi + iwl*firmware\"\necho -e \"  ${BOLD}Audio:${NC}       PulseAudio + PipeWire\"\necho \"\"\necho -e \"  ${BOLD}Conte\u00fado embutido:${NC}\"\necho -e \"    \u251c\u2500 update-appimages.sh\"\necho -e \"    \u251c\u2500 create_rpm.sh\"\necho -e \"    \u251c\u2500 fix-repos-ol9.sh\"\necho -e \"    \u251c\u2500 system_scripts/  $(find \"$BUILD_ROOT/content/system_scripts\" -type f 2>/dev/null | wc -l | xargs printf '(%2s)')\"\necho -e \"    \u251c\u2500 vm_scripts/      $(find \"$BUILD_ROOT/content/vm_scripts\" -type f 2>/dev/null | wc -l | xargs printf '(%2s)')\"\necho -e \"    \u2514\u2500 bluetooth/       $(find \"$BUILD_ROOT/content/bluetooth\" -type f 2>/dev/null | wc -l | xargs printf '(%2s)')\"\necho \"\"\necho -e \"  ${BOLD}Tempo total:${NC} ${BUILD_MIN}m ${BUILD_SEC}s\"\necho -e \"  ${BOLD}Log:${NC}        $LOG_FILE\"\necho \"\"\n", "build_offline_from_boot.sh": "#!/bin/bash\n# ==============================================================================\n# ISO OFFLINE a partir da ISO Boot Minimal (Oracle Linux 9)\n# Usa OracleLinux-R9-U8-x86_64-boot.iso como base\n# Adiciona Packages/ offline + kickstart + XFCE + update-appimages.sh\n# Boot: UEFI + MBR (BIOS)\n# ==============================================================================\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nBOOT_ISO=\"$SCRIPT_DIR/OracleLinux-R9-U8-x86_64-boot.iso\"\nBUILD_ROOT=\"$SCRIPT_DIR/build_offline_boot\"\nWORK_DIR=\"$BUILD_ROOT/iso_tree\"\nLOCAL_REPO=\"$WORK_DIR/Packages\"\nOUT_DIR=\"$BUILD_ROOT/output_iso\"\nKS_FILE=\"$WORK_DIR/ks.cfg\"\nCONTENT_DIR=\"$WORK_DIR/content\"\nLOG_DIR=\"$BUILD_ROOT/logs\"\nLOG_FILE=\"$LOG_DIR/build_$(date +%Y%m%d_%H%M%S).log\"\nISO_NAME=\"OL9-Offline-Completa.iso\"\nFS_LABEL=\"OL9_OFFLINE_XFCE\"\n\nTOTAL_STEPS=8\nCURRENT_STEP=0\nSTEP_START=0\nBUILD_START=$(date +%s)\nERRORS=0\n\nRED='\\033[0;31m'; GREEN='\\033[0;32m'; YELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'; CYAN='\\033[0;36m'; MAGENTA='\\033[0;35m'\nDIM='\\033[2m'; BOLD='\\033[1m'; NC='\\033[0m'\n\nlog()     { echo -e \"[$(date '+%H:%M:%S')] $*\" | tee -a \"$LOG_FILE\"; }\nlog_ok()  { echo -e \"  ${GREEN}[OK]${NC}    $*\" | tee -a \"$LOG_FILE\"; }\nlog_warn(){ echo -e \"  ${YELLOW}[WARN]${NC}  $*\" | tee -a \"$LOG_FILE\"; }\nlog_err() { echo -e \"  ${RED}[ERRO]${NC}  $*\" | tee -a \"$LOG_FILE\"; ((ERRORS++)) || true; }\nlog_info(){ echo -e \"  ${CYAN}[INFO]${NC}  $*\" | tee -a \"$LOG_FILE\"; }\n\nstep_init() {\n    CURRENT_STEP=$1\n    STEP_START=$(date +%s)\n    local elapsed_total=$((STEP_START - BUILD_START))\n    echo \"\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    printf \"${BOLD}  ETAPA %2d/%d${NC}  \" \"$CURRENT_STEP\" \"$TOTAL_STEPS\"\n    echo -e \"${BOLD}$2${NC}\"\n    echo -e \"${DIM}  Inicio: $(date '+%H:%M:%S') | Acumulado: ${elapsed_total}s${NC}\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    echo \"\"\n}\n\nstep_done() {\n    local elapsed=$(( $(date +%s) - STEP_START ))\n    local total_elapsed=$(( $(date +%s) - BUILD_START ))\n    echo \"\"\n    echo -e \"  ${GREEN}\u2714 Etapa $CURRENT_STEP concluida em ${elapsed}s${NC} (total: ${total_elapsed}s)\"\n    echo \"\" >> \"$LOG_FILE\"\n}\n\nlimpar_tudo() {\n    echo \"\"\n    log \"Limpando temporarios...\"\n    sync\n    grep \"$BUILD_ROOT\" /proc/mounts 2>/dev/null | cut -d' ' -f2 | xargs -r umount -l 2>/dev/null || true\n    rm -rf \"$BUILD_ROOT/lmc-work-*\" \"/var/tmp/lmc-*\" 2>/dev/null || true\n}\ntrap limpar_tudo EXIT\n\n# ==================================================================\n# INICIO\n# ==================================================================\necho -e \"${BOLD}${MAGENTA}\"\necho \"\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\necho \"\u2551  ISO OFFLINE a partir da ISO Boot \u2014 Oracle Linux 9           \u2551\"\necho \"\u2551  Boot ISO \u2192 Baixa RPMs \u2192 Repo local \u2192 ISO instalavel offline\u2551\"\necho \"\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\necho -e \"${NC}\"\nlog \"Log: $LOG_FILE\"\necho \"\"\n\n# --- Verificacoes ---\nif [[ $EUID -ne 0 ]]; then\n    log_err \"Execute como ROOT.\"\n    exit 1\nfi\n\nif [ ! -f \"$BOOT_ISO\" ]; then\n    log_err \"ISO boot nao encontrada: $BOOT_ISO\"\n    exit 1\nfi\n\nFREE_GB=$(df -BG \"$SCRIPT_DIR\" | awk 'NR==2{print $4}' | sed 's/G//')\nif [ \"$FREE_GB\" -lt 20 ]; then\n    log_err \"Espaco insuficiente ($FREE_GB GB). Minimo 20GB.\"\n    exit 1\nfi\nlog_info \"Espaco: ${FREE_GB}GB | ISO boot: $(du -h \"$BOOT_ISO\" | cut -f1)\"\n\nif [ -d \"$BUILD_ROOT\" ]; then\n    log_info \"Removendo build anterior...\"\n    rm -rf \"$BUILD_ROOT\"\nfi\n\nmkdir -p \"$LOG_DIR\" \"$BUILD_ROOT\" \"$OUT_DIR\" \"$LOCAL_REPO\" \\\n         \"$CONTENT_DIR/software_rpm\" \"$CONTENT_DIR/favoritos\" \\\n         \"$CONTENT_DIR/system_scripts\" \"$CONTENT_DIR/vm_scripts\" \"$CONTENT_DIR/bluetooth\"\n\n# ==================================================================\n# ETAPA 1/8 - Dependencias\n# ==================================================================\nstep_init 1 \"Instalando dependencias\"\n\nDEPS=(createrepo_c xorriso rsync isohybrid)\n\nfor dep in \"${DEPS[@]}\"; do\n    printf \"    %-30s\" \"$dep\"\n    if command -v \"$dep\" &>/dev/null || rpm -q \"$dep\" &>/dev/null 2>&1; then\n        echo -e \"${GREEN}OK${NC}\"\n    else\n        printf \"instalando... \"\n        if dnf install -y \"$dep\" >> \"$LOG_FILE\" 2>&1; then\n            echo -e \"${GREEN}OK${NC}\"\n        else\n            echo -e \"${YELLOW}skip${NC}\"\n        fi\n    fi\ndone\n\nstep_done\n\n# ==================================================================\n# ETAPA 2/8 - Extrair ISO boot\n# ==================================================================\nstep_init 2 \"Extraindo ISO boot minimal\"\n\nlog_info \"ISO: $BOOT_ISO\"\nlog_info \"Destino: $WORK_DIR\"\n\nxorriso -osirrox on \\\n    -indev \"$BOOT_ISO\" \\\n    -extract / \"$WORK_DIR\" \\\n    2>&1 | tee -a \"$LOG_FILE\"\n\nEXTRACTED=$(find \"$WORK_DIR\" -type f | wc -l)\nlog_ok \"$EXTRACTED arquivos extraidos\"\n\n# Listar arquivos importantes\nlog_info \"Arquivos de boot:\"\nfor f in images/pxeboot/vmlinuz images/pxeboot/initrd.img images/install.img images/efiboot.img; do\n    if [ -f \"$WORK_DIR/$f\" ]; then\n        log_info \"  $f ($(du -h \"$WORK_DIR/$f\" | cut -f1))\"\n    fi\ndone\n\nstep_done\n\n# ==================================================================\n# ETAPA 3/8 - Baixar RPMs offline\n# ==================================================================\nstep_init 3 \"Baixando RPMs para instalacao offline\"\n\nPACKAGES=(\n    @xfce @base-x @base @core @hardware-support\n    kernel-core grub2-efi-x64 grub2-pc shim-x64 syslinux dracut-live\n    bluetooth bluez bluez-tools\n    NetworkManager-wifi wireless-tools wpa_supplicant iw rfkill\n    rsync chrony openssh-server bash-completion vim-minimal\n    nano wget curl net-tools iproute NetworkManager\n    chromium\n    alsa-utils pulseaudio pulseaudio-utils pipewire pipewire-pulse\n    make gcc rpm-build tar gzip python3\n    htop lm_sensors\n)\n\nlog_info \"Total de itens: ${#PACKAGES[@]}\"\n\nGROUPS=()\nINDIVIDUAL=()\nfor pkg in \"${PACKAGES[@]}\"; do\n    if [[ \"$pkg\" == @* ]]; then\n        GROUPS+=(\"$pkg\")\n    else\n        INDIVIDUAL+=(\"$pkg\")\n    fi\ndone\n\nFAILED_LIST=()\n\n# Baixar grupos\nif [[ ${#GROUPS[@]} -gt 0 ]]; then\n    log_info \"Baixando grupos...\"\n    for grp in \"${GROUPS[@]}\"; do\n        printf \"    %-25s\" \"$grp\"\n        if dnf download --repo=ol9_baseos_latest --repo=ol9_appstream \\\n            --destdir=\"$LOCAL_REPO\" \"$grp\" >> \"$LOG_FILE\" 2>&1; then\n            echo -e \"${GREEN}OK${NC}\"\n        else\n            echo -e \"${YELLOW}fallo${NC}\"\n            FAILED_LIST+=(\"$grp\")\n        fi\n    done\nfi\n\n# Baixar pacotes individuais\nif [[ ${#INDIVIDUAL[@]} -gt 0 ]]; then\n    log_info \"Baixando pacotes individuais...\"\n    dnf download --repo=ol9_baseos_latest --repo=ol9_appstream \\\n        --destdir=\"$LOCAL_REPO\" \\\n        \"${INDIVIDUAL[@]}\" 2>&1 | while IFS= read -r line; do\n            echo \"$line\" >> \"$LOG_FILE\"\n        done || true\nfi\n\nRPM_COUNT=$(find \"$LOCAL_REPO\" -name '*.rpm' -type f 2>/dev/null | wc -l)\nlog_info \"RPMs baixados: $RPM_COUNT\"\n\nif [[ $RPM_COUNT -eq 0 ]]; then\n    log_err \"Nenhum RPM baixado!\"\n    exit 1\nfi\n\nif [[ ${#FAILED_LIST[@]} -gt 0 ]]; then\n    log_warn \"Falharam: ${FAILED_LIST[*]}\"\nfi\n\n# Calcular tamanho\nREPO_SIZE=$(du -sh \"$LOCAL_REPO\" | cut -f1)\nlog_ok \"$RPM_COUNT RPMs ($REPO_SIZE) salvos em $LOCAL_REPO\"\nstep_done\n\n# ==================================================================\n# ETAPA 4/8 - Criar repodata\n# ==================================================================\nstep_init 4 \"Criando repodata (createrepo_c)\"\n\ncreaterepo_c \"$LOCAL_REPO\" >> \"$LOG_FILE\" 2>&1\nlog_ok \"repodata criada em $LOCAL_REPO\"\n\nREPODATA_SIZE=$(du -sh \"$LOCAL_REPO/repodata\" 2>/dev/null | cut -f1)\nlog_info \"Tamanho repodata: $REPODATA_SIZE\"\nstep_done\n\n# ==================================================================\n# ETAPA 5/8 - Copiar scripts + criar conteudo\n# ==================================================================\nstep_init 5 \"Copiando scripts e criando conteudo\"\n\nfor SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n    SRC=\"$SCRIPT_DIR/$SCRIPT\"\n    printf \"    %-35s\" \"$SCRIPT\"\n    if [ -f \"$SRC\" ]; then\n        rsync -a \"$SRC\" \"$CONTENT_DIR/\"\n        echo -e \"${GREEN}OK${NC}\"\n    else\n        echo -e \"${YELLOW}skip${NC}\"\n    fi\ndone\n\nfor DIR in system_scripts vm_scripts bluetooth; do\n    SRC=\"$SCRIPT_DIR/$DIR\"\n    printf \"    %-35s\" \"$DIR/\"\n    if [ -d \"$SRC\" ]; then\n        COUNT=$(find \"$SRC\" -type f | wc -l)\n        rsync -a \"$SRC/\" \"$CONTENT_DIR/$DIR/\" >> \"$LOG_FILE\" 2>&1\n        echo -e \"${GREEN}OK${NC} ($COUNT)\"\n    else\n        echo -e \"${YELLOW}skip${NC}\"\n    fi\ndone\n\nprintf \"    %-35s\" \"software_rpm/\"\nif [ -d \"$SCRIPT_DIR/software_rpm\" ] && [ -n \"$(ls -A \"$SCRIPT_DIR/software_rpm\"/*.rpm 2>/dev/null)\" ]; then\n    C=$(ls \"$SCRIPT_DIR/software_rpm\"/*.rpm | wc -l)\n    rsync -a \"$SCRIPT_DIR/software_rpm/\" \"$CONTENT_DIR/software_rpm/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}OK${NC} ($C RPMs)\"\nelse\n    echo -e \"${DIM}vazio${NC}\"\nfi\n\nprintf \"    %-35s\" \"favoritos/\"\nif [ -d \"$SCRIPT_DIR/favoritos\" ] && [ -n \"$(ls -A \"$SCRIPT_DIR/favoritos\" 2>/dev/null)\" ]; then\n    C=$(find \"$SCRIPT_DIR/favoritos\" -type f | wc -l)\n    rsync -a \"$SCRIPT_DIR/favoritos/\" \"$CONTENT_DIR/favoritos/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}OK${NC} ($C)\"\nelse\n    echo -e \"${DIM}vazio${NC}\"\nfi\n\nTOTAL_CONTENT=$(find \"$CONTENT_DIR\" -type f 2>/dev/null | wc -l)\nlog_ok \"Total: ${TOTAL_CONTENT} arquivos\"\nstep_done\n\n# ==================================================================\n# ETAPA 6/8 - Kickstart + Boot configs\n# ==================================================================\nstep_init 6 \"Criando kickstart e configurando boot\"\n\n# --- Kickstart ---\ncat > \"$KS_FILE\" << 'EOFKS'\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\nbootloader --location=mbr --driveorder=sda\n\n# Repos offline via cdrom ( Packages/ na raiz da ISO )\nrepo --name=\"Packages\" --baseurl=file:///run/install/repo/Packages --noverifyssl\n\n# Backup online (se precisar)\nurl --url=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/ --noverifyssl\nrepo --name=\"AppStream\" --baseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/x86_64/ --noverifyssl\n\nnetwork --bootproto=dhcp --activate\n\nuser --name=oracle --password=oracle --plaintext\nrootpw --lock\n\nservices --enabled=\"chronyd,sshd,bluetooth,NetworkManager\"\n\nreboot\n\n%packages\n@xfce\n@base-x\n@base\n@core\n@hardware-support\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\nbluetooth\nbluez\nbluez-tools\nNetworkManager-wifi\nwireless-tools\nwpa_supplicant\niw\nrfkill\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\nchromium\nalsa-utils\npulseaudio\npulseaudio-utils\npipewire\npipewire-pulse\nmake\ngcc\nrpm-build\ntar\ngzip\npython3\nhtop\nlm_sensors\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\nset -x\n\nhostnamectl set-name oracle-offline\n\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\nsystemctl enable NetworkManager\n\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\n# Montar midia\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"\\$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    # Scripts para /usr/local/bin\n    for SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n        if [ -f \"/mnt/media/content/\\$SCRIPT\" ]; then\n            rsync -a \"/mnt/media/content/\\$SCRIPT\" /usr/local/bin/\n            chmod +x \"/usr/local/bin/\\$SCRIPT\"\n        fi\n    done\n\n    # Diretorios para /opt\n    for DIR in system_scripts vm_scripts bluetooth; do\n        if [ -d \"/mnt/media/content/\\$DIR\" ]; then\n            rsync -av \"/mnt/media/content/\\$DIR/\" \"/opt/\\$DIR/\"\n            chmod -R +x \"/opt/\\$DIR/\" 2>/dev/null || true\n        fi\n    done\n\n    # Repo local offline\n    if [ -d /mnt/media/Packages ]; then\n        mkdir -p /opt/local_repo\n        rsync -a /mnt/media/Packages/ /opt/local_repo/\n        if [ -d /mnt/media/Packages/repodata ]; then\n            rsync -a /mnt/media/Packages/repodata/ /opt/local_repo/repodata/\n        fi\n        cat > /etc/yum.repos.d/ol9-local-offline.repo << 'REPOEOF'\n[ol9_local_offline]\nname=Oracle Linux 9 Local Offline\nbaseurl=file:///opt/local_repo/\nenabled=1\ngpgcheck=0\nREPOEOF\n    fi\n\n    # Favoritos\n    if [ -d /mnt/media/content/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/content/favoritos/ /etc/skel/favoritos/\n        mkdir -p /home/oracle/favoritos\n        rsync -av /mnt/media/content/favoritos/ /home/oracle/favoritos/\n        chown -R oracle:oracle /home/oracle/favoritos 2>/dev/null || true\n    fi\n\n    if [ -f /mnt/media/content/checksums.txt ]; then\n        cd /mnt/media/content && sha256sum -c checksums.txt 2>/dev/null || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\nsystemctl enable bluetooth\n\ncat > /etc/NetworkManager/conf.d/wifi-powersave.conf << 'NMEOF'\n[connection]\nwifi.powersave = 2\nNMEOF\n\nln -sf /opt/system_scripts/ol9-full-setup.sh /usr/local/bin/ol9-setup 2>/dev/null || true\nln -sf /opt/system_scripts/otimizar-xfce.sh /usr/local/bin/otimizar-xfce 2>/dev/null || true\n\necho \"Instalacao offline concluida: $(date)\" > /root/INSTALL_OK\n%end\nEOFKS\n\nlog_ok \"Kickstart: $KS_FILE\"\n\n# --- GRUB UEFI (modificar o extraido) ---\n# Label original: OL-9-8-0-BaseOS-x86_64 -> novo: OL9_OFFLINE_XFCE\nGRUB_CFG=\"$WORK_DIR/EFI/BOOT/grub.cfg\"\nif [ -f \"$GRUB_CFG\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$GRUB_CFG\"\n    sed -i \"s|set timeout=60|set timeout=5|g\" \"$GRUB_CFG\"\n    log_ok \"grub.cfg UEFI atualizado (label: $FS_LABEL)\"\nfi\n\n# Adicionar entrada com kickstart automatico\nif [ -f \"$GRUB_CFG\" ]; then\n    cat >> \"$GRUB_CFG\" << 'GRUBKS'\n\nmenuentry 'Instalar com Kickstart (auto, XFCE)' --class fedora --class gnu-linux --class gnu --class os {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_XFCE inst.ks=hd:LABEL=OL9_OFFLINE_XFCE:/ks.cfg quiet\n    initrdefi /images/pxeboot/initrd.img\n}\nGRUBKS\n    log_ok \"Entrada kickstart adicionada ao grub.cfg\"\nfi\n\n# --- isolinux BIOS (modificar o extraido) ---\nISOLINUX_CFG=\"$WORK_DIR/isolinux/isolinux.cfg\"\nif [ -f \"$ISOLINUX_CFG\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$ISOLINUX_CFG\"\n    log_ok \"isolinux.cfg atualizado (label: $FS_LABEL)\"\n\n    # Adicionar entrada kickstart\n    cat >> \"$ISOLINUX_CFG\" << 'ISOLINUXKS'\n\nlabel kickstart\n  menu label ^Instalar com Kickstart (auto, XFCE)\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_XFCE inst.ks=hd:LABEL=OL9_OFFLINE_XFCE:/ks.cfg quiet\nISOLINUXKS\n    log_ok \"Entrada kickstart adicionada ao isolinux.cfg\"\nfi\n\n# --- .discinfo ---\nDISCINFO=\"$WORK_DIR/.discinfo\"\nif [ -f \"$DISCINFO\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$DISCINFO\"\n    log_ok \".discinfo atualizado\"\nfi\n\n# --- Atualizar grub.cfg DENTRO do efiboot.img ---\nEFIIMG=\"$WORK_DIR/images/efiboot.img\"\nEFIIMG_MOUNT=\"$BUILD_ROOT/efiboot_mount\"\nif [ -f \"$EFIIMG\" ]; then\n    log_info \"Atualizando grub.cfg dentro do efiboot.img...\"\n    mkdir -p \"$EFIIMG_MOUNT\"\n    if mount -o loop,rw \"$EFIIMG\" \"$EFIIMG_MOUNT\" 2>/dev/null; then\n        cp \"$GRUB_CFG\" \"$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\"\n        chmod 644 \"$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\"\n        umount \"$EFIIMG_MOUNT\"\n        log_ok \"efiboot.img atualizado com grub.cfg correto (label: $FS_LABEL)\"\n    else\n        log_warn \"Falha ao montar efiboot.img. Tentando via mtools...\"\n        if command -v mcopy &>/dev/null; then\n            mcopy -o \"$GRUB_CFG\" \"::$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\" 2>/dev/null || true\n            log_ok \"efiboot.img atualizado via mtools\"\n        else\n            log_err \"NAO FOI POSSIVEL atualizar efiboot.img. Boot UEFI pode falhar!\"\n        fi\n    fi\nfi\n\nstep_done\n\n# ==================================================================\n# ETAPA 7/8 - Gerar ISO\n# ==================================================================\nstep_init 7 \"Gerando ISO offline com xorriso\"\n\n# Calcular tamanho total\nTOTAL_ISO_SIZE=$(du -sh \"$WORK_DIR\" | cut -f1)\nlog_info \"Tamanho total da arvore ISO: $TOTAL_ISO_SIZE\"\nlog_info \"RPMs: $RPM_COUNT | Scripts: $TOTAL_CONTENT\"\n\nISO_PATH=\"$OUT_DIR/$ISO_NAME\"\nrm -rf \"$OUT_DIR\"\nmkdir -p \"$OUT_DIR\"\n\nlog_info \"Gerando ISO hibrida (UEFI + BIOS)...\"\n\nxorriso -as mkisofs \\\n    -iso-level 3 \\\n    -full-iso9660-filenames \\\n    -V \"$FS_LABEL\" \\\n    -o \"$ISO_PATH\" \\\n    -b isolinux/isolinux.bin \\\n    -c isolinux/boot.cat \\\n    -no-emul-boot \\\n    -boot-load-size 4 \\\n    -boot-info-table \\\n    -eltorito-alt-boot \\\n    -e images/efiboot.img \\\n    -no-emul-boot \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    -isohybrid-gpt-basdat \\\n    \"$WORK_DIR\" 2>&1 | tee -a \"$LOG_FILE\"\n\nif [ ! -f \"$ISO_PATH\" ]; then\n    log_err \"ISO nao gerada!\"\n    exit 1\nfi\n\nISO_SIZE=$(du -h \"$ISO_PATH\" | cut -f1)\nlog_ok \"ISO gerada: $ISO_PATH ($ISO_SIZE)\"\nstep_done\n\n# ==================================================================\n# ETAPA 8/8 - isohybrid + checksum + resumo\n# ==================================================================\nstep_init 8 \"Aplicando isohybrid + checksum + resumo\"\n\nprintf \"    isohybrid --uefi... \"\nif isohybrid --uefi \"$ISO_PATH\" 2>>\"$LOG_FILE\"; then\n    echo -e \"${GREEN}OK${NC}\"\nelse\n    echo -e \"${YELLOW}skip (ja hibrida)${NC}\"\nfi\n\ncd \"$OUT_DIR\"\nsha256sum \"$ISO_NAME\" > hash_iso.txt 2>/dev/null\nlog_ok \"SHA256 gerado\"\n\nISO_SIZE_FINAL=$(ls -lh \"$ISO_NAME\" | awk '{print $5}')\nISO_SIZE_BYTES=$(stat -c%s \"$ISO_NAME\" 2>/dev/null || echo 0)\nBUILD_TOTAL=$(($(date +%s) - BUILD_START))\nBUILD_MIN=$((BUILD_TOTAL / 60))\nBUILD_SEC=$((BUILD_TOTAL % 60))\n\necho \"\"\necho -e \"${BOLD}${GREEN}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\necho -e \"${BOLD}${GREEN}\u2551    ISO OFFLINE GERADA COM SUCESSO (a partir da ISO boot)!  \u2551${NC}\"\necho -e \"${BOLD}${GREEN}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\necho \"\"\necho -e \"  ${BOLD}Arquivo:${NC}  $OUT_DIR/$ISO_NAME\"\necho -e \"  ${BOLD}Tamanho:${NC}  $ISO_SIZE_FINAL\"\necho -e \"  ${BOLD}Checksum:${NC} $OUT_DIR/hash_iso.txt\"\necho \"\"\necho -e \"  ${BOLD}Base:${NC}     OracleLinux-R9-U8-x86_64-boot.iso\"\necho -e \"  ${BOLD}Boot:${NC}     UEFI + MBR (BIOS)\"\necho -e \"  ${BOLD}Desktop:${NC}  XFCE\"\necho -e \"  ${BOLD}Offline:${NC}  SIM \u2014 $RPM_COUNT RPMs embutidos\"\necho \"\"\necho -e \"  ${BOLD}Opcoes de boot:${NC}\"\necho -e \"    1) Install Oracle Linux 9.8.0\"\necho -e \"    2) Instalar com Kickstart (auto, XFCE)\"\necho -e \"    3) Test this media & install\"\necho -e \"    4) Text mode / Rescue\"\necho \"\"\necho -e \"  ${BOLD}Pos-install:${NC}\"\necho -e \"    update-appimages.sh   # Brave, VSCodium, Chromium, OpenCode\"\necho -e \"    ol9-setup             # EPEL + RPM Fusion + codecs\"\necho -e \"    otimizar-xfce         # Otimizar XFCE\"\necho \"\"\necho -e \"  ${BOLD}Tempo:${NC}    ${BUILD_MIN}m ${BUILD_SEC}s\"\necho -e \"  ${BOLD}Log:${NC}      $LOG_FILE\"\necho \"\"\n", "build_offline_ol9.sh": "#!/bin/bash\n# ==============================================================================\n# Gerador de ISO Offline - Oracle Linux 9 (XFCE + UEFI + MBR)\n# Extrai ISO boot, baixa RPMs, copia scripts com rsync, regenera ISO offline\n# ==============================================================================\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nBUILD_ROOT=\"$SCRIPT_DIR/build_offline\"\nWORK_DIR=\"$BUILD_ROOT/work\"\nISO_TREE=\"$WORK_DIR/iso_tree\"\nLOCAL_REPO=\"$ISO_TREE/Packages\"\nOUT_DIR=\"$BUILD_ROOT/output_iso\"\nKS_FILE=\"$ISO_TREE/ks.cfg\"\nCONTENT_DIR=\"$ISO_TREE/content\"\nLOG_DIR=\"$BUILD_ROOT/logs\"\nLOG_FILE=\"$LOG_DIR/build_$(date +%Y%m%d_%H%M%S).log\"\nSTATUS_FILE=\"$LOG_DIR/build_status.log\"\nBOOT_ISO=\"$SCRIPT_DIR/OracleLinux-R9-U8-x86_64-boot.iso\"\nISO_NAME=\"OL9-Offline-Completa.iso\"\nFS_LABEL=\"OL9_OFFLINE_XFCE\"\n\nTOTAL_STEPS=8\nCURRENT_STEP=0\nSTEP_START=0\nBUILD_START=$(date +%s)\nERRORS=0\n\ndeclare -A STEP_TIMES\ndeclare -A STEP_STATUS\nRPM_DOWNLOADED=0\nRPM_FAILED=0\nCONTENT_COPIED=0\nSCRIPTS_COPIED=0\n\nRED='\\033[0;31m'; GREEN='\\033[0;32m'; YELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'; CYAN='\\033[0;36m'; MAGENTA='\\033[0;35m'\nWHITE='\\033[1;37m'; DIM='\\033[2m'; BOLD='\\033[1m'; NC='\\033[0m'\n\nmkdir -p \"$LOG_DIR\" 2>/dev/null || true\n\nlog() {\n    local msg=\"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"\n    echo -e \"$msg\"\n    [ -d \"$(dirname \"$LOG_FILE\")\" ] 2>/dev/null && echo \"$msg\" >> \"$LOG_FILE\" 2>/dev/null || true\n    [ -d \"$(dirname \"$STATUS_FILE\")\" ] 2>/dev/null && echo \"$msg\" >> \"$STATUS_FILE\" 2>/dev/null || true\n}\n\nlog_ok() {\n    local msg=\"[OK]    $*\"\n    echo -e \"  ${GREEN}${msg}${NC}\"\n    log \"${msg}\" 2>/dev/null || true\n}\n\nlog_warn() {\n    local msg=\"[WARN]  $*\"\n    echo -e \"  ${YELLOW}${msg}${NC}\"\n    log \"${msg}\" 2>/dev/null || true\n}\n\nlog_err() {\n    local msg=\"[ERRO]  $*\"\n    echo -e \"  ${RED}${msg}${NC}\"\n    log \"${msg}\" 2>/dev/null || true\n    ((ERRORS++)) || true\n}\n\nlog_info() {\n    local msg=\"[INFO]  $*\"\n    echo -e \"  ${CYAN}${msg}${NC}\"\n    log \"${msg}\" 2>/dev/null || true\n}\n\nlog_status() {\n    local msg=\"[STATUS] $*\"\n    echo -e \"  ${WHITE}${msg}${NC}\"\n    log \"${msg}\" 2>/dev/null || true\n}\n\nlog_progress() {\n    local current=$1 total=$2 label=$3\n    local percent=$((current * 100 / total))\n    local width=40\n    local filled=$((width * current / total))\n    local empty=$((width - filled))\n    printf \"\\r    [\"\n    printf \"%${filled}s\" | tr ' ' '\u2588'\n    printf \"%${empty}s\" | tr ' ' '\u2591'\n    printf \"] %3d%% %s\" \"$percent\" \"$label\"\n    if [ \"$current\" -eq \"$total\" ]; then\n        echo \"\"\n    fi\n}\n\nlog_step_header() {\n    local step=$1 total=$2 title=$3\n    local elapsed_total=$(($(date +%s) - BUILD_START))\n    echo \"\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    printf \"${BOLD}${WHITE}  ETAPA %2d/%d${NC}  \" \"$step\" \"$total\"\n    echo -e \"${BOLD}${WHITE}$title${NC}\"\n    echo -e \"${DIM}  Inicio: $(date '+%H:%M:%S') | Acumulado: ${elapsed_total}s${NC}\"\n    echo -e \"${BOLD}${BLUE}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${NC}\"\n    echo \"\"\n    log \"ETAPA $step/$total: $title\" 2>/dev/null || true\n}\n\nlog_step_footer() {\n    local step=$1\n    local elapsed=$(( $(date +%s) - STEP_START ))\n    local total_elapsed=$(( $(date +%s) - BUILD_START ))\n    STEP_TIMES[$step]=$elapsed\n    STEP_STATUS[$step]=\"OK\"\n    echo \"\"\n    echo -e \"  ${GREEN}\u2714 Etapa $step concluida em ${elapsed}s${NC} (total: ${total_elapsed}s)\"\n    log \"ETAPA $step CONCLUIDA em ${elapsed}s (total: ${total_elapsed}s)\" 2>/dev/null || true\n    [ -d \"$(dirname \"$LOG_FILE\")\" ] 2>/dev/null && echo \"\" >> \"$LOG_FILE\" 2>/dev/null || true\n}\n\nlog_step_error() {\n    local step=$1\n    local elapsed=$(( $(date +%s) - STEP_START ))\n    STEP_TIMES[$step]=$elapsed\n    STEP_STATUS[$step]=\"ERRO\"\n    echo \"\"\n    echo -e \"  ${RED}\u2717 Etapa $step FALHOU em ${elapsed}s${NC}\"\n    log \"ETAPA $step FALHOU em ${elapsed}s\" 2>/dev/null || true\n}\n\nlimpar_tudo() {\n    echo \"\"\n    echo \"[LIMPEZA] Desmontando temporarios...\"\n    sync\n    grep \"$BUILD_ROOT\" /proc/mounts 2>/dev/null | cut -d' ' -f2 | xargs -r umount -l 2>/dev/null || true\n    rm -rf \"$BUILD_ROOT/iso_mount\" \"$BUILD_ROOT/lmc-work-*\" \"/var/tmp/lmc-*\" 2>/dev/null || true\n    echo \"[LIMPEZA] Concluida\"\n}\n\ngerar_resumo_final() {\n    local build_total=$(($(date +%s) - BUILD_START))\n    local build_min=$((build_total / 60))\n    local build_sec=$((build_total % 60))\n\n    echo \"\"\n    echo -e \"${BOLD}${MAGENTA}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\n    echo -e \"${BOLD}${MAGENTA}\u2551              RESUMO DO BUILD - ISO OFFLINE                  \u2551${NC}\"\n    echo -e \"${BOLD}${MAGENTA}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\n    echo \"\"\n\n    log \"RESUMO DO BUILD\"\n    log \"  Tempo total: ${build_total}s (${build_min}m ${build_sec}s)\"\n\n    echo -e \"  ${BOLD}Tempo total:${NC}    ${BUILD_MIN}m ${BUILD_SEC}s\"\n    echo -e \"  ${BOLD}Erros:${NC}          $ERRORS\"\n    echo \"\"\n\n    echo -e \"  ${BOLD}Detalhes por Etapa:${NC}\"\n    for i in $(seq 1 $TOTAL_STEPS); do\n        local time=${STEP_TIMES[$i]:-0}\n        local status=${STEP_STATUS[$i]:-PENDENTE}\n        if [ \"$status\" = \"OK\" ]; then\n            echo -e \"    ${GREEN}\u2714${NC} Etapa $i: $status (${time}s)\"\n        else\n            echo -e \"    ${RED}\u2717${NC} Etapa $i: $status (${time}s)\"\n        fi\n        log \"  Etapa $i: $status (${time}s)\"\n    done\n    echo \"\"\n\n    echo -e \"  ${BOLD}Conteudo:${NC}\"\n    echo -e \"    \u251c\u2500 RPMs:              $RPM_DOWNLOADED ($RPM_FAILED falharam)\"\n    echo -e \"    \u251c\u2500 Scripts:           $SCRIPTS_COPIED\"\n    echo -e \"    \u251c\u2500 Arquivos:          $CONTENT_COPIED\"\n    echo -e \"    \u2514\u2500 Tamanho repo:      $(du -sh \"$LOCAL_REPO\" 2>/dev/null | cut -f1)\"\n    echo \"\"\n\n    if [ -f \"$OUT_DIR/$ISO_NAME\" ]; then\n        local iso_size=$(du -h \"$OUT_DIR/$ISO_NAME\" | cut -f1)\n        echo -e \"  ${BOLD}ISO Gerada:${NC}\"\n        echo -e \"    \u251c\u2500 Arquivo:           $OUT_DIR/$ISO_NAME\"\n        echo -e \"    \u251c\u2500 Tamanho:           $iso_size\"\n        echo -e \"    \u251c\u2500 Checksum:          $OUT_DIR/hash_iso.txt\"\n        echo -e \"    \u251c\u2500 Label:             $FS_LABEL\"\n        echo -e \"    \u2514\u2500 Boot:              UEFI + MBR\"\n        echo \"\"\n        log \"ISO Gerada: $OUT_DIR/$ISO_NAME ($iso_size)\"\n    fi\n\n    echo -e \"  ${BOLD}Logs:${NC}\"\n    echo -e \"    \u251c\u2500 Principal:         $LOG_FILE\"\n    echo -e \"    \u2514\u2500 Status:            $STATUS_FILE\"\n    echo \"\"\n\n    if [ $ERRORS -gt 0 ]; then\n        echo -e \"${BOLD}${RED}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\n        echo -e \"${BOLD}${RED}\u2551  BUILD COMPLETADO COM $ERRORS ERRO(S)!                           \u2551${NC}\"\n        echo -e \"${BOLD}${RED}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\n        log \"BUILD COMPLETADO COM $ERRORS ERRO(S)!\"\n    else\n        echo -e \"${BOLD}${GREEN}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\n        echo -e \"${BOLD}${GREEN}\u2551          BUILD CONCLUIDO COM SUCESSO!                       \u2551${NC}\"\n        echo -e \"${BOLD}${GREEN}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\n        log \"BUILD CONCLUIDO COM SUCESSO!\"\n    fi\n}\n\ntrap limpar_tudo EXIT\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# INICIO\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\necho -e \"${BOLD}${MAGENTA}\"\necho \"\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\necho \"\u2551  ISO OFFLINE Oracle Linux 9 \u2014 Extrair + RPMs + Regenerar    \u2551\"\necho \"\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\necho -e \"${NC}\"\n\nlog \"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\"\nlog \"INICIO DO BUILD - ISO OFFLINE Oracle Linux 9\"\nlog \"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\"\nlog \"Log: $LOG_FILE\"\nlog \"Sistema: $(uname -n) | Kernel: $(uname -r) | User: $(whoami)\"\nlog \"Espaco: $(df -BG \"$SCRIPT_DIR\" | awk 'NR==2{print $4}')\"\necho \"\"\n\nif [[ $EUID -ne 0 ]]; then\n    log_err \"Execute como ROOT.\"\n    exit 1\nfi\n\nif [ ! -f \"$BOOT_ISO\" ]; then\n    log_err \"ISO boot nao encontrada: $BOOT_ISO\"\n    exit 1\nfi\n\nFREE_GB=$(df -BG \"$SCRIPT_DIR\" | awk 'NR==2{print $4}' | sed 's/G//')\nif [ \"$FREE_GB\" -lt 20 ]; then\n    log_err \"Espaco insuficiente ($FREE_GB GB). Minimo 20GB.\"\n    exit 1\nfi\nlog_info \"Espaco: ${FREE_GB}GB | ISO boot: $(du -h \"$BOOT_ISO\" | cut -f1)\"\n\nif [ -d \"$BUILD_ROOT\" ]; then\n    log_info \"Removendo build anterior...\"\n    rm -rf \"$BUILD_ROOT\"\nfi\n\nmkdir -p \"$LOG_DIR\" \"$BUILD_ROOT\" \"$WORK_DIR\" \"$ISO_TREE\" \"$LOCAL_REPO\" \\\n         \"$CONTENT_DIR/software_rpm\" \"$CONTENT_DIR/favoritos\" \\\n         \"$CONTENT_DIR/system_scripts\" \"$CONTENT_DIR/vm_scripts\" \\\n         \"$CONTENT_DIR/bluetooth\" \"$OUT_DIR\"\n\nlog_info \"Pasta de trabalho: $WORK_DIR\"\nlog_info \"Arvore ISO: $ISO_TREE\"\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 1/8 - Dependencias\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=1\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Instalando dependencias\"\n\nDEPS=(createrepo_c xorriso rsync isohybrid)\nDEPS_OK=0\nDEPS_FAIL=0\n\nfor dep in \"${DEPS[@]}\"; do\n    printf \"    %-30s\" \"$dep\"\n    if command -v \"$dep\" &>/dev/null || rpm -q \"$dep\" &>/dev/null 2>&1; then\n        echo -e \"${GREEN}OK${NC}\"\n        ((DEPS_OK++)) || true\n    else\n        printf \"instalando... \"\n        if dnf install -y \"$dep\" >> \"$LOG_FILE\" 2>&1; then\n            echo -e \"${GREEN}OK${NC}\"\n            ((DEPS_OK++)) || true\n        else\n            echo -e \"${YELLOW}skip${NC}\"\n            ((DEPS_FAIL++)) || true\n        fi\n    fi\ndone\n\nlog_status \"Dependencias: $DEPS_OK OK, $DEPS_FAIL falharam\"\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 2/8 - Extrair ISO boot\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=2\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Extraindo ISO boot minimal\"\n\nlog_status \"ISO: $BOOT_ISO\"\nlog_status \"Destino: $ISO_TREE\"\n\nprintf \"    Extraindo... \"\nxorriso -osirrox on \\\n    -indev \"$BOOT_ISO\" \\\n    -extract / \"$ISO_TREE\" \\\n    2>&1 | tee -a \"$LOG_FILE\"\n\nEXTRACTED=$(find \"$ISO_TREE\" -type f | wc -l)\necho \"\"\nlog_ok \"$EXTRACTED arquivos extraidos\"\n\nlog_status \"Arquivos de boot:\"\nfor f in images/pxeboot/vmlinuz images/pxeboot/initrd.img images/install.img images/efiboot.img; do\n    if [ -f \"$ISO_TREE/$f\" ]; then\n        log_info \"  $f ($(du -h \"$ISO_TREE/$f\" | cut -f1))\"\n    fi\ndone\n\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 3/8 - Baixar RPMs offline\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=3\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Baixando RPMs para instalacao offline\"\n\nALL_PACKAGES=(\n    kernel-core grub2-efi-x64 grub2-pc shim-x64 syslinux dracut-live\n    bluetooth bluez bluez-tools\n    NetworkManager-wifi wireless-tools wpa_supplicant iw rfkill\n    rsync chrony openssh-server bash-completion vim-minimal\n    nano wget curl net-tools iproute NetworkManager\n    chromium\n    alsa-utils pulseaudio pulseaudio-utils pipewire pipewire-pulse\n    make gcc rpm-build tar gzip python3\n    htop lm_sensors\n)\n\nlog_status \"Total de pacotes: ${#ALL_PACKAGES[@]}\"\nlog \"Pacotes a baixar: ${#ALL_PACKAGES[@]}\"\n\nDOWNLOADED=0\nSKIPPED=0\nTOTAL_PKGS=${#ALL_PACKAGES[@]}\n\nlog_status \"Baixando $TOTAL_PKGS pacotes (um por vez)...\"\n\nfor i in \"${!ALL_PACKAGES[@]}\"; do\n    pkg=\"${ALL_PACKAGES[$i]}\"\n    idx=$((i + 1))\n    log_progress $idx $TOTAL_PKGS \"$pkg\"\n\n    if dnf download --repo=ol9_baseos_latest --repo=ol9_appstream \\\n        --destdir=\"$LOCAL_REPO\" \"$pkg\" >> \"$LOG_FILE\" 2>&1; then\n        ((DOWNLOADED++)) || true\n    else\n        log \"  Pacote nao encontrado ou falhou: $pkg\" 2>/dev/null || true\n        ((SKIPPED++)) || true\n    fi\ndone\n\nRPM_COUNT=$(find \"$LOCAL_REPO\" -name '*.rpm' -type f 2>/dev/null | wc -l)\nlog_status \"RPMs baixados: $RPM_COUNT | Nao encontrados: $SKIPPED\"\n\nif [[ $RPM_COUNT -eq 0 ]]; then\n    log_err \"Nenhum RPM baixado!\"\n    log_step_error $CURRENT_STEP\n    exit 1\nfi\n\nREPO_SIZE=$(du -sh \"$LOCAL_REPO\" | cut -f1)\nlog_ok \"$RPM_COUNT RPMs ($REPO_SIZE) salvos em $LOCAL_REPO\"\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 4/8 - Criar repodata\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=4\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Criando repodata (createrepo_c)\"\n\nlog_status \"Executando createrepo_c em $LOCAL_REPO...\"\ncreaterepo_c \"$LOCAL_REPO\" >> \"$LOG_FILE\" 2>&1\nlog_ok \"repodata criada em $LOCAL_REPO\"\n\nREPODATA_SIZE=$(du -sh \"$LOCAL_REPO/repodata\" 2>/dev/null | cut -f1)\nlog_status \"Tamanho repodata: $REPODATA_SIZE\"\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 5/8 - Copiar scripts + criar conteudo\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=5\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Copiando scripts e criando conteudo\"\n\nlog_status \"Copiando scripts principais...\"\nfor SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n    SRC=\"$SCRIPT_DIR/$SCRIPT\"\n    printf \"    %-35s\" \"$SCRIPT\"\n    if [ -f \"$SRC\" ]; then\n        rsync -a \"$SRC\" \"$CONTENT_DIR/\"\n        echo -e \"${GREEN}OK${NC} ($(du -h \"$SRC\" | cut -f1))\"\n        ((SCRIPTS_COPIED++)) || true\n    else\n        echo -e \"${YELLOW}skip${NC}\"\n    fi\ndone\n\nlog_status \"Copiando diretorios...\"\nfor DIR in system_scripts vm_scripts bluetooth; do\n    SRC=\"$SCRIPT_DIR/$DIR\"\n    printf \"    %-35s\" \"$DIR/\"\n    if [ -d \"$SRC\" ]; then\n        COUNT=$(find \"$SRC\" -type f | wc -l)\n        rsync -a \"$SRC/\" \"$CONTENT_DIR/$DIR/\" >> \"$LOG_FILE\" 2>&1\n        echo -e \"${GREEN}OK${NC} ($COUNT arquivos)\"\n        ((CONTENT_COPIED+=COUNT)) || true\n    else\n        echo -e \"${YELLOW}skip${NC}\"\n    fi\ndone\n\nprintf \"    %-35s\" \"software_rpm/\"\nif [ -d \"$SCRIPT_DIR/software_rpm\" ] && [ -n \"$(ls -A \"$SCRIPT_DIR/software_rpm\"/*.rpm 2>/dev/null)\" ]; then\n    C=$(ls \"$SCRIPT_DIR/software_rpm\"/*.rpm 2>/dev/null | wc -l)\n    rsync -a \"$SCRIPT_DIR/software_rpm/\" \"$CONTENT_DIR/software_rpm/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}OK${NC} ($C RPMs)\"\n    ((CONTENT_COPIED+=C)) || true\nelse\n    echo -e \"${DIM}vazio${NC}\"\nfi\n\nprintf \"    %-35s\" \"favoritos/\"\nif [ -d \"$SCRIPT_DIR/favoritos\" ] && [ -n \"$(ls -A \"$SCRIPT_DIR/favoritos\" 2>/dev/null)\" ]; then\n    C=$(find \"$SCRIPT_DIR/favoritos\" -type f | wc -l)\n    rsync -a \"$SCRIPT_DIR/favoritos/\" \"$CONTENT_DIR/favoritos/\" >> \"$LOG_FILE\" 2>&1\n    echo -e \"${GREEN}OK${NC} ($C arquivos)\"\n    ((CONTENT_COPIED+=C)) || true\nelse\n    echo -e \"${DIM}vazio${NC}\"\nfi\n\nTOTAL_CONTENT=$(find \"$CONTENT_DIR\" -type f 2>/dev/null | wc -l)\nlog_ok \"Total: ${TOTAL_CONTENT} arquivos ($(du -sh \"$CONTENT_DIR\" | cut -f1))\"\nlog_status \"Conteudo total: $TOTAL_CONTENT arquivos\"\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 6/8 - Kickstart + Boot configs\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=6\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Criando kickstart e configurando boot\"\n\nlog_status \"Gerando kickstart...\"\ncat > \"$KS_FILE\" << 'EOFKS'\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\nbootloader --location=mbr --driveorder=sda\n\nrepo --name=\"Packages\" --baseurl=file:///run/install/repo/Packages --noverifyssl\n\nurl --url=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/ --noverifyssl\nrepo --name=\"AppStream\" --baseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/x86_64/ --noverifyssl\n\nnetwork --bootproto=dhcp --activate\n\nuser --name=oracle --password=oracle --plaintext\nrootpw --lock\n\nservices --enabled=\"chronyd,sshd,bluetooth,NetworkManager\"\n\nreboot\n\n%packages\n@xfce\n@base-x\n@base\n@core\n@hardware-support\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\nbluetooth\nbluez\nbluez-tools\nNetworkManager-wifi\nwireless-tools\nwpa_supplicant\niw\nrfkill\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\nchromium\nalsa-utils\npulseaudio\npulseaudio-utils\npipewire\npipewire-pulse\nmake\ngcc\nrpm-build\ntar\ngzip\npython3\nhtop\nlm_sensors\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\nset -x\n\nhostnamectl set-name oracle-offline\n\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\nsystemctl enable NetworkManager\n\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"\\$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    for SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n        if [ -f \"/mnt/media/content/\\$SCRIPT\" ]; then\n            rsync -a \"/mnt/media/content/\\$SCRIPT\" /usr/local/bin/\n            chmod +x \"/usr/local/bin/\\$SCRIPT\"\n        fi\n    done\n\n    for DIR in system_scripts vm_scripts bluetooth; do\n        if [ -d \"/mnt/media/content/\\$DIR\" ]; then\n            rsync -av \"/mnt/media/content/\\$DIR/\" \"/opt/\\$DIR/\"\n            chmod -R +x \"/opt/\\$DIR/\" 2>/dev/null || true\n        fi\n    done\n\n    if [ -d /mnt/media/Packages ]; then\n        mkdir -p /opt/local_repo\n        rsync -a /mnt/media/Packages/ /opt/local_repo/\n        if [ -d /mnt/media/Packages/repodata ]; then\n            rsync -a /mnt/media/Packages/repodata/ /opt/local_repo/repodata/\n        fi\n        cat > /etc/yum.repos.d/ol9-local-offline.repo << 'REPOEOF'\n[ol9_local_offline]\nname=Oracle Linux 9 Local Offline\nbaseurl=file:///opt/local_repo/\nenabled=1\ngpgcheck=0\nREPOEOF\n    fi\n\n    if [ -d /mnt/media/content/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/content/favoritos/ /etc/skel/favoritos/\n        mkdir -p /home/oracle/favoritos\n        rsync -av /mnt/media/content/favoritos/ /home/oracle/favoritos/\n        chown -R oracle:oracle /home/oracle/favoritos 2>/dev/null || true\n    fi\n\n    if [ -f /mnt/media/content/checksums.txt ]; then\n        cd /mnt/media/content && sha256sum -c checksums.txt 2>/dev/null || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\nsystemctl enable bluetooth\n\ncat > /etc/NetworkManager/conf.d/wifi-powersave.conf << 'NMEOF'\n[connection]\nwifi.powersave = 2\nNMEOF\n\nln -sf /opt/system_scripts/ol9-full-setup.sh /usr/local/bin/ol9-setup 2>/dev/null || true\nln -sf /opt/system_scripts/otimizar-xfce.sh /usr/local/bin/otimizar-xfce 2>/dev/null || true\n\necho \"Instalacao offline concluida: $(date)\" > /root/INSTALL_OK\n%end\nEOFKS\n\nKS_LINES=$(wc -l < \"$KS_FILE\")\nlog_ok \"Kickstart: $KS_FILE ($KS_LINES linhas)\"\n\nlog_status \"Configurando GRUB UEFI...\"\nGRUB_CFG=\"$ISO_TREE/EFI/BOOT/grub.cfg\"\nif [ -f \"$GRUB_CFG\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$GRUB_CFG\"\n    sed -i \"s|set timeout=60|set timeout=5|g\" \"$GRUB_CFG\"\n    log_ok \"grub.cfg UEFI atualizado (label: $FS_LABEL)\"\n\n    cat >> \"$GRUB_CFG\" << 'GRUBKS'\n\nmenuentry 'Instalar com Kickstart (auto, XFCE)' --class fedora --class gnu-linux --class gnu --class os {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_XFCE inst.ks=hd:LABEL=OL9_OFFLINE_XFCE:/ks.cfg quiet\n    initrdefi /images/pxeboot/initrd.img\n}\nGRUBKS\n    log_ok \"Entrada kickstart adicionada ao grub.cfg\"\nfi\n\nlog_status \"Configurando isolinux BIOS...\"\nISOLINUX_CFG=\"$ISO_TREE/isolinux/isolinux.cfg\"\nif [ -f \"$ISOLINUX_CFG\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$ISOLINUX_CFG\"\n    log_ok \"isolinux.cfg atualizado (label: $FS_LABEL)\"\n\n    cat >> \"$ISOLINUX_CFG\" << 'ISOLINUXKS'\n\nlabel kickstart\n  menu label ^Instalar com Kickstart (auto, XFCE)\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_XFCE inst.ks=hd:LABEL=OL9_OFFLINE_XFCE:/ks.cfg quiet\nISOLINUXKS\n    log_ok \"Entrada kickstart adicionada ao isolinux.cfg\"\nfi\n\nDISCINFO=\"$ISO_TREE/.discinfo\"\nif [ -f \"$DISCINFO\" ]; then\n    sed -i \"s|OL-9-8-0-BaseOS-x86_64|${FS_LABEL}|g\" \"$DISCINFO\"\n    log_ok \".discinfo atualizado\"\nfi\n\nEFIIMG=\"$ISO_TREE/images/efiboot.img\"\nEFIIMG_MOUNT=\"$BUILD_ROOT/efiboot_mount\"\nif [ -f \"$EFIIMG\" ]; then\n    log_status \"Atualizando grub.cfg dentro do efiboot.img...\"\n    mkdir -p \"$EFIIMG_MOUNT\"\n    if mount -o loop,rw \"$EFIIMG\" \"$EFIIMG_MOUNT\" 2>/dev/null; then\n        cp \"$GRUB_CFG\" \"$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\"\n        chmod 644 \"$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\"\n        umount \"$EFIIMG_MOUNT\"\n        log_ok \"efiboot.img atualizado com grub.cfg correto (label: $FS_LABEL)\"\n    else\n        log_warn \"Falha ao montar efiboot.img. Tentando via mtools...\"\n        if command -v mcopy &>/dev/null; then\n            mcopy -o \"$GRUB_CFG\" \"::$EFIIMG_MOUNT/EFI/BOOT/grub.cfg\" 2>/dev/null || true\n            log_ok \"efiboot.img atualizado via mtools\"\n        else\n            log_err \"NAO FOI POSSIVEL atualizar efiboot.img. Boot UEFI pode falhar!\"\n        fi\n    fi\nfi\n\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 7/8 - Gerar ISO\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=7\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Gerando ISO offline com xorriso\"\n\nTOTAL_ISO_SIZE=$(du -sh \"$ISO_TREE\" | cut -f1)\nlog_status \"Tamanho da arvore ISO: $TOTAL_ISO_SIZE\"\nlog_status \"RPMs: $RPM_COUNT | Scripts: $TOTAL_CONTENT\"\n\nISO_PATH=\"$OUT_DIR/$ISO_NAME\"\nrm -rf \"$OUT_DIR\"\nmkdir -p \"$OUT_DIR\"\n\nlog_status \"Gerando ISO hibrida (UEFI + BIOS)...\"\n\nxorriso -as mkisofs \\\n    -iso-level 3 \\\n    -full-iso9660-filenames \\\n    -V \"$FS_LABEL\" \\\n    -o \"$ISO_PATH\" \\\n    -b isolinux/isolinux.bin \\\n    -c isolinux/boot.cat \\\n    -no-emul-boot \\\n    -boot-load-size 4 \\\n    -boot-info-table \\\n    -eltorito-alt-boot \\\n    -e images/efiboot.img \\\n    -no-emul-boot \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    -isohybrid-gpt-basdat \\\n    \"$ISO_TREE\" 2>&1 | tee -a \"$LOG_FILE\"\n\nif [ ! -f \"$ISO_PATH\" ]; then\n    log_err \"ISO nao gerada!\"\n    log_step_error $CURRENT_STEP\n    exit 1\nfi\n\nISO_SIZE=$(du -h \"$ISO_PATH\" | cut -f1)\nlog_ok \"ISO gerada: $ISO_PATH ($ISO_SIZE)\"\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# ETAPA 8/8 - isohybrid + checksum + resumo\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nSTEP_START=$(date +%s)\nCURRENT_STEP=8\nlog_step_header $CURRENT_STEP $TOTAL_STEPS \"Aplicando isohybrid + checksum + resumo\"\n\nlog_status \"Aplicando isohybrid --uefi...\"\nprintf \"    isohybrid --uefi... \"\nif isohybrid --uefi \"$ISO_PATH\" 2>>\"$LOG_FILE\"; then\n    echo -e \"${GREEN}OK${NC}\"\nelse\n    echo -e \"${YELLOW}skip (ja hibrida)${NC}\"\nfi\n\nlog_status \"Gerando checksum SHA256...\"\ncd \"$OUT_DIR\"\nsha256sum \"$ISO_NAME\" > hash_iso.txt 2>/dev/null\nlog_ok \"SHA256 gerado\"\n\nISO_SIZE_FINAL=$(ls -lh \"$ISO_NAME\" | awk '{print $5}')\nISO_SIZE_BYTES=$(stat -c%s \"$ISO_NAME\" 2>/dev/null || echo 0)\nBUILD_TOTAL=$(($(date +%s) - BUILD_START))\nBUILD_MIN=$((BUILD_TOTAL / 60))\nBUILD_SEC=$((BUILD_TOTAL % 60))\n\nlog_step_footer $CURRENT_STEP\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n# RESUMO FINAL\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\ngerar_resumo_final\n\necho -e \"  ${BOLD}Base:${NC}     OracleLinux-R9-U8-x86_64-boot.iso\"\necho -e \"  ${BOLD}Boot:${NC}     UEFI + MBR (BIOS)\"\necho -e \"  ${BOLD}Desktop:${NC}  XFCE\"\necho -e \"  ${BOLD}Offline:${NC}  SIM \u2014 $RPM_COUNT RPMs embutidos\"\necho \"\"\necho -e \"  ${BOLD}Opcoes de boot:${NC}\"\necho -e \"    1) Install Oracle Linux 9.8.0\"\necho -e \"    2) Instalar com Kickstart (auto, XFCE)\"\necho -e \"    3) Test this media & install\"\necho -e \"    4) Text mode / Rescue\"\necho \"\"\necho -e \"  ${BOLD}Pos-install:${NC}\"\necho -e \"    update-appimages.sh   # Brave, VSCodium, Chromium, OpenCode\"\necho -e \"    ol9-setup             # EPEL + RPM Fusion + codecs\"\necho -e \"    otimizar-xfce         # Otimizar XFCE\"\necho \"\"\necho -e \"  ${BOLD}Tempo:${NC}    ${BUILD_MIN}m ${BUILD_SEC}s\"\necho -e \"  ${BOLD}Log:${NC}      $LOG_FILE\"\necho \"\"\n", "build_ol9_openbox_offline.sh": "#!/bin/bash\n#============================================================\n# Script: build_ol9_openbox_offline.sh\n# Objetivo: Corrigir OL9-Offline-Completa.iso instalando\n#           Openbox como ambiente padr\u00e3o (auto-login), com\n#           pacotes para Wi-Fi autom\u00e1tico. 100% offline.\n#\n# Pr\u00e9-requisitos: dnf, sudo, createrepo_c, xorriso\n# Uso: sudo bash build_ol9_openbox_offline.sh\n#============================================================\nset -euo pipefail\n\n# ============================================================\n# CONFIGURA\u00c7\u00c3O\n# ============================================================\nISO_SRC=\"/mnt/iso_ol9\"\nISO_ORIGEM=\"/home/wander/ISO/OL9-Offline-Completa.iso\"\nISO_DESTINO=\"/home/wander/ISO/OL9-Offline-Completa.iso\"\nISO_STAGING=\"/tmp/ol9_openbox_build/OL9-Openbox-Offline-Completa.iso\"\nWORK_DIR=\"/tmp/ol9_openbox_build\"\nINSTALLROOT=\"${WORK_DIR}/installroot\"\nPKGDIR=\"${WORK_DIR}/Packages\"\nVOLUME_ID=\"OL9_OFFLINE_OPENBOX\"\n\nGREEN='\\033[0;32m'\nRED='\\033[0;31m'\nYELLOW='\\033[1;33m'\nCYAN='\\033[0;36m'\nNC='\\033[0m'\n\nlog()   { echo -e \"${CYAN}[$(date +%H:%M:%S)]${NC} $1\"; }\nok()    { echo -e \"${GREEN}[$(date +%H:%M:%S)] OK:${NC} $1\"; }\nwarn()  { echo -e \"${YELLOW}[$(date +%H:%M:%S)] WARN:${NC} $1\"; }\nerr()   { echo -e \"${RED}[$(date +%H:%M:%S)] ERRO:${NC} $1\"; }\nfatal() { err \"$1\"; exit 1; }\n\n[[ $EUID -ne 0 ]] && fatal \"Execute como root: sudo bash $0\"\n[[ ! -d \"$ISO_SRC\" ]] && fatal \"Monte a ISO fonte em $ISO_SRC (mount -o loop $ISO_ORIGEM $ISO_SRC)\"\n\nfor cmd in dnf createrepo_c xorriso; do\n    command -v \"$cmd\" &>/dev/null || fatal \"Depend\u00eancia '$cmd' n\u00e3o encontrada.\"\ndone\n[[ -f /usr/share/syslinux/isohdpfx.bin ]] || fatal \"Falta /usr/share/syslinux/isohdpfx.bin\"\n\nlog \"=========================================\"\nlog \"  REBUILD OL9 OPENBOX OFFLINE\"\nlog \"=========================================\"\nlog \"ISO fonte:   $ISO_ORIGEM\"\nlog \"Volume ID:   $VOLUME_ID\"\nlog \"\"\n\n# ============================================================\n# ETAPA 1: Limpeza e prepara\u00e7\u00e3o\n# ============================================================\nlog \"ETAPA 1/8: Limpeza e prepara\u00e7\u00e3o...\"\npkill -9 -f \"dnf.*installroot\" 2>/dev/null || true\nsleep 1\nrm -rf \"$WORK_DIR\"\nmkdir -p \"$WORK_DIR\" \"$PKGDIR\"\nok \"Ambiente preparado em $WORK_DIR\"\n\n# ============================================================\n# ETAPA 2: Copiar estrutura base da ISO (exceto Packages antigo)\n# ============================================================\nlog \"ETAPA 2/8: Copiando estrutura base da ISO...\"\nfor item in \"$ISO_SRC\"/*; do\n    base=$(basename \"$item\")\n    [[ \"$base\" == \"Packages\" ]] && continue\n    cp -a \"$item\" \"$WORK_DIR/\"\ndone\nmkdir -p \"$WORK_DIR/Packages\"\nok \"Estrutura base copiada\"\n\n# ============================================================\n# ETAPA 3: Copiar pacotes do ISO XFCE (reuso, base completa)\n# ============================================================\n# O ISO XFCE (OL9-XFCE-Offline-Completa.iso) j\u00e1 cont\u00e9m os RPMs\n# dos grupos base (@core @base @base-x @hardware-support).\n# Reutilizamos para evitar rebaixar ~1.5GB da internet.\nXFCE_PKG=\"/mnt/iso_xfce/Packages\"\nif [ -d \"$XFCE_PKG\" ]; then\n    log \"ETAPA 3/8: Reutilizando pacotes base do ISO XFCE...\"\n    cp -a \"$XFCE_PKG\"/. \"$PKGDIR/\"\n    # Remove repodata antigo (ser\u00e1 regenerado)\n    rm -rf \"$PKGDIR/repodata\"\n    ok \"Copiados $(ls \"$PKGDIR\"/*.rpm 2>/dev/null | wc -l) RPMs do ISO XFCE\"\nelse\n    log \"ETAPA 3/8: ISO XFCE n\u00e3o montado; pacotes base vir\u00e3o via dnf.\"\nfi\n\n# ============================================================\n# ETAPA 4: Baixar pacotes extras (openbox + wifi) via dnf\n# ============================================================\nlog \"ETAPA 4/8: Baixando pacotes extras via dnf download --resolve...\"\n\ndnf download \\\n    --destdir=\"$PKGDIR\" \\\n    --resolve \\\n    --alldeps \\\n    --setopt=install_weak_deps=False \\\n    --disablerepo=ol9_UEKR7,ol9_codeready_builder \\\n    --exclude='kernel-uek*' \\\n    openbox tint2 xcompmgr polkit-gnome network-manager-applet \\\n    wmctrl xdotool xterm 2>&1 | grep -vE '^$|Falha ao carregar' || true\n\nif ! ls \"$PKGDIR\"/openbox-*.rpm >/dev/null 2>&1; then\n    fatal \"openbox n\u00e3o dispon\u00edvel em Packages. Verifique os reposit\u00f3rios.\"\nfi\n\nTOTAL=$(ls \"$PKGDIR\"/*.rpm 2>/dev/null | wc -l)\nSIZE=$(du -sh \"$PKGDIR\" | cut -f1)\nok \"Total no Packages/: $TOTAL RPMs, $SIZE\"\n\n# ============================================================\n# ETAPA 5: Gerar repodata (com grupos comps.xml)\n# ============================================================\nlog \"ETAPA 5/8: Gerando repodata (grupos comps.xml)...\"\n\n# Comps (grupos @core @base @base-x @hardware-support) vindos do cache do host\nBASEOS_COMPS=$(ls /var/cache/dnf/ol9_baseos_latest-*/repodata/*-comps.xml.gz 2>/dev/null | head -1)\nAPPSTREAM_COMPS=$(ls /var/cache/dnf/ol9_appstream-*/repodata/*-comps.xml.gz 2>/dev/null | head -1)\n\nif [[ -n \"$BASEOS_COMPS\" && -n \"$APPSTREAM_COMPS\" ]]; then\n    zcat \"$BASEOS_COMPS\" > \"$WORK_DIR/comps_baseos.xml\"\n    zcat \"$APPSTREAM_COMPS\" > \"$WORK_DIR/comps_appstream.xml\"\n    python3 << 'PYEOF'\nimport re\nimport xml.etree.ElementTree as ET\n\ndef load(path):\n    data = open(path).read()\n    data = re.sub(r'<!DOCTYPE[^>]*>', '', data)\n    return ET.fromstring(data)\n\ndef ids(root, tag):\n    return [el.findtext('id') for el in root.findall(tag)]\n\ncomps = ET.Element('comps')\nb = load('/tmp/ol9_openbox_build/comps_baseos.xml')\na = load('/tmp/ol9_openbox_build/comps_appstream.xml')\n\nfor tag in ('group', 'category', 'environment'):\n    seen = set(ids(comps, tag))\n    for src in (b, a):\n        for el in src.findall(tag):\n            ident = el.findtext('id')\n            if ident not in seen:\n                seen.add(ident)\n                comps.append(el)\nlp = b.find('langpacks')\nif lp is not None:\n    comps.append(lp)\n\ntree = ET.ElementTree(comps)\ntree.write('/tmp/ol9_openbox_build/comps_merged.xml', encoding='UTF-8', xml_declaration=True)\nPYEOF\n    createrepo_c --database --groupfile \"$WORK_DIR/comps_merged.xml\" \"$PKGDIR\"\nelse\n    warn \"comps.xml n\u00e3o encontrado no cache; grupos kickstart podem falhar\"\n    createrepo_c --database \"$PKGDIR\"\nfi\nok \"Repodata criada\"\n\n# ============================================================\n# ETAPA 6: Atualizar ks.cfg (Openbox padr\u00e3o, auto-login, wifi)\n# ============================================================\nlog \"ETAPA 6/8: Gravando ks.cfg...\"\n\ncat > \"$WORK_DIR/ks.cfg\" << 'KSEOF'\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\nbootloader --location=mbr --driveorder=sda\n\nrepo --name=\"Packages\" --baseurl=file:///run/install/repo/Packages --noverifyssl\n\nnetwork --bootproto=dhcp --activate\n\nuser --name=oracle --password=oracle --plaintext\nrootpw --lock\n\nservices --enabled=\"chronyd,sshd,bluetooth,NetworkManager\"\n\nreboot\n\n%packages\n@core\n@base\n@base-x\n@hardware-support\n\n# --- Openbox (ambiente padr\u00e3o, leve) ---\nopenbox\ntint2\nxcompmgr\npolkit-gnome\nwmctrl\nxdotool\nxorg-x11-xinit\n\n# --- Aplicativos ---\nxfce4-terminal\nxterm\nthunar\nthunar-volman\ngvfs\n\n# --- Kernel e Boot ---\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\n\n# --- Bluetooth ---\nbluez\n\n# --- Rede e Wireless (Wi-Fi autom\u00e1tico) ---\nNetworkManager-wifi\nNetworkManager-tui\nwpa_supplicant\niw\n\n# --- Sistema e Utilit\u00e1rios ---\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\n\n# --- \u00c1udio ---\nalsa-utils\npipewire\npipewire-pulseaudio\n\n# --- Desenvolvimento ---\nmake\ngcc\nrpm-build\ntar\ngzip\npython3\n\n# --- Monitoramento ---\nhtop\nlm_sensors\n\n# --- Navegador ---\nchromium\n\n# --- Excluir pacotes indesejados ---\n-dnf-plugin-spacewalk\n-rhn-client-tools\n-rhn-setup\n-rhnlib\n-rhnsd\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\nset -x\n\nhostnamectl set-name oracle-openbox\n\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\nsystemctl enable NetworkManager\n\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\n# =============================================\n# Auto-login do usu\u00e1rio oracle no tty1\n# =============================================\nmkdir -p /etc/systemd/system/getty@tty1.service.d\ncat > /etc/systemd/system/getty@tty1.service.d/override.conf << 'TEOF'\n[Service]\nExecStart=\nExecStart=-/sbin/agetty --autologin oracle --noclear tty1 $TERM\nTEOF\nsystemctl daemon-reload\n\n# =============================================\n# Sess\u00e3o X: startx -> openbox-session (dbus)\n# =============================================\ncat > /etc/skel/.bash_profile << 'BEOF'\nif [ -z \"$DISPLAY\" ] && [ \"${XDG_VTNR:-}\" = \"1\" ]; then\n    exec startx\nfi\nBEOF\n\ncat > /etc/skel/.xinitrc << 'XEOF'\n#!/bin/sh\nif [ -x /usr/bin/dbus-launch ]; then\n    exec dbus-launch --exit-with-session openbox-session\nelse\n    exec openbox-session\nfi\nXEOF\n\n# Aplica ao usu\u00e1rio oracle (j\u00e1 criado pelo kickstart)\ncp -f /etc/skel/.bash_profile /home/oracle/.bash_profile\ncp -f /etc/skel/.xinitrc /home/oracle/.xinitrc\nchown oracle:oracle /home/oracle/.bash_profile /home/oracle/.xinitrc\n\n# =============================================\n# Openbox: autostart (painel, wifi, compositor, polkit)\n# =============================================\ncat > /etc/xdg/openbox/autostart << 'AEOF'\n# Compositor leve\nxcompmgr &\n# Painel/taskbar (fornece a bandeja de sistema)\ntint2 &\n# Agente de autentica\u00e7\u00e3o (polkit)\nif [ -x /usr/libexec/polkit-gnome-authentication-agent-1 ]; then\n    /usr/libexec/polkit-gnome-authentication-agent-1 &\nfi\n# Applet de rede (Wi-Fi na bandeja)\nif [ -x /usr/bin/nm-applet ]; then\n    nm-applet &\nfi\n# Fundo de tela simples\nif [ -x /usr/bin/xsetroot ]; then\n    xsetroot -solid \"#2E3440\" &\nfi\nAEOF\n\n# =============================================\n# Menu do Openbox (est\u00e1tico e funcional)\n# =============================================\ncat > /etc/xdg/openbox/menu.xml << 'MEOF'\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<openbox_menu xmlns=\"http://openbox.org/3.4/menu\">\n  <menu id=\"root-menu\" label=\"Menu\">\n    <item label=\"Terminal\">\n      <action name=\"Execute\"><command>xfce4-terminal</command></action>\n    </item>\n    <item label=\"Gerenciador de Arquivos\">\n      <action name=\"Execute\"><command>thunar</command></action>\n    </item>\n    <item label=\"Navegador Chromium\">\n      <action name=\"Execute\"><command>chromium</command></action>\n    </item>\n    <separator/>\n    <item label=\"Configurar Wi-Fi (nmtui)\">\n      <action name=\"Execute\"><command>xfce4-terminal -e nmtui</command></action>\n    </item>\n    <item label=\"Monitor do Sistema (htop)\">\n      <action name=\"Execute\"><command>xfce4-terminal -e htop</command></action>\n    </item>\n    <separator/>\n    <item label=\"Reiniciar Openbox\">\n      <action name=\"Restart\"/>\n    </item>\n    <item label=\"Sair\">\n      <action name=\"Exit\"/>\n    </item>\n  </menu>\n</openbox_menu>\nMEOF\n\n# =============================================\n# Wi-Fi autom\u00e1tico: NetworkManager + powersave off\n# =============================================\ncat > /etc/NetworkManager/conf.d/wifi-powersave.conf << 'NMEOF'\n[connection]\nwifi.powersave = 2\nNMEOF\n\ncat > /etc/NetworkManager/conf.d/autoconnect.conf << 'NMOF'\n[connection]\nautoconnect = true\n[main]\nautoconnect = true\nNMOF\n\nsystemctl enable NetworkManager-wait-online.service 2>/dev/null || true\n\n# =============================================\n# Copiar scripts/conte\u00fado do disco instalador\n# =============================================\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    for SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n        if [ -f \"/mnt/media/content/$SCRIPT\" ]; then\n            rsync -a \"/mnt/media/content/$SCRIPT\" /usr/local/bin/\n            chmod +x \"/usr/local/bin/$SCRIPT\"\n        fi\n    done\n\n    for DIR in system_scripts vm_scripts bluetooth; do\n        if [ -d \"/mnt/media/content/$DIR\" ]; then\n            rsync -av \"/mnt/media/content/$DIR/\" \"/opt/$DIR/\"\n            chmod -R +x \"/opt/$DIR/\" 2>/dev/null || true\n        fi\n    done\n\n    if [ -d /mnt/media/Packages ]; then\n        mkdir -p /opt/local_repo\n        rsync -a /mnt/media/Packages/ /opt/local_repo/\n        if [ -d /mnt/media/Packages/repodata ]; then\n            rsync -a /mnt/media/Packages/repodata/ /opt/local_repo/repodata/\n        fi\n        cat > /etc/yum.repos.d/ol9-local-offline.repo << 'REPOEOF'\n[ol9_local_offline]\nname=Oracle Linux 9 Local Offline\nbaseurl=file:///opt/local_repo/\nenabled=1\ngpgcheck=0\nREPOEOF\n    fi\n\n    if [ -d /mnt/media/content/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/content/favoritos/ /etc/skel/favoritos/\n        mkdir -p /home/oracle/favoritos\n        rsync -av /mnt/media/content/favoritos/ /home/oracle/favoritos/\n        chown -R oracle:oracle /home/oracle/favoritos 2>/dev/null || true\n    fi\n\n    if [ -f /mnt/media/content/checksums.txt ]; then\n        cd /mnt/media/content && sha256sum -c checksums.txt 2>/dev/null || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\n# Aliases \u00fateis\ncat > /etc/profile.d/openbox.sh << 'PEOF'\nalias wifi='nmcli dev wifi list'\nalias wifi-on='nmcli radio wifi on'\nalias wifi-off='nmcli radio wifi off'\nalias wifi-config='nmtui'\nPEOF\n\nln -sf /opt/system_scripts/ol9-full-setup.sh /usr/local/bin/ol9-setup 2>/dev/null || true\n\necho \"Instalacao offline Openbox concluida: $(date)\" > /root/INSTALL_OK\n%end\nKSEOF\n\nok \"ks.cfg gravado\"\n\n# ============================================================\n# ETAPA 7: Atualizar isolinux.cfg e grub (novo label)\n# ============================================================\nlog \"ETAPA 7/8: Atualizando configura\u00e7\u00f5es de boot...\"\n\nOLD_LABEL=\"OL9_OFFLINE_XFCE\"\nNEW_LABEL=\"OL9_OFFLINE_OPENBOX\"\n\n# isolinux.cfg\nsed -i \"s/$OLD_LABEL/$NEW_LABEL/g\" \"$WORK_DIR/isolinux/isolinux.cfg\"\nsed -i 's/Instalar com Kickstart (auto, XFCE)/Instalar com Kickstart (auto, Openbox)/' \"$WORK_DIR/isolinux/isolinux.cfg\"\n\n# EFI grub.cfg\nsed -i \"s/$OLD_LABEL/$NEW_LABEL/g\" \"$WORK_DIR/EFI/BOOT/grub.cfg\"\nsed -i 's/Instalar com Kickstart (auto, XFCE)/Instalar com Kickstart (auto, Openbox)/' \"$WORK_DIR/EFI/BOOT/grub.cfg\"\n\n# efiboot.img (imagem FAT com pr\u00f3prio grub.cfg)\nEFIBOOT=\"$WORK_DIR/images/efiboot.img\"\nEFI_MNT=\"$WORK_DIR/efiboot_mnt\"\nmkdir -p \"$EFI_MNT\"\nmount -o loop \"$EFIBOOT\" \"$EFI_MNT\"\nsed -i \"s/$OLD_LABEL/$NEW_LABEL/g\" \"$EFI_MNT/EFI/BOOT/grub.cfg\"\nsed -i 's/Instalar com Kickstart (auto, XFCE)/Instalar com Kickstart (auto, Openbox)/' \"$EFI_MNT/EFI/BOOT/grub.cfg\"\numount \"$EFI_MNT\"\nrmdir \"$EFI_MNT\"\nok \"Boot configs atualizados para $NEW_LABEL\"\n\n# ============================================================\n# ETAPA 8: Gerar nova ISO com xorriso\n# ============================================================\nlog \"ETAPA 8/8: Gerando nova ISO com xorriso...\"\n\nISO_SIZE=$(du -sb \"$WORK_DIR\" | cut -f1)\nISO_SIZE_GB=$(echo \"scale=2; $ISO_SIZE / 1073741824\" | bc)\nlog \"  Tamanho estimado da ISO: ${ISO_SIZE_GB}GB\"\n\nxorriso -as mkisofs \\\n    -iso-level 3 \\\n    -full-iso9660-filenames \\\n    -volid \"$VOLUME_ID\" \\\n    -output \"$ISO_STAGING\" \\\n    -eltorito-boot isolinux/isolinux.bin \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        --eltorito-catalog isolinux/boot.cat \\\n    -eltorito-alt-boot \\\n        -e images/efiboot.img \\\n        -no-emul-boot \\\n        -isohybrid-gpt-basdat \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    \"$WORK_DIR\"\n\nok \"ISO gerada em $ISO_STAGING\"\n\n# ============================================================\n# LIMPEZA E RELAT\u00d3RIO FINAL\n# ============================================================\nFINAL_SIZE=$(du -h \"$ISO_STAGING\" | cut -f1)\nFINAL_RPMS=$(ls \"$PKGDIR\"/*.rpm 2>/dev/null | wc -l)\n\necho \"\"\nlog \"=========================================\"\nlog \"  CONSTRU\u00c7\u00c3O CONCLU\u00cdDA (staging)\"\nlog \"=========================================\"\nlog \"ISO:          $ISO_STAGING\"\nlog \"Tamanho:      $FINAL_SIZE\"\nlog \"Pacotes:      $FINAL_RPMS RPMs\"\nlog \"Volume ID:    $VOLUME_ID\"\nlog \"=========================================\"\nlog \"Agora substitua a ISO original com:\"\nlog \"  mv $ISO_STAGING $ISO_DESTINO\"\nlog \"=========================================\"\n", "cache-guard.sh": "#!/usr/bin/env bash\n# =============================================================================\n# cache-guard.sh \u2014 Prote\u00e7\u00e3o de mem\u00f3ria e libera\u00e7\u00e3o AUTOM\u00c1TICA de cache\n# -----------------------------------------------------------------------------\n# Alvo: Oracle Linux 9.8 / UEK 6.12 / systemd 252 / cgroup v2 / 2 CPUs / 3.3 GB\n#\n# Objetivo: impedir que UMA aplica\u00e7\u00e3o (navegador, editor, llama.cpp, opencode)\n# bloqueie o desempenho do sistema inteiro por press\u00e3o de mem\u00f3ria.\n#\n# Estrat\u00e9gia em 4 camadas:\n#   1) Limites por cgroup no app.slice   -> o kernel faz reclaim autom\u00e1tico de\n#                                            cache e estrangula o app (MemoryHigh)\n#                                            antes de derrubar o sistema.\n#   2) Watchdog nativo (este script)     -> sob press\u00e3o, libera cache via\n#                                            memory.reclaim do cgroup culpado e,\n#                                            em \u00faltimo caso, encerra S\u00d3 esse app.\n#   3) PSI + systemd-oomd (root)         -> rede de seguran\u00e7a do kernel/sistema.\n#   4) Helpers: run (roda app com teto), reclaim (libera\u00e7\u00e3o manual), status.\n#\n# Uso:\n#   ./cache-guard.sh user-install     limites (1) + watchdog (2) \u2014 SEM sudo\n#   ./cache-guard.sh user-uninstall\n#   ./cache-guard.sh system-install   PSI + systemd-oomd (3) \u2014 COM sudo + reboot\n#   ./cache-guard.sh system-uninstall\n#   ./cache-guard.sh install          user-install + system-install (sudo)\n#   ./cache-guard.sh status           diagn\u00f3stico do estado atual\n#   ./cache-guard.sh reclaim [bytes]  libera cache AGORA do maior app (padr\u00e3o 256M)\n#   ./cache-guard.sh run <cmd> [...]  roda um app dentro de um scope com teto\n#   ./cache-guard.sh watch            uma passada do watchdog (usado pelo timer)\n#   ./cache-guard.sh work-setup       slice dedicado p/ Edge+Codium+opencode (tetos por app)\n#   ./cache-guard.sh work-status      situa\u00e7\u00e3o dos tetos do work.slice\n#   ./cache-guard.sh work-uninstall   remove slice + atalhos + override do watchdog\n#   ./cache-guard.sh help\n#\n# Vari\u00e1veis (ajust\u00e1veis por env):\n#   GUARD_APP_HIGH=50%       MemoryHigh do app.slice (limite SUAVE = reclaim auto)\n#   GUARD_APP_MAX=80%        MemoryMax do app.slice (limite DURO = \u00faltimo recurso)\n#   GUARD_APP_SWAP_MAX=1G    MemorySwapMax do app.slice (teto de swap dos apps)\n#   GUARD_LOW_MB=300         abaixo disso o watchdog come\u00e7a a agir\n#   GUARD_CRIT_MB=120        abaixo disso o watchdog pode encerrar o app pior\n#   GUARD_RECLAIM_MB=256     quanto de cache liberar por passada\n#   GUARD_KILL=yes|no        permite encerrar o app culpado em caso cr\u00edtico\n#   GUARD_PSI_LIMIT=25       press\u00e3o de mem\u00f3ria (PSI avg10 %) para agir\n#   GUARD_OOMD_SWAP_LIMIT=50%  SwapUsedLimit do systemd-oomd (padr\u00e3o: 50% do swap)\n#   GUARD_WORK_MEM_HIGH=1.3G  MemoryHigh coletivo do work.slice (trio pesado)\n#   GUARD_WORK_MEM_MAX=1.9G   MemoryMax coletivo do work.slice\n#   GUARD_WORK_SWAP_MAX=1G    MemorySwapMax do work.slice\n#   GUARD_WORK_APPS=...       tabela \"funcao|binario|High|Max\" (1 por linha)\n# =============================================================================\n\nset -uo pipefail\n\n# ---- config -----------------------------------------------------------------\nGUARD_APP_HIGH=\"${GUARD_APP_HIGH:-50%}\"\nGUARD_APP_MAX=\"${GUARD_APP_MAX:-80%}\"\nGUARD_APP_SWAP_MAX=\"${GUARD_APP_SWAP_MAX:-1G}\"\nGUARD_LOW_MB=\"${GUARD_LOW_MB:-300}\"\nGUARD_CRIT_MB=\"${GUARD_CRIT_MB:-120}\"\nGUARD_RECLAIM_MB=\"${GUARD_RECLAIM_MB:-256}\"\nGUARD_KILL=\"${GUARD_KILL:-yes}\"\nGUARD_KILL_MIN_MB=\"${GUARD_KILL_MIN_MB:-80}\"     # s\u00f3 encerra app com anon >= isso\nGUARD_KILL_COOLDOWN=\"${GUARD_KILL_COOLDOWN:-60}\" # segundos entre encerramentos\nGUARD_PSI_LIMIT=\"${GUARD_PSI_LIMIT:-25}\"\n# SwapUsedLimit do systemd-oomd: % do swap total a partir do qual o oomd age.\n# Valor baixo (50%) evita thrash no swap de disco (4,9G) nesta maquina.\nGUARD_OOMD_SWAP_LIMIT=\"${GUARD_OOMD_SWAP_LIMIT:-50%}\"\n\n# ---- work.slice: trio pesado (Edge + VSCodium + opencode) ------------------\nGUARD_WORK_SLICE=\"${GUARD_WORK_SLICE:-work.slice}\"\nGUARD_WORK_MEM_HIGH=\"${GUARD_WORK_MEM_HIGH:-1.3G}\"\nGUARD_WORK_MEM_MAX=\"${GUARD_WORK_MEM_MAX:-1.9G}\"\nGUARD_WORK_SWAP_MAX=\"${GUARD_WORK_SWAP_MAX:-1G}\"\n# formato por linha: <funcao>|<binario>|<MemoryHigh>|<MemoryMax>\nGUARD_WORK_APPS=\"${GUARD_WORK_APPS:-edge|microsoft-edge|450M|700M\ncodium|codium|450M|700M\nopencode|opencode|700M|1G}\"\n\n# Nunca encerrar: shell/desktop/sess\u00e3o e componentes do pr\u00f3prio sistema.\nGUARD_PROTECT=\"${GUARD_PROTECT:-gnome-shell|Xorg|gnome-session|session-manager|gdm|dbus|systemd|pipewire|wireplumber|xdg-desktop-portal|gvfs|evolution|gsd-|goa-|cache-guard|spawn-|dwarfs|tracker|ibus}\"\n\nSTATE_FILE=\"${XDG_RUNTIME_DIR:-/tmp}/cache-guard.state\"\n\nSELF=\"$(readlink -f \"$0\")\"\nSCRIPT_DIR=\"$(dirname \"$SELF\")\"\n\nUSER_UNIT_DIR=\"$HOME/.config/systemd/user\"\nAPP_SLICE_DROPIN=\"$USER_UNIT_DIR/app.slice.d/50-cache-guard.conf\"\nWATCH_SERVICE=\"$USER_UNIT_DIR/cache-guard-watch.service\"\nWATCH_TIMER=\"$USER_UNIT_DIR/cache-guard-watch.timer\"\n\nOOMD_CFG_DIR=/etc/systemd/oomd.conf.d\nOOMD_CFG=\"$OOMD_CFG_DIR/50-cache-guard.conf\"\nOOMD_USER_DROPIN=/etc/systemd/system/user@.service.d/50-cache-guard-oomd.conf\nGRUB_FILE=/etc/default/grub\nKCMD=/etc/kernel/cmdline\n\n# ---- helpers ----------------------------------------------------------------\nsay()  { printf '\\033[1;36m== %s\\033[0m\\n' \"$*\"; }\nok()   { printf '\\033[1;32m   %s\\033[0m\\n' \"$*\"; }\nwarn() { printf '\\033[1;33mAVISO: %s\\033[0m\\n' \"$*\" >&2; }\ndie()  { printf '\\033[1;31mERRO: %s\\033[0m\\n' \"$*\" >&2; exit 1; }\nlog()  { printf '[%s] %s\\n' \"$(date '+%F %T')\" \"$*\"; logger -t cache-guard -p daemon.notice -- \"$*\" 2>/dev/null || true; }\n\nneed_root() { [ \"$(id -u)\" -eq 0 ] || die \"execute com sudo:  sudo $0 ${1:-}\"; }\nasroot()    { if [ \"$(id -u)\" -eq 0 ]; then \"$@\"; else sudo \"$@\"; fi; }\nhas()       { command -v \"$1\" >/dev/null 2>&1; }\n\nmeminfo() { awk -v k=\"$1:\" '$1==k{print $2}' /proc/meminfo; }\nmb()      { echo $(( ${1:-0} / 1024 )); }\nunit_active()  { systemctl is-active  --quiet \"$1\" 2>/dev/null && echo active   || echo inactive; }\nunit_active_u(){ systemctl --user is-active  --quiet \"$1\" 2>/dev/null && echo active   || echo inactive; }\nunit_state()   { local s; s=\"$(systemctl is-enabled \"$1\" 2>/dev/null)\"; echo \"${s:-n/a}\"; }\nunit_state_u() { local s; s=\"$(systemctl --user is-enabled \"$1\" 2>/dev/null)\"; echo \"${s:-n/a}\"; }\n\n# raiz do cgroup do usu\u00e1rio atual\nuser_cg() { printf '/sys/fs/cgroup/user.slice/user-%s.slice/user@%s.service' \"$(id -u)\" \"$(id -u)\"; }\n\npsi_mem_avg10() {\n  [ -r /proc/pressure/memory ] || return 0\n  sed -n 's/^some .*avg10=\\([0-9.]*\\).*/\\1/p' /proc/pressure/memory\n}\n\n# cgroup de app com maior valor da chave (file|anon|slab) dentro do app.slice\nbiggest_app_cgroup() {\n  local key=\"$1\" base worst_val=0 worst=\"\" d val\n  base=\"$(user_cg)/app.slice\"\n  [ -d \"$base\" ] || return 0\n  shopt -s nullglob\n  for d in \"$base\"/*/; do\n    [ -r \"$d/memory.stat\" ] || continue\n    val=$(awk -v k=\"$key\" '$1==k{print $2}' \"$d/memory.stat\" 2>/dev/null)\n    [ -n \"${val:-}\" ] || continue\n    if [ \"$val\" -gt \"$worst_val\" ]; then worst_val=\"$val\"; worst=\"${d%/}\"; fi\n  done\n  shopt -u nullglob\n  [ -n \"$worst\" ] && printf '%s' \"$worst\"\n}\n\n# nome de unit do systemd usa \\xNN para escapar (ex.: app-gnome\\x2dsession\\x2dmanager)\nunescape_name() { printf '%s' \"$1\" | sed -e 's/\\\\x2d/-/g' -e 's/\\\\x2e/./g' -e 's/\\\\x20/ /g'; }\n\n# cgroup de app que pode ser encerrado (maior anon, respeitando a prote\u00e7\u00e3o)\nbiggest_killable_cgroup() {\n  local base worst_val=0 worst=\"\" d val name name_d min_kb\n  min_kb=$(( GUARD_KILL_MIN_MB * 1024 ))\n  base=\"$(user_cg)/app.slice\"\n  [ -d \"$base\" ] || return 0\n  shopt -s nullglob\n  for d in \"$base\"/*/; do\n    [ -r \"$d/memory.stat\" ] || continue\n    name=\"$(basename \"$d\")\"\n    name_d=\"$(unescape_name \"$name\")\"\n    printf '%s' \"$name_d\" | grep -qiE \"$GUARD_PROTECT\" && continue\n    val=$(awk -v k=\"anon\" '$1==k{print $2}' \"$d/memory.stat\" 2>/dev/null)\n    [ -n \"${val:-}\" ] || continue\n    # s\u00f3 considera candidato se tiver mem\u00f3ria an\u00f4nima relevante (evita matar app pequeno)\n    [ \"$val\" -lt \"$min_kb\" ] && continue\n    if [ \"$val\" -gt \"$worst_val\" ]; then worst_val=\"$val\"; worst=\"${d%/}\"; fi\n  done\n  shopt -u nullglob\n  [ -n \"$worst\" ] && printf '%s' \"$worst\"\n}\n\n# encerra todos os processos de um cgroup (preferindo cgroup.kill do kernel)\nkill_cgroup() {\n  local cg=\"$1\" p\n  if [ -w \"$cg/cgroup.kill\" ]; then\n    echo 1 > \"$cg/cgroup.kill\" 2>/dev/null && return 0\n  fi\n  for p in $(cat \"$cg/cgroup.procs\" 2>/dev/null); do kill -TERM \"$p\" 2>/dev/null || true; done\n  sleep 2\n  for p in $(cat \"$cg/cgroup.procs\" 2>/dev/null); do kill -KILL \"$p\" 2>/dev/null || true; done\n}\n\n# =============================================================================\n# CAMADA 2 \u2014 watchdog: libera cache sob press\u00e3o (usado pelo timer do usu\u00e1rio)\n# =============================================================================\ncmd_watch() {\n  local avail_kb low_kb crit_kb psi pressured=no worst bytes\n  low_kb=$(( GUARD_LOW_MB * 1024 ))\n  crit_kb=$(( GUARD_CRIT_MB * 1024 ))\n  avail_kb=$(meminfo MemAvailable)\n  psi=\"$(psi_mem_avg10)\"\n\n  # ---- guarda-corpo: NUNCA agir com leitura inv\u00e1lida de mem\u00f3ria -------------\n  case \"${avail_kb:-}\" in\n    ''|*[!0-9]*) log \"MemAvailable inv\u00e1lido ('${avail_kb:-}'); abortando por seguran\u00e7a\"; return 0 ;;\n  esac\n  [ \"$avail_kb\" -gt 0 ] || { log \"MemAvailable=0 (leitura suspeita); abortando por seguran\u00e7a\"; return 0; }\n\n  if [ -n \"$psi\" ] && awk -v p=\"$psi\" -v l=\"$GUARD_PSI_LIMIT\" 'BEGIN{exit !(p>l)}'; then\n    pressured=yes\n  fi\n\n  # Sem press\u00e3o e com RAM suficiente: nada a fazer (silencioso).\n  if [ \"$avail_kb\" -ge \"$low_kb\" ] && [ \"$pressured\" = no ]; then\n    return 0\n  fi\n\n  log \"press\u00e3o: MemAvailable=$(mb \"$avail_kb\")MB psi=${psi:-n/a} -> liberando cache\"\n\n  worst=\"$(biggest_app_cgroup file)\"\n  if [ -n \"$worst\" ]; then\n    bytes=\"${GUARD_RECLAIM_MB}M\"\n    if echo \"$bytes\" > \"$worst/memory.reclaim\" 2>/dev/null; then\n      log \"reclaim $bytes de $(basename \"$worst\")\"\n    fi\n  fi\n\n  avail_kb=$(meminfo MemAvailable)\n  case \"${avail_kb:-}\" in ''|*[!0-9]*) return 0 ;; esac\n  [ \"$avail_kb\" -ge \"$crit_kb\" ] && return 0\n  [ \"$GUARD_KILL\" = yes ] || return 0\n\n  # ---- cooldown: n\u00e3o encerra mais de um app a cada N segundos --------------\n  local now last=0\n  now=$(date +%s)\n  if [ -f \"$STATE_FILE\" ]; then\n    read -r last _ < \"$STATE_FILE\" 2>/dev/null || last=0\n    case \"${last:-0}\" in ''|*[!0-9]*) last=0 ;; esac\n  fi\n  if [ $(( now - last )) -lt \"$GUARD_KILL_COOLDOWN\" ]; then\n    log \"cr\u00edtico, mas em cooldown (\u00faltima a\u00e7\u00e3o h\u00e1 $(( now - last ))s)\"\n    return 0\n  fi\n\n  # Ainda cr\u00edtico: encerra S\u00d3 o app culpado (maior mem\u00f3ria an\u00f4nima).\n  worst=\"$(biggest_killable_cgroup)\"\n  if [ -n \"$worst\" ]; then\n    log \"CR\u00cdTICO: encerrando $(basename \"$worst\") (MemAvailable=$(mb \"$avail_kb\")MB)\"\n    kill_cgroup \"$worst\"\n    printf '%s %s\\n' \"$now\" \"$(basename \"$worst\")\" > \"$STATE_FILE\" 2>/dev/null || true\n  fi\n  return 0\n}\n\n# =============================================================================\n# CAMADA 1 \u2014 limites per-app (app.slice) + timer do watchdog  [SEM sudo]\n# =============================================================================\ninstall_watch_timer() {\n  mkdir -p \"$USER_UNIT_DIR\"\n  cat > \"$WATCH_SERVICE\" <<EOF\n[Unit]\nDescription=cache-guard \u2014 watchdog de mem\u00f3ria (libera\u00e7\u00e3o autom\u00e1tica de cache)\n\n[Service]\nType=oneshot\nExecStart=$SELF watch\nNice=10\nIOSchedulingClass=best-effort\nIOSchedulingPriority=6\nEOF\n\n  cat > \"$WATCH_TIMER\" <<EOF\n[Unit]\nDescription=cache-guard \u2014 watchdog de mem\u00f3ria (timer)\n\n[Timer]\nOnBootSec=2min\nOnUnitActiveSec=30s\nAccuracySec=5s\n\n[Install]\nWantedBy=timers.target\nEOF\n\n  systemctl --user daemon-reload\n  systemctl --user enable --now cache-guard-watch.timer >/dev/null 2>&1 || true\n}\n\ncmd_user_install() {\n  say \"Camada 1 \u2014 limites do app.slice (sem sudo)\"\n  mkdir -p \"$USER_UNIT_DIR/app.slice.d\"\n  cat > \"$APP_SLICE_DROPIN\" <<EOF\n# cache-guard.sh \u2014 teto coletivo de mem\u00f3ria para os apps do usu\u00e1rio.\n# MemoryHigh: limite SUAVE -> o kernel libera cache do app e o estrangula\n#             antes de comprometer o sistema. \u00c9 o \"reclaim autom\u00e1tico\".\n# MemoryMax : limite DURO -> \u00faltimo recurso (OOM s\u00f3 dentro do app.slice).\n# MemorySwapMax: impede que os apps entupam o zram/swap (evita thrashing).\n[Slice]\nMemoryHigh=$GUARD_APP_HIGH\nMemoryMax=$GUARD_APP_MAX\nMemorySwapMax=$GUARD_APP_SWAP_MAX\nEOF\n  systemctl --user daemon-reload\n  # aplica j\u00e1 em runtime (sem reiniciar sess\u00e3o)\n  if systemctl --user set-property app.slice \\\n        MemoryHigh=\"$GUARD_APP_HIGH\" \\\n        MemoryMax=\"$GUARD_APP_MAX\" \\\n        MemorySwapMax=\"$GUARD_APP_SWAP_MAX\" 2>/dev/null; then\n    ok \"app.slice: MemoryHigh=$GUARD_APP_HIGH MemoryMax=$GUARD_APP_MAX MemorySwapMax=$GUARD_APP_SWAP_MAX\"\n  else\n    warn \"n\u00e3o foi poss\u00edvel aplicar em runtime; valer\u00e1 na pr\u00f3xima sess\u00e3o\"\n  fi\n\n  say \"Camada 2 \u2014 watchdog do usu\u00e1rio (sem sudo)\"\n  install_watch_timer\n  ok \"timer: $(systemctl --user is-enabled cache-guard-watch.timer 2>/dev/null || echo '?')/$(systemctl --user is-active cache-guard-watch.timer 2>/dev/null || echo '?')\"\n\n  echo\n  ok \"Pronto (parte do usu\u00e1rio). Para a camada 3 (sistema):  sudo $SELF system-install\"\n}\n\ncmd_user_uninstall() {\n  say \"Removendo limites e watchdog do usu\u00e1rio\"\n  systemctl --user disable --now cache-guard-watch.timer >/dev/null 2>&1 || true\n  rm -f \"$WATCH_SERVICE\" \"$WATCH_TIMER\" \"$APP_SLICE_DROPIN\"\n  rmdir \"$USER_UNIT_DIR/app.slice.d\" 2>/dev/null || true\n  systemctl --user daemon-reload\n  systemctl --user set-property app.slice MemoryHigh=infinity MemoryMax=infinity MemorySwapMax=infinity 2>/dev/null || true\n  ok \"removido\"\n}\n\n# =============================================================================\n# CAMADA 3 \u2014 PSI + systemd-oomd  [sudo + reboot]\n# =============================================================================\ngrub_add_arg() {\n  local arg=\"$1\" cur new\n  # /etc/default/grub\n  if [ -f \"$GRUB_FILE\" ]; then\n    cur=\"$(sed -n 's/^GRUB_CMDLINE_LINUX=\"\\(.*\\)\"/\\1/p' \"$GRUB_FILE\")\"\n    case \" $cur \" in *\" $arg \"*) : ;; *)\n      new=\"${cur:+$cur }$arg\"\n      cp -a \"$GRUB_FILE\" \"${GRUB_FILE}.bak.cache-guard\" 2>/dev/null || true\n      sed -i \"s|^GRUB_CMDLINE_LINUX=.*|GRUB_CMDLINE_LINUX=\\\"$new\\\"|\" \"$GRUB_FILE\" ;;\n    esac\n  fi\n  # /etc/kernel/cmdline (kernels futuros)\n  if [ -f \"$KCMD\" ]; then\n    cur=\"$(tr '\\n' ' ' < \"$KCMD\")\"\n    case \" $cur \" in *\" $arg \"*) : ;; *)\n      cp -a \"$KCMD\" \"${KCMD}.bak.cache-guard\" 2>/dev/null || true\n      printf '%s\\n' \"$(printf '%s %s' \"$cur\" \"$arg\" | tr -s ' ' | sed 's/^ //; s/ $//')\" > \"$KCMD\" ;;\n    esac\n  fi\n  # BLS (kernel atual)\n  if has grubby; then\n    grubby --update-kernel=ALL --args=\"$arg\" >/dev/null 2>&1 || true\n  fi\n}\n\ncmd_system_install() {\n  need_root system-install\n  say \"Camada 3a \u2014 habilitando PSI na cmdline do kernel (psi=1)\"\n  if grep -q 'psi=1' /proc/cmdline; then\n    ok \"psi=1 j\u00e1 ativo\"\n  else\n    grub_add_arg psi=1\n    ok \"psi=1 adicionado (efetivo ap\u00f3s REBOOT; hoje /proc/pressure n\u00e3o existe)\"\n  fi\n\n  say \"Camada 3b \u2014 instalando systemd-oomd\"\n  if rpm -q systemd-oomd >/dev/null 2>&1; then\n    ok \"systemd-oomd j\u00e1 instalado\"\n  elif has dnf; then\n    dnf -y install systemd-oomd 2>&1 | tail -3\n  else\n    yum -y install systemd-oomd 2>&1 | tail -3\n  fi\n\n  say \"Camada 3c \u2014 limiares do oomd\"\n  mkdir -p \"$OOMD_CFG_DIR\"\n  cat > \"$OOMD_CFG\" <<EOF\n# cache-guard.sh \u2014 limiares do systemd-oomd\n# SwapUsedLimit: com zram de 1G + swap de disco, n\u00e3o deixar o swap passar de 50%\n#                (evita thrash no disco lento antes de o PSI agir).\n# DefaultMemoryPressureLimit/DurationSec: mata o cgroup mais problem\u00e1tico\n# quando a press\u00e3o de mem\u00f3ria (PSI) fica alta por tempo sustentado.\n[OOM]\nSwapUsedLimit=$GUARD_OOMD_SWAP_LIMIT\nDefaultMemoryPressureLimit=55%\nDefaultMemoryPressureDurationSec=20s\nEOF\n  ok \"$OOMD_CFG\"\n\n  say \"Camada 3d \u2014 oomd monitora o user@.service (protege o desktop)\"\n  mkdir -p \"$(dirname \"$OOMD_USER_DROPIN\")\"\n  cat > \"$OOMD_USER_DROPIN\" <<EOF\n# cache-guard.sh \u2014 deixa o systemd-oomd agir sobre a sess\u00e3o do usu\u00e1rio\n[Service]\nManagedOOMMemoryPressure=kill\nManagedOOMMemoryPressureLimit=50%\nManagedOOMSwap=kill\nEOF\n  ok \"$OOMD_USER_DROPIN\"\n\n  systemctl daemon-reload\n  systemctl enable systemd-oomd.service >/dev/null 2>&1 || true\n  if systemctl start systemd-oomd.service 2>/dev/null; then\n    ok \"systemd-oomd ativo\"\n  else\n    warn \"systemd-oomd habilitado, mas s\u00f3 ativa ap\u00f3s REBOOT (precisa do psi=1)\"\n  fi\n  echo\n  ok \"Parte do sistema pronta. Reinicie e confira:  oomctl ; cat /proc/pressure/memory\"\n}\n\ncmd_system_uninstall() {\n  need_root system-uninstall\n  say \"Revertendo camada 3 (sistema)\"\n  rm -f \"$OOMD_CFG\" \"$OOMD_USER_DROPIN\"\n  systemctl disable --now systemd-oomd.service >/dev/null 2>&1 || true\n  if has grubby; then\n    grubby --update-kernel=ALL --remove-args=\"psi=1\" >/dev/null 2>&1 || true\n  fi\n  [ -f \"$GRUB_FILE\" ] && sed -i 's/[[:space:]]\\?psi=1//g' \"$GRUB_FILE\"\n  [ -f \"$KCMD\" ] && sed -i 's/[[:space:]]\\?psi=1//g' \"$KCMD\"\n  systemctl daemon-reload\n  ok \"removido (psi=1 sai no pr\u00f3ximo reboot)\"\n}\n\n# =============================================================================\n# Helpers: reclaim / run / status\n# =============================================================================\ncmd_reclaim() {\n  local bytes=\"${1:-${GUARD_RECLAIM_MB}M}\" worst\n  worst=\"$(biggest_app_cgroup file)\"\n  [ -n \"$worst\" ] || die \"nenhum cgroup de app encontrado em $(user_cg)/app.slice\"\n  if echo \"$bytes\" > \"$worst/memory.reclaim\" 2>/dev/null; then\n    ok \"reclaim $bytes de $(basename \"$worst\")\"\n  else\n    die \"falha ao reclamar de $worst\"\n  fi\n}\n\ncmd_run() {\n  [ $# -gt 0 ] || die \"uso: $0 run <comando> [args...]\"\n  exec systemd-run --user --scope --collect --quiet \\\n    -p MemoryHigh=\"$GUARD_APP_HIGH\" \\\n    -p MemoryMax=\"$GUARD_APP_MAX\" \\\n    -p MemorySwapMax=\"$GUARD_APP_SWAP_MAX\" \\\n    -p ManagedOOMMemoryPressure=kill \\\n    -- \"$@\"\n}\n\ncmd_status() {\n  local avail total psi high max swapmax\n  total=$(meminfo MemTotal); avail=$(meminfo MemAvailable)\n  say \"cache-guard \u2014 status\"\n  printf '   RAM ............. %sMiB total / %sMiB dispon\u00edvel\\n' \"$(mb \"$total\")\" \"$(mb \"$avail\")\"\n  printf '   Swap usado ...... %s\\n' \"$(free -h | awk '/Swap/{print $3\" / \"$2}')\"\n  psi=\"$(psi_mem_avg10)\"\n  if [ -n \"$psi\" ]; then\n    printf '   PSI mem\u00f3ria ..... avg10=%s%%\\n' \"$psi\"\n  else\n    printf '   PSI mem\u00f3ria ..... INDISPON\u00cdVEL (sem psi=1 no kernel)\\n'\n  fi\n  printf '   systemd-oomd .... %s / %s\\n' \\\n    \"$(unit_state systemd-oomd.service)\" \\\n    \"$(unit_active systemd-oomd.service)\"\n  high=$(systemctl --user show app.slice -p MemoryHigh --value 2>/dev/null || echo n/a)\n  max=$(systemctl --user show app.slice -p MemoryMax --value 2>/dev/null || echo n/a)\n  swapmax=$(systemctl --user show app.slice -p MemorySwapMax --value 2>/dev/null || echo n/a)\n  printf '   app.slice ....... MemoryHigh=%s MemoryMax=%s MemorySwapMax=%s\\n' \"$high\" \"$max\" \"$swapmax\"\n  printf '   watchdog ........ %s / %s\\n' \\\n    \"$(unit_state_u cache-guard-watch.timer)\" \\\n    \"$(unit_active_u cache-guard-watch.timer)\"\n  echo \"   maiores apps (memory.current):\"\n  local base d c n\n  base=\"$(user_cg)/app.slice\"; shopt -s nullglob\n  for d in \"$base\"/*/; do\n    c=$(cat \"$d/memory.current\" 2>/dev/null || echo 0)\n    n=$(basename \"${d%/}\")\n    printf '     %10s  %s\\n' \"$(numfmt --to=iec \"$c\" 2>/dev/null || echo \"$c\")\" \"$n\"\n  done | sort -rh | head -8\n  shopt -u nullglob\n}\n\n# =============================================================================\n# work.slice \u2014 slice dedicado + tetos por app (Edge + VSCodium + opencode)\n# =============================================================================\nwork_aliases_text() {\n  cat <<'EOF'\n# >>> cache-guard work.slice (auto) \u2014 N\u00c3O edite entre as marcas\n# Abre Edge, VSCodium e opencode dentro dos tetos do work.slice.\n# Recrie com:  ./scripts/cache-guard.sh work-setup\nEOF\n  local fn bin high max\n  while IFS='|' read -r fn bin high max; do\n    [ -n \"$fn\" ] || continue\n    printf 'function %s() { local b; b=\"$(type -P %s)\" || b=\"\"; [ -n \"$b\" ] || { echo \"%s: binario %s nao encontrado\" >&2; return 1; }; systemd-run --user --scope --collect --quiet --slice=%s -p MemoryHigh=%s -p MemoryMax=%s -- \"$b\" \"$@\"; }\\n' \\\n      \"$fn\" \"$bin\" \"$fn\" \"$bin\" \"$GUARD_WORK_SLICE\" \"$high\" \"$max\"\n  done <<< \"$GUARD_WORK_APPS\"\n  printf '%s\\n' \"# <<< cache-guard work.slice (auto)\"\n}\n\n# remove apenas o bloco marcado do ~/.bashrc (mant\u00e9m o resto intacto)\nstrip_work_aliases() {\n  local rc=\"$HOME/.bashrc\" tmp\n  [ -f \"$rc\" ] || return 0\n  tmp=\"$(mktemp)\"\n  awk '\n    /^# >>> cache-guard work.slice \\(auto\\)$/ { skip=1; next }\n    /^# <<< cache-guard work.slice \\(auto\\)$/ { skip=0; next }\n    !skip { print }\n  ' \"$rc\" > \"$tmp\" && mv \"$tmp\" \"$rc\"\n}\n\ninstall_work_aliases() {\n  local rc=\"$HOME/.bashrc\"\n  strip_work_aliases\n  if [ ! -f \"$rc\" ]; then\n    printf '# ~/.bashrc\\n[ -f /etc/bashrc ] && . /etc/bashrc\\n' > \"$rc\"\n  fi\n  work_aliases_text >> \"$rc\"\n  ok \"atalhos 'edge', 'codium' e 'opencode' em $rc (rode: source ~/.bashrc)\"\n}\n\ncmd_work_setup() {\n  say \"work.slice \u2014 slice dedicado p/ os tres pesados (Edge + Codium + opencode)\"\n  mkdir -p \"$USER_UNIT_DIR\"\n  cat > \"$USER_UNIT_DIR/$GUARD_WORK_SLICE\" <<EOF\n# cache-guard.sh (work-setup) \u2014 orcamento coletivo dos tres pesados\n[Slice]\nMemoryHigh=$GUARD_WORK_MEM_HIGH\nMemoryMax=$GUARD_WORK_MEM_MAX\nMemorySwapMax=$GUARD_WORK_SWAP_MAX\nEOF\n  systemctl --user daemon-reload\n  systemctl --user start \"$GUARD_WORK_SLICE\" 2>/dev/null || true\n  ok \"$GUARD_WORK_SLICE: high=$GUARD_WORK_MEM_HIGH max=$GUARD_WORK_MEM_MAX swap=$GUARD_WORK_SWAP_MAX\"\n\n  # watchdog: libera cache mas NAO encerra apps (os limites agora sao os tetos)\n  mkdir -p \"$WATCH_SERVICE.d\"\n  cat > \"$WATCH_SERVICE.d/override.conf\" <<'EOF'\n[Service]\nEnvironment=GUARD_KILL=no\nEOF\n  systemctl --user daemon-reload\n  ok \"watchdog: GUARD_KILL=no (libera cache, mas nao encerra apps)\"\n  install_work_aliases\n  echo \"   Abra com:  edge / codium / opencode\"\n}\n\ncmd_work_uninstall() {\n  say \"Removendo work.slice + atalhos + override do watchdog\"\n  systemctl --user stop \"$GUARD_WORK_SLICE\" 2>/dev/null || true\n  rm -f \"$USER_UNIT_DIR/$GUARD_WORK_SLICE\"\n  rm -rf \"$WATCH_SERVICE.d\"\n  systemctl --user daemon-reload\n  strip_work_aliases\n  ok \"removido (apps ja abertos continuam; novos voltam ao app.slice padrao)\"\n}\n\ncmd_work_status() {\n  local base d cur sum=0\n  base=\"$(user_cg)/$GUARD_WORK_SLICE\"\n  say \"work.slice \u2014 orcamento dos tres pesados\"\n  printf '   slice ......... %s (ativo: %s)\\n' \"$GUARD_WORK_SLICE\" \"$(unit_active_u \"$GUARD_WORK_SLICE\")\"\n  printf '   tetos ......... high=%s max=%s swap=%s\\n' \"$GUARD_WORK_MEM_HIGH\" \"$GUARD_WORK_MEM_MAX\" \"$GUARD_WORK_SWAP_MAX\"\n  local fn bin high max\n  echo \"   por app (configurado no cache-guard.sh):\"\n  while IFS='|' read -r fn bin high max; do\n    [ -n \"$fn\" ] || continue\n    printf '     %-9s  High=%-5s Max=%-5s  (%s)\\n' \"$fn\" \"$high\" \"$max\" \"$bin\"\n  done <<< \"$GUARD_WORK_APPS\"\n  echo \"   uso real por scope dentro do slice:\"\n  if [ -d \"$base\" ]; then\n    shopt -s nullglob\n    for d in \"$base\"/*/; do\n      cur=$(cat \"$d/memory.current\" 2>/dev/null || echo 0)\n      sum=$(( sum + cur ))\n      printf '     %10s  %s\\n' \"$(numfmt --to=iec \"$cur\" 2>/dev/null || echo \"$cur\")\" \"$(basename \"${d%/}\")\"\n    done\n    shopt -u nullglob\n    printf '   total em uso: %s  (coletivo max %s)\\n' \"$(numfmt --to=iec \"$sum\" 2>/dev/null || echo \"$sum\")\" \"$GUARD_WORK_MEM_MAX\"\n  else\n    echo \"   (slice vazio/inativo \u2014 abra um app com edge / codium / opencode)\"\n  fi\n}\n\n# =============================================================================\n# dispatch\n# =============================================================================\nusage() { sed -n '2,59p' \"$SELF\" | sed 's/^# \\{0,1\\}//'; }\n\ncase \"${1:-}\" in\n  user-install)    cmd_user_install ;;\n  user-uninstall)  cmd_user_uninstall ;;\n  system-install)  cmd_system_install ;;\n  system-uninstall) cmd_system_uninstall ;;\n  install)         cmd_user_install; cmd_system_install ;;\n  status)          cmd_status ;;\n  reclaim)         shift; cmd_reclaim \"$@\" ;;\n  run)             shift; cmd_run \"$@\" ;;\n  watch)           cmd_watch ;;\n  work-setup)      cmd_work_setup ;;\n  work-status)     cmd_work_status ;;\n  work-uninstall)  cmd_work_uninstall ;;\n  \"\"|-h|--help|help) usage ;;\n  *) die \"comando desconhecido: $1 (use: $0 help)\" ;;\nesac\n", "create_rpm.sh": "#!/bin/bash\n# ==============================================================================\n# Criador Autom\u00e1tico de RPM a partir de arquivos .tar.gz\n# ==============================================================================\n\nset -e\n\nSCRIPT_VERSION=\"1.0\"\n\nprint_usage() {\n    cat <<EOF\nUso: $0 [OP\u00c7\u00d5ES] arquivo.tar.gz\n\nOP\u00c7\u00d5ES:\n    -n, --name         Nome do pacote (padr\u00e3o: nome do arquivo sem extens\u00e3o)\n    -v, --version      Vers\u00e3o do pacote (padr\u00e3o: extra\u00edda do nome ou 1.0)\n    -r, --release      Release do pacote (padr\u00e3o: 1)\n    -d, --description  Descri\u00e7\u00e3o do pacote\n    -l, --license      Licen\u00e7a (padr\u00e3o: MIT)\n    -p, --prefix       Prefixo de instala\u00e7\u00e3o (padr\u00e3o: /usr/local)\n    -m, --maintainer   Mantenedor do pacote\n    --no-install       Apenas criar RPM, n\u00e3o instalar\n    -h, --help         Mostrar esta ajuda\n\nEXEMPLOS:\n    $0 programa-1.0.0.tar.gz\n    $0 -n meuprog -v 2.0 -d \"Meu Programa\" programa.tar.gz\nEOF\n    exit 0\n}\n\ncheck_deps() {\n    MISSING=()\n    for cmd in rpmbuild tar gzip; do\n        if ! command -v $cmd &> /dev/null; then\n            MISSING+=($cmd)\n        fi\n    done\n\n    if [ ${#MISSING[@]} -gt 0 ]; then\n        echo \"Instalando depend\u00eancias...\"\n        if command -v dnf &> /dev/null; then\n            sudo dnf install -y \"${MISSING[@]}\" rpm-build\n        elif command -v yum &> /dev/null; then\n            sudo yum install -y \"${MISSING[@]}\" rpm-build\n        fi\n    fi\n}\n\nsetup_rpmbuild() {\n    RPMBUILD_DIR=\"$HOME/rpmbuild\"\n    for dir in BUILD BUILDROOT RPMS SOURCES SPECS SRPMS; do\n        mkdir -p \"$RPMBUILD_DIR/$dir\"\n    done\n}\n\nparse_name_version() {\n    local archive=\"$1\"\n    local basename=$(basename \"$archive\" .tar.gz)\n    \n    if [[ \"$basename\" =~ ^(.+)-([0-9]+\\.[0-9]+\\.[0-9]+)$ ]]; then\n        PKG_NAME=\"${BASH_REMATCH[1]}\"\n        PKG_VERSION=\"${BASH_REMATCH[2]}\"\n    elif [[ \"$basename\" =~ ^(.+)-([0-9]+\\.[0-9]+)$ ]]; then\n        PKG_NAME=\"${BASH_REMATCH[1]}\"\n        PKG_VERSION=\"${BASH_REMATCH[2]}\"\n    else\n        PKG_NAME=\"$basename\"\n        PKG_VERSION=\"1.0\"\n    fi\n}\n\ncreate_spec() {\n    local archive=\"$1\"\n    local archive_name=$(basename \"$archive\")\n    \n    # Extrair temporariamente para descobrir o nome do diret\u00f3rio\n    TEMP_DIR=$(mktemp -d)\n    tar -xzf \"$archive\" -C \"$TEMP_DIR\"\n    SOURCE_DIR=$(ls -1 \"$TEMP_DIR\" | head -1)\n    SOURCE_PATH=\"$TEMP_DIR/$SOURCE_DIR\"\n    \n    # Verificar se \u00e9 bin\u00e1rio pr\u00e9-compilado ou c\u00f3digo fonte\n    if [ -f \"$SOURCE_PATH/configure\" ] || [ -f \"$SOURCE_PATH/Makefile\" ]; then\n        HAS_BUILD=true\n    else\n        HAS_BUILD=false\n    fi\n    rm -rf \"$TEMP_DIR\"\n    \n    if [ \"$HAS_BUILD\" = true ]; then\n        BUILD_SECTION=\"\n%build\nif [ -f configure ]; then\n    ./configure --prefix=${PKG_PREFIX}\nelif [ -f Makefile ]; then\n    make\nfi\nmake %{?_smp_mflags}\n\n%install\nmake install DESTDIR=%{buildroot}\"\n    else\n        BUILD_SECTION=\"\n%install\nmkdir -p %{buildroot}${PKG_PREFIX}\ncp -r . %{buildroot}${PKG_PREFIX}/\"\n    fi\n    \n    cat > \"$SPEC_FILE\" <<EOF\nName:           ${PKG_NAME}\nVersion:        ${PKG_VERSION}\nRelease:        ${PKG_RELEASE}%{?dist}\nSummary:        ${PKG_DESCRIPTION}\nLicense:        ${PKG_LICENSE}\nPackager:      ${PKG_MAINTAINER}\nSource0:        %{name}-%{version}.tar.gz\nPrefix:         ${PKG_PREFIX}\n\n%description\n${PKG_DESCRIPTION}\n\n%prep\n%setup -q -n ${SOURCE_DIR}\n${BUILD_SECTION}\n\n%files\n%defattr(-,root,root,-)\n${PKG_PREFIX}/*\n\n%changelog\n* $(date '+%a %b %d %Y') ${PKG_MAINTAINER} - ${PKG_VERSION}-${PKG_RELEASE}\n- Pacote RPM criado automaticamente\nEOF\n}\n\nbuild_rpm() {\n    local archive=\"$1\"\n    local archive_name=$(basename \"$archive\")\n    \n    cp \"$archive\" \"$SOURCES_DIR/\"\n    \n    echo \"=== Criando RPM...\"\n    \n    # Obter tamanho do arquivo fonte para estimativa\n    ARCHIVE_SIZE=$(stat -c%s \"$archive\" 2>/dev/null || stat -f%z \"$archive\" 2>/dev/null)\n    ARCHIVE_SIZE_KB=$((ARCHIVE_SIZE / 1024))\n    ESTIMATED_RPM_SIZE=$((ARCHIVE_SIZE_KB * 2))\n    \n    # Fun\u00e7\u00e3o para mostrar barra de progresso\n    show_progress() {\n        local percent=$1\n        local width=40\n        local filled=$((width * percent / 100))\n        local empty=$((width - filled))\n        \n        printf \"\\r[\"\n        printf \"%${filled}s\" | tr ' ' '\u2588'\n        printf \"%${empty}s\" | tr ' ' '\u2591'\n        printf \"] %3d%%\" \"$percent\"\n    }\n    \n    # Fun\u00e7\u00e3o de cleanup\n    cleanup() {\n        kill $MONITOR_PID 2>/dev/null\n        rm -f \"$LOG_FILE\"\n    }\n    trap cleanup EXIT\n    \n    LOG_FILE=\"/tmp/rpmbuild_$$.log\"\n    mkfifo \"$LOG_FILE\" 2>/dev/null\n    \n    # Monitor de progresso com estimativa baseada no tempo e tamanho\n    (\n        PHASES=(\"Preparando fontes\" \"Compilando c\u00f3digo\" \"Instalando arquivos\" \"Gerando pacote RPM\" \"Verificando integridade\")\n        PHASE=0\n        START_TIME=$(date +%s)\n        LAST_PHASE=0\n        \n        while kill -0 $$ 2>/dev/null; do\n            CURRENT_TIME=$(date +%s)\n            ELAPSED=$((CURRENT_TIME - START_TIME))\n            \n            # Detectar fase pelo log\n            if grep -q \"Executing(%prep)\" \"$LOG_FILE\" 2>/dev/null; then\n                PHASE=0\n            fi\n            if grep -q \"Executing(%build)\" \"$LOG_FILE\" 2>/dev/null; then\n                PHASE=1\n            fi\n            if grep -q \"Executing(%install)\" \"$LOG_FILE\" 2>/dev/null; then\n                PHASE=2\n            fi\n            if grep -q \"Creating.*rpm\" \"$LOG_FILE\" 2>/dev/null || grep -q \"Building target packages\" \"$LOG_FILE\" 2>/dev/null; then\n                PHASE=3\n            fi\n            if grep -q \"Wrote:\" \"$LOG_FILE\" 2>/dev/null; then\n                PHASE=4\n            fi\n            \n            # Calcular progresso\n            BASE=$((PHASE * 20))\n            \n            # Adicionar progresso baseado no tempo gasto na fase\n            if [ $PHASE -eq $LAST_PHASE ] && [ $ELAPSED -gt 0 ]; then\n                TIME_BONUS=$(( (ELAPSED % 10) * 2 ))\n            else\n                TIME_BONUS=0\n            fi\n            \n            PROGRESS=$((BASE + TIME_BONUS))\n            [ $PROGRESS -gt 98 ] && PROGRESS=98\n            [ $PROGRESS -lt 0 ] && PROGRESS=0\n            \n            LAST_PHASE=$PHASE\n            \n            # Mostrar tamanho estimado\n            ESTIMATED_CURRENT=$((ESTIMATED_RPM_SIZE * PROGRESS / 100))\n            \n            printf \"\\r\"\n            show_progress $PROGRESS\n            printf \" %-25s | Est: ~%d KB\" \"${PHASES[$PHASE]}\" \"$ESTIMATED_CURRENT\"\n            \n            sleep 0.2\n        done\n    ) &\n    MONITOR_PID=$!\n    \n    # Executar rpmbuild\n    rpmbuild -ba \"$SPEC_FILE\" > \"$LOG_FILE\" 2>&1\n    RPM_EXIT=$?\n    \n    kill $MONITOR_PID 2>/dev/null\n    wait $MONITOR_PID 2>/dev/null\n    \n    printf \"\\r\"\n    show_progress 100\n    printf \" Concluido!\\n\"\n    \n    rm -f \"$LOG_FILE\"\n    \n    if [ $RPM_EXIT -ne 0 ]; then\n        echo \"ERRO: Falha ao criar RPM (c\u00f3digo: $RPM_EXIT)\"\n        echo \"Verifique os logs em $HOME/rpmbuild/\"\n        cat \"$HOME/rpmbuild/SPECS/${PKG_NAME}.log\" 2>/dev/null || true\n        exit 1\n    fi\n    \n    local rpm_file=$(find \"$RPMS_DIR\" -name \"*.rpm\" -type f 2>/dev/null | head -1)\n    \n    if [ -n \"$rpm_file\" ]; then\n        RPM_SIZE=$(du -h \"$rpm_file\" | cut -f1)\n        RPM_SIZE_BYTES=$(stat -c%s \"$rpm_file\" 2>/dev/null || stat -f%z \"$rpm_file\" 2>/dev/null)\n        RPM_SIZE_KB=$((RPM_SIZE_BYTES / 1024))\n        \n        echo \"\"\n        echo \"\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\n        echo \"\u2551          RPM CRIADO COM SUCESSO!                 \u2551\"\n        echo \"\u2560\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2563\"\n        printf \"\u2551  Arquivo: %-40s\u2551\\n\" \"$rpm_file\"\n        printf \"\u2551  Tamanho: %-41s\u2551\\n\" \"$RPM_SIZE ($RPM_SIZE_KB KB)\"\n        echo \"\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\n        echo \"\"\n        \n        if [ \"$INSTALL_RPM\" = true ]; then\n            echo \"Instalando RPM...\"\n            if sudo rpm -ivh \"$rpm_file\" 2>/dev/null; then\n                echo \"RPM instalado com sucesso!\"\n            else\n                echo \"Tentando atualiza\u00e7\u00e3o...\"\n                sudo rpm -Uvh \"$rpm_file\"\n            fi\n        fi\n    else\n        echo \"ERRO: RPM n\u00e3o encontrado ap\u00f3s build\"\n        exit 1\n    fi\n}\n\n# ============================================\n# MAIN\n# ============================================\n\nPKG_NAME=\"\"\nPKG_VERSION=\"\"\nPKG_RELEASE=\"1\"\nPKG_DESCRIPTION=\"Pacote criado automaticamente\"\nPKG_LICENSE=\"MIT\"\nPKG_PREFIX=\"/usr/local\"\nPKG_MAINTAINER=\"$USER\"\nINSTALL_RPM=true\n\nif [ $# -eq 0 ]; then\n    print_usage\nfi\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        -n|--name) PKG_NAME=\"$2\"; shift 2 ;;\n        -v|--version) PKG_VERSION=\"$2\"; shift 2 ;;\n        -r|--release) PKG_RELEASE=\"$2\"; shift 2 ;;\n        -d|--description) PKG_DESCRIPTION=\"$2\"; shift 2 ;;\n        -l|--license) PKG_LICENSE=\"$2\"; shift 2 ;;\n        -p|--prefix) PKG_PREFIX=\"$2\"; shift 2 ;;\n        -m|--maintainer) PKG_MAINTAINER=\"$2\"; shift 2 ;;\n        --no-install) INSTALL_RPM=false; shift ;;\n        -h|--help) print_usage ;;\n        -*) echo \"Op\u00e7\u00e3o desconhecida: $1\"; exit 1 ;;\n        *) ARCHIVE=\"$1\"; shift ;;\n    esac\ndone\n\nif [ -z \"$ARCHIVE\" ]; then\n    echo \"ERRO: Arquivo .tar.gz n\u00e3o especificado\"\n    exit 1\nfi\n\nif [ ! -f \"$ARCHIVE\" ]; then\n    echo \"ERRO: Arquivo n\u00e3o encontrado: $ARCHIVE\"\n    exit 1\nfi\n\nif [[ ! \"$ARCHIVE\" =~ \\.tar\\.gz$ ]]; then\n    echo \"ERRO: Arquivo deve ter extens\u00e3o .tar.gz\"\n    exit 1\nfi\n\necho \"=== Criador de RPM v${SCRIPT_VERSION} ===\"\necho \"Arquivo: $ARCHIVE\"\n\ncheck_deps\nsetup_rpmbuild\nparse_name_version \"$ARCHIVE\"\n\n[ -z \"$PKG_NAME\" ] && PKG_NAME=\"$parse_result_name\"\n[ -z \"$PKG_VERSION\" ] && PKG_VERSION=\"$parse_result_version\"\n\nRPMBUILD_DIR=\"$HOME/rpmbuild\"\nSOURCES_DIR=\"$RPMBUILD_DIR/SOURCES\"\nSPECS_DIR=\"$RPMBUILD_DIR/SPECS\"\nRPMS_DIR=\"$RPMBUILD_DIR/RPMS/x86_64\"\nSPEC_FILE=\"$SPECS_DIR/${PKG_NAME}.spec\"\n\necho \"Nome: $PKG_NAME\"\necho \"Vers\u00e3o: $PKG_VERSION\"\necho \"Release: $PKG_RELEASE\"\necho \"\"\n\ncreate_spec \"$ARCHIVE\"\nbuild_rpm \"$ARCHIVE\"\n", "debian.sh": "#!/bin/bash\nset -e\n\n# 1. Definir o nome da pasta de trabalho (ao lado deste script)\nBASE_DIR=\"$(dirname \"$(readlink -f \"$0\")\")/build-debian\"\nmkdir -p \"$BASE_DIR/auto\"\nmkdir -p \"$BASE_DIR/config/package-lists\"\n\ncd \"$BASE_DIR\"\n\n# 2. Criar o script auto/config (baseado no seu recorte)\ncat <<EOF > auto/config\n#!/bin/sh\nset -e\n\nlb config noauto \\\\\n--mode debian \\\\\n--architectures amd64 \\\\\n--debian-installer live \\\\\n--archive-areas \"main contrib non-free non-free-firmware\" \\\\\n--apt-indices true \\\\\n--memtest none \\\\\n\"\\${@}\"\nEOF\n\nchmod +x auto/config\n\n# 3. Criar a lista de pacotes (my-list.list.chroot)\ncat <<EOF > config/package-lists/my-list.list.chroot\nxserver-xorg\nxserver-xorg-video-intel\nintel-microcode\ni965-va-driver\nintel-hdcp\nfirmware-intel-sound\nfirmware-zd1211\nintel-media-va-driver\nfirmware-iwlwifi\nnet-tools\nwireless-tools\nwpasupplicant\nlxde\nchromium\nyt-dlp\ndefault-jre\nnodejs\nnpm\nidle\npython3-full\npython3-pip\nEOF\n\n# 4. Iniciar a montagem (Build)\necho \"Iniciando a configura\u00e7\u00e3o e build da ISO...\"\nsudo lb clean --purge\nlb config\nsudo lb build\n\necho \"Processo conclu\u00eddo! A ISO deve estar na pasta: $BASE_DIR\"\n", "diagnostico-api.sh": "#!/usr/bin/env bash\n# Diagn\u00f3stico somente-leitura da API amor animal.\n# Uso: sudo bash diagnostico-api.sh\nset -u\n\nDOMINIO=\"api.projetosdinamicos.com.br\"\nPORTA_LOCAL=\"${PORTA_LOCAL:-3002}\"\nCONTAINER=\"${CONTAINER:-amoranimal-api}\"\n\necho \"== 1. DNS ==\"\nDNSIP=$(getent hosts \"$DOMINIO\" | awk '{print $1; exit}')\necho \"$DOMINIO -> ${DNSIP:-SEM RESOLUCAO}\"\n\necho\necho \"== 2. IPs na interface do servidor ==\"\nip -4 -o addr show scope global | awk '{print \"  \" $2 \" \" $4}'\n\necho\necho \"== 3. IP publico de saida (egress) ==\"\nEGRESS=$(curl -s --max-time 8 https://api.ipify.org 2>/dev/null)\necho \"  ${EGRESS:-falha ao consultar}\"\n\necho\necho \"== 4. Portas escutando ==\"\nsudo ss -tlnp 2>/dev/null | grep -E \":(${PORTA_LOCAL}|80|443)\\b\" || echo \"  nada escutando em ${PORTA_LOCAL}/80/443\"\n\necho\necho \"== 5. API local (dentro do servidor) ==\"\nfor rota in /health /voluntario /amoranimal/voluntario; do\n    code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 8 \"http://127.0.0.1:${PORTA_LOCAL}${rota}\" 2>/dev/null)\n    echo \"  GET ${rota} -> ${code:-falha}\"\ndone\n\necho\necho \"== 6. Proxy local (SNI e Host corretos) ==\"\ncurl -k -s -o /dev/null -w \"  https://${DOMINIO}/amoranimal/voluntario -> %{http_code}\\n\" \\\n    --max-time 8 --resolve \"${DOMINIO}:443:127.0.0.1\" \\\n    \"https://${DOMINIO}/amoranimal/voluntario\" 2>/dev/null \\\n    || echo \"  falha ao conectar no proxy local\"\n\necho\necho \"== 7. CORS respondido pela API local ==\"\ncurl -s -o /dev/null -D - --max-time 8 \\\n    -H \"Origin: https://amoranimal.ong.br\" \\\n    \"http://127.0.0.1:${PORTA_LOCAL}/voluntario\" 2>/dev/null \\\n    | grep -iE '^HTTP|access-control-allow-origin' | sed 's/^/  /' \\\n    || echo \"  API local nao respondeu\"\n\necho\necho \"== 7b. Validacao da config do nginx ==\"\nsudo nginx -t 2>&1 | sed 's/^/  /' || echo \"  nginx -t FALHOU (config invalida)\"\n\necho\necho \"== 8. Servicos de ingress ==\"\nfor s in nginx caddy cloudflared traefik; do\n    if systemctl list-unit-files 2>/dev/null | grep -q \"^${s}\"; then\n        echo \"  ${s}: $(systemctl is-active \"$s\" 2>/dev/null)\"\n    fi\ndone\n\necho\necho \"== 9. Container ==\"\nsudo docker inspect \"$CONTAINER\" \\\n    --format '  status={{.State.Status}} health={{.State.Health.Status}} restarts={{.RestartCount}} started={{.State.StartedAt}}' \\\n    2>/dev/null || echo \"  container ${CONTAINER} nao encontrado\"\n\necho\necho \"== 10. Firewall ==\"\nsudo ufw status 2>/dev/null | head -5 | sed 's/^/  /' || true\n\necho\necho \"== 11. Vhost do dominio ==\"\nsudo nginx -T 2>/dev/null | grep -n -A20 \"server_name .*${DOMINIO}\" | head -40 | sed 's/^/  /' \\\n    || echo \"  sem vhost nginx para ${DOMINIO}\"\n\necho\necho \"== CONCLUSAO ==\"\nif [ -n \"${DNSIP:-}\" ] && ip -4 -o addr show scope global | grep -q \" ${DNSIP}/\"; then\n    echo \"  OK: ${DNSIP} esta em uma interface do servidor (entrada direta possivel).\"\nelse\n    echo \"  ATENCAO: ${DNSIP:-?} NAO esta em nenhuma interface.\"\n    echo \"  -> o DNS aponta para IP de NAT/outro host; conexoes de entrada nao chegam aqui.\"\n    if [ -n \"${EGRESS:-}\" ] && [ \"${EGRESS}\" = \"${DNSIP:-}\" ]; then\n        echo \"  -> e o mesmo IP de saida (egress): tipico de NAT compartilhado.\"\n        echo \"     Solucao: IP publico dedicado, Load Balancer ou Cloudflare Tunnel.\"\n    fi\nfi\n", "fix-repos-ol9.sh": "#!/bin/bash\n#\n# fix-repos-ol9.sh\n# Script para corrigir reposit\u00f3rios do Oracle Linux 9.7\n# Remove configs antigas, instala reposit\u00f3rios atualizados,\n# desabilita plugins quebrados e limpa o cache do DNF.\n#\n\nset -e\n\nVERMELHO='\\033[0;31m'\nVERDE='\\033[0;32m'\nAMARELO='\\033[1;33m'\nAZUL='\\033[0;34m'\nNC='\\033[0m'\n\nlog_info()  { echo -e \"${AZUL}[INFO]${NC}  $1\"; }\nlog_ok()    { echo -e \"${VERDE}[OK]${NC}    $1\"; }\nlog_warn()  { echo -e \"${AMARELO}[WARN]${NC}  $1\"; }\nlog_erro()  { echo -e \"${VERMELHO}[ERRO]${NC} $1\"; }\n\n###############################################################################\n# Verifica se est\u00e1 rodando como root\n###############################################################################\nif [[ $EUID -ne 0 ]]; then\n    log_erro \"Este script precisa ser executado como root (sudo).\"\n    exit 1\nfi\n\n###############################################################################\n# Verifica se \u00e9 Oracle Linux 9.x\n###############################################################################\nif ! grep -qi \"Oracle Linux\" /etc/oracle-release 2>/dev/null; then\n    log_erro \"Este script \u00e9 exclusivo para Oracle Linux 9.\"\n    exit 1\nfi\n\nVERSAO=$(grep -oP '\\d+\\.\\d+' /etc/oracle-release | head -1)\nlog_info \"Oracle Linux detectado: $VERSAO\"\n\n###############################################################################\n# Backup dos reposit\u00f3rios atuais\n###############################################################################\nBACKUP_DIR=\"/etc/yum.repos.d/backup-$(date +%Y%m%d%H%M%S)\"\nmkdir -p \"$BACKUP_DIR\"\ncp /etc/yum.repos.d/*.repo \"$BACKUP_DIR/\" 2>/dev/null || true\nlog_ok \"Backup dos .repo em: $BACKUP_DIR\"\n\n###############################################################################\n# Remove todos os arquivos .repo existentes (vamos recriar)\n###############################################################################\nrm -f /etc/yum.repos.d/*.repo\nlog_info \"Arquivos .repo antigos removidos.\"\n\n###############################################################################\n# oracle-linux.repo \u2014 reposit\u00f3rios oficiais Oracle Linux 9\n###############################################################################\ncat > /etc/yum.repos.d/oracle-linux.repo << 'REPO'\n[ol9_baseos_latest]\nname=Oracle Linux 9 BaseOS Latest ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_appstream]\nname=Oracle Linux 9 Application Stream ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_UEKR7]\nname=Oracle Linux 9 UEK R7 ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/UEKR7/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_kvm_utils]\nname=Oracle Linux 9 KVM Utilities ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/kvm/utils/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_codeready_builder]\nname=Oracle Linux 9 CodeReady Builder ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/codeready/builder/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\n\n[ol9_distro_builder]\nname=Oracle Linux 9 Distro Builder ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/distro/builder/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\n\n[ol9_optional_latest]\nname=Oracle Linux 9 Optional Latest ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/optional/latest/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\nREPO\nlog_ok \"oracle-linux.repo criado com reposit\u00f3rios oficiais.\"\n\n###############################################################################\n# epel.repo \u2014 EPEL via Fedora (\u00fanica fonte dispon\u00edvel para OL9)\n###############################################################################\n# O Oracle N\u00c3O hospeda mirror pr\u00f3prio de EPEL em yum.oracle.com.\n# A fonte oficial e funcional \u00e9 o Fedora EPEL.\n###############################################################################\n\n# Tenta instalar oracle-epel-release-el9 (configura EPEL para apontar\n# para os mirrors do Fedora). Se falhar, cria manualmente.\nif ! rpm -q oracle-epel-release-el9 &>/dev/null; then\n    log_info \"Instalando oracle-epel-release-el9...\"\n    dnf install -y oracle-epel-release-el9 2>/dev/null || \\\n        log_warn \"Falha ao instalar oracle-epel-release-el9. Configura\u00e7\u00e3o manual ser\u00e1 usada.\"\nfi\n\n# Garante que o reposit\u00f3rio EPEL aponte para o Fedora, n\u00e3o para yum.oracle.com\ncat > /etc/yum.repos.d/epel.repo << 'REPO'\n[epel]\nname=Extra Packages for Enterprise Linux 9 - $basearch\nmetalink=https://mirrors.fedoraproject.org/metalink?repo=epel-9&arch=$basearch\nenabled=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\ngpgcheck=1\n\n[epel-next]\nname=Extra Packages for Enterprise Linux 9 - Next - $basearch\nmetalink=https://mirrors.fedoraproject.org/metalink?repo=epel-next-9&arch=$basearch\nenabled=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\ngpgcheck=1\nREPO\nlog_ok \"epel.repo criado apontando para Fedora EPEL (metalink).\"\n\n# Baixa a chave GPG do EPEL-9 caso n\u00e3o exista\nif [[ ! -f /etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9 ]]; then\n    log_info \"Baixando chave GPG do EPEL-9...\"\n    curl -sL https://dl.fedoraproject.org/pub/epel/RPM-GPG-KEY-EPEL-9 \\\n        -o /etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9 2>/dev/null && \\\n        log_ok \"Chave GPG EPEL-9 baixada.\" || \\\n        log_erro \"Falha ao baixar chave GPG EPEL-9.\"\nfi\n\n###############################################################################\n# Desabilita plugins quebrados (ulninfo, spacewalk)\n###############################################################################\nfor PLUGIN in ulninfo spacewalk; do\n    CONF=\"/etc/dnf/plugins/${PLUGIN}.conf\"\n    if [[ -f \"$CONF\" ]]; then\n        if grep -qi \"^enabled\" \"$CONF\" 2>/dev/null; then\n            sed -i 's/^enabled.*/enabled=0/' \"$CONF\"\n        else\n            echo \"enabled=0\" >> \"$CONF\"\n        fi\n        log_ok \"Plugin '$PLUGIN' desabilitado em: $CONF\"\n    fi\ndone\n\n# Fallback: caso os .conf n\u00e3o existam, cria um disable via drop-in\nfor PLUGIN in ulninfo spacewalk; do\n    CONF=\"/etc/dnf/plugins/${PLUGIN}.conf\"\n    if [[ ! -f \"$CONF\" ]]; then\n        mkdir -p /etc/dnf/plugins\n        cat > \"$CONF\" << 'EOF'\n[main]\nenabled=0\nEOF\n        log_ok \"Plugin '$PLUGIN' desabilitado (conf criado do zero).\"\n    fi\ndone\n\n###############################################################################\n# rpmfusion.repo \u2014 RPM Fusion (codecs, drivers, etc.)\n###############################################################################\ncat > /etc/yum.repos.d/rpmfusion.repo << 'REPO'\n[rpmfusion-free]\nname=RPM Fusion for EPEL 9 - Free\nbaseurl=https://download1.rpmfusion.org/free/el/updates/9/$basearch/\nenabled=1\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-rpmfusion-free-el-9\n\n[rpmfusion-free-updates-testing]\nname=RPM Fusion for EPEL 9 - Free - Testing\nbaseurl=https://download1.rpmfusion.org/free/el/updates/testing/9/$basearch/\nenabled=0\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-rpmfusion-free-el-9\n\n[rpmfusion-nonfree]\nname=RPM Fusion for EPEL 9 - Nonfree\nbaseurl=https://download1.rpmfusion.org/nonfree/el/updates/9/$basearch/\nenabled=1\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-rpmfusion-nonfree-el-9\n\n[rpmfusion-nonfree-updates-testing]\nname=RPM Fusion for EPEL 9 - Nonfree - Testing\nbaseurl=https://download1.rpmfusion.org/nonfree/el/updates/testing/9/$basearch/\nenabled=0\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-rpmfusion-nonfree-el-9\nREPO\nlog_ok \"rpmfusion.repo criado (free + nonfree).\"\n\n# Baixa chaves GPG do RPM Fusion\nfor KEY in free nonfree; do\n    FILE=\"/etc/pki/rpm-gpg/RPM-GPG-KEY-rpmfusion-${KEY}-el-9\"\n    if [[ ! -f \"$FILE\" ]]; then\n        curl -sL \"https://download1.rpmfusion.org/${KEY}/el/updates/9/x86_64/RPM-GPG-KEY-rpmfusion-${KEY}-el-9\" \\\n            -o \"$FILE\" 2>/dev/null && \\\n            log_ok \"Chave GPG RPM Fusion ${KEY} baixada.\" || \\\n            log_warn \"Falha ao baixar chave GPG RPM Fusion ${KEY}.\"\n    fi\ndone\n\n###############################################################################\n# Remove caches inv\u00e1lidos do DNF\n###############################################################################\nlog_info \"Limpando cache do DNF...\"\ndnf clean all 2>/dev/null || true\n\n###############################################################################\n# Testa os reposit\u00f3rios\n###############################################################################\nlog_info \"Testando conectividade dos reposit\u00f3rios...\"\ndnf repolist 2>&1 | grep -E \"^ol9_|^epel\" || true\n\nlog_info \"\"\nlog_ok \"Script conclu\u00eddo!\"\nlog_info \"Reposit\u00f3rios configurados e prontos para uso.\"\nlog_info \"Backup dispon\u00edvel em: $BACKUP_DIR\"\nlog_info \"\"\nlog_info \"Para testar a instala\u00e7\u00e3o de um pacote, execute:\"\nlog_info \"  dnf install -y <pacote>\"\n", "fix_boot_ol9_offline.sh": "#!/bin/bash\n#============================================================\n# Script: fix_boot_ol9_offline.sh\n# Objetivo: Corrigir bugs de boot (UEFI e MBR) da ISO\n#           OL9-Offline-Completa.iso e reescrever a imagem.\n#\n# Corrige:\n#   1. Entrada padr\u00e3o de boot era \"Test this media\" (rd.live.check)\n#      em uma ISO sem checksum embutido => sistema travava.\n#      Agora: default = Kickstart (auto) e checksum embutido\n#      (implantisomd5) para a verifica\u00e7\u00e3o de m\u00eddia funcionar.\n#   2. inst.stage2 sem caminho expl\u00edcito (dependia de .treeinfo).\n#      Agora: inst.stage2=hd:LABEL=...:/images/install.img.\n#   3. Arquivos ocultos (.discinfo) n\u00e3o copiados (glob ignorava\n#      dotfiles). Agora restaurados.\n#   4. ks.cfg usava 'bootloader --location=mbr' (incompat\u00edvel com\n#      UEFI). Removido para anaconda auto-detectar o modo.\n#   5. console=ttyS0/tty0 para instala\u00e7\u00e3o headless observ\u00e1vel.\n#\n# Pr\u00e9-requisitos: sudo, xorriso, mtools, isomd5sum, syslinux\n# Uso: sudo bash fix_boot_ol9_offline.sh\n#============================================================\nset -euo pipefail\n\nISO_ORIGEM=\"/home/wander/ISO/OL9-Offline-Completa.iso\"\nISO_STAGING=\"/tmp/opencode/ol9bootfix.iso\"\nWORK_DIR=\"/tmp/opencode/rebuild\"\nSRC_MNT=\"/mnt/iso_ol9fix\"\nVOLUME_ID=\"OL9_OFFLINE_OPENBOX\"\n\nGREEN='\\033[0;32m'; RED='\\033[0;31m'; YELLOW='\\033[1;33m'; CYAN='\\033[0;36m'; NC='\\033[0m'\nlog()  { echo -e \"${CYAN}[$(date +%H:%M:%S)]${NC} $1\"; }\nok()   { echo -e \"${GREEN}[$(date +%H:%M:%S)] OK:${NC} $1\"; }\nfatal(){ echo -e \"${RED}[$(date +%H:%M:%S)] ERRO:${NC} $1\"; exit 1; }\n\n[[ $EUID -ne 0 ]] && fatal \"Execute como root: sudo bash $0\"\nfor cmd in xorriso mcopy implantisomd5 mount umount; do\n    command -v \"$cmd\" &>/dev/null || fatal \"Depend\u00eancia '$cmd' n\u00e3o encontrada.\"\ndone\n[[ -f \"$ISO_ORIGEM\" ]] || fatal \"ISO n\u00e3o encontrada: $ISO_ORIGEM\"\n[[ -f /usr/share/syslinux/isohdpfx.bin ]] || fatal \"Falta /usr/share/syslinux/isohdpfx.bin\"\n\nlog \"=========================================\"\nlog \"  FIX BOOT OL9 OFFLINE (UEFI + MBR)\"\nlog \"=========================================\"\n\nlog \"ETAPA 1/6: Montando ISO fonte em $SRC_MNT...\"\nmkdir -p \"$SRC_MNT\"\nmountpoint -q \"$SRC_MNT\" && umount \"$SRC_MNT\" 2>/dev/null || true\nmount -o loop,ro \"$ISO_ORIGEM\" \"$SRC_MNT\"\nok \"ISO fonte montada\"\n\nlog \"ETAPA 2/6: Copiando estrutura (incluindo dotfiles)...\"\nrm -rf \"$WORK_DIR\"; mkdir -p \"$WORK_DIR\"\ncp -a \"$SRC_MNT\"/. \"$WORK_DIR/\"\nok \"Estrutura copiada ($(du -sh \"$WORK_DIR\" | cut -f1))\"\n\nlog \"ETAPA 3/6: Aplicando corre\u00e7\u00f5es de boot...\"\n\n# ---- isolinux.cfg (MBR / BIOS) ----\ncat > \"$WORK_DIR/isolinux/isolinux.cfg\" << 'ISOLINUXEOF'\ndefault vesamenu.c32\ntimeout 150\n\ndisplay boot.msg\n\nmenu clear\nmenu background splash.png\nmenu title Oracle Linux 9.8.0 (Offline - Openbox)\nmenu vshift 8\nmenu rows 18\nmenu margin 8\nmenu helpmsgrow 15\nmenu tabmsgrow 13\n\nmenu color border * #00000000 #00000000 none\nmenu color sel 0 #ffffffff #00000000 none\nmenu color title 0 #ff7ba3d0 #00000000 none\nmenu color tabmsg 0 #ff3a6496 #00000000 none\nmenu color unsel 0 #84b8ffff #00000000 none\nmenu color hotsel 0 #84b8ffff #00000000 none\nmenu color hotkey 0 #ffffffff #00000000 none\nmenu color help 0 #ffffffff #00000000 none\nmenu color scrollbar 0 #ffffffff #ff355594 none\nmenu color timeout 0 #ffffffff #00000000 none\nmenu color timeout_msg 0 #ffffffff #00000000 none\nmenu color cmdmark 0 #84b8ffff #00000000 none\nmenu color cmdline 0 #ffffffff #00000000 none\n\nmenu tabmsg Press Tab for full configuration options on menu items.\n\nmenu separator # insert an empty line\nmenu separator # insert an empty line\n\nlabel linux\n  menu label ^Install Oracle Linux 9.8.0\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img console=ttyS0,115200n8 console=tty0 quiet\n\nlabel check\n  menu label Test this ^media & install Oracle Linux 9.8.0\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img rd.live.check console=ttyS0,115200n8 console=tty0 quiet\n\nlabel fips\n  menu label ^Install Oracle Linux 9.8.0 in FIPS mode\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img console=ttyS0,115200n8 console=tty0 quiet fips=1\n\nmenu separator # insert an empty line\n\nmenu begin ^Troubleshooting\n  menu title Troubleshooting\n\nlabel text\n  menu indent count 5\n  menu label Install Oracle Linux 9.8.0 using ^text mode\n  text help\n\tTry this option out if you're having trouble installing\n\tOracle Linux 9.8.0.\n  endtext\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.text console=ttyS0,115200n8 console=tty0 quiet\n\nlabel rescue\n  menu indent count 5\n  menu label ^Rescue an Oracle Linux system\n  text help\n\tIf the system will not boot, this lets you access files\n\tand edit config files to try to get it booting again.\n  endtext\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.rescue console=ttyS0,115200n8 console=tty0 quiet\n\nlabel memtest\n  menu label Run a ^memory test\n  text help\n\tIf your system is having issues, a problem with your\n\tsystem's memory may be the cause. Use this utility to\n\tsee if the memory is working correctly.\n  endtext\n  kernel memtest\n\nmenu separator # insert an empty line\n\nlabel local\n  menu label Boot from ^local drive\n  localboot 0xffff\n\nmenu separator # insert an empty line\nmenu separator # insert an empty line\n\nlabel returntomain\n  menu label Return to ^main menu\n  menu exit\n\nmenu end\n\nlabel kickstart\n  menu label ^Instalar com Kickstart (auto, Openbox)\n  menu default\n  kernel vmlinuz\n  append initrd=initrd.img inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.ks=hd:LABEL=OL9_OFFLINE_OPENBOX:/ks.cfg console=ttyS0,115200n8 console=tty0 quiet\nISOLINUXEOF\nok \"isolinux.cfg corrigido\"\n\n# ---- isolinux/grub.conf (BIOS legacy, alguns firmwares) ----\ncat > \"$WORK_DIR/isolinux/grub.conf\" << 'GRUBCONFEOF'\ndefault=0\ntimeout 15\nhiddenmenu\ntitle Instalar com Kickstart (auto, Openbox)\n\tfindiso\n\tkernel @KERNELPATH@ @ROOT@ inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.ks=hd:LABEL=OL9_OFFLINE_OPENBOX:/ks.cfg console=ttyS0,115200n8 console=tty0 quiet\n\tinitrd @INITRDPATH@\ntitle Install Oracle Linux 9.8.0\n\tfindiso\n\tkernel @KERNELPATH@ @ROOT@ inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img console=ttyS0,115200n8 console=tty0 quiet\n\tinitrd @INITRDPATH@\ntitle Test this media & install Oracle Linux 9.8.0\n\tfindiso\n\tkernel @KERNELPATH@ @ROOT@ inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img rd.live.check console=ttyS0,115200n8 console=tty0 quiet\n\tinitrd @INITRDPATH@\nGRUBCONFEOF\nok \"isolinux/grub.conf corrigido\"\n\n# ---- EFI/BOOT/grub.cfg (UEFI) ----\ncat > \"$WORK_DIR/EFI/BOOT/grub.cfg\" << 'GRUBEOF'\nset default=\"4\"\nset timeout=15\n\nfunction load_video {\n  insmod efi_gop\n  insmod efi_uga\n  insmod video_bochs\n  insmod video_cirrus\n  insmod all_video\n}\n\nload_video\nset gfxpayload=keep\ninsmod gzio\ninsmod part_gpt\ninsmod ext2\n### END /etc/grub.d/00_header ###\n\nsearch --no-floppy --set=root -l 'OL9_OFFLINE_OPENBOX'\n\n### BEGIN /etc/grub.d/10_linux ###\nmenuentry 'Install Oracle Linux 9.8.0' --class fedora --class gnu-linux --class gnu --class os {\n\tlinuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img console=ttyS0,115200n8 console=tty0 quiet\n\tinitrdefi /images/pxeboot/initrd.img\n}\nmenuentry 'Test this media & install Oracle Linux 9.8.0' --class fedora --class gnu-linux --class gnu --class os {\n\tlinuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img rd.live.check console=ttyS0,115200n8 console=tty0 quiet\n\tinitrdefi /images/pxeboot/initrd.img\n}\nmenuentry 'Install Oracle Linux 9.8.0 in FIPS mode' --class fedora --class gnu-linux --class gnu --class os {\n\tlinuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img console=ttyS0,115200n8 console=tty0 quiet fips=1\n\tinitrdefi /images/pxeboot/initrd.img\n}\nsubmenu 'Troubleshooting -->' {\n\tmenuentry 'Install Oracle Linux 9.8.0 in text mode' --class fedora --class gnu-linux --class gnu --class os {\n\t\tlinuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.text console=ttyS0,115200n8 console=tty0 quiet\n\t\tinitrdefi /images/pxeboot/initrd.img\n\t}\n\tmenuentry 'Rescue an Oracle Linux system' --class fedora --class gnu-linux --class gnu --class os {\n\t\tlinuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.rescue console=ttyS0,115200n8 console=tty0 quiet\n\t\tinitrdefi /images/pxeboot/initrd.img\n\t}\n}\n\nmenuentry 'Instalar com Kickstart (auto, Openbox)' --class fedora --class gnu-linux --class gnu --class os {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_OFFLINE_OPENBOX:/images/install.img inst.ks=hd:LABEL=OL9_OFFLINE_OPENBOX:/ks.cfg console=ttyS0,115200n8 console=tty0 quiet\n    initrdefi /images/pxeboot/initrd.img\n}\nGRUBEOF\nok \"EFI/BOOT/grub.cfg corrigido\"\n\n# ---- efiboot.img (imagem FAT interna do UEFI) ----\nmcopy -o -i \"$WORK_DIR/images/efiboot.img\" \"$WORK_DIR/EFI/BOOT/grub.cfg\" ::/EFI/BOOT/grub.cfg\nok \"efiboot.img/grub.cfg atualizado\"\n\n# ---- ks.cfg (bootloader auto-detect UEFI/MBR) ----\nsed -i 's/^bootloader --location=mbr --driveorder=sda/bootloader --driveorder=sda/' \"$WORK_DIR/ks.cfg\"\nok \"ks.cfg: bootloader corrigido (auto-detect UEFI/MBR)\"\n\n# ---- .discinfo (arquivo oculto, exigido pela anaconda) ----\nEPOCH=$(date +%s)\nprintf '%s.%s\\nOracle Linux 9.8.0\\nx86_64\\n' \"$EPOCH\" \"000000\" > \"$WORK_DIR/.discinfo\"\nok \".discinfo criado\"\n\nlog \"ETAPA 4/6: Gerando nova ISO com xorriso...\"\numount \"$SRC_MNT\"\nxorriso -as mkisofs \\\n    -iso-level 3 \\\n    -full-iso9660-filenames \\\n    -volid \"$VOLUME_ID\" \\\n    -output \"$ISO_STAGING\" \\\n    -eltorito-boot isolinux/isolinux.bin \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        --eltorito-catalog isolinux/boot.cat \\\n    -eltorito-alt-boot \\\n        -e images/efiboot.img \\\n        -no-emul-boot \\\n        -isohybrid-gpt-basdat \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    \"$WORK_DIR\"\nok \"ISO gerada: $ISO_STAGING\"\n\nlog \"ETAPA 5/6: Embutindo checksum ISO (isomd5sum)...\"\nimplantisomd5 --force \"$ISO_STAGING\"\nok \"Checksum embutido\"\n\nlog \"ETAPA 6/6: Verifica\u00e7\u00e3o final...\"\nisoinfo -d -i \"$ISO_STAGING\" | grep -E 'Volume id|El Torito' | head -5\ncheckisomd5 \"$ISO_STAGING\" 2>&1 || true\nfdisk -l \"$ISO_STAGING\" 2>&1 | grep -E 'iso|EFI'\n\nlog \"  -- Defaults de boot na ISO gerada --\"\nisoinfo -R -x /ISOLINUX/ISOLINUX.CFG -i \"$ISO_STAGING\" 2>/dev/null | grep -E '^\\s*menu default|label kickstart|inst.ks=' || true\nisoinfo -R -x /EFI/BOOT/GRUB.CFG -i \"$ISO_STAGING\" 2>/dev/null | grep -E 'set default|Instalar com Kickstart' || true\nisoinfo -R -x /.DISCINFO -i \"$ISO_STAGING\" 2>/dev/null || echo \"  [ERRO] .discinfo ausente na ISO!\"\nisoinfo -R -x /KS.CFG -i \"$ISO_STAGING\" 2>/dev/null | grep -E 'bootloader' || true\n\necho \"\"\nlog \"=========================================\"\nlog \"  ISO CORRIGIDA: $ISO_STAGING\"\nlog \"  Tamanho: $(du -h \"$ISO_STAGING\" | cut -f1)\"\nlog \"  Default: Kickstart auto (UEFI e MBR)\"\nlog \"  Para substituir a original:\"\nlog \"    cp $ISO_STAGING $ISO_ORIGEM\"\nlog \"=========================================\"\n", "gerar_sku.sh": "#!/usr/bin/env bash\n\nVERSION=\"1.0.0\"\n\n# ============================================================\n#  gerar_sku.sh - Gera SKU no padr\u00e3o comercial\n#\n#  Formato padr\u00e3o comercial:\n#     CATEGORIA-SUBCATEGORIA-CARACTERISTICA-COR-TAMANHO\n#\n#  Cada campo \u00e9 representado por um prefixo (abrevia\u00e7\u00e3o).\n#  Ex.: CAMISETA MASCULINA B\u00c1SICA PRETA M -> CAM-MASC-BAS-PRE-M\n# ============================================================\n\nset -euo pipefail\n\n# --- Cores para output --------------------------------\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nCYAN='\\033[0;36m'\nNC='\\033[0m'\n\n# ------------------------------------------------------------\n# Fun\u00e7\u00e3o: extrair prefixo de um texto\n#   - Remove acentos, espa\u00e7os, caracteres especiais\n#   - Se o campo for vazio, retorna um valor padr\u00e3o\n# ------------------------------------------------------------\ngerar_prefixo() {\n    local texto=\"$1\"\n    local padrao=\"${2:-N/A}\"\n\n    # Remove acentos\n    texto=$(echo \"$texto\" | iconv -f utf-8 -t ascii//TRANSLIT 2>/dev/null || echo \"$texto\")\n\n    # Remove caracteres especiais e espa\u00e7os, deixa letras/numero\n    texto=$(echo \"$texto\" | sed 's/[^A-Za-z0-9]//g' | tr -d ' ')\n\n    # Converte para mai\u00fasculas\n    texto=$(echo \"$texto\" | tr '[:lower:]' '[:upper:]')\n\n    if [[ -z \"$texto\" ]]; then\n        echo \"$padrao\"\n        return\n    fi\n\n    # Pega as primeiras 3 letras\n    echo \"${texto:0:3}\"\n}\n\n# ------------------------------------------------------------\n# Fun\u00e7\u00e3o: ler input do usu\u00e1rio (com suporte a valor padr\u00e3o)\n# ------------------------------------------------------------\nperguntar() {\n    local msg=\"$1\"\n    local padrao=\"${2:-}\"\n\n    if [[ -n \"$padrao\" ]]; then\n        read -r -p \"$(echo -e \"${CYAN}$msg${NC} [padr\u00e3o: ${padrao}]: \")\" resposta\n        resposta=\"${resposta:-$padrao}\"\n    else\n        read -r -p \"$(echo -e \"${CYAN}$msg${NC}: \")\" resposta\n    fi\n\n    echo \"$resposta\"\n}\n\n# ------------------------------------------------------------\n# Fun\u00e7\u00e3o: m\u00e1scara de convers\u00e3o de cor para c\u00f3digo\n# ------------------------------------------------------------\ncodigo_cor() {\n    local cor=\"$1\"\n    cor=$(echo \"$cor\" | tr '[:upper:]' '[:lower:]' | sed 's/[\u00e1\u00e0\u00e2\u00e3]/a/g; s/[\u00e9\u00e8\u00ea]/e/g; s/[\u00ed\u00ec]/i/g; s/[\u00f3\u00f2\u00f4\u00f5]/o/g; s/[\u00fa\u00f9\u00fb]/u/g; s/[\u00e7]/c/g')\n\n    case \"$cor\" in\n        preto|black)           echo \"PRE\" ;;\n        branco|white)          echo \"BRA\" ;;\n        vermelho|red)          echo \"VER\" ;;\n        azul|blue)             echo \"AZU\" ;;\n        verde|green)           echo \"VERD\" ;;\n        amarelo|yellow)        echo \"AMA\" ;;\n        rosa|pink)             echo \"ROS\" ;;\n        roxo|purple|violeta)   echo \"ROX\" ;;\n        laranja|orange)        echo \"LAR\" ;;\n        cinza|gray|grey)       echo \"CIN\" ;;\n        marrom|brown)          echo \"MAR\" ;;\n        bege|beige)            echo \"BEG\" ;;\n        dourado|gold)          echo \"DOU\" ;;\n        prata|prateado|silver) echo \"PRA\" ;;\n        *)                     gerar_prefixo \"$1\" ;;\n    esac\n}\n\n# ------------------------------------------------------------\n# Fun\u00e7\u00e3o: m\u00e1scara de convers\u00e3o de tamanho\n# ------------------------------------------------------------\ncodigo_tamanho() {\n    local tam=\"$1\"\n    tam=$(echo \"$tam\" | tr '[:lower:]' '[:upper:]' | sed 's/[^A-Za-z0-9]//g')\n\n    case \"$tam\" in\n        P)        echo \"P\" ;;\n        M)        echo \"M\" ;;\n        G)        echo \"G\" ;;\n        GG)       echo \"GG\" ;;\n        XG|XGG)   echo \"XG\" ;;\n        UNICO)    echo \"UNI\" ;;\n        *)        echo \"${tam:0:3}\" ;;\n    esac\n}\n\n# ------------------------------------------------------------\n# Fun\u00e7\u00e3o: gerar um sufixo aleat\u00f3rio (evita duplicidade total)\n# ------------------------------------------------------------\ngerar_sufixo() {\n    echo \"$(date +%s%N | sha256sum | tr -d 'a-f0-9 ' | head -c 2 | tr '[:lower:]' '[:upper:]')\"\n}\n\n# ------------------------------------------------------------\n# Banner de apresenta\u00e7\u00e3o\n# ------------------------------------------------------------\nmostrar_banner() {\n    cat <<\"EOF\"\n  ____  _  _  _  __   __  ____\n / ___|| || || | \\ \\ / / |  _ \\\n| |   | | || | __\\ V /  | |_) |\n| |___| |__' |/ _ \\| |   |  _ <\n \\____|_|  |_| \\___/|_|   |_| \\_\\  -- Gerador de SKU v1.0\nEOF\n    echo -e \"${GREEN}Formato de sa\u00edda:${NC} CATEGORIA-SUBCATEGORIA-CARACTERISTICA-COR-TAMANHO\"\n    echo\n}\n\n# ============================================================\n# MAIN\n# ============================================================\n\nmostrar_banner\n\necho -e \"${YELLOW}Preencha os dados do produto para gerar o SKU.${NC}\"\necho\n\n# --- Coleta de inputs -------------------------------------\ncategoria=$(perguntar \"Categoria (ex: Camiseta)\"              \"GERAL\")\nsubcategoria=$(perguntar \"Subcategoria (ex: Masculina)\"        \"B\u00c1SIC\")\ncaracteristica=$(perguntar \"Caracter\u00edstica (ex: B\u00e1sica)\"       \"CL\u00c1SS\")\ncor=$(perguntar \"Cor (ex: Preta)\"                              \"PRETA\")\ntamanho=$(perguntar \"Tamanho (ex: M)\"                          \"UNI\")\n\n# --- Gera\u00e7\u00e3o de prefixos ------------------------------------\np_cat=$(gerar_prefixo \"$categoria\" \"GER\")\np_sub=$(gerar_prefixo \"$subcategoria\" \"BAS\")\np_car=$(gerar_prefixo \"$caracteristica\" \"CLA\")\n\n# Usa m\u00e1scara inteligente para cor e tamanho (mais amig\u00e1vel)\np_cor=$(codigo_cor \"$cor\")\np_tam=$(codigo_tamanho \"$tamanho\")\n\n# --- Monta e exibe o SKU ------------------------------------\nsku=\"${p_cat}-${p_sub}-${p_car}-${p_cor}-${p_tam}\"\n\necho\necho -e \"${GREEN}============================================${NC}\"\necho -e \"${CYAN}SKU gerado:${NC} ${GREEN}${sku}${NC}\"\necho -e \"${GREEN}============================================${NC}\"\necho\n\n# -- Resumo dos inputs (debug / confer\u00eancia) ----------------\necho -e \"${YELLOW}Resumo:${NC}\"\nprintf \"  %-18s %-8s %s\\n\" \"Campo\" \"Prefixo\" \"Original\"\nprintf \"  %-18s %-8s %s\\n\" \"-------\" \"-------\" \"--------\"\nprintf \"  %-18s %-8s %s\\n\" \"Categoria\"       \"$p_cat\" \"$categoria\"\nprintf \"  %-18s %-8s %s\\n\" \"Subcategoria\"    \"$p_sub\" \"$subcategoria\"\nprintf \"  %-18s %-8s %s\\n\" \"Caracter\u00edstica\"  \"$p_car\" \"$caracteristica\"\nprintf \"  %-18s %-8s %s\\n\" \"Cor\"             \"$p_cor\" \"$cor\"\nprintf \"  %-18s %-8s %s\\n\" \"Tamanho\"         \"$p_tam\" \"$tamanho\"\n\necho\n\n# --- Op\u00e7\u00e3o de copiar para clipboard ------------------------\nread -r -p \"$(echo -e \"${CYAN}Copiar SKU para a \u00e1rea de transfer\u00eancia? [s/N]: ${NC}\")\" copiar\nif [[ \"${copiar,,}\" == \"s\" ]]; then\n    if command -v xclip >/dev/null 2>&1; then\n        echo -n \"$sku\" | xclip -selection clipboard\n        echo -e \"${GREEN}SKU copiado!${NC}\"\n    elif command -v xsel >/dev/null 2>&1; then\n        echo -n \"$sku\" | xsel --clipboard --input\n        echo -e \"${GREEN}SKU copiado!${NC}\"\n    elif command -v wl-copy >/dev/null 2>&1; then\n        echo -n \"$sku\" | wl-copy\n        echo -e \"${GREEN}SKU copiado!${NC}\"\n    else\n        echo -e \"${RED}Ferramenta de clipboard n\u00e3o encontrada (xclip/xsel/wl-copy).${NC}\"\n    fi\nfi\n\n# --- Op\u00e7\u00e3o de salvar em arquivo ----------------------------\nread -r -p \"$(echo -e \"${CYAN}Salvar SKU em arquivo skus.txt? [s/N]: ${NC}\")\" salvar\nif [[ \"${salvar,,}\" == \"s\" ]]; then\n    echo \"$sku\" >> \"skus.txt\"\n    echo -e \"${GREEN}SKU salvo em skus.txt${NC}\"\nfi\n\necho -e \"${GREEN}Pronto!${NC}\"\nexit 0\n", "gerar_sku_ebook.sh": "#!/usr/bin/env bash\n\n# ============================================================\n#  gerar_sku_ebook.sh - Gera SKU para produtos digitais (ebook)\n#\n#  Formato:\n#     TEMA-SUBCATEGORIA-NUMERO\n#\n#  Ex.: TEC-PROG-001  (Tecnologia / Programa\u00e7\u00e3o / 1\u00ba ebook)\n#\n#  O n\u00famero \u00e9 sequencial e \u00e9 acompanhado em um arquivo de\n#  controle (contador). O status do n\u00ba mais recente \u00e9 gravado\n#  em sku_ebook_contador.txt.\n# ============================================================\n\n# Usa o diret\u00f3rio onde o script est\u00e1 em vez dos paths hardcoded\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nCONTADOR_FILE=\"${SCRIPT_DIR}/sku_ebook_contador.txt\"\n\n# --- Cores -----------------------------------------------\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nCYAN='\\033[0;36m'\nNC='\\033[0m'\n\n# ---------------------------------------------------------\n# Prefixo: remove acentos/caracteres especiais, pega 3 letras\n# ---------------------------------------------------------\nprefixo() {\n    local t=\"$1\"\n    local padrao=\"${2:-N/A}\"\n    t=$(echo \"$t\" | iconv -f utf-8 -t ascii//TRANSLIT 2>/dev/null || echo \"$t\")\n    t=$(echo \"$t\" | sed 's/[^A-Za-z0-9]//g' | tr '[:lower:]' '[:upper:]')\n    [[ -z \"$t\" ]] && { echo \"$padrao\"; return; }\n    echo \"${t:0:3}\"\n}\n\n# ---------------------------------------------------------\n# Ler o contador atual a partir do arquivo de controle.\n# Se n\u00e3o existir, come\u00e7a em 0.\n# ---------------------------------------------------------\nler_contador() {\n    if [[ -f \"$CONTADOR_FILE\" ]]; then\n        cat \"$CONTADOR_FILE\"\n    else\n        echo \"0\"\n    fi\n}\n\n# ---------------------------------------------------------\n# Incrementar e salvar o contador\n# ---------------------------------------------------------\ngravar_contador() {\n    echo \"$1\" > \"$CONTADOR_FILE\"\n}\n\n# ---------------------------------------------------------\n# Input com suporte a valor padr\u00e3o\n# ---------------------------------------------------------\nperguntar() {\n    local msg=\"$1\" padrao=\"${2:-}\"\n    local resp\n    if [[ -n \"$padrao\" ]]; then\n        read -r -p \"$(echo -e \"${CYAN}${msg}${NC} [padr\u00e3o: ${padrao}]: \")\" resp\n        resp=\"${resp:-$padrao}\"\n    else\n        read -r -p \"$(echo -e \"${CYAN}${msg}${NC}: \")\" resp\n    fi\n    echo \"$resp\"\n}\n\n# =========================================================\n# MAIN\n# =========================================================\n\necho -e \"${GREEN}Gerador de SKU para EBOOK${NC}\"\necho -e \"Formato: ${YELLOW}TEMA-SUBCATEGORIA-NUMERO${NC} (ex.: TEC-PROG-001)\"\necho\n\ntema=$(perguntar \"Tema/assunto (ex: Tecnologia)\"             \"GERAL\")\nsubtema=$(perguntar \"Subcategoria (ex: Programa\u00e7\u00e3o)\"          \"GERAL\")\n\ncontador=$(ler_contador)\nnovo=$((contador + 1))\nnumero=$(printf \"%03d\" \"$novo\")\ngravar_contador \"$novo\"\n\np_tema=$(prefixo \"$tema\" \"GER\")\np_sub=$(prefixo \"$subtema\" \"GER\")\n\nsku=\"${p_tema}-${p_sub}-${numero}\"\n\necho\necho -e \"${GREEN}============================================${NC}\"\necho -e \"${CYAN}SKU do ebook gerado:${NC} ${GREEN}${sku}${NC}\"\necho -e \"${GREEN}============================================${NC}\"\necho\n\nprintf \"  %-18s %-8s %s\\n\" \"Campo\" \"Prefixo\" \"Original\"\nprintf \"  %-18s %-8s %s\\n\" \"-------\" \"-------\" \"--------\"\nprintf \"  %-18s %-8s %s\\n\" \"Tema\"          \"$p_tema\" \"$tema\"\nprintf \"  %-18s %-8s %s\\n\" \"Subcategoria\"  \"$p_sub\"  \"$subtema\"\nprintf \"  %-18s %-8s %s\\n\" \"N\u00famero\"        \"$numero\" \"sequencial\"\n\necho\nread -r -p \"$(echo -e \"${CYAN}Salvar em arquivo de ebooks? [s/N]: ${NC}\")\" salvar\nif [[ \"${salvar,,}\" == \"s\" ]]; then\n    echo \"$sku\" >> \"${SCRIPT_DIR}/skus_ebook.txt\"\n    echo -e \"${GREEN}Salvo em skus_ebook.txt${NC}\"\nfi\n\necho\necho -e \"${YELLOW}Pr\u00f3ximo n\u00famero ser\u00e1:${NC} $(printf '%03d' $((novo + 1)))\"\nexit 0\n", "git-sync.sh": "#!/bin/bash\n\n# \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\n# \u2551  git-sync.sh \u2014 Sincroniza repositorio com GitHub        \u2551\n# \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\n\nset -euo pipefail\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  .ENV EMBUTIDO (heredoc) + ARQUIVO EXTERNO (preferido)\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n_carregar_env() {\n    local _k _v\n    while IFS='=' read -r _k _v; do\n        case \"$_k\" in\n            ''|'#'*) continue ;;\n            GIT_SYNC_TOKEN)      export GIT_SYNC_TOKEN=\"$_v\" ;;\n            GIT_SYNC_TOKEN_URL)  export GIT_SYNC_TOKEN_URL=\"$_v\" ;;\n        esac\n    done\n}\n\n_carregar_env <<'GIT_SYNC_ENV'\n# \u2500\u2500 chave=valor (fallback embutido) \u2500\u2500\nGIT_SYNC_TOKEN=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\nGIT_SYNC_TOKEN_URL=https://github.com/settings/tokens/new?scopes=repo&description=git-sync\nGIT_SYNC_ENV\n\n_TOKEN_FILE=\"${HOME}/.config/git-sync/token\"\nif [ -f \"$_TOKEN_FILE\" ]; then\n    GIT_SYNC_TOKEN=\"$(tr -d '[:space:]' < \"$_TOKEN_FILE\")\"\nfi\n\nV='\\033[0;32m'  A='\\033[0;34m'  AM='\\033[1;33m'\nVM='\\033[0;31m'  M='\\033[0;35m'  R='\\033[0m'  B='\\033[1m'\n\n_REPO_DIR=\"${1:-.}\"\n\n_RENOVAR_ONLY=0\nif [[ \"${1:-}\" == \"-t\" || \"${1:-}\" == \"-token\" ]]; then\n    shift\n    _REPO_DIR=\"${1:-.}\"\n    _RENOVAR_ONLY=1\nfi\n\nif ! cd \"$_REPO_DIR\" 2>/dev/null; then\n    echo -e \"${VM}Erro: diretorio '$_REPO_DIR' nao existe.${R}\"\n    exit 1\nfi\n\nif ! git rev-parse --is-inside-work-tree &>/dev/null; then\n    echo -e \"${VM}Erro: nao e um repositorio git.${R}\"\n    exit 1\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  INFORMACOES DO AMBIENTE\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n_branch=$(git branch --show-current 2>/dev/null || echo \"main\")\n_remote_url=$(git remote get-url origin 2>/dev/null || echo \"\")\n_git_user=$(git config user.name 2>/dev/null || echo \"desconhecido\")\n_git_email=$(git config user.email 2>/dev/null || echo \"desconhecido\")\n_repo_name=$(basename -s .git \"$_remote_url\" 2>/dev/null || echo \"local\")\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  STATUS DO TOKEN\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n_token=\"${GIT_SYNC_TOKEN:-}\"\n\nif [ -n \"$_token\" ]; then\n    _token_status=\"${V}ok${R} (existe)\"\nelse\n    _token_status=\"${VM}nok${R} (nao existe)\"\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  RENOVACAO DE TOKEN VIA xdg-open\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n-token() {\n    local _url=\"${GIT_SYNC_TOKEN_URL}\"\n    echo \"\"\n    echo -e \"${AM}Abrindo o navegador para gerar um novo token...${R}\"\n    if command -v xdg-open >/dev/null 2>&1; then\n        xdg-open \"$_url\" >/dev/null 2>&1 || true\n    else\n        echo -e \"${AM}xdg-open nao encontrado \u2014 abra a URL manualmente:${R}\"\n        echo \"  $_url\"\n    fi\n    echo \"\"\n    echo -ne \"${A}Cole o novo token (ghp_...): ${R}\"\n    read -r _novo\n    _novo=\"${_novo//[[:space:]]/}\"\n    if [[ ! \"$_novo\" =~ ^(ghp_|gho_|github_pat_) ]]; then\n        echo -e \"${VM}Token invalido ou vazio.${R}\"\n        return 1\n    fi\n    mkdir -p \"$(dirname \"$_TOKEN_FILE\")\"\n    umask 077\n    cat > \"$_TOKEN_FILE\" <<EOF\n$_novo\nEOF\n    _token=\"$_novo\"\n    if [ -n \"$_remote_url\" ]; then\n        _repo_path=$(echo \"$_remote_url\" | sed -E 's|https?://[^@]*@github.com/||;s|https?://github.com/||;s|\\.git$||;s|\\.git/||')\n        git remote set-url origin \"https://${_token}@github.com/${_repo_path}.git\"\n    fi\n    echo -e \"${V}ok${R} \u2014 token salvo em $_TOKEN_FILE e remote atualizado\"\n}\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  MODO STANDALONE: git-sync.sh -token [repo]\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nif [ \"$_RENOVAR_ONLY\" = \"1\" ]; then\n    if -token; then\n        echo \"\"\n        echo -e \"${A}Testando credenciais (git ls-remote)...${R}\"\n        if git ls-remote origin >/dev/null 2>&1; then\n            echo -e \"${V}${B}Novo token funcionando!${R}\"\n        else\n            echo -e \"${VM}Token salvo, mas o acesso ao remoto falhou.${R}\"\n        fi\n    fi\n    exit 0\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  VERIFICACAO DE ALINHAMENTO PRE-SYNC\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n_verificar_alinhamento() {\n    echo \"\"\n    echo -e \"${M}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${R}\"\n    echo -e \"${M}     Verificacao de Alinhamento       ${R}\"\n    echo -e \"${M}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${R}\"\n    echo \"\"\n\n    local _erros=0\n    local _avisos=0\n\n    # \u2500\u2500 1. Fetch remoto \u2500\u2500\n    echo -e \"${A}[1/5]${R} Buscando atualizacoes do remoto...\"\n    if git fetch origin \"$_branch\" 2>/dev/null; then\n        echo -e \"  ${V}ok${R} \u2014 fetch concluido\"\n    else\n        echo -e \"  ${VM}falha${R} \u2014 nao foi possivel acessar o remoto\"\n        (( _erros++ ))\n    fi\n\n    # \u2500\u2500 2. Verificar divergencia local vs remoto \u2500\u2500\n    echo \"\"\n    echo -e \"${A}[2/5]${R} Comparando branch local com remoto...\"\n    _local_hash=$(git rev-parse HEAD 2>/dev/null)\n    _remote_hash=$(git rev-parse \"origin/$_branch\" 2>/dev/null || echo \"\")\n    _base_hash=$(git merge-base HEAD \"origin/$_branch\" 2>/dev/null || echo \"\")\n\n    if [ -n \"$_remote_hash\" ] && [ \"$_local_hash\" = \"$_remote_hash\" ]; then\n        echo -e \"  ${V}ok${R} \u2014 local e remoto estao identicos\"\n    elif [ -n \"$_base_hash\" ] && [ \"$_local_hash\" != \"$_remote_hash\" ]; then\n        _local_ahead=$(git rev-list --count \"origin/$_branch..HEAD\" 2>/dev/null || echo \"0\")\n        _local_behind=$(git rev-list --count \"HEAD..origin/$_branch\" 2>/dev/null || echo \"0\")\n\n        if [ \"$_local_behind\" -gt 0 ] && [ \"$_local_ahead\" -gt 0 ]; then\n            echo -e \"  ${VM}CONFLITO${R} \u2014 branches divergentes: $_local_ahead commits a frente, $_local_behind atras\"\n            (( _erros++ ))\n        elif [ \"$_local_behind\" -gt 0 ]; then\n            echo -e \"  ${AM}AVISO${R} \u2014 local esta $_local_behind commit(s) atras do remoto (pull necessario)\"\n            (( _avisos++ ))\n        elif [ \"$_local_ahead\" -gt 0 ]; then\n            echo -e \"  ${AM}AVISO${R} \u2014 local esta $_local_ahead commit(s) a frente do remoto (push necessario)\"\n            (( _avisos++ ))\n        fi\n    else\n        echo -e \"  ${VM}erro${R} \u2014 nao foi possivel comparar branches\"\n        (( _erros++ ))\n    fi\n\n    # \u2500\u2500 3. Verificar arquivos nao rastreados (untracked) \u2500\u2500\n    echo \"\"\n    echo -e \"${A}[3/5]${R} Verificando arquivos nao rastreados...\"\n    _untracked=$(git ls-files --others --exclude-standard 2>/dev/null | wc -l)\n    if [ \"$_untracked\" -gt 0 ]; then\n        echo -e \"  ${AM}AVISO${R} \u2014 $_untracked arquivo(s) nao rastreado(s) sera(o) ignorado(s) no pull\"\n        (( _avisos++ ))\n    else\n        echo -e \"  ${V}ok${R} \u2014 todos os arquivos estao rastreados\"\n    fi\n\n    # \u2500\u2500 4. Verificar stash pendente \u2500\u2500\n    echo \"\"\n    echo -e \"${A}[4/5]${R} Verificando stash pendente...\"\n    _stash_count=$(git stash list 2>/dev/null | wc -l)\n    if [ \"$_stash_count\" -gt 0 ]; then\n        echo -e \"  ${AM}AVISO${R} \u2014 $_stash_count stash(es) pendente(s) \u2014 considere usar stash pop\"\n        (( _avisos++ ))\n    else\n        echo -e \"  ${V}ok${R} \u2014 nenhum stash pendente\"\n    fi\n\n    # \u2500\u2500 5. Verificar conflitos de merge anteriores \u2500\u2500\n    echo \"\"\n    echo -e \"${A}[5/5]${R} Verificando conflitos de merge...\"\n    _unmerged=$(git diff --name-only --diff-filter=U 2>/dev/null | wc -l)\n    if [ \"$_unmerged\" -gt 0 ]; then\n        echo -e \"  ${VM}ERRO${R} \u2014 $_unmerged arquivo(s) com conflito de merge nao resolvido(s)\"\n        (( _erros++ ))\n    else\n        echo -e \"  ${V}ok${R} \u2014 nenhum conflito de merge\"\n    fi\n\n    # \u2500\u2500 Resultado \u2500\u2500\n    echo \"\"\n    echo -e \"${M}\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500${R}\"\n    if [ \"$_erros\" -gt 0 ]; then\n        echo -e \"  ${VM}RESULTADO: $_erros erro(s), $_avisos aviso(s)${R}\"\n        echo -e \"  ${VM}Corrija os erros antes de sincronizar.${R}\"\n        echo \"\"\n        return 1\n    elif [ \"$_avisos\" -gt 0 ]; then\n        echo -e \"  ${AM}RESULTADO: 0 erros, $_avisos aviso(s)${R}\"\n        echo -e \"  ${AM}Prosseguir com cuidado.${R}\"\n        echo \"\"\n        return 0\n    else\n        echo -e \"  ${V}RESULTADO: tudo alinhado, pronto para sync${R}\"\n        echo \"\"\n        return 0\n    fi\n}\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  PAINEL DE CONTROLE\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\necho \"\"\necho -e \"${M}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${R}\"\necho -e \"${M}        git-sync \u2014 Painel            ${R}\"\necho -e \"${M}\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550${R}\"\necho \"\"\necho -e \"  ${A}Usuario:${R}    ${B}$_git_user${R} <$_git_email>\"\necho -e \"  ${A}Repositorio:${R} ${B}$_repo_name${R}\"\necho -e \"  ${A}Branch:${R}      ${B}$_branch${R}\"\necho -e \"  ${A}Token:${R}       $_token_status\"\necho \"\"\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  ULTIMOS 5 COMMITS\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\necho -e \"${A}Ultimos 5 commits:${R}\"\ngit log --oneline -5 --color=always 2>/dev/null | while IFS= read -r _line; do\n    echo -e \"  $_line\"\ndone\necho \"\"\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  ARQUIVOS MODIFICADOS\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n_changes=$(git status --porcelain)\n\nif [ -z \"$_changes\" ]; then\n    echo -e \"${AM}Nada para sincronizar.${R}\"\n    echo \"\"\n    echo -ne \"${A}Fazer pull mesmo assim? [s/N]:${R} \"\n    read -r _do_pull\n    if [ \"${_do_pull,,}\" = \"s\" ]; then\n        echo -e \"${A}git pull origin $_branch${R}\"\n        git pull origin \"$_branch\" 2>/dev/null && echo -e \"${V}Pull concluido.${R}\" || echo -e \"${AM}Pull nao precisou ou houve conflito.${R}\"\n    fi\n    exit 0\nfi\n\necho -e \"${A}Arquivos modificados:${R}\"\necho \"$_changes\" | while IFS= read -r _line; do\n    _status=\"${_line:0:2}\"\n    _file=\"${_line:3}\"\n    case \"$_status\" in\n        \"M \") echo -e \"  ${V}M${R}  $_file\";;\n        \" D\") echo -e \"  ${VM}D${R}  $_file\";;\n        \"A \") echo -e \"  ${AM}A${R}  $_file\";;\n        \"??\") echo -e \"  ${M}?${R}  $_file\";;\n        *)    echo -e \"  $_file\";;\n    esac\ndone\necho \"\"\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  VERIFICACAO DE ALINHAMENTO\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nif ! _verificar_alinhamento; then\n    echo -ne \"${VM}Deseja abortar a sincronizacao? [S/n]:${R} \"\n    read -r _abort\n    if [ \"${_abort,,}\" != \"n\" ]; then\n        echo -e \"${VM}Operacao abortada.${R}\"\n        exit 1\n    fi\n    echo -e \"${AM}Continuando mesmo assim...${R}\"\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  ATUALIZAR REMOTE COM TOKEN\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\nif [ -n \"$_remote_url\" ] && [ -n \"$_token\" ]; then\n    _repo_path=$(echo \"$_remote_url\" | sed -E 's|https?://[^@]*@github.com/||;s|https?://github.com/||;s|\\.git$||;s|\\.git/||')\n    _new_url=\"https://${_token}@github.com/${_repo_path}.git\"\n    git remote set-url origin \"$_new_url\"\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n#  CONFIRMACAO E COMMIT\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\necho -ne \"${A}Mensagem do commit${R} [Atualizacao]: \"\nread -r _msg\n_msg=\"${_msg:-Atualizacao}\"\n\necho \"\"\necho -e \"${A}Resumo da operacao:${R}\"\necho -e \"  Usuario:    $_git_user <$_git_email>\"\necho -e \"  Repositorio: $_repo_name\"\necho -e \"  Branch:     $_branch\"\necho -e \"  Commit msg: $_msg\"\necho \"\"\necho -ne \"${AM}Confirmar e sincronizar? [s/N]:${R} \"\nread -r _confirm\n\nif [ \"${_confirm,,}\" != \"s\" ]; then\n    echo -e \"${VM}Operacao cancelada.${R}\"\n    exit 0\nfi\n\necho \"\"\necho -e \"${A}git add -A${R}\"\ngit add -A\n\necho -e \"${A}git commit -m \\\"$_msg\\\"${R}\"\ngit commit -m \"$_msg\"\n\necho \"\"\necho -e \"${A}git pull origin $_branch --rebase${R}\"\ngit pull origin \"$_branch\" --rebase 2>/dev/null || echo -e \"${AM}Pull nao precisou ou houve conflito.${R}\"\n\necho \"\"\necho -e \"${A}git push origin $_branch${R}\"\nif git push origin \"$_branch\" 2>&1; then\n    echo \"\"\n    echo -e \"${V}${B}Sincronizado com sucesso!${R}\"\n    exit 0\nfi\n\necho \"\"\necho -e \"${VM}Falha no push.${R}\"\necho -ne \"${AM}Token pode ter expirado. Renovar agora? [s/N]:${R} \"\nread -r _renew\nif [ \"${_renew,,}\" = \"s\" ]; then\n    if -token; then\n        echo \"\"\n        echo -e \"${A}git push origin $_branch (nova tentativa)${R}\"\n        if git push origin \"$_branch\" 2>&1; then\n            echo \"\"\n            echo -e \"${V}${B}Sincronizado com sucesso!${R}\"\n            exit 0\n        fi\n        echo -e \"${VM}Falha no push mesmo com token novo.${R}\"\n    fi\nfi\necho -e \"${A}Verifique: https://github.com/settings/tokens${R}\"\nexit 1\n", "install_llm.sh": "#!/bin/sh\n# ==============================================================\n# install_sh \u2014 Instala SQLite + Integra com LLM (Llamafile)\n# Purpose: Baixar depend\u00eancias do SQLite, integrar banco de dados\n# nas opera\u00e7\u00f5es da LLM, melhorar desempenho e configurar pontes Python.\n# Requer: Debian/Ubuntu, root.\n# ==============================================================\n\nset -eu\n\nRED='\\033[0;31m'; GREEN='\\033[0;32m'; YELLOW='\\033[1;33m'; NC='\\033[0m'\ninfo()  { printf \"${GREEN}[INFO]${NC} %s\\n\" \"$1\"; }\nwarn()  { printf \"${YELLOW}[WARN]${NC} %s\\n\" \"$1\" >&2; }\nerror() { printf \"${RED}[ERRO]${NC} %s\\n\" \"$1\" >&2; exit 1; }\n\n[ \"$(id -u)\" -eq 0 ] || error \"Execute como root: sudo bash install_sh.sh\"\n\n# --- Detectar gerenciador de pacotes ---\n_apt_update_done=0\n_apt_update() {\n  if [ \"$_apt_update_done\" -eq 0 ]; then\n    info \"Executando apt-get update...\"\n    apt-get update -qq || error \"Falha ao executar apt-get update\"\n    _apt_update_done=1\n  fi\n}\n\n# --- Verificar Debian/Ubuntu ---\nif [ ! -f /etc/debian_version ]; then\n  error \"Este script requer Debian 11+ ou Ubuntu. /etc/debian_version nao encontrado.\"\nfi\nDEB_VER=$(cat /etc/debian_version 2>/dev/null || echo \"desconhecido\")\ninfo \"Sistema: Debian $DEB_VER\"\n\n# --- curl ---\nif ! command -v curl >/dev/null 2>&1; then\n  warn \"curl nao encontrado \u2014 instalando...\"\n  _apt_update && apt-get install -y -qq curl\n  command -v curl >/dev/null 2>&1 && info \"curl instalado\" || error \"Falha ao instalar curl\"\nfi\n\n# --- openssl ---\nif ! command -v openssl >/dev/null 2>&1; then\n  warn \"openssl nao encontrado \u2014 instalando...\"\n  _apt_update && apt-get install -y -qq openssl\n  command -v openssl >/dev/null 2>&1 && info \"openssl instalado\" || error \"Falha ao instalar openssl\"\nfi\n\n# --- sqlite3 ---\nif ! command -v sqlite3 >/dev/null 2>&1; then\n  warn \"sqlite3 nao encontrado \u2014 instalando...\"\n  _apt_update && apt-get install -y -qq sqlite3\n  command -v sqlite3 >/dev/null 2>&1 && info \"sqlite3 instalado\" || error \"Falha ao instalar sqlite3\"\nfi\n\n# --- python3-sqlite3 ---\nif ! python3 -c \"import sqlite3\" >/dev/null 2>&1; then\n  warn \"python3-sqlite3 nao encontrado \u2014 instalando...\"\n  _apt_update && apt-get install -y -qq python3-sqlite3\n  python3 -c \"import sqlite3; print('python3-sqlite3 ok')\" && info \"python3-sqlite3 instalado\" || error \"Falha ao instalar python3-sqlite3\"\nfi\n\n# --- Diret\u00f3rios de instala\u00e7\u00e3o ---\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nINSTALL_DIR=\"/var/www/llm\"\nSRC_DIR=\"$INSTALL_DIR/api/src\"\nDATA_DIR=\"$INSTALL_DIR/data\"\nmkdir -p \"$SRC_DIR\" \"$DATA_DIR\" && info \"Diret\u00f3rios criados: $SRC_DIR, $DATA_DIR\"\n\n# --- Banco de dados SQLite com performance optimizations ---\nDB_PATH=\"$DATA_DIR/llm.db\"\n\ninfo \"Inicializando banco de dados SQLite com optimiza\u00e7\u00f5es de desempenho...\"\n\nsqlite3 \"$DB_PATH\" <<SQLEOF\nPRAGMA journal_mode=WAL;\nPRAGMA synchronous=NORMAL;\nPRAGMA cache_size=-64000;         -- 64MB cache\nPRAGMA temp_store=MEMORY;\nPRAGMA foreign_keys=OFF;\n\nCREATE TABLE IF NOT EXISTS conversa (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    papel TEXT NOT NULL,\n    conteudo TEXT NOT NULL,\n    timestamp TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS interacoes (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    prompt TEXT NOT NULL,\n    resposta TEXT,\n    tokens_uso INTEGER,\n    modelo TEXT,\n    timestamp TEXT NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_interacoes_prompt ON interacoes(prompt);\nCREATE INDEX IF NOT EXISTS idx_interacoes_modelo ON interacoes(modelo);\nCREATE INDEX IF NOT EXISTS idx_interacoes_timestamp ON interacoes(timestamp);\n\nCREATE TABLE IF NOT EXISTS configuracoes (\n    chave TEXT PRIMARY KEY,\n    valor TEXT NOT NULL\n);\nSQLEOF\n\nchmod 600 \"$DB_PATH\" && info \"Banco de dados criado: $DB_PATH com WAL e indexes\"\n\n# Inserir configura\u00e7\u00f5es padr\u00e3o se nao existirem\nDEFAULT_CONTEXT_SIZE=1024\nDEFAULT_THREADS=2\nsqlite3 \"$DB_PATH\" \"INSERT OR IGNORE INTO configuracoes (chave, valor) VALUES ('CONTEXT_SIZE', '$DEFAULT_CONTEXT_SIZE');\"\nsqlite3 \"$DB_PATH\" \"INSERT OR IGNORE INTO configuracoes (chave, valor) VALUES ('THREADS', '$DEFAULT_THREADS');\"\ninfo \"Tabelas SQLite criadas com indexes de performance\"\n\n# --- Ponteiro Python para SQLite ---\nPY_BRIDGE_DST=\"$DATA_DIR/sqlite_llm_bridge.py\"\n\nif [ -f \"$SCRIPT_DIR/api/src/sqlite_llm_bridge.py\" ]; then\n  cp \"$SCRIPT_DIR/api/src/sqlite_llm_bridge.py\" \"$PY_BRIDGE_DST\"\n  chmod +x \"$PY_BRIDGE_DST\"\n  info \"Ponteiro Python copiado: $PY_BRIDGE_DST\"\nelse\n  warn \"Arquivo ponteiro Python nao encontrado em $SCRIPT_DIR/api/src/sqlite_llm_bridge.py \u2014 criando versao minima\"\n  cat > \"$PY_BRIDGE_DST\" <<'PYEOF'\n#!/usr/bin/env python3\nimport sqlite3, os, sys, datetime\nDB=os.getenv(\"LLM_DB_PATH\",\"/var/www/llm/data/llm.db\")\nc=sqlite3.connect(DB)\ndef log(p, t): c.execute(\"INSERT INTO conversa (papel,conteudo,timestamp) VALUES (?,?,?)\",(p,t,datetime.now().isoformat())); c.commit()\ndef hist(n=10): c.execute(\"SELECT papel,conteudo,timestamp FROM conversa ORDER BY id DESC LIMIT %s\"%(n,)); return c.fetchall()\ndef get(k,df=None): r=c.execute(\"SELECT valor FROM configuracoes WHERE chave=%s\"%(k,)).fetchone(); return r[0] if r else df\ndef setk(k,v): c.execute(\"INSERT OR REPLACE INTO configuracoes (chave,valor) VALUES (%s,%s)\"%(k,v)); c.commit()\nc.close()\nPYEOF\n  chmod +x \"$PY_BRIDGE_DST\"\n  info \"Ponteiro Python minim criado: $PY_BRIDGE_DST\"\nfi\n\n# --- .env ---\nif [ ! -f \"$INSTALL_DIR/.env\" ]; then\n  API_TOKEN=$(openssl rand -hex 16 2>/dev/null || echo \"$(date +%s)$RANDOM\" | md5sum | head -c 32)\n  cat > \"$INSTALL_DIR/.env\" <<ENVEOF\n# App\nPORT=8080\nAPI_TOKEN=$API_TOKEN\nCOMPOSE_PROJECT_NAME=llm\n\n# Modelo Llamafile\nMODEL_NAME=LFM2.5-230M-Q4_K_M\nMODEL_FILE=LFM2.5-Q4_K_M.llamafile\nGGUF_FILE=LFM2.5-230M-Q4_K_M.gguf\nCONTEXT_SIZE=1024\nTHREADS=2\nENVEOF\n  chmod 600 \"$INSTALL_DIR/.env\" && info \"Arquivo .env criado\"\nelse\n  info \"Arquivo .env ja existe: $INSTALL_DIR/.env\"\nfi\n\n# --- Baixar modelo GGUF se nao existir ---\nGGUF_SRC=\"$INSTALL_DIR/LFM2.5-230M-Q4_K_M.gguf\"\nif [ ! -f \"$GGUF_SRC\" ]; then\n  info \"Modelo GGUF nao encontrado. Baixando de HuggingFace...\"\n  wget -c --tries=5 --timeout=60 -O \"$GGUF_SRC\" \\\n    \"https://huggingface.co/LiquidAI/LFM2.5-230M-GGUF/resolve/main/LFM2.5-230M-Q4_K_M.gguf\" || \\\n    error \"Falha ao baixar o modelo GGUF de HuggingFace\"\n  info \"Modelo baixado: $GGUF_FILE\"\nelse\n  info \"Modelo GGUF ja existente: $GGUF_FILE\"\nfi\n\n# --- Baixar runtime llamafile ---\nLLAMAFILE_RUNTIME=\"llamafile-0.10.6\"\nLLAMAFILE_URL=\"https://github.com/Mozilla-Ocho/llamafile/releases/download/0.10.6/llamafile-0.10.6\"\nif [ -f \"$SCRIPT_DIR/$LLAMAFILE_RUNTIME\" ] && [ -x \"$SCRIPT_DIR/$LLAMAFILE_RUNTIME\" ]; then\n  info \"Usando runtime local: $LLAMAFILE_RUNTIME\"\nelse\n  warn \"$LLAMAFILE_RUNTIME nao encontrado. Baixando...\"\n  wget -O \"$SCRIPT_DIR/$LLAMAFILE_RUNTIME\" \"$LLAMAFILE_URL\" || error \"Falha ao baixar $LLAMAFILE_URL\"\n  chmod +x \"$SCRIPT_DIR/$LLAMAFILE_RUNTIME\"\n  info \"Baixado: $LLAMAFILE_RUNTIME\"\nfi\n\n# --- zipalign ---\nZIPALIGN=\"zipalign-0.10.6\"\nZIPALIGN_URL=\"https://github.com/Mozilla-Ocho/llamafile/releases/download/0.10.6/zipalign-0.10.6\"\nif [ -f \"$SCRIPT_DIR/$ZIPALIGN\" ] && [ -x \"$SCRIPT_DIR/$ZIPALIGN\" ]; then\n  info \"Usando zipalign local: $ZIPALIGN\"\nelse\n  warn \"$ZIPALIGN nao encontrado. Baixando...\"\n  wget -O \"$SCRIPT_DIR/$ZIPALIGN\" \"$ZIPALIGN_URL\" || error \"Falha ao baixar $ZIPALIGN_URL\"\n  chmod +x \"$SCRIPT_DIR/$ZIPALIGN\"\n  info \"Baixado: $ZIPALIGN\"\nfi\n\n# --- Gerar .llamafile executavel via zipalign -j0 ---\nLLAMAFILE_OUT=\"LFM2.5-230M-Q4_K_M.llamafile\"\nif [ -f \"$INSTALL_DIR/$LLAMAFILE_OUT\" ]; then\n  warn \"${LLAMAFILE_OUT} ja existe. Serah recriado.\"\n  rm -f \"$INSTALL_DIR/$LLAMAFILE_OUT\"\nfi\n\ninfo \"Copiando runtime para ${LLAMAFILE_OUT}...\"\ncp \"$SCRIPT_DIR/$LLAMAFILE_RUNTIME\" \"$INSTALL_DIR/$LLAMAFILE_OUT\"\nchmod +x \"$INSTALL_DIR/$LLAMAFILE_OUT\"\n\ninfo \"Empacotando GGUF + .args com zipalign (-j0)...\"\ncat > \"$INSTALL_DIR/.args\" <<ARGSEOF\n-m /zip/${GGUF_FILE}\n-c 1024\n--nologo\n-np 1\nARGSEOF\n\n\"$SCRIPT_DIR/$ZIPALIGN\" -j0 \"$INSTALL_DIR/$LLAMAFILE_OUT\" \"$GGUF_SRC\" \"$INSTALL_DIR/.args\" || \\\n  error \"Falha ao executar zipalign\"\nchmod +x \"$INSTALL_DIR/$LLAMAFILE_OUT\"\nSIZE_LLAMA=$(du -h \"$INSTALL_DIR/$LLAMAFILE_OUT\" | awk '{print $1}')\ninfo \"Gerado com sucesso: ${LLAMAFILE_OUT} (${SIZE_LLAMA})\"\n\n# --- Systemd service (opcional) ---\nSERVICE_FILE=\"/etc/systemd/system/lfm-llamafile.service\"\ncat > \"$SERVICE_FILE\" <<EOF\n[Unit]\nDescription=LFM2.5-230M Llamafile Server\nAfter=network.target\n\n[Service]\nType=simple\nUser=root\nWorkingDirectory=${INSTALL_DIR}\nExecStart=${INSTALL_DIR}/${LLAMAFILE_OUT} --ctx-size 1024 -t 2 -tb 2 -np 1 --server --host 127.0.0.1 --port 8080\nRestart=on-failure\nRestartSec=5\n\n[Install]\nWantedBy=multi-user.target\nEOF\nsystemctl daemon-reload 2>/dev/null || warn \"Nao foi possivel recarregar systemd\"\nsystemctl enable lfm-llamafile.service 2>/dev/null || warn \"Nao foi possivel habilitar o service systemd\"\ninfo \"Servico systemd criado: $SERVICE_FILE\"\n\n# --- Nginx: publicar o LLM em https://api.projetosdinamicos.com.br/llm/ ---\nNGINX_SITE=\"/etc/nginx/sites-available/default\"\nNGINX_DIR=\"/etc/nginx/llm.d\"\nNGINX_LOCATIONS=\"$NGINX_DIR/llm.conf\"\n# O curinga e proposital: se o diretorio estiver vazio, o nginx ignora o\n# include em vez de falhar. Assim o vhost pode ser recarregado antes do LLM.\nNGINX_INCLUDE=\"include ${NGINX_DIR}/*.conf;\"\ninfo \"Criando configuracao nginx...\"\n\nmkdir -p \"$NGINX_DIR\"\nchmod 755 \"$NGINX_DIR\"\n\n# Heredoc com o location. O `proxy_pass` com barra final remove /llm/ antes de\n# entregar ao llamafile: /llm/v1/chat/completions -> /v1/chat/completions.\ncat > \"$NGINX_LOCATIONS\" <<'NGINXEOF'\n# /llm/ -> llamafile (127.0.0.1:8080). Gerado por install_llm.sh.\nlocation /llm/ {\n    proxy_pass http://127.0.0.1:8080/;\n    proxy_http_version 1.1;\n    proxy_set_header Host $host;\n    proxy_set_header X-Real-IP $remote_addr;\n    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n    proxy_set_header X-Forwarded-Proto $scheme;\n\n    # Streaming (SSE): sem buffer e sem timeout curto\n    proxy_buffering off;\n    proxy_cache off;\n    proxy_read_timeout 600s;\n    proxy_send_timeout 600s;\n\n    # Prompts/contextos maiores que o default de 1M do nginx\n    client_max_body_size 25M;\n\n    # Rate limit por IP (zone definida em /etc/nginx/nginx.conf pelo instalador)\n    limit_req zone=llm burst=5 nodelay;\n    limit_req_status 429;\n\n    # CORS para a pagina estatica OpenChat (GitHub Pages / projetosdinamicos)\n    add_header Access-Control-Allow-Origin \"*\" always;\n    add_header Access-Control-Allow-Methods \"GET, POST, OPTIONS\" always;\n    add_header Access-Control-Allow-Headers \"Content-Type, Authorization\" always;\n    add_header Access-Control-Max-Age 86400 always;\n    if ($request_method = OPTIONS) { return 204; }\n}\nNGINXEOF\ninfo \"Location do LLM criada: $NGINX_LOCATIONS\"\n\n# --- Rate limit: a zone precisa estar no contexto http do nginx.conf ---\nNGINX_MAIN=\"/etc/nginx/nginx.conf\"\nNGINX_RATE_LINE='    limit_req_zone $binary_remote_addr zone=llm:10m rate=2r/s;'\nNGINX_MAIN_BACKUP=\"\"\nif grep -q 'zone=llm:' \"$NGINX_MAIN\" 2>/dev/null; then\n    info \"Rate limit do LLM ja presente em $NGINX_MAIN\"\nelse\n    NGINX_MAIN_BACKUP=\"$NGINX_MAIN.bak.$(date +%Y%m%d-%H%M%S)\"\n    cp -a \"$NGINX_MAIN\" \"$NGINX_MAIN_BACKUP\"\n    TMP_MAIN=$(mktemp)\n    awk -v line=\"$NGINX_RATE_LINE\" '\n        { print }\n        !done && /^[[:space:]]*http[[:space:]]*\\{/ { print line; done = 1 }\n    ' \"$NGINX_MAIN\" > \"$TMP_MAIN\"\n\n    if grep -q 'zone=llm:' \"$TMP_MAIN\"; then\n        chmod --reference=\"$NGINX_MAIN\" \"$TMP_MAIN\" 2>/dev/null || chmod 644 \"$TMP_MAIN\"\n        mv \"$TMP_MAIN\" \"$NGINX_MAIN\"\n        info \"Rate limit adicionado em $NGINX_MAIN (2 req/s, burst 5)\"\n    else\n        rm -f \"$TMP_MAIN\"\n        NGINX_MAIN_BACKUP=\"\"\n        warn \"Nao encontrei o bloco 'http {' em $NGINX_MAIN\"\n        warn \"Adicione manualmente: $NGINX_RATE_LINE\"\n        # Sem a zone, 'limit_req' no location quebraria o nginx -t.\n        sed -i '/limit_req zone=llm/d; /limit_req_status 429/d' \"$NGINX_LOCATIONS\" 2>/dev/null || true\n        warn \"Rate limit removido do location; o LLM sobe sem limite por IP\"\n    fi\nfi\n\n# Inclui o arquivo dentro do server 443 de api.projetosdinamicos.com.br.\n# Insere logo apos o marcador do bloco amoranimal (que fica nesse server),\n# de forma idempotente: se o include ja existe, nao duplica.\nNGINX_BACKUP=\"\"\nif grep -qF \"$NGINX_INCLUDE\" \"$NGINX_SITE\" 2>/dev/null; then\n    info \"Include do LLM ja presente em $NGINX_SITE\"\nelse\n    NGINX_BACKUP=\"$NGINX_SITE.bak.$(date +%Y%m%d-%H%M%S)\"\n    cp -a \"$NGINX_SITE\" \"$NGINX_BACKUP\"\n    TMP_CONF=$(mktemp)\n    awk -v inc=\"    $NGINX_INCLUDE\" '\n        { print }\n        /# LOCATION_END amoranimal/ { print inc }\n    ' \"$NGINX_SITE\" > \"$TMP_CONF\"\n\n    if grep -qF \"$NGINX_INCLUDE\" \"$TMP_CONF\"; then\n        chmod --reference=\"$NGINX_SITE\" \"$TMP_CONF\" 2>/dev/null || chmod 644 \"$TMP_CONF\"\n        mv \"$TMP_CONF\" \"$NGINX_SITE\"\n        info \"Include do LLM adicionado em $NGINX_SITE\"\n    else\n        rm -f \"$TMP_CONF\"\n        warn \"Marcador '# LOCATION_END amoranimal' nao encontrado em $NGINX_SITE\"\n        warn \"Adicione manualmente esta linha dentro do server 443: $NGINX_INCLUDE\"\n    fi\nfi\n\n# Valida e recarrega; se falhar, restaura os backups para nao derrubar a 443\nif nginx -t; then\n    systemctl reload nginx 2>/dev/null || systemctl restart nginx\n    info \"Nginx recarregado\"\nelse\n    if [ -n \"$NGINX_BACKUP\" ]; then\n        cp -a \"$NGINX_BACKUP\" \"$NGINX_SITE\"\n        warn \"Config restaurada de $NGINX_BACKUP\"\n    fi\n    if [ -n \"$NGINX_MAIN_BACKUP\" ]; then\n        cp -a \"$NGINX_MAIN_BACKUP\" \"$NGINX_MAIN\"\n        warn \"Config restaurada de $NGINX_MAIN_BACKUP\"\n    fi\n    error \"nginx -t falhou ao configurar /llm/\"\nfi\n\n# --- Final ---\necho \"\"\ninfo \"===== Instalacao concluida! =====\"\necho \"\"\necho \"  Pasta:   $INSTALL_DIR\"\necho \"  Modelo:  $LLAMAFILE_OUT\"\necho \"  API:     http://127.0.0.1:8080/health\"\necho \"  Publico: https://api.projetosdinamicos.com.br/llm/health\"\necho \"  OpenChat: https://www.projetosdinamicos.com.br/openchat.html\"\necho \"  Banco:   $DB_PATH (SQLite com WAL e indexes)\"\necho \"  Bridge:  $PY_BRIDGE_DST\"\necho \"\"\necho \"  Comandos utilis:\"\necho \"    Logs:      $LLAMAFILE_OUT --ctx-size 1024 -t 2 -tb 2 -np 1 --server --host 127.0.0.1 --port 8080\"\necho \"    Service:   systemctl start/stop lfm-llamafile\"\necho \"    Stop:      pkill -f '$LLAMAFILE_OUT'\"\necho \"\"\necho \"  .env:    $INSTALL_DIR/.env\"\necho \"\"\n\ninfo \"Testando API...\"\nresp=$(curl -s \"http://127.0.0.1:8080/health\" 2>/dev/null) || resp=\"\"\necho \"$resp\" | grep -q '\"status\":\"ok\"' && info \"Local:      \u2713 http://127.0.0.1:8080/health\" || warn \"Local:      \u2717 $resp\"\n\ncode=$(curl -s -o /dev/null -w '%{http_code}' \\\n    \"https://api.projetosdinamicos.com.br/llm/health\" 2>/dev/null) || code=000\n[ \"$code\" = \"200\" ] \\\n    && info \"Publico:    \u2713 https://api.projetosdinamicos.com.br/llm/health\" \\\n    || warn \"Publico:    \u2717 HTTP $code (confira DNS, certificado e nginx)\"\n\necho && info \"Testes concluidos!\"", "manutencao-api.sh": "#!/usr/bin/env bash\n# =============================================================================\n# manutencao-api.sh \u2014 Diagn\u00f3stico de manuten\u00e7\u00e3o da API (somente leitura)\n#\n# Cobre os quatro pontos pedidos:\n#   1. Docker       \u2014 daemon, containers, sa\u00fade, restarts, portas, compose\n#   2. Descoberta   \u2014 quem escuta, qual processo/arquivo, systemd, containers\n#   3. server.js    \u2014 exist\u00eancia, sintaxe, permiss\u00f5es, m\u00f3dulos, vers\u00e3o em uso\n#   4. nginx        \u2014 nginx -t, vhost carregado, locations duplicadas,\n#                     upstreams, certificados, CORS e probe p\u00fablico\n#\n# Uso:\n#   sudo bash manutencao-api.sh\n#   sudo API_FILE=/var/www/projeto/api/sc/server.js bash manutencao-api.sh\n#   bash manutencao-api.sh --help\n#\n# Vari\u00e1veis de ambiente:\n#   API_FILE      arquivo da API        (default: /var/www/projeto/api/sc/server.js)\n#   NGINX_SITE    vhost                 (default: /etc/nginx/sites-available/default)\n#   DOMINIO       host p\u00fablico          (default: api.projetosdinamicos.com.br)\n#   API_PREFIX    prefixo da API        (default: amoranimal)\n#   LLM_PREFIX    prefixo do LLM        (default: llm)\n#   PORTA_LOCAL   porta esperada        (default: 3002)\n#   API_HEALTH    rota de health        (default: /health)\n#   CONTAINER_RE  nomes de containers   (default: amoranimal|crebortoli|llamafile|api|node)\n#\n# Sa\u00edda:\n#   0 = tudo ok | 1 = avisos | 2 = falhas\n#\n# O script N\u00c3O altera nada (sem restart, sem reload, sem escrita de config).\n# =============================================================================\n\nset -u\n\nAPI_FILE=\"${API_FILE:-/var/www/projeto/api/sc/server.js}\"\nNGINX_SITE=\"${NGINX_SITE:-/etc/nginx/sites-available/default}\"\nDOMINIO=\"${DOMINIO:-api.projetosdinamicos.com.br}\"\nAPI_PREFIX=\"${API_PREFIX:-amoranimal}\"\nLLM_PREFIX=\"${LLM_PREFIX:-llm}\"\nPORTA_LOCAL=\"${PORTA_LOCAL:-3002}\"\nAPI_HEALTH=\"${API_HEALTH:-/health}\"\nORIGEM=\"${ORIGEM:-https://www.${DOMINIO#api.}}\"\nCONTAINER_RE=\"${CONTAINER_RE:-amoranimal|crebortoli|llamafile|api|node}\"\n\n_c_ok=0\n_c_warn=0\n_c_fail=0\n\nif [ -t 1 ]; then\n    R=$'\\033[0;31m'; G=$'\\033[0;32m'; Y=$'\\033[1;33m'\n    B=$'\\033[0;34m'; C=$'\\033[0;36m'; N=$'\\033[0m'\nelse\n    R=''; G=''; Y=''; B=''; C=''; N=''\nfi\n\nok()    { _c_ok=$((_c_ok + 1));    printf '  %s[ OK ]%s %s\\n'  \"$G\" \"$N\" \"$*\"; }\naviso() { _c_warn=$((_c_warn + 1)); printf '  %s[AVISO]%s %s\\n' \"$Y\" \"$N\" \"$*\"; }\nfalha() { _c_fail=$((_c_fail + 1)); printf '  %s[FALHA]%s %s\\n' \"$R\" \"$N\" \"$*\"; }\ninfo()  {                           printf '  %s[info]%s %s\\n'  \"$B\" \"$N\" \"$*\"; }\nsecao() {                           printf '\\n%s== %s ==%s\\n'    \"$C\" \"$*\" \"$N\"; }\n\nuso() {\n    sed -n '3,/^# ====/p' \"$0\" | sed 's/^# \\{0,1\\}//' | grep -v '^=*$'\n    exit 0\n}\n\ncase \"${1:-}\" in\n    -h|--help) uso ;;\n    '') ;;\n    *) echo \"Op\u00e7\u00e3o desconhecida: $1 (use --help)\" >&2; exit 64 ;;\nesac\n\n# Privil\u00e9gio: usa sudo -n se j\u00e1 n\u00e3o for root; se n\u00e3o der, segue sem e avisa.\nSUDO=\"\"\nSEM_PRIV=0\nif [ \"$(id -u)\" -eq 0 ]; then\n    SUDO=\"\"\nelif command -v sudo >/dev/null 2>&1 && sudo -n true 2>/dev/null; then\n    SUDO=\"sudo\"\nelse\n    SEM_PRIV=1\nfi\n\nexiste() { [ -e \"$1\" ]; }\ntem_cmd() { command -v \"$1\" >/dev/null 2>&1; }\nporta_aberta() {\n    local p=\"$1\"\n    tem_cmd ss || return 1\n    ss -tlnH 2>/dev/null | awk '{print $4}' | grep -qE \"[:.]${p}$\"\n}\n\n# =============================================================================\n# 0. AMBIENTE\n# =============================================================================\nsecao \"0. Ambiente\"\n\ninfo \"$(hostname) \u2022 $(date '+%Y-%m-%d %H:%M:%S %Z') \u2022 kernel $(uname -r)\"\ninfo \"uptime:$(uptime -p 2>/dev/null | sed 's/^up/ up/')\"\n[ \"$SUDO\" = \"sudo\" ] && info \"executando com sudo -n\"\n[ \"$SEM_PRIV\" -eq 1 ] && aviso \"sem root/sudo: algumas checagens (ss -p, docker, nginx -T, logs) ficam limitadas\"\n\nif tem_cmd df; then\n    while read -r uso_pct ponto; do\n        uso_num=${uso_pct%\\%}\n        if [ \"${uso_num:-0}\" -ge 90 ] 2>/dev/null; then\n            aviso \"disco ${ponto} em ${uso_pct}\"\n        else\n            info \"disco ${ponto} em ${uso_pct}\"\n        fi\n    done < <(df -P / /var 2>/dev/null | awk 'NR>1 {print $5, $6}' | sort -u)\nfi\n\n# =============================================================================\n# 1. DOCKER\n# =============================================================================\nsecao \"1. Docker\"\n\nCONTAINERS_RELACIONADOS=()\n\nif ! tem_cmd docker; then\n    aviso \"docker n\u00e3o instalado (se a API n\u00e3o usa containers, ignore)\"\nelse\n    if ! $SUDO docker info >/dev/null 2>&1; then\n        falha \"docker instalado, mas o daemon n\u00e3o responde (systemctl status docker)\"\n    else\n        ok \"daemon docker ativo \u2014 vers\u00e3o $($SUDO docker version --format '{{.Server.Version}}' 2>/dev/null)\"\n\n        if $SUDO docker compose version >/dev/null 2>&1; then\n            info \"docker compose: $($SUDO docker compose version --short 2>/dev/null)\"\n        elif tem_cmd docker-compose; then\n            info \"docker-compose (v1): $(docker-compose version --short 2>/dev/null)\"\n        else\n            aviso \"nem 'docker compose' nem 'docker-compose' dispon\u00edveis\"\n        fi\n\n        mapa=$($SUDO docker ps -a --format '{{.Names}}\\t{{.Image}}\\t{{.Status}}' 2>/dev/null)\n        if [ -z \"$mapa\" ]; then\n            info \"nenhum container criado\"\n        else\n            while IFS=$'\\t' read -r nome imagem status; do\n                [ -n \"$nome\" ] || continue\n                if echo \"$nome\" | grep -Eqi \"$CONTAINER_RE\"; then\n                    CONTAINERS_RELACIONADOS+=(\"$nome\")\n                    if echo \"$status\" | grep -q '^Up'; then\n                        ok \"container ${nome} \u2014 ${status} (${imagem})\"\n                    else\n                        falha \"container ${nome} \u2014 ${status} (${imagem})\"\n                    fi\n\n                    health=$($SUDO docker inspect -f '{{if .State.Health}}{{.State.Health.Status}}{{else}}-{{end}}' \"$nome\" 2>/dev/null)\n                    restarts=$($SUDO docker inspect -f '{{.RestartCount}}' \"$nome\" 2>/dev/null)\n                    portas=$($SUDO docker port \"$nome\" 2>/dev/null | tr '\\n' ' ')\n\n                    [ -n \"${restarts:-}\" ] && [ \"${restarts:-0}\" -gt 5 ] 2>/dev/null \\\n                        && aviso \"container ${nome} reiniciou ${restarts}x (crash loop?)\"\n                    case \"${health:-}\" in\n                        healthy)   info \"${nome}: health healthy\" ;;\n                        unhealthy) falha \"${nome}: health unhealthy\" ;;\n                        starting)  aviso \"${nome}: health starting (ainda subindo)\" ;;\n                    esac\n                    [ -n \"${portas:-}\" ] && info \"${nome}: ${portas}\"\n                fi\n            done <<< \"$mapa\"\n\n            outros=$(printf '%s\\n' \"$mapa\" | cut -f1 | grep -Evi \"$CONTAINER_RE\" | wc -l)\n            [ \"$outros\" -gt 0 ] && info \"${outros} container(s) fora do filtro de nome\"\n        fi\n\n        # Projetos compose em execu\u00e7\u00e3o\n        if $SUDO docker compose ls -a >/dev/null 2>&1; then\n            projetos=$($SUDO docker compose ls -a 2>/dev/null | tail -n +2)\n            if [ -n \"$projetos\" ]; then\n                info \"projetos compose:\"\n                printf '%s\\n' \"$projetos\" | sed 's/^/         /'\n            fi\n        fi\n\n        if $SUDO docker system df >/dev/null 2>&1; then\n            info \"uso do docker:\"\n            $SUDO docker system df 2>/dev/null | sed 's/^/         /'\n        fi\n    fi\nfi\n\n# =============================================================================\n# 2. DESCOBERTA DA API\n# =============================================================================\nsecao \"2. Descoberta da API\"\n\n# Escolhe o arquivo: vari\u00e1vel > candidatos conhecidos\nAPI_FILE_ORIGEM=\"vari\u00e1vel API_FILE\"\nif ! existe \"$API_FILE\"; then\n    encontrado=\"\"\n    for cand in \\\n        /var/www/projeto/api/sc/server.js \\\n        /var/www/projeto/api/server.js \\\n        /home/*/scripts/server.js \\\n        /opt/*/server.js \\\n        /srv/*/server.js\n    do\n        if [ -f \"$cand\" ]; then encontrado=\"$cand\"; break; fi\n    done\n    if [ -n \"$encontrado\" ]; then\n        aviso \"$API_FILE n\u00e3o existe; usando candidato $encontrado\"\n        API_FILE=\"$encontrado\"\n        API_FILE_ORIGEM=\"descoberta autom\u00e1tica\"\n    else\n        falha \"$API_FILE n\u00e3o existe e nenhum candidato foi encontrado\"\n        API_FILE_ORIGEM=\"\"\n    fi\nfi\n[ -n \"$API_FILE_ORIGEM\" ] && [ -f \"$API_FILE\" ] && info \"arquivo da API: $API_FILE ($API_FILE_ORIGEM)\"\n\n# Portas escutando\nPORTA_PIDS=()      # \"porta:pid\"\nPORTAS_API=()\nif tem_cmd ss; then\n    linhas_ss=$($SUDO ss -tlnp 2>/dev/null | awk 'NR>1')\n    if [ -z \"$linhas_ss\" ]; then\n        falha \"nenhum socket TCP escutando (ss vazio)\"\n    else\n        while IFS= read -r linha; do\n            [ -n \"$linha\" ] || continue\n            endereco=$(awk '{print $4}' <<< \"$linha\")\n            porta=${endereco##*:}\n            case \"$porta\" in ''|'*'|*[!0-9]*) continue ;; esac\n            pid=$(sed -n 's/.*pid=\\([0-9][0-9]*\\).*/\\1/p' <<< \"$linha\" | head -1)\n            prog=$(sed -n 's/.*users:((\"\\([^\"]*\\)\".*/\\1/p' <<< \"$linha\" | head -1)\n            [ -n \"$pid\" ] && PORTA_PIDS+=(\"${porta}:${pid}\")\n\n            case \"$porta\" in\n                80|443|3001|3002|8080) info \"porta ${porta} \u2014 ${prog:-?}${pid:+ (pid $pid)}\" ;;\n            esac\n\n            if [ -n \"$pid\" ] && [ -r \"/proc/$pid/cmdline\" ]; then\n                cmd=$(tr '\\0' ' ' < \"/proc/$pid/cmdline\" 2>/dev/null)\n                if echo \"$cmd\" | grep -Eq 'node|llamafile|gunicorn|uvicorn'; then\n                    cwd=$(readlink \"/proc/$pid/cwd\" 2>/dev/null)\n                    alvo=\"\"\n                    for arg in $cmd; do\n                        case \"$arg\" in *.js|*.mjs|*.cjs) alvo=\"$arg\" ;; esac\n                    done\n                    case \"$alvo\" in\n                        /*) arquivo_proc=\"$alvo\" ;;\n                        '') arquivo_proc=\"\" ;;\n                        *)  arquivo_proc=\"${cwd%/}/${alvo}\" ;;\n                    esac\n                    PORTAS_API+=(\"$porta\")\n                    info \"porta ${porta}: pid ${pid} \u2014 ${arquivo_proc:-$cmd}\"\n                    if [ -n \"$arquivo_proc\" ] && [ -f \"$API_FILE\" ] \\\n                        && [ \"$(readlink -f \"$arquivo_proc\" 2>/dev/null)\" = \"$(readlink -f \"$API_FILE\" 2>/dev/null)\" ]; then\n                        ok \"processo pid ${pid} est\u00e1 executando $API_FILE\"\n                        API_PID=\"$pid\"\n                    fi\n                fi\n            fi\n        done <<< \"$linhas_ss\"\n    fi\n\n    # Fallback: pgrep em processos node\n    if tem_cmd pgrep; then\n        while read -r pid; do\n            [ -n \"$pid\" ] || continue\n            cwd=$(readlink \"/proc/$pid/cwd\" 2>/dev/null)\n            cmd=$(tr '\\0' ' ' < \"/proc/$pid/cmdline\" 2>/dev/null)\n            [ -n \"$cmd\" ] && info \"processo node pid ${pid}: ${cmd} (cwd: ${cwd:-?})\"\n        done < <(pgrep -f '[n]ode .*\\.js' 2>/dev/null)\n    fi\nelse\n    aviso \"ss n\u00e3o dispon\u00edvel \u2014 descoberta de portas limitada\"\nfi\n\n# Unidades systemd relacionadas\nif tem_cmd systemctl; then\n    unidades=$(systemctl list-units --type=service --no-legend --no-pager 2>/dev/null \\\n        | awk '{print $1, $3, $4}' | grep -Ei 'amoranimal|crebortoli|llama|(^|[^a-z])api([^a-z]|$)|(^|[^a-z])node([^a-z]|$)' || true)\n    if [ -n \"$unidades\" ]; then\n        info \"servi\u00e7os systemd relacionados:\"\n        printf '%s\\n' \"$unidades\" | sed 's/^/         /'\n        while read -r u; do\n            [ -n \"$u\" ] && falha \"servi\u00e7o ${u} n\u00e3o est\u00e1 ativo\"\n        done < <(printf '%s\\n' \"$unidades\" | awk '$2!=\"active\" {print $1}')\n    else\n        info \"nenhum servi\u00e7o systemd com nome de API/node\"\n    fi\nfi\n\n# Sondas locais de health (portas do processo + esperadas)\nportas_probe=$(printf '%s\\n' \"${PORTAS_API[@]:-}\" \"$PORTA_LOCAL\" 3001 3002 8080 \\\n    | grep -E '^[0-9]+$' | sort -un)\nfor p in $portas_probe; do\n    code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 3 \"http://127.0.0.1:${p}${API_HEALTH}\" 2>/dev/null)\n    case \"$code\" in\n        200) ok \"GET 127.0.0.1:${p}${API_HEALTH} -> 200\" ;;\n        000|'') info \"127.0.0.1:${p} sem resposta (porta fechada)\" ;;\n        *)   aviso \"GET 127.0.0.1:${p}${API_HEALTH} -> ${code}\" ;;\n    esac\ndone\n\n# Sonda p\u00fablica: pela 443 local (se esta m\u00e1quina for o edge) ou por DNS real\nif tem_cmd curl; then\n    if porta_aberta 443; then\n        code=$(curl -k -s -o /dev/null -w '%{http_code}' --max-time 8 \\\n            --resolve \"${DOMINIO}:443:127.0.0.1\" \\\n            \"https://${DOMINIO}/${API_PREFIX}${API_HEALTH}\" 2>/dev/null)\n        case \"$code\" in\n            200) ok \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} -> 200 (via localhost)\" ;;\n            000|'') falha \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} sem resposta (nginx parado?)\" ;;\n            *)   aviso \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} -> ${code}\" ;;\n        esac\n    else\n        info \"esta m\u00e1quina n\u00e3o escuta 443 \u2014 testando o dom\u00ednio pela internet\"\n        code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 \\\n            \"https://${DOMINIO}/${API_PREFIX}${API_HEALTH}\" 2>/dev/null)\n        case \"$code\" in\n            200) ok \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} -> 200 (via DNS)\" ;;\n            000|'') falha \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} inacess\u00edvel (DNS/firewall/edge)\" ;;\n            *)   aviso \"p\u00fablico ${DOMINIO}/${API_PREFIX}${API_HEALTH} -> ${code} (via DNS)\" ;;\n        esac\n    fi\nfi\n\n# =============================================================================\n# 3. ARQUIVO DA API (server.js)\n# =============================================================================\nsecao \"3. Arquivo da API\"\n\nif [ -z \"${API_FILE_ORIGEM:-}\" ] || [ ! -f \"$API_FILE\" ]; then\n    falha \"arquivo da API n\u00e3o encontrado \u2014 pulando testes de server.js\"\nelse\n    dono=$(stat -c '%U:%G' \"$API_FILE\" 2>/dev/null)\n    perm=$(stat -c '%a' \"$API_FILE\" 2>/dev/null)\n    tam=$(stat -c '%s' \"$API_FILE\" 2>/dev/null)\n    mtime=$(stat -c '%y' \"$API_FILE\" 2>/dev/null)\n    sha=$(sha256sum \"$API_FILE\" 2>/dev/null | awk '{print $1}')\n    info \"${API_FILE}\"\n    info \"dono ${dono} \u2022 perms ${perm} \u2022 ${tam} bytes \u2022 mtime ${mtime}\"\n    info \"sha256 ${sha}\"\n\n    case \"$perm\" in\n        6[0-7][0-7]|7[0-7][0-7]) : ;;\n        *) aviso \"permiss\u00f5es ${perm}: o servidor web/container pode n\u00e3o conseguir ler\" ;;\n    esac\n    echo \"$dono\" | grep -q '^root:' && aviso \"arquivo pertence a root \u2014 confirme se o processo roda como root (evite)\"\n\n    # Sintaxe: node no host ou dentro de um container\n    if tem_cmd node; then\n        if node --check \"$API_FILE\" >/tmp/manut_node_check.$$ 2>&1; then\n            ok \"node --check (host): sintaxe v\u00e1lida\"\n        else\n            falha \"node --check (host): $(tr '\\n' ' ' < /tmp/manut_node_check.$$ | cut -c1-220)\"\n        fi\n        rm -f /tmp/manut_node_check.$$\n    else\n        checado=0\n        for c in \"${CONTAINERS_RELACIONADOS[@]:-}\"; do\n            [ -n \"$c\" ] || continue\n            if $SUDO docker exec \"$c\" test -f \"$API_FILE\" 2>/dev/null; then\n                if $SUDO docker exec \"$c\" node --check \"$API_FILE\" >/tmp/manut_node_check.$$ 2>&1; then\n                    ok \"node --check (container ${c}): sintaxe v\u00e1lida\"\n                else\n                    falha \"node --check (container ${c}): $(tr '\\n' ' ' < /tmp/manut_node_check.$$ | cut -c1-220)\"\n                fi\n                rm -f /tmp/manut_node_check.$$\n                checado=1\n                break\n            fi\n        done\n        [ \"$checado\" -eq 0 ] && aviso \"node n\u00e3o dispon\u00edvel no host nem com o arquivo exposto em container \u2014 sintaxe n\u00e3o validada\"\n    fi\n\n    # M\u00f3dulos relativos que n\u00e3o existem (erro cl\u00e1ssico ap\u00f3s mover/renomear arquivos)\n    faltando=0\n    if tem_cmd grep; then\n        while read -r req; do\n            [ -n \"$req\" ] || continue\n            base=\"${API_FILE%/*}\"\n            alvo=\"${base}/${req}\"\n            if ! existe \"$alvo\" && ! existe \"${alvo}.js\" && ! existe \"${alvo}.json\" \\\n                && ! existe \"${alvo}/index.js\" && ! existe \"${alvo}/index.json\"; then\n                falha \"require('${req}') n\u00e3o resolve (procurado em ${base})\"\n                faltando=$((faltando + 1))\n            fi\n        done < <(grep -oE \"require\\\\(['\\\"]\\\\./[^'\\\"]+\" \"$API_FILE\" 2>/dev/null \\\n            | sed -E \"s/.*require\\\\(['\\\"]//\" | sort -u)\n        [ \"$faltando\" -eq 0 ] && ok \"todos os require('./...') resolvem\"\n    fi\n\n    # Listen/porta e .env\n    if grep -qE '\\.listen\\(' \"$API_FILE\"; then\n        linhas_listen=$(grep -nE '\\.listen\\(' \"$API_FILE\" | head -3 | sed 's/^/         /')\n        info \"listen():\"\n        printf '%s\\n' \"$linhas_listen\"\n    else\n        aviso \"n\u00e3o encontrei .listen( no arquivo \u2014 confirme como a API \u00e9 servida\"\n    fi\n\n    env_file=\"${API_FILE%/*}/.env\"\n    if [ -f \"$env_file\" ]; then\n        porta_env=$(grep -E '^[[:space:]]*PORT[[:space:]]*=' \"$env_file\" 2>/dev/null | tail -1 | cut -d= -f2- | tr -d '\"' | tr -d \"'\" | tr -d '[:space:]')\n        info \".env encontrado \u2022 PORT=${porta_env:-n\u00e3o definido}\"\n        if [ -n \"${porta_env:-}\" ] && [ -n \"${PORTAS_API[0]:-}\" ] && [ \"$porta_env\" != \"${PORTAS_API[0]}\" ]; then\n            aviso \".env PORT=${porta_env} difere da porta escutada ${PORTAS_API[0]}\"\n        fi\n    else\n        info \"sem .env em ${API_FILE%/*} (vari\u00e1veis v\u00eam do systemd/compose?)\"\n    fi\n\n    # Arquivo mais novo que o processo em execu\u00e7\u00e3o => precisa reiniciar\n    if [ -n \"${API_PID:-}\" ] && [ -r \"/proc/${API_PID}\" ]; then\n        inicio_proc=$(stat -c '%Y' \"/proc/${API_PID}\" 2>/dev/null)\n        mtime_epoch=$(stat -c '%Y' \"$API_FILE\" 2>/dev/null)\n        if [ -n \"${inicio_proc:-}\" ] && [ -n \"${mtime_epoch:-}\" ] && [ \"$mtime_epoch\" -gt \"$inicio_proc\" ]; then\n            aviso \"server.js foi alterado DEPOIS do start do pid ${API_PID} \u2014 reinicie o servi\u00e7o para aplicar\"\n        else\n            ok \"processo em execu\u00e7\u00e3o (pid ${API_PID}) iniciou depois da \u00faltima altera\u00e7\u00e3o do arquivo\"\n        fi\n    fi\n\n    # Vers\u00e3o do arquivo dentro do container vs host\n    for c in \"${CONTAINERS_RELACIONADOS[@]:-}\"; do\n        [ -n \"$c\" ] || continue\n        if $SUDO docker exec \"$c\" test -f \"$API_FILE\" 2>/dev/null; then\n            sha_ct=$($SUDO docker exec \"$c\" sha256sum \"$API_FILE\" 2>/dev/null | awk '{print $1}')\n            if [ -n \"${sha_ct:-}\" ] && [ \"$sha_ct\" = \"$sha\" ]; then\n                ok \"c\u00f3pia dentro de ${c} id\u00eantica ao host\"\n            else\n                aviso \"c\u00f3pia dentro de ${c} DIFERENTE do host (container precisa de rebuild/copy)\"\n            fi\n        fi\n    done\n\n    # Backups e diferen\u00e7as\n    backups=$(ls -1t \"${API_FILE}\".bak* \"${API_FILE%.js}\"*.bak* 2>/dev/null | head -5 || true)\n    if [ -n \"$backups\" ]; then\n        info \"backups recentes:\"\n        printf '%s\\n' \"$backups\" | sed 's/^/         /'\n        ultimo=$(printf '%s\\n' \"$backups\" | head -1)\n        cmp -s \"$API_FILE\" \"$ultimo\" && info \"\u00faltimo backup \u00e9 id\u00eantico ao arquivo atual\" \\\n            || info \"arquivo atual difere do \u00faltimo backup ($(basename \"$ultimo\"))\"\n    else\n        info \"nenhum backup .bak encontrado ao lado do arquivo\"\n    fi\n\n    # Logs recentes com erro\n    if [ -n \"${API_PID:-}\" ]; then\n        unidade=$(sed -n 's#.*/\\([^/]*\\.service\\).*#\\1#p' \"/proc/${API_PID}/cgroup\" 2>/dev/null | head -1)\n        if [ -n \"${unidade:-}\" ] && tem_cmd journalctl; then\n            erros=$($SUDO journalctl -u \"$unidade\" -n 120 --no-pager 2>/dev/null | grep -iE 'error|exception|unhandled|ECONN|EADDRINUSE' | tail -5)\n            if [ -n \"$erros\" ]; then\n                aviso \"\u00faltimos erros em ${unidade}:\"\n                printf '%s\\n' \"$erros\" | sed 's/^/         /'\n            else\n                ok \"journalctl -u ${unidade}: sem erros nas \u00faltimas 120 linhas\"\n            fi\n        fi\n    fi\n    for c in \"${CONTAINERS_RELACIONADOS[@]:-}\"; do\n        [ -n \"$c\" ] || continue\n        erros=$($SUDO docker logs --tail 120 \"$c\" 2>&1 | grep -iE 'error|exception|unhandled|ECONN|EADDRINUSE' | tail -5)\n        if [ -n \"$erros\" ]; then\n            aviso \"\u00faltimos erros no container ${c}:\"\n            printf '%s\\n' \"$erros\" | sed 's/^/         /'\n        fi\n    done\nfi\n\n# =============================================================================\n# 4. NGINX\n# =============================================================================\nsecao \"4. Nginx\"\n\nif ! tem_cmd nginx; then\n    falha \"nginx n\u00e3o instalado\"\nelse\n    info \"nginx $(nginx -v 2>&1 | sed 's#nginx version: nginx/##')\"\n\n    # nginx -t\n    if saida_t=$($SUDO nginx -t 2>&1); then\n        ok \"nginx -t: configura\u00e7\u00e3o v\u00e1lida\"\n        printf '%s\\n' \"$saida_t\" | grep -Ei 'warn|emerg' | sed 's/^/         /'\n    else\n        falha \"nginx -t FALHOU \u2014 $(printf '%s' \"$saida_t\" | tr '\\n' ' ' | cut -c1-240)\"\n        printf '%s\\n' \"$saida_t\" | sed 's/^/         /'\n    fi\n\n    # Servi\u00e7o ativo\n    if tem_cmd systemctl; then\n        estado=$(systemctl is-active nginx 2>/dev/null)\n        [ \"$estado\" = \"active\" ] && ok \"systemd: nginx active\" || falha \"systemd: nginx ${estado:-desconhecido}\"\n    fi\n\n    # Escuta 80/443 \u2014 o sintoma que derrubou a API antes\n    if tem_cmd ss; then\n        for p in 80 443; do\n            if porta_aberta \"$p\"; then\n                ok \"escutando na porta ${p}\"\n            else\n                falha \"nada escutando na porta ${p} (nginx carregou algum server block?)\"\n            fi\n        done\n    else\n        aviso \"ss n\u00e3o dispon\u00edvel \u2014 n\u00e3o foi poss\u00edvel verificar 80/443\"\n    fi\n\n    # Arquivo do vhost e symlink\n    if [ -f \"$NGINX_SITE\" ]; then\n        ok \"vhost existe: $NGINX_SITE\"\n        alvo=$(readlink -f \"$NGINX_SITE\" 2>/dev/null)\n        for en in /etc/nginx/sites-enabled/*; do\n            [ -e \"$en\" ] || continue\n            if [ \"$(readlink -f \"$en\" 2>/dev/null)\" = \"$alvo\" ]; then\n                ok \"habilitado via $(basename \"$en\")\"\n                HABILITADO=1\n            fi\n        done\n        [ \"${HABILITADO:-0}\" -eq 1 ] || falha \"vhost n\u00e3o est\u00e1 em sites-enabled \u2014 o nginx n\u00e3o carrega esse arquivo\"\n\n        # O arquivo testado \u00e9 o que o nginx realmente carrega?\n        if $SUDO nginx -T >/dev/null 2>&1; then\n            if $SUDO nginx -T 2>/dev/null | grep -q \"configuration file ${alvo}\"; then\n                ok \"nginx -T confirma que ${alvo} est\u00e1 carregado\"\n            else\n                falha \"nginx -T N\u00c3O mostra ${alvo} \u2014 voc\u00ea est\u00e1 editando o arquivo errado\"\n            fi\n        else\n            aviso \"nginx -T indispon\u00edvel (sem permiss\u00e3o?) \u2014 n\u00e3o foi poss\u00edvel confirmar o arquivo carregado\"\n        fi\n\n        # server_name e locations esperadas\n        dominios_cfg=$(grep -hoE 'server_name[[:space:]]+[^;]+' \"$NGINX_SITE\" 2>/dev/null | sed 's/server_name[[:space:]]*//' | tr ' ' '\\n' | sort -u | tr '\\n' ' ')\n        info \"server_name: ${dominios_cfg:-nenhum}\"\n        echo \" $dominios_cfg \" | grep -q \" ${DOMINIO} \" \\\n            && ok \"server_name cont\u00e9m ${DOMINIO}\" \\\n            || aviso \"server_name n\u00e3o cont\u00e9m ${DOMINIO}\"\n\n        grep -qE \"location[[:space:]]+/${API_PREFIX}/\" \"$NGINX_SITE\" \\\n            && ok \"location /${API_PREFIX}/ presente\" \\\n            || falha \"location /${API_PREFIX}/ ausente\"\n\n        grep -qE \"location[[:space:]]+/${LLM_PREFIX}/\" \"$NGINX_SITE\" 2>/dev/null \\\n            && ok \"location /${LLM_PREFIX}/ presente no vhost\" \\\n            || info \"location /${LLM_PREFIX}/ n\u00e3o est\u00e1 no vhost (pode estar em include)\"\n\n        # Include do LLM (arquivo separado)\n        if $SUDO nginx -T 2>/dev/null | grep -q \"llm.d/.*\\.conf\"; then\n            ok \"include /etc/nginx/llm.d/*.conf carregado\"\n        else\n            info \"include de /etc/nginx/llm.d n\u00e3o detectado\"\n        fi\n\n        # Locations duplicadas no mesmo server (causa do outage anterior)\n        dup=$(\n            $SUDO awk '\n                function limpar(s) {\n                    gsub(/^[[:space:]]+/, \"\", s)\n                    gsub(/[[:space:]]+$/, \"\", s)\n                    sub(/[[:space:]]*\\{.*$/, \"\", s)\n                    gsub(/[[:space:]]+/, \" \", s)\n                    return s\n                }\n                {\n                    bruto = $0\n                    sub(/#.*/, \"\", bruto)\n                    abre = gsub(/\\{/, \"{\", bruto)\n                    fecha = gsub(/\\}/, \"}\", bruto)\n                    if (dentro && prof == 1 && bruto ~ /^[[:space:]]*location[[:space:]]/) {\n                        chave = limpar(bruto)\n                        if (chave in visto) {\n                            printf \"server %d: %s (linha %d) repete a linha %d\\n\", srv, chave, FNR, visto[chave]\n                            achou = 1\n                        } else {\n                            visto[chave] = FNR\n                        }\n                    }\n                    if (!dentro) {\n                        if (bruto ~ /^[[:space:]]*server[[:space:]]*\\{/) {\n                            dentro = 1; srv++; prof = abre - fecha; delete visto\n                        }\n                        next\n                    }\n                    prof += abre - fecha\n                    if (prof <= 0) dentro = 0\n                }\n                END { if (!achou) print \"\" }\n            ' \"$NGINX_SITE\" 2>/dev/null\n        )\n        if [ -n \"$dup\" ]; then\n            falha \"location duplicada no mesmo server:\"\n            printf '%s\\n' \"$dup\" | sed 's/^/         /'\n        else\n            ok \"nenhuma location duplicada no mesmo server\"\n        fi\n\n        # Upstreams: extrai proxy_pass e testa connectividade\n        while read -r up; do\n            [ -n \"$up\" ] || continue\n            hostporta=$(printf '%s' \"$up\" | sed -E 's#^https?://##; s#/.*$##')\n            code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 4 \"http://${hostporta}${API_HEALTH}\" 2>/dev/null)\n            case \"$code\" in\n                000|'') aviso \"upstream ${up} sem resposta em ${API_HEALTH}\" ;;\n                *)      ok \"upstream ${up} respondeu ${code} em ${API_HEALTH}\" ;;\n            esac\n        done < <(grep -oE 'proxy_pass[[:space:]]+https?://[^;]+' \"$NGINX_SITE\" 2>/dev/null \\\n            | sed -E 's#proxy_pass[[:space:]]+##' | sort -u)\n\n        # Certificados: exist\u00eancia e validade\n        certs=$(grep -hoE 'ssl_certificate[[:space:]]+[^;]+' \"$NGINX_SITE\" 2>/dev/null | sed -E 's/ssl_certificate[[:space:]]+//' | sort -u)\n        if [ -n \"$certs\" ] && tem_cmd openssl; then\n            while read -r cert; do\n                [ -n \"$cert\" ] || continue\n                if [ -r \"$cert\" ]; then\n                    fim=$(openssl x509 -in \"$cert\" -noout -enddate 2>/dev/null | cut -d= -f2)\n                    if [ -n \"$fim\" ]; then\n                        fim_epoch=$(date -d \"$fim\" +%s 2>/dev/null || echo 0)\n                        agora=$(date +%s)\n                        dias=$(( (fim_epoch - agora) / 86400 ))\n                        if [ \"$dias\" -lt 0 ]; then\n                            falha \"certificado EXPIRADO: $cert ($fim)\"\n                        elif [ \"$dias\" -lt 21 ]; then\n                            aviso \"certificado expira em ${dias} dias: $cert\"\n                        else\n                            ok \"certificado v\u00e1lido por ${dias} dias ($cert)\"\n                        fi\n                    fi\n                else\n                    aviso \"certificado referenciado mas ileg\u00edvel: $cert\"\n                fi\n            done <<< \"$certs\"\n        fi\n    else\n        falha \"vhost n\u00e3o existe: $NGINX_SITE\"\n    fi\n\n    # CORS e preflight pela 443 local\n    if ! tem_cmd curl; then\n        aviso \"curl n\u00e3o instalado \u2014 CORS/preflight n\u00e3o testados\"\n    elif ! porta_aberta 443; then\n        info \"esta m\u00e1quina n\u00e3o escuta 443 \u2014 CORS/preflight locais n\u00e3o se aplicam\"\n    else\n        cors=$(curl -k -s -o /dev/null -D - --max-time 8 \\\n            --resolve \"${DOMINIO}:443:127.0.0.1\" \\\n            -H \"Origin: ${origem}\" \\\n            \"https://${DOMINIO}/${API_PREFIX}${API_HEALTH}\" 2>/dev/null \\\n            | grep -i '^access-control-allow-origin' | tr -d '\\r' | head -1)\n        [ -n \"$cors\" ] && ok \"CORS: ${cors}\" || aviso \"sem header CORS para Origin ${origem}\"\n\n        preflight=$(curl -k -s -o /dev/null -w '%{http_code}' --max-time 8 \\\n            --resolve \"${DOMINIO}:443:127.0.0.1\" -X OPTIONS \\\n            -H \"Origin: ${origem}\" \\\n            -H 'Access-Control-Request-Method: POST' \\\n            -H 'Access-Control-Request-Headers: content-type' \\\n            \"https://${DOMINIO}/${API_PREFIX}/voluntario\" 2>/dev/null)\n        case \"$preflight\" in\n            2*) ok \"preflight OPTIONS -> ${preflight}\" ;;\n            *)  aviso \"preflight OPTIONS -> ${preflight} (esperado 2xx)\" ;;\n        esac\n    fi\n\n    # Logs de erro do nginx\n    for log in /var/log/nginx/error.log; do\n        if [ -r \"$log\" ] && tem_cmd tail; then\n            recentes=$(tail -n 40 \"$log\" 2>/dev/null | grep -iE '\\[(crit|alert|emerg)\\]|duplicate location|no live upstreams' | tail -5)\n            if [ -n \"$recentes\" ]; then\n                aviso \"eventos recentes em ${log}:\"\n                printf '%s\\n' \"$recentes\" | sed 's/^/         /'\n            else\n                ok \"${log}: sem crit/alert/emerg nas \u00faltimas 40 linhas\"\n            fi\n        fi\n    done\nfi\n\n# =============================================================================\n# RESUMO\n# =============================================================================\nsecao \"Resumo\"\nprintf '  %sOK%s: %d   %savisos%s: %d   %sfalhas%s: %d\\n' \\\n    \"$G\" \"$N\" \"$_c_ok\" \"$Y\" \"$N\" \"$_c_warn\" \"$R\" \"$N\" \"$_c_fail\"\n\nif [ \"$_c_fail\" -gt 0 ]; then\n    printf '  %sResultado: FALHAS encontradas \u2014 corrija antes de reiniciar servi\u00e7os.%s\\n' \"$R\" \"$N\"\n    exit 2\nelif [ \"$_c_warn\" -gt 0 ]; then\n    printf '  %sResultado: operacional, com avisos.%s\\n' \"$Y\" \"$N\"\n    exit 1\nelse\n    printf '  %sResultado: tudo certo.%s\\n' \"$G\" \"$N\"\n    exit 0\nfi\n", "oracle.sh": "#!/bin/bash\n# ==============================================================================\n# Gerador de ISO Hibrida (UEFI + MBR) - Oracle Linux 9 (Sistema Basico)\n# Instalacao via kickstart com suporte completo a boot em ambos os modos\n# ==============================================================================\n\nset -e\n\n# --- Cores e Formatacao ---\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nCYAN='\\033[0;36m'\nBOLD='\\033[1m'\nNC='\\033[0m'\n\n# --- Variaveis ---\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nBUILD_ROOT=\"$SCRIPT_DIR/build_hybrid\"\nOUT_DIR=\"$BUILD_ROOT/output_iso\"\nKS_FILE=\"$BUILD_ROOT/ks_minimal.cfg\"\nGRUB_DIR=\"$BUILD_ROOT/grub_files\"\nLOG_FILE=\"$BUILD_ROOT/build.log\"\nISO_NAME=\"OL9-Minimal-Hybrid.iso\"\n\nTOTAL_STEPS=8\nCURRENT_STEP=0\nSTEP_START=0\nERRORS=0\nWARNINGS=0\n\n# --- Funcoes de Log ---\ntimestamp() { date '+%H:%M:%S'; }\n\nelapsed() {\n    local s=$1\n    printf '%02dm%02ds' $((s/60)) $((s%60))\n}\n\nlog_header() {\n    echo \"\"\n    echo -e \"${BLUE}\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501${NC}\"\n    echo -e \"${BOLD}${CYAN}  [$1/$TOTAL_STEPS] $2${NC}\"\n    echo -e \"${BLUE}\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501${NC}\"\n}\n\nlog_progress() {\n    echo -e \"  ${YELLOW}[status=progress]${NC} $(timestamp) - $1\"\n}\n\nlog_ok() {\n    echo -e \"  ${GREEN}[status=ok]${NC}      $(timestamp) - $1\"\n}\n\nlog_erro() {\n    echo -e \"  ${RED}[status=error]${NC}   $(timestamp) - $1\"\n    ((ERRORS++)) || true\n}\n\nlog_aviso() {\n    echo -e \"  ${YELLOW}[status=warn]${NC}    $(timestamp) - $1\"\n    ((WARNINGS++)) || true\n}\n\nlog_info() {\n    echo -e \"  ${CYAN}[status=info]${NC}    $(timestamp) - $1\"\n}\n\nstep_init() {\n    CURRENT_STEP=$1\n    STEP_START=$(date +%s)\n    log_header \"$1\" \"$2\"\n    log_progress \"Inicio da etapa\"\n}\n\nstep_done() {\n    local end=$(date +%s)\n    local dur=$(( end - STEP_START ))\n    log_ok \"Etapa concluida em $(elapsed $dur)\"\n}\n\nrun_cmd() {\n    local desc=\"$1\"\n    shift\n    log_progress \"Executando: ${desc}\"\n    if \"$@\" >> \"$LOG_FILE\" 2>&1; then\n        log_ok \"${desc} - OK\"\n    else\n        log_erro \"${desc} - FALHOU (verifique $LOG_FILE)\"\n        return 1\n    fi\n}\n\n# --- Limpeza ---\nlimpar_tudo() {\n    echo \"\"\n    log_progress \"Limpando temporarios...\"\n    sync\n    grep \"$BUILD_ROOT\" /proc/mounts 2>/dev/null | cut -d' ' -f2 | xargs -r umount -l 2>/dev/null || true\n    rm -rf \"$BUILD_ROOT/lmc-work-*\" \"/var/tmp/lmc-*\" 2>/dev/null || true\n    log_ok \"Temporarios limpos\"\n}\ntrap limpar_tudo EXIT\n\n# --- Inicio ---\necho -e \"${BOLD}${CYAN}\"\necho \"  \u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\necho \"  \u2551  GERADOR DE ISO HIBRIDA - Oracle Linux 9                \u2551\"\necho \"  \u2551  UEFI + MBR (BIOS) | Kickstart                         \u2551\"\necho \"  \u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\necho -e \"${NC}\"\n\nlog_progress \"Log detalhado: $LOG_FILE\"\nlog_progress \"Data: $(date '+%d/%m/%Y %H:%M:%S')\"\necho \"\"\n\n# --- Verificacoes Iniciais ---\nif [[ $EUID -ne 0 ]]; then\n    log_erro \"Execute como ROOT.\"\n    exit 1\nfi\nlog_ok \"Executando como root\"\n\nFREE_GB=$(df -BG \"$SCRIPT_DIR\" | awk 'NR==2 {print $4}' | sed 's/G//')\nif [ \"$FREE_GB\" -lt 10 ]; then\n    log_erro \"Espaco insuficiente ($FREE_GB GB). Minimo 10GB.\"\n    exit 1\nfi\nlog_ok \"Espaco em disco: ${FREE_GB}GB disponivel (minimo: 10GB)\"\n\nmkdir -p \"$BUILD_ROOT\" \"$GRUB_DIR\" \"$BUILD_ROOT/content/software_rpm\" \"$BUILD_ROOT/content/favoritos\"\nlog_ok \"Diretorios de build criados\"\n\nTOTAL_START=$(date +%s)\n\n# =============================================================================\n# ETAPA 1/8 - Dependencias\n# =============================================================================\nstep_init 1 \"Instalando dependencias\"\n\nlog_progress \"Instalando epel-release...\"\nif dnf install -y epel-release >> \"$LOG_FILE\" 2>&1; then\n    log_ok \"epel-release instalado\"\nelse\n    log_aviso \"epel-release pode ja estar instalado\"\nfi\n\nPACKAGES=\"lorax lorax-lmc-novirt xorriso rsync syslinux grub2-efi-x64 shim-x64 grub2-tools lorax-templates-generic\"\nlog_progress \"Instalando pacotes: $PACKAGES\"\nif dnf install -y $PACKAGES >> \"$LOG_FILE\" 2>&1; then\n    log_ok \"Todas as dependencias instaladas\"\nelse\n    log_erro \"Falha na instalacao de dependencias\"\n    exit 1\nfi\n\nmkdir -p \"$BUILD_ROOT/content/software_rpm\" \\\n         \"$BUILD_ROOT/content/favoritos\" \\\n         \"$OUT_DIR\" \\\n         \"$GRUB_DIR\"\nlog_ok \"Estrutura de diretorios preparada\"\n\nstep_done\n\n# =============================================================================\n# ETAPA 2/8 - Pacotes Locais\n# =============================================================================\nstep_init 2 \"Copiando pacotes locais\"\n\nSOFTWARE_SRC=\"$SCRIPT_DIR/software_rpm\"\nFAVORITOS_SRC=\"$SCRIPT_DIR/favoritos\"\n\nif [ -d \"$SOFTWARE_SRC\" ] && [ -n \"$(ls -A \"$SOFTWARE_SRC\" 2>/dev/null)\" ]; then\n    RPM_COUNT=$(find \"$SOFTWARE_SRC\" -name '*.rpm' 2>/dev/null | wc -l)\n    log_progress \"Encontrados $RPM_COUNT pacotes RPM em $SOFTWARE_SRC\"\n    rsync -av --progress \"$SOFTWARE_SRC/\" \"$BUILD_ROOT/content/software_rpm/\" 2>&1 | while IFS= read -r line; do\n        log_info \"$line\"\n    done\n    log_ok \"$RPM_COUNT pacotes RPM copiados\"\nelse\n    log_aviso \"Nenhum pacote local encontrado em $SOFTWARE_SRC, pulando...\"\nfi\n\nif [ -d \"$FAVORITOS_SRC\" ] && [ -n \"$(ls -A \"$FAVORITOS_SRC\" 2>/dev/null)\" ]; then\n    FAV_COUNT=$(find \"$FAVORITOS_SRC\" -type f 2>/dev/null | wc -l)\n    log_progress \"Encontrados $FAV_COUNT favoritos\"\n    rsync -av --progress \"$FAVORITOS_SRC/\" \"$BUILD_ROOT/content/favoritos/\" 2>&1 | while IFS= read -r line; do\n        log_info \"$line\"\n    done\n    log_ok \"$FAV_COUNT favoritos copiados\"\nelse\n    log_aviso \"Nenhum favorito encontrado, pulando...\"\nfi\n\nstep_done\n\n# =============================================================================\n# ETAPA 3/8 - Kickstart\n# =============================================================================\nstep_init 3 \"Gerando Kickstart\"\n\nlog_progress \"Criando .buildstamp para anaconda...\"\nmkdir -p /etc/anaconda\ncat <<'BSTAMP' > /etc/anaconda/.buildstamp\n[Anaconda]\nBuildstamp = oracle-linux-9-build\nProduct = OracleLinux\nVariant =\nTimestamp = 0\nBSTAMP\nlog_ok \".buildstamp criado em /etc/anaconda/.buildstamp\"\n\nlog_progress \"Gerando arquivo de kickstart: $KS_FILE\"\ncat <<'EOFKS' > \"$KS_FILE\"\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\n# Disco - apaga tudo e particiona automaticamente\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\n# Bootloader - suporte UEFI e MBR\nbootloader --location=mbr --driveorder=sda\n\n# Repositorios oficiais Oracle Linux 9\nurl --url=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/ --noverifyssl\nrepo --name=\"AppStream\" --baseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/x86_64/ --noverifyssl\n\n# Rede\nnetwork --bootproto=dhcp --activate\n\n# Senha root (altere apos instalacao)\nuser --name=oracle --password=oracle --plaintext\n\n# Senha root\nrootpw --lock\n\n# Servicos basicos\nservices --enabled=\"chronyd,sshd\"\n\nreboot\n\n%packages\n@core\n@base\n@hardware-support\n@xfce\n@base-x\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\nchromium\nbluetooth\nbluez\nbluez-tools\nNetworkManager-wifi\nwireless-tools\nwpa_supplicant\niwl*firmware\niw\nrfkill\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\n\n# Configurar hostname\nhostnamectl set-name oracle-minimal\n\n# Habilitar servicos\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\n\n# Criar usuario oracle\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\n# Montar midia para injetar arquivos extras\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    # Instalar RPMs locais se existirem\n    if [ -d /mnt/media/software_rpm ] && ls /mnt/media/software_rpm/*.rpm >/dev/null 2>&1; then\n        dnf install -y /mnt/media/software_rpm/*.rpm || true\n    fi\n\n    # Copiar favoritos\n    if [ -d /mnt/media/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/favoritos/ /etc/skel/favoritos/\n    fi\n\n    # Checksums\n    if [ -f /mnt/media/checksums.txt ]; then\n        cd /mnt/media && sha256sum -c checksums.txt || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\necho \"Instalacao concluida com sucesso!\" > /root/INSTALL_OK\n%end\nEOFKS\n\nKS_LINES=$(wc -l < \"$KS_FILE\")\nlog_ok \"Kickstart gerado: $KS_FILE ($KS_LINES linhas)\"\nlog_info \"  - Idioma: pt_BR.UTF-8\"\nlog_info \"  - Timezone: America/Sao_Paulo\"\nlog_info \"  - Repos: OracleLinux OL9 baseos + AppStream\"\nlog_info \"  - Desktop: XFCE\"\nlog_info \"  - Usuario: oracle\"\n\nstep_done\n\n# =============================================================================\n# ETAPA 4/8 - GRUB UEFI\n# =============================================================================\nstep_init 4 \"Configurando GRUB para UEFI\"\n\nlog_progress \"Criando diretorio GRUB: $GRUB_DIR\"\nmkdir -p \"$GRUB_DIR\"\n\nlog_progress \"Gerando grub.cfg...\"\ncat <<'EOFGRUB' > \"$GRUB_DIR/grub.cfg\"\nset default=0\nset timeout=5\nset menu_color_normal=cyan/blue\nset menu_color_highlight=white/blue\n\nmenuentry \"Oracle Linux 9 - Instalar\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_MIN_HYB quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 - Instalar (Texto)\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_MIN_HYB text quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 - Modo Resgate\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_MIN_HYB rescue quiet\n    initrdefi /images/pxeboot/initrd.img\n}\n\nmenuentry \"Oracle Linux 9 - Testar midia e instalar\" {\n    linuxefi /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL9_MIN_HYB rd.live.check quiet\n    initrdefi /images/pxeboot/initrd.img\n}\nEOFGRUB\n\nlog_ok \"grub.cfg gerado com 4 entradas de menu\"\nlog_info \"  - Instalar (GUI)\"\nlog_info \"  - Instalar (Texto)\"\nlog_info \"  - Modo Resgate\"\nlog_info \"  - Testar midia e instalar\"\n\nstep_done\n\n# =============================================================================\n# ETAPA 5/8 - Build ISO\n# =============================================================================\nstep_init 5 \"Build da ISO com livemedia-creator\"\n\nlog_progress \"Removendo diretorio de saida (livemedia-creator exige que nao exista)...\"\nrm -rf \"$OUT_DIR\"\nlog_ok \"Diretorio de saida removido\"\n\nlog_progress \"Iniciando livemedia-creator (pode demorar varios minutos)...\"\nlog_info \"  KS: $KS_FILE\"\nlog_info \"  Projeto: OracleLinux\"\nlog_info \"  Release: 9\"\nlog_info \"  ISO: $ISO_NAME\"\nlog_info \"  Label: OL9_MIN_HYB\"\n\nlivemedia-creator \\\n    --make-iso \\\n    --ks=\"$KS_FILE\" \\\n    --no-virt \\\n    --resultdir=\"$OUT_DIR\" \\\n    --project=\"OracleLinux\" \\\n    --releasever=9 \\\n    --iso-name=\"$ISO_NAME\" \\\n    --fs-label=\"OL9_MIN_HYB\" \\\n    --anaconda-arg=--product=OracleLinux \\\n    --anaconda-arg=--variant= \\\n    2>&1 | tee -a \"$LOG_FILE\"\n\nlog_progress \"Buscando ISO gerada...\"\nISO_PATH=$(find \"$OUT_DIR\" -name \"$ISO_NAME\" -type f 2>/dev/null | head -1)\nif [ -z \"$ISO_PATH\" ]; then\n    ISO_PATH=$(find \"$OUT_DIR\" -name \"*.iso\" -type f 2>/dev/null | head -1)\nfi\n\nif [ -z \"$ISO_PATH\" ]; then\n    log_erro \"Nenhum ISO gerado. Verifique $LOG_FILE\"\n    exit 1\nfi\n\nISO_SIZE_RAW=$(stat -c%s \"$ISO_PATH\" 2>/dev/null || echo 0)\nISO_SIZE_HUMAN=$(ls -lh \"$ISO_PATH\" | awk '{print $5}')\nlog_ok \"ISO gerada: $ISO_PATH ($ISO_SIZE_HUMAN)\"\n\nstep_done\n\n# =============================================================================\n# ETAPA 6/8 - GRUB UEFI na ISO\n# =============================================================================\nstep_init 6 \"Injetando GRUB UEFI na ISO\"\n\nif [ -d \"$GRUB_DIR\" ]; then\n    XORRISO_OPTS=\"-boot_info -patch_joliet -r-rock -append_partition 2 0xef $GRUB_DIR/efi.img -e /isolinux/boot.cat\"\n    log_progress \"Opcoes xorriso configuradas para UEFI\"\n    log_info \"  - EFI partition: $GRUB_DIR/efi.img\"\n    log_info \"  - Boot catalog: /isolinux/boot.cat\"\n    log_ok \"Configuracao UEFI preparada\"\nelse\n    log_aviso \"Diretorio GRUB nao encontrado, pulando injecao UEFI\"\nfi\n\nstep_done\n\n# =============================================================================\n# ETAPA 7/8 - isohybrid\n# =============================================================================\nstep_init 7 \"Aplicando isohybrid (MBR + UEFI)\"\n\nTEMP_ISO=\"$OUT_DIR/${ISO_NAME%.iso}-tmp.iso\"\nlog_progress \"Criando backup temporario da ISO...\"\ncp \"$ISO_PATH\" \"$TEMP_ISO\"\nlog_ok \"Backup: $TEMP_ISO\"\n\nlog_progress \"Tentando isohybrid --uefi...\"\nif isohybrid --uefi \"$ISO_PATH\" 2>>\"$LOG_FILE\"; then\n    log_ok \"isohybrid --uefi aplicado com sucesso\"\nelse\n    log_aviso \"isohybrid --uefi falhou, tentando fallback com xorriso...\"\n    xorriso -as dd -indev \"$TEMP_ISO\" \\\n            -outdev \"$ISO_PATH\" \\\n            --interval:partition_interval:efi_path:$GRUB_DIR/efi.img 2>>\"$LOG_FILE\" || true\n    log_ok \"Fallback xorriso aplicado\"\nfi\n\nlog_progress \"Removendo backup temporario...\"\nrm -f \"$TEMP_ISO\" 2>/dev/null || true\nlog_ok \"Temporario removido\"\n\nstep_done\n\n# =============================================================================\n# ETAPA 8/8 - Arquivos Extras\n# =============================================================================\nstep_init 8 \"Injetando arquivos extras na ISO\"\n\ncd \"$BUILD_ROOT/content\"\nif [ -n \"$(ls -A . 2>/dev/null)\" ]; then\n    EXTRA_FILES=$(find . -type f 2>/dev/null | wc -l)\n    log_progress \"Encontrados $EXTRA_FILES arquivos extras para injetar\"\n\n    log_progress \"Extraindo ISO para montagem...\"\n    mkdir -p \"$BUILD_ROOT/iso_mount\"\n    xorriso -osirrox on -indev \"$ISO_PATH\" -extract / \"$BUILD_ROOT/iso_mount\" 2>>\"$LOG_FILE\" || true\n    log_ok \"ISO extraida para $BUILD_ROOT/iso_mount\"\n\n    if [ -d \"$BUILD_ROOT/iso_mount\" ]; then\n        log_progress \"Copiando arquivos extras para ISO montada...\"\n        rsync -av \"$BUILD_ROOT/content/\" \"$BUILD_ROOT/iso_mount/\" 2>&1 | while IFS= read -r line; do\n            log_info \"$line\"\n        done\n        log_ok \"Arquivos extras copiados\"\n\n        log_progress \"Regenerando ISO com xorriso (mantendo boot)...\"\n        cd \"$BUILD_ROOT/iso_mount\"\n        xorriso -as mkisofs \\\n            -r -V \"OL9_MIN_HYB\" \\\n            -o \"$ISO_PATH\" \\\n            -b isolinux/isolinux.bin \\\n            -c isolinux/boot.cat \\\n            -no-emul-boot \\\n            -boot-load-size 4 \\\n            -boot-info-table \\\n            -eltorito-alt-boot \\\n            -e images/efiboot.img \\\n            -no-emul-boot \\\n            -isohybrid-gpt-basdat \\\n            . 2>>\"$LOG_FILE\" || true\n        log_ok \"ISO regenerada com arquivos extras\"\n    fi\nelse\n    log_aviso \"Nenhum arquivo extra encontrado, pulando...\"\nfi\n\n# --- Checksum ---\nlog_progress \"Gerando checksum SHA256...\"\ncd \"$OUT_DIR\"\nsha256sum \"$ISO_NAME\" > hash_iso.txt\nHASH=$(awk '{print $1}' hash_iso.txt)\nlog_ok \"Checksum gerado: ${HASH:0:16}...\"\n\n# --- Resumo Final ---\nTOTAL_END=$(date +%s)\nTOTAL_DUR=$(( TOTAL_END - TOTAL_START ))\n\nISO_SIZE=$(ls -lh \"$ISO_PATH\" | awk '{print $5}')\n\necho \"\"\necho -e \"${GREEN}\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557${NC}\"\necho -e \"${GREEN}\u2551            ISO HIBRIDA GERADA COM SUCESSO!                 \u2551${NC}\"\necho -e \"${GREEN}\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d${NC}\"\necho \"\"\necho -e \"  ${BOLD}Arquivo:${NC}    $ISO_PATH\"\necho -e \"  ${BOLD}Tamanho:${NC}    $ISO_SIZE\"\necho -e \"  ${BOLD}Boot:${NC}       UEFI + MBR (BIOS)\"\necho -e \"  ${BOLD}Checksum:${NC}   $OUT_DIR/hash_iso.txt\"\necho -e \"  ${BOLD}SHA256:${NC}     ${HASH:0:32}...\"\necho -e \"  ${BOLD}Tempo:${NC}      $(elapsed $TOTAL_DUR)\"\necho -e \"  ${BOLD}Log:${NC}        $LOG_FILE\"\necho \"\"\n\nif [ \"$ERRORS\" -gt 0 ]; then\n    echo -e \"  ${RED}Erros: $ERRORS${NC}\"\nfi\nif [ \"$WARNINGS\" -gt 0 ]; then\n    echo -e \"  ${YELLOW}Avisos: $WARNINGS${NC}\"\nfi\necho \"\"\n", "rebuild_ol9_xfce_offline.sh": "#!/bin/bash\n#============================================================\n# Script: rebuild_ol9_xfce_offline.sh\n# Objetivo: Reconstruir a ISO OL9-Offline-Completa.iso com\n#           instala\u00e7\u00e3o 100% offline do XFCE4\n#\n# Pr\u00e9-requisitos: dnf, sudo, createrepo_c, xorriso\n# Uso: sudo bash rebuild_ol9_xfce_offline.sh\n#============================================================\nset -euo pipefail\n\n# ============================================================\n# CONFIGURA\u00c7\u00c3O\n# ============================================================\nISO_ORIGEM=\"/home/wander/ISO/OL9-Offline-Completa.iso\"\nISO_DESTINO=\"/home/wander/ISO/OL9-XFCE-Offline-Completa.iso\"\nMOUNT_POINT=\"/tmp/iso_mount\"\nWORK_DIR=\"/tmp/iso_build\"\nINSTALLROOT=\"${WORK_DIR}/installroot\"\nPKGDIR=\"${WORK_DIR}/Packages\"\nVOLUME_ID=\"OL9_OFFLINE_XFCE\"\n\nGREEN='\\033[0;32m'\nRED='\\033[0;31m'\nYELLOW='\\033[1;33m'\nCYAN='\\033[0;36m'\nNC='\\033[0m'\n\nlog()   { echo -e \"${CYAN}[$(date +%H:%M:%S)]${NC} $1\"; }\nok()    { echo -e \"${GREEN}[$(date +%H:%M:%S)] OK:${NC} $1\"; }\nwarn()  { echo -e \"${YELLOW}[$(date +%H:%M:%S)] WARN:${NC} $1\"; }\nerr()   { echo -e \"${RED}[$(date +%H:%M:%S)] ERRO:${NC} $1\"; }\nfatal() { err \"$1\"; exit 1; }\n\n# ============================================================\n# VERIFICA\u00c7\u00d5ES INICIAIS\n# ============================================================\n[[ $EUID -ne 0 ]] && fatal \"Execute como root: sudo bash $0\"\n[[ ! -f \"$ISO_ORIGEM\" ]] && fatal \"ISO original n\u00e3o encontrada: $ISO_ORIGEM\"\n\nfor cmd in dnf createrepo_c xorriso; do\n    command -v \"$cmd\" &>/dev/null || fatal \"Depend\u00eancia '$cmd' n\u00e3o encontrada. Instale com: dnf install $cmd\"\ndone\n\nlog \"=========================================\"\nlog \"  REBUILD OL9 XFCE OFFLINE\"\nlog \"=========================================\"\nlog \"ISO origem:    $ISO_ORIGEM\"\nlog \"ISO destino:   $ISO_DESTINO\"\nlog \"Volume ID:     $VOLUME_ID\"\nlog \"\"\n\n# ============================================================\n# ETAPA 1: Limpeza e prepara\u00e7\u00e3o\n# ============================================================\nlog \"ETAPA 1/7: Limpeza e prepara\u00e7\u00e3o do ambiente...\"\n\n# Mata processos dnf anteriores\npkill -9 -f \"dnf.*installroot\" 2>/dev/null || true\nsleep 1\n\n# Desmonta ISO anterior se montada\numount \"$MOUNT_POINT\" 2>/dev/null || true\n\n# Limpa diret\u00f3rios de trabalho\nrm -rf \"$WORK_DIR\"\nrm -rf \"$MOUNT_POINT\"\nmkdir -p \"$MOUNT_POINT\" \"$WORK_DIR\" \"$PKGDIR\"\n\nok \"Ambiente preparado\"\n\n# ============================================================\n# ETAPA 2: Montar ISO original\n# ============================================================\nlog \"ETAPA 2/7: Montando ISO original...\"\nmount -o loop \"$ISO_ORIGEM\" \"$MOUNT_POINT\"\nok \"ISO montada em $MOUNT_POINT\"\n\n# ============================================================\n# ETAPA 3: Copiar estrutura base da ISO\n# ============================================================\nlog \"ETAPA 3/7: Copiando estrutura base da ISO...\"\n\n# Copia tudo exceto Packages/ antigo\nfor item in \"$MOUNT_POINT\"/*; do\n    basename=$(basename \"$item\")\n    if [[ \"$basename\" == \"Packages\" ]]; then\n        continue\n    fi\n    cp -a \"$item\" \"$WORK_DIR/\"\ndone\n\n# Mant\u00e9m a estrutura\nmkdir -p \"$WORK_DIR/Packages\"\nok \"Estrutura base copiada\"\n\n# ============================================================\n# ETAPA 4: Baixar pacotes para instala\u00e7\u00e3o offline completa\n# ============================================================\nlog \"ETAPA 4/7: Baixando pacotes via dnf (resolve depend\u00eancias)... [status=progress]\"\nlog \"  Isso pode demorar 10-30 minutos dependendo da conex\u00e3o... [status=progress]\"\n\n# Cria installroot limpo\nrm -rf \"$INSTALLROOT\"\nmkdir -p \"$INSTALLROOT\"\n\ndnf --releasever=9 \\\n    --installroot=\"$INSTALLROOT\" \\\n    --setopt=keepcache=True \\\n    --setopt=install_weak_deps=False \\\n    -y install \\\n    @core @base @base-x @hardware-support \\\n    xfce4-session xfce4-panel xfwm4 xfdesktop thunar thunar-volman \\\n    xfce4-terminal xfce4-settings xfce4-power-manager xfce4-notifyd \\\n    xfce4-screenshooter xfce4-taskmanager xfce4-whiskermenu-plugin \\\n    xfce4-appfinder xfconf garcon mousepad parole ristretto \\\n    gdm \\\n    kernel-core grub2-efi-x64 grub2-pc shim-x64 syslinux dracut-live \\\n    bluez bluez-obexd NetworkManager-wifi \\\n    wpa_supplicant iw rfkill rsync chrony openssh-server bash-completion \\\n    vim-minimal nano wget curl net-tools iproute NetworkManager chromium \\\n    alsa-utils pipewire pipewire-pulseaudio \\\n    make gcc rpm-build tar gzip python3 htop lm_sensors \\\n    --exclude='kernel-uek*' \\\n    --exclude='dnf-plugin-spacewalk' \\\n    --exclude='rhn-client-tools' \\\n    --exclude='rhn-setup' \\\n    --exclude='rhnlib' \\\n    --exclude='rhnsd' 2>&1 | while IFS= read -r line; do\n        [ -z \"$line\" ] && continue\n        log \"  $line [status=progress]\"\n    done\n\nok \"Pacotes baixados pelo dnf [status=completed]\"\n\n# Copia RPMs do cache para Packages/\nlog \"  Copiando RPMs do cache para Packages/...\"\nfind \"$INSTALLROOT/var/cache/dnf\" -name \"*.rpm\" -exec cp -u {} \"$PKGDIR/\" \\;\n\nTOTAL=$(ls \"$PKGDIR\"/*.rpm 2>/dev/null | wc -l)\nSIZE=$(du -sh \"$PKGDIR\" | cut -f1)\n\nif [[ \"$TOTAL\" -lt 100 ]]; then\n    fatal \"Poucos pacotes baixados ($TOTAL). Verifique a conex\u00e3o ou erros do dnf.\"\nfi\n\nok \"Pacotes: $TOTAL arquivos, tamanho $SIZE\"\n\n# ============================================================\n# ETAPA 5: Gerar repodata\n# ============================================================\nlog \"ETAPA 5/7: Gerando repodata para o repo local...\"\n\ncreaterepo_c --database \"$PKGDIR\"\nok \"Repodata criada em $PKGDIR/repodata/\"\n\n# ============================================================\n# ETAPA 6: Atualizar ks.cfg para 100% offline\n# ============================================================\nlog \"ETAPA 6/7: Atualizando ks.cfg para instala\u00e7\u00e3o 100% offline...\"\n\ncat > \"$WORK_DIR/ks.cfg\" << 'KSEOF'\nkeyboard br-abnt2\nlang pt_BR.UTF-8\ntimezone America/Sao_Paulo --utc\n\nzerombr\nclearpart --all --initlabel\nautopart --type=plain\n\nbootloader --location=mbr --driveorder=sda\n\nrepo --name=\"Packages\" --baseurl=file:///run/install/repo/Packages --noverifyssl\n\nnetwork --bootproto=dhcp --activate\n\nuser --name=oracle --password=oracle --plaintext\nrootpw --lock\n\nservices --enabled=\"chronyd,sshd,bluetooth,NetworkManager\"\n\nreboot\n\n%packages\n@core\n@base\n@base-x\n@hardware-support\n\n# --- XFCE4 Desktop (ambiente completo) ---\nxfce4-session\nxfce4-panel\nxfce4-settings\nxfce4-appfinder\nxfce4-power-manager\nxfce4-notifyd\nxfce4-screenshooter\nxfce4-taskmanager\nxfce4-whiskermenu-plugin\nxfwm4\nxfdesktop\nxfconf\ngarcon\nthunar\nthunar-volman\nmousepad\nparole\nristretto\n\n# --- Display Manager ---\ngdm\n\n# --- Kernel e Boot ---\nkernel-core\ngrub2-efi-x64\ngrub2-pc\nshim-x64\nsyslinux\ndracut-live\n\n# --- Bluetooth ---\nbluez\nbluez-obexd\n\n# --- Rede e Wireless ---\nNetworkManager-wifi\nwpa_supplicant\niw\nrfkill\n\n# --- Sistema e Utilit\u00e1rios ---\nrsync\nchrony\nopenssh-server\nbash-completion\nvim-minimal\nnano\nwget\ncurl\nnet-tools\niproute\nNetworkManager\n\n# --- \u00c1udio ---\nalsa-utils\npipewire\npipewire-pulseaudio\n\n# --- Desenvolvimento ---\nmake\ngcc\nrpm-build\ntar\ngzip\npython3\n\n# --- Monitoramento ---\nhtop\nlm_sensors\n\n# --- Navegador ---\nchromium\n\n# --- Excluir pacotes indesejados ---\n-dnf-plugin-spacewalk\n-rhn-client-tools\n-rhn-setup\n-rhnlib\n-rhnsd\n%end\n\n%post --log=/root/post-install.log\n#!/bin/bash\nset -x\n\nhostnamectl set-name oracle-offline\n\nsystemctl enable sshd\nsystemctl enable chronyd\nsystemctl enable bluetooth\nsystemctl enable NetworkManager\nsystemctl enable gdm\n\nuseradd -m -s /bin/bash -G wheel oracle 2>/dev/null || true\necho \"oracle:oracle\" | chpasswd 2>/dev/null || true\n\nmkdir -p /mnt/media\nfor dev in /dev/cdrom /dev/sr0 /dev/sr1; do\n    if mount \"\\$dev\" /mnt/media 2>/dev/null; then\n        break\n    fi\ndone\n\nif mountpoint -q /mnt/media; then\n    for SCRIPT in update-appimages.sh create_rpm.sh fix-repos-ol9.sh; do\n        if [ -f \"/mnt/media/content/\\$SCRIPT\" ]; then\n            rsync -a \"/mnt/media/content/\\$SCRIPT\" /usr/local/bin/\n            chmod +x \"/usr/local/bin/\\$SCRIPT\"\n        fi\n    done\n\n    for DIR in system_scripts vm_scripts bluetooth; do\n        if [ -d \"/mnt/media/content/\\$DIR\" ]; then\n            rsync -av \"/mnt/media/content/\\$DIR/\" \"/opt/\\$DIR/\"\n            chmod -R +x \"/opt/\\$DIR/\" 2>/dev/null || true\n        fi\n    done\n\n    if [ -d /mnt/media/Packages ]; then\n        mkdir -p /opt/local_repo\n        rsync -a /mnt/media/Packages/ /opt/local_repo/\n        if [ -d /mnt/media/Packages/repodata ]; then\n            rsync -a /mnt/media/Packages/repodata/ /opt/local_repo/repodata/\n        fi\n        cat > /etc/yum.repos.d/ol9-local-offline.repo << 'REPOEOF'\n[ol9_local_offline]\nname=Oracle Linux 9 Local Offline\nbaseurl=file:///opt/local_repo/\nenabled=1\ngpgcheck=0\nREPOEOF\n    fi\n\n    if [ -d /mnt/media/content/favoritos ]; then\n        mkdir -p /etc/skel/favoritos\n        rsync -av /mnt/media/content/favoritos/ /etc/skel/favoritos/\n        mkdir -p /home/oracle/favoritos\n        rsync -av /mnt/media/content/favoritos/ /home/oracle/favoritos/\n        chown -R oracle:oracle /home/oracle/favoritos 2>/dev/null || true\n    fi\n\n    if [ -f /mnt/media/content/checksums.txt ]; then\n        cd /mnt/media/content && sha256sum -c checksums.txt 2>/dev/null || echo \"AVISO: Checksum inconsistente\"\n    fi\n\n    umount /mnt/media 2>/dev/null || true\nfi\n\ncat > /etc/NetworkManager/conf.d/wifi-powersave.conf << 'NMEOF'\n[connection]\nwifi.powersave = 2\nNMEOF\n\nln -sf /opt/system_scripts/ol9-full-setup.sh /usr/local/bin/ol9-setup 2>/dev/null || true\nln -sf /opt/system_scripts/otimizar-xfce.sh /usr/local/bin/otimizar-xfce 2>/dev/null || true\n\necho \"Instalacao offline XFCE concluida: $(date)\" > /root/INSTALL_OK\n%end\nKSEOF\n\nok \"ks.cfg atualizado (100% offline, XFCE4 como padr\u00e3o)\"\n\n# ============================================================\n# ETAPA 7: Gerar nova ISO\n# ============================================================\nlog \"ETAPA 7/7: Gerando nova ISO com xorriso...\"\n\nISO_SIZE=$(du -sb \"$WORK_DIR\" | cut -f1)\nISO_SIZE_GB=$(echo \"scale=2; $ISO_SIZE / 1073741824\" | bc)\nlog \"  Tamanho da ISO estimado: ${ISO_SIZE_GB}GB\"\n\nxorriso -as mkisofs \\\n    -iso-level 3 \\\n    -full-iso9660-filenames \\\n    -volid \"$VOLUME_ID\" \\\n    -output \"$ISO_DESTINO\" \\\n    -eltorito-boot isolinux/isolinux.bin \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        --eltorito-catalog isolinux/boot.cat \\\n    -eltorito-alt-boot \\\n        -e images/efiboot.img \\\n        -no-emul-boot \\\n        -isohybrid-gpt-basdat \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    \"$WORK_DIR\"\n\nok \"ISO gerada: $ISO_DESTINO\"\n\n# ============================================================\n# LIMPEZA E RELAT\u00d3RIO FINAL\n# ============================================================\numount \"$MOUNT_POINT\" 2>/dev/null || true\n\nFINAL_SIZE=$(du -h \"$ISO_DESTINO\" | cut -f1)\nFINAL_RPMS=$(ls \"$PKGDIR\"/*.rpm 2>/dev/null | wc -l)\n\necho \"\"\nlog \"=========================================\"\nlog \"  CONSTRU\u00c7\u00c3O CONCLU\u00cdDA\"\nlog \"=========================================\"\nlog \"ISO destino:  $ISO_DESTINO\"\nlog \"Tamanho:      $FINAL_SIZE\"\nlog \"Pacotes:      $FINAL_RPMS RPMs\"\nlog \"Volume ID:    $VOLUME_ID\"\nlog \"\"\nlog \"Modos de boot dispon\u00edveis:\"\nlog \"  BIOS:  Instalar / Kickstart auto (XFCE)\"\nlog \"  UEFI:  Instalar / Kickstart auto (XFCE)\"\nlog \"\"\nlog \"Kickstart (auto): selecionar 'Instalar com Kickstart' no menu\"\nlog \"  - Instala XFCE4 como ambiente padr\u00e3o\"\nlog \"  - 100% offline (sem depend\u00eancia de internet)\"\nlog \"  - Usu\u00e1rio: oracle/oracle\"\nlog \"=========================================\"\n", "remove_old_kernels.sh": "#!/bin/bash\n#\n# remove_old_kernels.sh\n# Safely remove old kernels on Oracle Linux 9.x, keeping only the newest N\n# versions (default: 2). The running kernel is always protected.\n# Also handles kernel-uek packages alongside regular kernel packages.\n# Integrates with crash/travamento audit settings.\n#\n# Usage: see --help\n\nset -euo pipefail\n\nKEEP=2\nDRY_RUN=0\nSET_LIMIT=0\nCLEAN=0\nINCLUDE_UKE=0   # 1=also consider kernel-uek, 0=only regular kernel (default)\nLIST_ONLY=0     # 1=only list, don't propose removal\n\nlog()  { printf '%s\\n' \"$*\"; }\nwarn() { printf 'WARNING: %s\\n' \"$*\" >&2; }\ndie()  { printf 'ERROR: %s\\n' \"$*\" >&2; exit 1; }\n\nusage() {\n    cat <<'EOF'\nUsage: remove_old_kernels.sh [options]\n\n  -k, --keep N           How many total kernels to keep (default: 2)\n  -n, --dry-run          Only show what would be removed, change nothing\n  -c, --set-limit        Also set installonly_limit=N in /etc/dnf/dnf.conf\n  -u, --include-uek      Also include kernel-uek packages in the count\n  -U, --exclude-uek      Only consider regular kernel packages (default)\n      --clean             Run 'dnf clean all' after a successful removal\n      --list-only         List kernels without proposing removal\n  -h, --help              Show this help\n\nThe newest N kernels are kept across both regular and UEK kernels (if\nincluded). The running kernel is always protected \u2014 if it is not among the\nnewest N, the oldest of those N is dropped instead so the system stays\nbootable.  Old kernels are a common cause of boot issues and\ntravamentos; removing them frees disk space and reduces maintenance overhead.\nEOF\n}\n\n# ---------------------------------------------------------------------------\n# Parse arguments\n# ---------------------------------------------------------------------------\nwhile (( $# )); do\n    case \"$1\" in\n        -k|--keep)           KEEP=\"${2:?--keep requires a number}\"; shift 2 ;;\n        -k=*|--keep=*)       KEEP=\"${1#*=}\"; shift ;;\n        -n|--dry-run)        DRY_RUN=1; shift ;;\n        -c|--set-limit)      SET_LIMIT=1; shift ;;\n        -u|--include-uek)    INCLUDE_UKE=1; shift ;;\n        -U|--exclude-uek)    INCLUDE_UKE=0; shift ;;\n        --clean)             CLEAN=1; shift ;;\n        --list-only)         LIST_ONLY=1; shift ;;\n        -h|--help)           usage; exit 0 ;;\n        *)                   usage >&2; die \"unknown option: $1\" ;;\n    esac\ndone\n\n[[ \"$KEEP\" =~ ^[1-9][0-9]*$ ]] || die \"--keep must be a positive integer (got '$KEEP')\"\n\n# ---------------------------------------------------------------------------\n# Determine which kernel packages to query\n# ---------------------------------------------------------------------------\nif (( INCLUDE_UKE )); then\n    PKG_BASES=(kernel kernel-uek)\nelse\n    PKG_BASES=(kernel)\nfi\n\n# ---------------------------------------------------------------------------\n# Gather installed kernel versions from rpm\n# Stores:  installed[0..n-1] = \"VERSION-RELEASE.ARCH\" sorted newest last\n# ---------------------------------------------------------------------------\nrunning=\"$(uname -r)\"\n\nread_versions() {  # $1 = package name pattern (e.g. \"kernel\" or \"kernel-uek\")\n    # Only output versions if package is installed; rpm -q returns non-zero if not found\n    if rpm -q \"$1\" >/dev/null 2>&1; then\n        rpm -q \"$1\" --qf '%{VERSION}-%{RELEASE}.%{ARCH}\\n' | sort -Vu\n    fi\n}\n\n# Collect versions from all requested package bases\nmapfile -t installed < <(for pb in \"${PKG_BASES[@]}\"; do\n    read_versions \"$pb\"\ndone | sort -Vu)\n\n(( ${#installed[@]} )) || die \"no installed kernel packages found\"\n\n# Helper: check if a version string matches the running kernel\nis_running() { [[ \"$1\" == \"$running\" ]]; }\n\nlog \"=== Current running kernel: $running ===\"\nlog \"Installed kernels (${#installed[@]}):\"\nprintf '  %s\\n' \"${installed[@]}\"\nlog\n\nn=${#installed[@]}\nif (( n <= KEEP )); then\n    log \"Only $n kernel(s) installed and keep=$KEEP -> nothing to do.\"\n    exit 0\nfi\n\n# ---------------------------------------------------------------------------\n# Decide which versions to keep: the newest KEEP, forcing the running kernel in\n# ---------------------------------------------------------------------------\ndeclare -A keep=()\n# Initially mark the newest KEEP versions from the sorted list\nfor (( i = n - KEEP; i < n; i++ )); do\n    keep[\"${installed[i]}\"]=1\ndone\n\n# If the running kernel is not already among the kept versions, replace the\n# oldest of the kept ones with the running kernel so the system stays bootable.\nif ! [[ -v keep[\"$running\"] ]]; then\n    running_installed=0\n    for v in \"${installed[@]}\"; do\n        is_running \"$v\" && running_installed=1\n    done\n    if (( running_installed )); then\n        oldest_kept=\"${installed[n-KEEP]}\"\n        unset \"keep[$oldest_kept]\"\n        keep[\"$running\"]=1\n        warn \"running kernel $running is not among the newest $KEEP;\"\n        warn \"keeping it instead of $oldest_kept so the system stays bootable.\"\n    else\n        warn \"running kernel $running is not an installed kernel package; it will not be touched.\"\n    fi\nfi\n\n# ---------------------------------------------------------------------------\n# Versions to remove = installed - kept\n# ---------------------------------------------------------------------------\nremove_versions=()\nfor v in \"${installed[@]}\"; do\n    [[ -v keep[\"$v\"] ]] || remove_versions+=(\"$v\")\ndone\n\nif (( ${#remove_versions[@]} == 0 )); then\n    log \"Nothing to remove.\"\n    exit 0\nfi\n\n# ---------------------------------------------------------------------------\n# Build the full package name list for the versions to remove\n# ---------------------------------------------------------------------------\nmapfile -t all_pkgs < <(rpm -qa --qf '%{NAME}-%{VERSION}-%{RELEASE}.%{ARCH}\\n')\n\nspecs=()\nfor v in \"${remove_versions[@]}\"; do\n    for p in \"${all_pkgs[@]}\"; do\n        # Match: package name starts with kernel- or kernel, and version-release.arch matches\n        if [[ \"$p\" == kernel* || \"$p\" == kernel-uek* ]]; then\n            if [[ \"$p\" == kernel-uek-* ]]; then\n                pkg_version=\"${p#kernel-uek-}\"\n            else\n                pkg_version=\"${p#kernel-}\"\n            fi\n            if [[ \"$pkg_version\" == \"$v\" ]]; then\n                specs+=(\"$p\")\n            fi\n        fi\n    done\ndone\n\n(( ${#specs[@]} )) || die \"no packages matched the old versions (unexpected)\"\n\n# ---------------------------------------------------------------------------\n# Summary / Propose removal\n# ---------------------------------------------------------------------------\nlog \"Keeping:\"\nfor v in \"${installed[@]}\"; do\n    [[ -v keep[\"$v\"] ]] && log \"  $v\"\ndone\nlog \"Removing:\"\nprintf '  %s\\n' \"${remove_versions[@]}\"\nlog\n\nif (( DRY_RUN )); then\n    log \"Dry run: nothing was removed.\"\n    exit 0\nfi\n\nif (( LIST_ONLY )); then\n    log \"List-only mode: no packages will be removed.\"\n    exit 0\nfi\n\n(( EUID == 0 )) || command -v sudo >/dev/null || die \"need root or sudo to remove packages\"\n\n# ---------------------------------------------------------------------------\n# Remove\n# ---------------------------------------------------------------------------\nlog \"Removing packages:\"\nsudo dnf remove -y \"${specs[@]}\"\n\n# ---------------------------------------------------------------------------\n# Optional: make dnf keep only $KEEP kernels automatically from now on\n# ---------------------------------------------------------------------------\nif (( SET_LIMIT )); then\n    set_dnf_opt() {  # $1 = option, $2 = value\n        if grep -qE \"^[[:space:]]*$1=\" /etc/dnf/dnf.conf 2>/dev/null; then\n            sudo sed -i -E \"s/^([[:space:]]*$1=).*/\\1$2/\" /etc/dnf/dnf.conf\n        else\n            grep -q '^\\[main\\]' /etc/dnf/dnf.conf 2>/dev/null || printf '\\n[main]\\n' | sudo tee -a /etc/dnf/dnf.conf >/dev/null\n            printf '%s=%s\\n' \"$1\" \"$2\" | sudo tee -a /etc/dnf/dnf.conf >/dev/null\n        fi\n    }\n    set_dnf_opt installonly_limit \"$KEEP\"\n    set_dnf_opt protect_running_kernel true\n    log \"dnf.conf updated: installonly_limit=$KEEP, protect_running_kernel=true\"\nfi\n\nif (( CLEAN )); then\n    log\n    log \"Cleaning cached packages...\"\n    sudo dnf clean all\nfi\n\n# ---------------------------------------------------------------------------\n# Summary\n# ---------------------------------------------------------------------------\nmapfile -t remaining < <(for pb in \"${PKG_BASES[@]}\"; do\n    read_versions \"$pb\"\ndone | sort -Vu)\nlog\nlog \"Done! Kernels now installed (${#remaining[@]}):\"\nprintf '  %s\\n' \"${remaining[@]}\"\n\nif (( ${#remaining[@]} > KEEP )); then\n    warn \"more than $KEEP kernels still installed - check the output above\"\nfi\n\n# ---------------------------------------------------------------------------\n# Post-removal: check for crashkernel/travamento related settings\n# ---------------------------------------------------------------------------\nif (( DRY_RUN == 0 && CLEAN == 0 )); then\n    say()  { printf '\\n\\033[1;36m== %s\\033[0m\\n' \"$*\"; }\n    ok()   { printf '   \\033[1;32mOK\\033[0m  %s\\n' \"$*\"; }\n    warn() { printf '   \\033[1;33mAVISO\\033[0m  %s\\n' \"$*\" >&2; }\n\n    say \"Checking crashkernel/kdump configuration...\"\n    if grep -q 'crashkernel=' /proc/cmdline; then\n        if systemctl is-active --quiet kdump 2>/dev/null; then\n            ok \"kdump is active - crashkernel will be preserved for crash recovery\"\n        else\n            warn \"crashkernel is in cmdline but kdump is NOT active\"\n            warn \"Consider removing crashkernel parameter if kdump is not used\"\n            warn \"  This can free ~448 MiB RAM (current: $(tr ' ' '\\n' < /proc/cmdline | grep '^crashkernel=' | head -1))\"\n        fi\n    else\n        ok \"no crashkernel parameter in kernel cmdline\"\n    fi\n\n    say \"Checking installonly_limit...\"\n    current_limit=\"$(grep -oP '^installonly_limit=\\K[0-9]+' /etc/dnf/dnf.conf 2>/dev/null || echo 'not set')\"\n    if [[ \"$current_limit\" != \"$KEEP\" ]]; then\n        log \"installonly_limit is currently: $current_limit (recommended: $KEEP)\"\n        log \"Run: sudo remove_old_kernels.sh --set-limit --keep $KEEP\"\n    else\n        ok \"installonly_limit=$KEEP is correctly set\"\n    fi\nfi", "setup-performance.sh": "#!/usr/bin/env bash\n# =============================================================================\n# setup-performance.sh\n# -----------------------------------------------------------------------------\n# Reproduz as alteracoes de memoria/desempenho/boot aplicadas no Oracle Linux 9.8\n# (UEK 6.12). IDEMPOTENTE: pode rodar varias vezes sem efeito colateral.\n#\n# Uso:\n#   sudo ./setup-performance.sh\n#\n# Etapas aplicadas:\n#   1) /etc/sysctl.d/99-performance.conf      vm.swappiness=15 e vm.vfs_cache_pressure=50\n#   2) /etc/systemd/system/zram-swap.service  swap zram (SEM \"Before=swap.target\",\n#                                             que causava ciclo de ordenacao no systemd)\n#   3) kdump desabilitado + crashkernel removido (libera ~448 MiB no reboot)\n#   4) sysstat instalado e com coleta ativa   (historico sar/rpm de desempenho)\n#   5) NetworkManager wifi.powersave=2        (power-save do Wi-Fi desligado)\n#   6) Video Intel i915                       remove \"rhgb\" (mantem \"quiet\") e aplica\n#                                             i915.enable_psr=0 i915.enable_fbc=0\n#   7) GRUB timeout                           GRUB_TIMEOUT=1 / TIMEOUT_STYLE=menu\n#   8) Console serial ttyS0                   menu do GRUB + console=ttyS0 no kernel\n#                                             + getty de login (DO_SERIAL=no p/ pular)\n#   9) NVRAM EFI                              remove entradas mortas (rEFInd/rede/\n#                                             genericas) e deixa Oracle Linux + fallback\n#  10) backlight intel_backlight              regra udev + valor salvo (painel aceso)\n#  11) journald persistente (opcional)        logs sobrevivem a reboot  PERSIST_JOURNALD=yes\n#  12) fsck                                   checagem no proximo boot (DO_FSCK=auto|yes|no)\n#  13) kernels antigos                        remove versoes antigas mantendo KEEP_KERNELS\n#                                             por flavor (DO_KERNELS=yes|no)\n# =============================================================================\n#\n# Variaveis de ambiente (yes/no) para PULAR etapas:\n#   DO_VIDEO=no            pula a etapa 6\n#   DO_GRUB_TIMEOUT=no     pula a etapa 7\n#   DO_SERIAL=no           pula a etapa 8 (console serial)\n#   DO_EFI=no              pula a etapa 9\n#   DO_BACKLIGHT=no        pula a etapa 10\n#   PERSIST_JOURNALD=yes   ativa a etapa 11 (padrao: no)\n#   DO_FSCK=yes|auto|no    etapa 12 (padrao: auto = so agenda se algum fs estiver sujo)\n#   DO_KERNELS=no          pula a etapa 13 (limpeza de kernels antigos)\n#   KEEP_KERNELS=2         quantos kernels manter por flavor (minimo 2, padrao: 2)\n#   INSTALL_SYSSTAT=no     pula a instalacao do sysstat\n#   ZRAM_SIZE=2G           tamanho do zram (padrao: 1G)\n#   SERIAL_PORT=ttyS0      porta serial da etapa 8 (padrao: ttyS0)\n#   SERIAL_SPEED=115200    velocidade da serial da etapa 8 (padrao: 115200)\n#\n# Exemplo:\n#   sudo DO_EFI=no ./setup-performance.sh\n# =============================================================================\nset -euo pipefail\n\n# ---- pre-requisitos ---------------------------------------------------------\nif [ \"$(id -u)\" -ne 0 ]; then\n  echo \"ERRO: execute com sudo:  sudo $0\" >&2\n  exit 1\nfi\n\n# ---- opcoes ----------------------------------------------------------------\nZRAM_SIZE=\"${ZRAM_SIZE:-1G}\"\nDO_VIDEO=\"${DO_VIDEO:-yes}\"\nDO_GRUB_TIMEOUT=\"${DO_GRUB_TIMEOUT:-yes}\"\nDO_SERIAL=\"${DO_SERIAL:-yes}\"\nSERIAL_PORT=\"${SERIAL_PORT:-ttyS0}\"\nSERIAL_SPEED=\"${SERIAL_SPEED:-115200}\"\nDO_EFI=\"${DO_EFI:-yes}\"\nDO_BACKLIGHT=\"${DO_BACKLIGHT:-yes}\"\nDO_FSCK=\"${DO_FSCK:-auto}\"\nDO_KERNELS=\"${DO_KERNELS:-yes}\"\nKEEP_KERNELS=\"${KEEP_KERNELS:-2}\"\nPERSIST_JOURNALD=\"${PERSIST_JOURNALD:-no}\"\nINSTALL_SYSSTAT=\"${INSTALL_SYSSTAT:-yes}\"\n\nSYSCTL_FILE=/etc/sysctl.d/99-performance.conf\nZRAM_UNIT=/etc/systemd/system/zram-swap.service\nSYSSTAT_CFG=/etc/sysconfig/sysstat\nGRUB_FILE=/etc/default/grub\nKCMD=/etc/kernel/cmdline\nTS=\"$(date '+%Y-%m-%d %H:%M:%S')\"\necho \">>> setup-performance.sh iniciado em $TS (zram=${ZRAM_SIZE})\"\n\n# helper: aplica uma lista de args numa linha GRUB_CMDLINE_LINUX=\"...\"\ngrub_cmdline_set() {\n  # uso: grub_cmdline_set \"remover=rhgb|quiet\" \"adicionar=i915.foo=1\"\n  local cur new tok want remove_list add_list\n  # NAO removemos \"quiet\" (decisao do usuario): apenas \"rhgb\" e removido.\n  remove_list=\"rhgb\"\n  add_list=\"i915.enable_psr=0 i915.enable_fbc=0\"\n  cur=\"$(sed -n 's/^GRUB_CMDLINE_LINUX=\"\\(.*\\)\"/\\1/p' \"$GRUB_FILE\" 2>/dev/null || true)\"\n  new=\"\"\n  for tok in $cur; do\n    case \" $remove_list \" in *\" $tok \"*) continue ;; esac\n    new=\"${new:+$new }$tok\"\n  done\n  for want in $add_list; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  sed -i \"s|^GRUB_CMDLINE_LINUX=.*|GRUB_CMDLINE_LINUX=\\\"$new\\\"|\" \"$GRUB_FILE\"\n}\n\n# helper: adiciona tokens (idempotente) em GRUB_CMDLINE_LINUX, preservando o resto\ngrub_cmdline_add() {\n  local cur new want\n  cur=\"$(sed -n 's/^GRUB_CMDLINE_LINUX=\"\\(.*\\)\"/\\1/p' \"$GRUB_FILE\" 2>/dev/null || true)\"\n  new=\"$cur\"\n  for want in \"$@\"; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  sed -i \"s|^GRUB_CMDLINE_LINUX=.*|GRUB_CMDLINE_LINUX=\\\"$new\\\"|\" \"$GRUB_FILE\"\n}\n\n# helper: adiciona tokens (idempotente) em /etc/kernel/cmdline (kernels futuros)\nkcmdline_add() {\n  local f=\"$KCMD\" cur new want\n  [ -f \"$f\" ] || return 0\n  cur=\"$(tr '\\n' ' ' < \"$f\")\"\n  new=\"$cur\"\n  for want in \"$@\"; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  printf '%s\\n' \"$(printf '%s' \"$new\" | sed -E 's/[[:space:]]+/ /g; s/^ //; s/ $//')\" > \"$f\"\n}\n\n# helper: garante dono root, permissao 0644 e contexto SELinux correto do arquivo\nfixfile() {\n  local f=\"$1\"\n  [ -e \"$f\" ] || return 0\n  chown root:root \"$f\" 2>/dev/null || true\n  chmod 0644 \"$f\" 2>/dev/null || true\n  if command -v restorecon >/dev/null 2>&1; then\n    restorecon -F \"$f\" >/dev/null 2>&1 || true\n  fi\n}\n\n# =============================================================================\n# 1) sysctl de memoria ---------------------------------------------------------\n# =============================================================================\necho\necho \"== [1/13] sysctl -> $SYSCTL_FILE\"\ncat > \"$SYSCTL_FILE\" <<'EOF'\n# Tuning de mem\u00f3ria (setup-performance.sh)\n# swappiness < 30  -> menos uso de swap; mant\u00e9m p\u00e1ginas an\u00f4nimas na RAM\n# vfs_cache_pressure < 100 -> mant\u00e9m mais page cache de inodes/dentries\nvm.swappiness=15\nvm.vfs_cache_pressure=50\nEOF\nfixfile \"$SYSCTL_FILE\"\nsysctl --system >/dev/null 2>&1 || true\necho \"   ativo: vm.swappiness=$(sysctl -n vm.swappiness) | vm.vfs_cache_pressure=$(sysctl -n vm.vfs_cache_pressure)\"\n\n# =============================================================================\n# 2) zram swap (corrigido: sem Before=swap.target -> evita ciclo de ordenacao) -\n# =============================================================================\necho\necho \"== [2/13] zram-swap -> $ZRAM_UNIT (${ZRAM_SIZE}, prioridade 200)\"\ncat > \"$ZRAM_UNIT\" <<EOF\n[Unit]\nDescription=ZRAM swap (${ZRAM_SIZE}, prioridade 200)\nAfter=local-fs.target\nDocumentation=man:zramctl(8)\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStartPre=-/sbin/modprobe zram\nExecStartPre=-/bin/sh -c 'if [ -e /sys/block/zram0 ] && [ \"\\$(cat /sys/block/zram0/disksize 2>/dev/null || echo 0)\" != \"0\" ]; then /sbin/modprobe -r zram&&/sbin/modprobe zram; fi'\nExecStartPre=/bin/sh -c 'echo ${ZRAM_SIZE} > /sys/block/zram0/disksize'\nExecStart=/sbin/mkswap /dev/zram0\nExecStart=/sbin/swapon -p 200 /dev/zram0\nExecStop=/sbin/swapoff /dev/zram0\nExecStopPost=-/sbin/modprobe -r zram\n\n[Install]\nWantedBy=multi-user.target\nEOF\nfixfile \"$ZRAM_UNIT\"\nsystemctl daemon-reload\nsystemctl enable zram-swap.service >/dev/null 2>&1 || true\nsystemctl restart zram-swap.service\necho \"   estado: $(systemctl is-active zram-swap.service)\"\necho \"   swap ativo:\"\nswapon --show | sed 's/^/      /'\n\n# =============================================================================\n# 3) kdump desabilitado + crashkernel removido (libera RAM no proximo boot) ----\n# =============================================================================\necho\necho \"== [3/13] kdump / crashkernel\"\nif systemctl is-enabled kdump 2>/dev/null | grep -q enabled; then\n  systemctl disable --now kdump || true\n  echo \"   kdump desabilitado (reserva crashkernel s\u00f3 libera ~448 MiB ap\u00f3s REBOOT)\"\nelse\n  echo \"   kdump j\u00e1 desabilitado\"\nfi\n\n[ -f \"$GRUB_FILE\" ] && cp -a \"$GRUB_FILE\" \"${GRUB_FILE}.bak.$(date +%F)\" 2>/dev/null || true\n[ -f \"$KCMD\" ]     && cp -a \"$KCMD\"     \"${KCMD}.bak.$(date +%F)\"     2>/dev/null || true\nsed -ri 's/([[:space:]]|\")crashkernel=[^\"[:space:]]+/\\1/' \"$GRUB_FILE\"\n[ -f \"$KCMD\" ] && sed -ri 's/crashkernel=[^[:space:]]+//' \"$KCMD\" || true\n\nif command -v grubby >/dev/null 2>&1; then\n  grubby --update-kernel=ALL --remove-args=crashkernel 2>&1 | sed 's/^/   grubby: /' || true\nelse\n  command -v grub2-mkconfig >/dev/null 2>&1 && grub2-mkconfig -o /boot/grub2/grub.cfg || true\nfi\necho \"   GRUB_CMDLINE_LINUX: $(grep -o 'GRUB_CMDLINE_LINUX=.*' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\nif grep -qs crashkernel /boot/loader/entries/*.conf 2>/dev/null; then\n  echo \"   AVISO: ainda h\u00e1 crashkernel em /boot/loader/entries \u2014 confira p\u00f3s-reboot\"\nelse\n  echo \"   ok: nenhum entry BLS com crashkernel\"\nfi\n\n# =============================================================================\n# 4) sysstat (historico de desempenho) ----------------------------------------\n# =============================================================================\necho\necho \"== [4/13] sysstat\"\nif [ \"${INSTALL_SYSSTAT}\" = \"yes\" ] && ! rpm -q sysstat >/dev/null 2>&1; then\n  if command -v dnf >/dev/null 2>&1; then\n    dnf -y install sysstat 2>&1 | tail -3\n  else\n    yum -y install sysstat 2>&1 | tail -3\n  fi\nelse\n  echo \"   sysstat j\u00e1 instalado ou pulado\"\nfi\nif [ -f \"$SYSSTAT_CFG\" ]; then\n  sed -i 's/^ENABLED=.*/ENABLED=\"true\"/' \"$SYSSTAT_CFG\" 2>/dev/null || true\n  grep -q '^ENABLED=' \"$SYSSTAT_CFG\" || echo 'ENABLED=\"true\"' >> \"$SYSSTAT_CFG\"\nfi\nsystemctl enable --now sysstat.service       >/dev/null 2>&1 || true\nsystemctl enable --now sysstat-collect.timer 2>/dev/null || true\nsystemctl enable --now sysstat-summary.timer 2>/dev/null || true\necho \"   timers: $(systemctl is-active sysstat-collect.timer 2>/dev/null || true)\"\n\n# =============================================================================\n# 5) Wi-Fi power-save desligado (latencia/rede) -------------------------------\n# =============================================================================\necho\necho \"== [5/13] NetworkManager wifi.powersave=2\"\nNM=/etc/NetworkManager/conf.d/default-wifi-powersave-on.conf\nif [ -d /etc/NetworkManager/conf.d ]; then\n  cat > \"$NM\" <<'EOF'\n[connection]\nwifi.powersave = 2\nEOF\n  fixfile \"$NM\"\n  systemctl reload NetworkManager 2>/dev/null || true\n  echo \"   $NM gravado\"\nelse\n  echo \"   NetworkManager ausente \u2014 etapa ignorada\"\nfi\n\n# =============================================================================\n# 6) Video Intel i915 (remove \"rhgb\"; \"quiet\" e mantido) -----------------------\n# =============================================================================\necho\necho \"== [6/13] video i915 + remover 'rhgb' (mantem 'quiet')\"\nif [ \"${DO_VIDEO}\" = \"yes\" ]; then\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --remove-args=\"rhgb\" 2>&1 | sed 's/^/   grubby: /' || true\n    grubby --update-kernel=ALL --args=\"i915.enable_psr=0 i915.enable_fbc=0\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  grub_cmdline_set\n  echo \"   GRUB_CMDLINE_LINUX: $(grep -o 'GRUB_CMDLINE_LINUX=.*' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   kernel padrao: $(grubby --default-kernel 2>/dev/null || echo n/a)\"\nelse\n  echo \"   pulado (DO_VIDEO=no)\"\nfi\n\n# =============================================================================\n# 7) GRUB timeout curto -------------------------------------------------------\n# =============================================================================\necho\necho \"== [7/13] GRUB timeout=1\"\nif [ \"${DO_GRUB_TIMEOUT}\" = \"yes\" ] && [ -f \"$GRUB_FILE\" ]; then\n  sed -i 's/^GRUB_TIMEOUT=.*/GRUB_TIMEOUT=1/' \"$GRUB_FILE\"\n  if grep -q '^GRUB_TIMEOUT_STYLE=' \"$GRUB_FILE\"; then\n    sed -i 's/^GRUB_TIMEOUT_STYLE=.*/GRUB_TIMEOUT_STYLE=menu/' \"$GRUB_FILE\"\n  else\n    echo 'GRUB_TIMEOUT_STYLE=menu' >> \"$GRUB_FILE\"\n  fi\n  command -v grub2-mkconfig >/dev/null 2>&1 && grub2-mkconfig -o /boot/grub2/grub.cfg >/dev/null 2>&1 || true\n  echo \"   $(grep -E '^GRUB_TIMEOUT(_STYLE)?=' \"$GRUB_FILE\" | tr '\\n' ' ')\"\nelse\n  echo \"   pulado (DO_GRUB_TIMEOUT=no)\"\nfi\n\n# =============================================================================\n# 8) console serial ttyS0 (menu GRUB + kernel console + getty de login) --------\n# =============================================================================\necho\necho \"== [8/13] console serial ${SERIAL_PORT} (${SERIAL_SPEED} 8N1)\"\nif [ \"${DO_SERIAL}\" = \"yes\" ]; then\n  SERIAL_CONSOLE_ARGS=\"console=tty0 console=${SERIAL_PORT},${SERIAL_SPEED}n8\"\n\n  # 8a) saida do menu do GRUB na serial, mantendo o console de video\n  if [ -f \"$GRUB_FILE\" ]; then\n    if grep -q '^GRUB_TERMINAL=' \"$GRUB_FILE\"; then\n      sed -i 's|^GRUB_TERMINAL=.*|GRUB_TERMINAL=\"console serial\"|' \"$GRUB_FILE\"\n    else\n      # GRUB_TERMINAL tem prioridade; comenta GRUB_TERMINAL_OUTPUT p/ evitar conflito\n      sed -i 's|^GRUB_TERMINAL_OUTPUT=.*|# &|' \"$GRUB_FILE\"\n      echo 'GRUB_TERMINAL=\"console serial\"' >> \"$GRUB_FILE\"\n    fi\n    if grep -q '^GRUB_SERIAL_COMMAND=' \"$GRUB_FILE\"; then\n      sed -i \"s|^GRUB_SERIAL_COMMAND=.*|GRUB_SERIAL_COMMAND=\\\"serial --speed=${SERIAL_SPEED} --unit=0 --word=8 --parity=no --stop=1\\\"|\" \"$GRUB_FILE\"\n    else\n      echo \"GRUB_SERIAL_COMMAND=\\\"serial --speed=${SERIAL_SPEED} --unit=0 --word=8 --parity=no --stop=1\\\"\" >> \"$GRUB_FILE\"\n    fi\n  fi\n\n  # 8b) parametros do kernel: BLS (kernel atual) + /etc/kernel/cmdline (futuros)\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --args=\"$SERIAL_CONSOLE_ARGS\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  kcmdline_add $SERIAL_CONSOLE_ARGS\n  grub_cmdline_add $SERIAL_CONSOLE_ARGS\n\n  # 8c) regenera o grub.cfg para aplicar GRUB_TERMINAL/GRUB_SERIAL_COMMAND no menu\n  if command -v grub2-mkconfig >/dev/null 2>&1; then\n    grub2-mkconfig -o /boot/grub2/grub.cfg >/dev/null 2>&1 || true\n  fi\n\n  # 8d) getty de login na serial (login ja disponivel sem reboot)\n  systemctl enable --now \"serial-getty@${SERIAL_PORT}.service\" >/dev/null 2>&1 || true\n\n  echo \"   menu GRUB ..... $(grep -E '^GRUB_TERMINAL=' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   serial cmd .... $(grep -E '^GRUB_SERIAL_COMMAND=' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   kernel console  $(grep -ho 'console=[^ ]*' /boot/loader/entries/*.conf 2>/dev/null | sort -u | tr '\\n' ' ')\"\n  echo \"   getty ......... $(systemctl is-enabled \"serial-getty@${SERIAL_PORT}.service\" 2>/dev/null || echo n/a) / $(systemctl is-active \"serial-getty@${SERIAL_PORT}.service\" 2>/dev/null || echo n/a)\"\n  echo \"   (reboot necessario para o menu e o console do kernel valerem)\"\nelse\n  echo \"   pulado (DO_SERIAL=no)\"\nfi\n\n# =============================================================================\n# 9) NVRAM EFI: remover entradas mortas (rEFInd/rede/genericas) ---------------\n# =============================================================================\necho\necho \"== [9/13] limpeza NVRAM EFI\"\nif [ \"${DO_EFI}\" = \"yes\" ] && command -v efibootmgr >/dev/null 2>&1; then\n  keep=\"$(efibootmgr 2>/dev/null | awk '/^BootCurrent:/{print $2}')\"\n  [ -n \"$keep\" ] || keep=\"$(efibootmgr -v 2>/dev/null | awk '/SHIMX64.EFI/{print $1}' | sed 's/Boot//; s/\\*//' | head -1)\"\n  echo \"   mantendo BootCurrent=$keep\"\n  while read -r num rest; do\n    clean=\"${num#Boot}\"; clean=\"${clean%\\*}\"\n    [ \"$clean\" = \"$keep\" ] && continue\n    case \"$rest\" in\n      *rEFInd*|*\"EFI Shell\"*|*IP4*|*IP6*|*PXE*|*VenHw*)\n        echo \"   removendo $num ($rest)\"\n        efibootmgr -b \"$clean\" -B >/dev/null 2>&1 || true\n        ;;\n    esac\n  done < <(efibootmgr -v 2>/dev/null | grep -E '^Boot[0-9A-Fa-f]{4}')\n\n  order=\"$keep\"\n  for b in $(efibootmgr 2>/dev/null | awk '/^Boot[0-9A-Fa-f]{4}\\*/{print $1}' | sed 's/Boot//; s/\\*//'); do\n    [ \"$b\" = \"$keep\" ] && continue\n    order=\"${order:+$order,}$b\"\n  done\n  [ -n \"$order\" ] && efibootmgr -o \"$order\" >/dev/null 2>&1 || true\n  efibootmgr -t 1 >/dev/null 2>&1 || true\n  echo \"   depois:\"\n  efibootmgr 2>/dev/null | grep -E \"BootCurrent|Timeout|BootOrder|^Boot\" | sed 's/^/      /'\nelse\n  echo \"   pulado (DO_EFI=no ou efibootmgr ausente)\"\nfi\n\n# =============================================================================\n# 10) backlight intel_backlight (painel aceso desde o inicio do boot) ---------\n# =============================================================================\necho\necho \"== [10/13] backlight intel_backlight\"\nBL_DIR=/sys/class/backlight/intel_backlight\nBL_RULE=/etc/udev/rules.d/99-backlight-brightness.rules\nif [ \"${DO_BACKLIGHT}\" = \"yes\" ] && [ -d \"$BL_DIR\" ]; then\n  bl_max=\"$(cat \"$BL_DIR/max_brightness\" 2>/dev/null || echo 0)\"\n  if [ \"${bl_max:-0}\" -gt 0 ] 2>/dev/null; then\n    bl_val=$(( bl_max * 77 / 100 ))\n    cat > \"$BL_RULE\" <<EOF\n# Forca o brilho do painel logo que o dispositivo de backlight aparece (setup-performance.sh).\n# Valor atual: ${bl_val}/${bl_max} (~77%). Ajuste conforme necessario.\nACTION==\"add\", SUBSYSTEM==\"backlight\", KERNEL==\"intel_backlight\", ATTR{brightness}=\"${bl_val}\"\nEOF\n    fixfile \"$BL_RULE\"\n    udevadm control --reload-rules 2>/dev/null || true\n    echo \"$bl_val\" > \"$BL_DIR/brightness\" 2>/dev/null || true\n    /usr/lib/systemd/systemd-backlight save backlight:intel_backlight 2>/dev/null || true\n    echo \"   brilho fixado em ${bl_val}/${bl_max} + $BL_RULE\"\n  else\n    echo \"   max_brightness indisponivel \u2014 etapa ignorada\"\n  fi\nelse\n  echo \"   pulado (DO_BACKLIGHT=no ou interface ausente)\"\nfi\n\n# =============================================================================\n# 11) journald persistente (opcional) -----------------------------------------\n# =============================================================================\necho\necho \"== [11/13] journald\"\nJOURNAL_DIR=/var/log/journal\nif [ \"${PERSIST_JOURNALD}\" = \"yes\" ]; then\n  mkdir -p \"$JOURNAL_DIR\"\n  chown root:systemd-journal \"$JOURNAL_DIR\" 2>/dev/null || true\n  chmod 2755 \"$JOURNAL_DIR\" 2>/dev/null || true\n  command -v restorecon >/dev/null 2>&1 && restorecon -RF \"$JOURNAL_DIR\" >/dev/null 2>&1 || true\n  systemctl restart systemd-journald 2>/dev/null || true\n  echo \"   journald persistente ativado em $JOURNAL_DIR\"\nelse\n  echo \"   pulado (PERSIST_JOURNALD=no) \u2014 logs ficam s\u00f3 em /run (perdem no reboot)\"\nfi\n\n# =============================================================================\n# 12) fsck (auto|yes|no) \u2014 checagem no proximo boot --------------------------\n# =============================================================================\n# DO_FSCK=auto (padrao): s\u00f3 agenda se algum ext4 estiver sujo\n# DO_FSCK=yes           : agenda checagem completa no proximo boot\n# DO_FSCK=no            : n\u00e3o faz nada (s\u00f3 relat\u00f3rio de estado)\necho\necho \"== [12/13] fsck (modo: ${DO_FSCK})\"\nFSCK_DEVS=\"$(lsblk -rno NAME,FSTYPE 2>/dev/null | awk '$2==\"ext4\"{print \"/dev/\"$1}')\"\nneed_fsck=no\nfor dev in $FSCK_DEVS; do\n  st=\"$(dumpe2fs -h \"$dev\" 2>/dev/null | awk '/Filesystem state/{print $NF}' || true)\"\n  echo \"   $dev: ${st:-n/a}\"\n  [ \"${st:-}\" != \"clean\" ] && need_fsck=yes\ndone\nif [ \"${DO_FSCK}\" = \"no\" ]; then\n  echo \"   pulado (DO_FSCK=no)\"\nelif [ \"${DO_FSCK}\" = \"yes\" ] || [ \"$need_fsck\" = \"yes\" ]; then\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --args=\"fsck.mode=force fsck.repair=yes\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  echo \"   AGENDADO: fsck.mode=force fsck.repair=yes no proximo boot.\"\n  echo \"   (pode demorar no HDD; remova depois com:)\" \n  echo \"     sudo grubby --update-kernel=ALL --remove-args=\\\"fsck.mode=force fsck.repair=yes\\\"\"\nelse\n  echo \"   nada a fazer: filesystems limpos (use DO_FSCK=yes para for\u00e7ar)\"\nfi\n\n# =============================================================================\n# 13) kernels antigos: manter KEEP_KERNELS por flavor --------------------------\n# =============================================================================\n# Remove versoes antigas com \"dnf remove --oldinstallonly\", que faz a transacao\n# correta dos pacotes DIVIDIDOS (kernel, kernel-core, kernel-modules,\n# kernel-modules-core) e do equivalente -uek. O kernel EM USO e o kernel PADRAO\n# sao protegidos via --exclude. O dnf exige installonly_limit >= 2 (minimo 2).\necho\necho \"== [13/13] kernels antigos (manter ${KEEP_KERNELS} por flavor)\"\nif [ \"${DO_KERNELS}\" = \"yes\" ]; then\n  # dnf aceita no minimo 2; sanear entrada\n  case \"${KEEP_KERNELS}\" in ''|*[!0-9]*) KEEP_KERNELS=2 ;; esac\n  if [ \"${KEEP_KERNELS}\" -lt 2 ]; then KEEP_KERNELS=2; fi\n\n  # release sem arquitetura (ex.: \"6.12.0-206.104.4.4.el9uek\")\n  running_rel=\"$(uname -r)\"; running_rel=\"${running_rel%.*}\"\n  default_rel=\"\"\n  if command -v grubby >/dev/null 2>&1; then\n    default_rel=\"$(grubby --default-kernel 2>/dev/null | sed 's#.*/vmlinuz-##; s#\\.[^.]*$##')\"\n  fi\n\n  # protege em uso + padrao (glob cobre todos os subpacotes do mesmo flavor)\n  excludes=(--exclude=\"kernel*-${running_rel}*\")\n  if [ -n \"$default_rel\" ] && [ \"$default_rel\" != \"$running_rel\" ]; then\n    excludes+=(--exclude=\"kernel*-${default_rel}*\")\n  fi\n\n  echo \"   em uso ..... $(uname -r)\"\n  [ -n \"$default_rel\" ] && echo \"   padrao ..... ${default_rel}\"\n  echo \"   protegido .. ${excludes[*]}\"\n  echo \"   antes ...... $(rpm -q --qf '%{VERSION}-%{RELEASE} ' kernel kernel-uek 2>/dev/null || echo n/a)\"\n\n  # dry-run antes de agir (locale C -> saida estavel para o parse)\n  plan=\"$(LC_ALL=C dnf --assumeno remove --oldinstallonly \\\n            --setopt=installonly_limit=\"${KEEP_KERNELS}\" \"${excludes[@]}\" 2>&1 || true)\"\n  if printf '%s\\n' \"$plan\" | grep -q 'Nothing to do'; then\n    echo \"   nada a remover (ja dentro do limite de ${KEEP_KERNELS})\"\n  elif printf '%s\\n' \"$plan\" | grep -q '^Removing:'; then\n    printf '%s\\n' \"$plan\" | sed -n '/^Removing:/,/^$/p' | sed 's/^/   /'\n    dnf -y remove --oldinstallonly --setopt=installonly_limit=\"${KEEP_KERNELS}\" \\\n        \"${excludes[@]}\" 2>&1 | sed 's/^/   /' || true\n    echo \"   depois ..... $(rpm -q --qf '%{VERSION}-%{RELEASE} ' kernel kernel-uek 2>/dev/null || echo n/a)\"\n  else\n    echo \"   dry-run inconclusivo; nenhuma alteracao feita.\"\n    printf '%s\\n' \"$plan\" | sed 's/^/      /' | head -n 5\n  fi\nelse\n  echo \"   pulado (DO_KERNELS=no)\"\nfi\n\n# =============================================================================\n# resumo -----------------------------------------------------------------------\n# =============================================================================\necho\necho \"==================================================================\"\necho \" RESUMO (${ZRAM_SIZE}):\"\necho \"   sysctl mem\u00f3ria ....... $(sysctl -n vm.swappiness 2>/dev/null)/15 e $(sysctl -n vm.vfs_cache_pressure 2>/dev/null)/50\"\necho \"   zram ................. $(swapon --show | awk '$1==\"/dev/zram0\"{print $2,$3,$4; f=1} END{if(!f)print \"N\u00c3O ATIVO!\"}')\"\necho \"   kdump ................ $(systemctl is-enabled kdump 2>/dev/null || true)\"\necho \"   sar/sysstat .......... $(command -v sar >/dev/null 2>&1 && echo 'instalado' || echo 'ausente') | coleta: $(systemctl is-active sysstat-collect.timer 2>/dev/null || true)\"\necho \"   video i915 ........... $(grep -o 'i915.enable_psr=0' \"$GRUB_FILE\" >/dev/null 2>&1 && echo 'parametros aplicados' || echo 'n/a')\"\necho \"   GRUB timeout ......... $(grep -oE 'GRUB_TIMEOUT=[0-9]+' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\necho \"   serial console ....... $(systemctl is-enabled \"serial-getty@${SERIAL_PORT}.service\" >/dev/null 2>&1 && echo \"getty@${SERIAL_PORT} ok\" || echo 'n/a') | $(grep -ho \"console=${SERIAL_PORT}[^ ]*\" /boot/loader/entries/*.conf 2>/dev/null | sort -u | tr '\\n' ' ')\"\necho \"   EFI .................. $(efibootmgr 2>/dev/null | awk '/^BootOrder:/{print $2}' || echo n/a)\"\necho \"   backlight ............ $(cat \"$BL_DIR/brightness\" 2>/dev/null || echo n/a)/$(cat \"$BL_DIR/max_brightness\" 2>/dev/null || echo n/a)\"\necho \"   journald ............. $([ -d /var/log/journal ] && echo 'persistente' || echo 'vol\u00e1til (/run)')\"\necho \"   fsck ................. $(grep -qs 'fsck.mode=force' /boot/loader/entries/*.conf 2>/dev/null && echo 'agendado p/ pr\u00f3ximo boot' || echo 'n\u00e3o agendado')\"\necho \"   kernels .............. $(rpm -q --qf '%{VERSION}-%{RELEASE} ' kernel kernel-uek 2>/dev/null | sed 's/ *$//' || echo n/a)\"\necho \"   REBOOT pendente? ..... crashkernel removido do boot ir\u00e1 liberar ~448 MiB de RAM\"\necho \"==================================================================\"\nexit 0\n", "system_scripts/appimage2rpm.sh": "#!/bin/bash\nset -euo pipefail\n\nusage() {\n  cat <<EOF\nUsage: $0 <AppImage> [options]\n\nConvert an AppImage to an RPM package for Oracle Linux / RHEL 9.\n\nOptions:\n  -o <dir>    Output directory for the RPM (default: current dir)\n  -n <name>   Package name (default: derived from AppImage filename)\n  -v <ver>    Package version (default: derived from AppImage filename)\n  -h          Show this help\n\nExample:\n  $0 foo-1.2.3-x86_64.AppImage\nEOF\n  exit 1\n}\n\nOUTDIR=\".\"\nPACKAGE_NAME=\"\"\nPACKAGE_VER=\"\"\n\nwhile getopts \"o:n:v:h\" opt; do\n  case \"$opt\" in\n    o) OUTDIR=\"$OPTARG\" ;;\n    n) PACKAGE_NAME=\"$OPTARG\" ;;\n    v) PACKAGE_VER=\"$OPTARG\" ;;\n    h) usage ;;\n    *) usage ;;\n  esac\ndone\n\nshift $((OPTIND-1))\n[ $# -lt 1 ] && usage\n\nAPPIMAGE=\"$1\"\n[ ! -f \"$APPIMAGE\" ] && echo \"Error: file not found: $APPIMAGE\" && exit 1\n[ ! -x \"$APPIMAGE\" ] && echo \"Error: file not executable: $APPIMAGE\" && exit 1\n\nBASENAME=$(basename \"$APPIMAGE\")\nBASENAME_NOEXT=\"${BASENAME%.AppImage}\"\n\n# Derive name + version from filename if not provided\nif [ -z \"$PACKAGE_NAME\" ] || [ -z \"$PACKAGE_VER\" ]; then\n  IFS='-' read -ra PARTS <<< \"$BASENAME_NOEXT\"\n  if [ ${#PARTS[@]} -ge 3 ]; then\n    CANDIDATE_VER=\"${PARTS[-2]}-${PARTS[-1]}\"\n    CANDIDATE_VER=\"${CANDIDATE_VER#v}\"\n    CANDIDATE_NAME=\"\"\n    for ((i=0; i<${#PARTS[@]}-2; i++)); do\n      [ -n \"$CANDIDATE_NAME\" ] && CANDIDATE_NAME+=\"-\"\n      CANDIDATE_NAME+=\"${PARTS[$i]}\"\n    done\n    if [ -z \"$PACKAGE_NAME\" ]; then PACKAGE_NAME=\"$CANDIDATE_NAME\"; fi\n    if [ -z \"$PACKAGE_VER\" ]; then PACKAGE_VER=\"$CANDIDATE_VER\"; fi\n  else\n    [ -z \"$PACKAGE_NAME\" ] && PACKAGE_NAME=\"$BASENAME_NOEXT\"\n    [ -z \"$PACKAGE_VER\" ] && PACKAGE_VER=\"1.0.0\"\n  fi\nfi\n\n# Sanitize version for RPM (no hyphens)\nPACKAGE_VER=\"${PACKAGE_VER//-/_}\"\n\nWORKDIR=$(mktemp -d)\ntrap \"rm -rf '$WORKDIR'\" EXIT\n\necho \"=== Extracting AppImage ===\"\ncd \"$WORKDIR\"\n\"$APPIMAGE\" --appimage-extract >/dev/null 2>&1\ncd squashfs-root\n\necho \"=== Analyzing structure ===\"\n\nAPPNAME=\"$PACKAGE_NAME\"\nWRAPPER_SCRIPT=\"\"\n\n# Find the main binary / wrapper\nif [ -f \"AppRun\" ]; then\n  WRAPPER_SCRIPT=\"AppRun\"\nelif [ -f \"apprun\" ]; then\n  WRAPPER_SCRIPT=\"apprun\"\nelse\n  WRAPPER_SCRIPT=$(find . -maxdepth 2 -type f -name \"*.sh\" -o -name \"*-wrapper\" -o -name \"wrapper\" | head -1)\n  WRAPPER_SCRIPT=\"${WRAPPER_SCRIPT#./}\"\nfi\n\n[ -z \"$WRAPPER_SCRIPT\" ] && echo \"Error: no AppRun/wrapper found\" && exit 1\n\n# Determine the main binary directory\nBIN_DIR=\"\"\nWRAPPER_DIR=$(dirname \"$WRAPPER_SCRIPT\")\nif [ \"$WRAPPER_DIR\" = \".\" ]; then\n  # Check if usr/bin/ or opt/ has the real binary\n  if [ -d \"opt/$APPNAME\" ]; then\n    BIN_DIR=\"opt/$APPNAME\"\n  elif [ -d \"usr/lib/$APPNAME\" ]; then\n    BIN_DIR=\"usr/lib/$APPNAME\"\n  elif [ -d \"usr/lib64/$APPNAME\" ]; then\n    BIN_DIR=\"usr/lib64/$APPNAME\"\n  else\n    BIN_DIR=\"opt/$APPNAME\"\n  fi\nelse\n  BIN_DIR=\"$WRAPPER_DIR\"\nfi\nBIN_DIR=\"${BIN_DIR#./}\"\n\n# Make sure we're using the subdirectory, not \".\"\nif [ \"$BIN_DIR\" = \".\" ]; then\n  mkdir -p \"opt/$APPNAME\"\n  find . -maxdepth 1 -type f | while read f; do\n    [ \"$(basename \"$f\")\" != \".DirIcon\" ] && mv \"$f\" \"opt/$APPNAME/\"\n  done\n  cp -a usr \"opt/$APPNAME/\" 2>/dev/null || true\n  BIN_DIR=\"opt/$APPNAME\"\nfi\n\necho \"  Binary dir: $BIN_DIR\"\necho \"  Wrapper: $WRAPPER_SCRIPT\"\n\n# Desktop file\nDESKTOP_FILE=$(find . -maxdepth 2 -name \"*.desktop\" | head -1)\n[ -z \"$DESKTOP_FILE\" ] && echo \"Error: no .desktop file found\" && exit 1\nDESKTOP_FILE=\"${DESKTOP_FILE#./}\"\necho \"  Desktop file: $DESKTOP_FILE\"\n\n# Icon\nICON_FILE=\"\"\nfor icon in \"${APPNAME}.png\" \"${APPNAME}.svg\" \"icon.png\" \"icon.svg\"; do\n  [ -f \"$icon\" ] && ICON_FILE=\"$icon\" && break\ndone\n# Try to find it from the desktop file\nif [ -z \"$ICON_FILE\" ]; then\n  ICON_NAME=$(grep -i '^Icon=' \"$DESKTOP_FILE\" | head -1 | cut -d= -f2)\n  [ -n \"$ICON_NAME\" ] && for ext in png svg; do\n    found=$(find . -name \"${ICON_NAME}.${ext}\" -maxdepth 2 | head -1)\n    [ -n \"$found\" ] && ICON_FILE=\"${found#./}\" && break\n  done\nfi\n# Last resort: find any png\n[ -z \"$ICON_FILE\" ] && ICON_FILE=$(find . -maxdepth 2 -name \"*.png\" | head -1)\n[ -z \"$ICON_FILE\" ] && ICON_FILE=$(find usr/share/icons -name \"*.png\" | head -1)\nICON_FILE=\"${ICON_FILE#./}\"\necho \"  Icon: $ICON_FILE\"\n\n# Determine License from desktop file\nLICENSE=$(grep -i '^X-AppImage-License=' \"$DESKTOP_FILE\" 2>/dev/null | cut -d= -f2) || true\n[ -z \"$LICENSE\" ] && LICENSE=\"Proprietary\"\n\n# Determine Summary from desktop file\nSUMMARY=$(grep -i '^Comment=' \"$DESKTOP_FILE\" 2>/dev/null | head -1 | cut -d= -f2) || true\n[ -z \"$SUMMARY\" ] && SUMMARY=\"$APPNAME\"\nSUMMARY=\"${SUMMARY:0:80}\"\n\n# Determine URL\nURL=$(grep -i '^URL=' \"$DESKTOP_FILE\" 2>/dev/null | head -1 | cut -d= -f2) || true\n[ -z \"$URL\" ] && URL=\"https://$APPNAME.org\"\n\n# Check for Libraries\nHAS_LIBS=\"false\"\nif ls \"$BIN_DIR\"/*.so* >/dev/null 2>&1; then\n  HAS_LIBS=\"true\"\nfi\n\n# Check for locales\nHAS_LOCALES=\"false\"\n[ -d \"$BIN_DIR/locales\" ] && HAS_LOCALES=\"true\"\n\n# Detect wrapper name for the symlink\nWRAPPER_IN_BIN=$(basename \"$WRAPPER_SCRIPT\")\n# But what's the actual executable inside BIN_DIR?\nLAUNCHER_IN_BIN=$(find \"$BIN_DIR\" -maxdepth 1 -type f -executable ! -name \"*.so*\" ! -name \"*.pak\" ! -name \"*.dat\" ! -name \"*.json\" | head -1)\nLAUNCHER_NAME=$(basename \"$LAUNCHER_IN_BIN\" 2>/dev/null || echo \"$APPNAME\")\n\n# Do we need to fix the desktop Exec line?\nDESKTOP_EXEC=$(grep '^Exec=' \"$DESKTOP_FILE\" 2>/dev/null | head -1 | cut -d= -f2 | cut -d' ' -f1)\nDESKTOP_EXEC=$(basename \"$DESKTOP_EXEC\" 2>/dev/null || echo \"$WRAPPER_IN_BIN\")\n\n# Post-install ldconfig needed only if there are .so files\nPOST_LDCONFIG=\"\"\n[ \"$HAS_LIBS\" = \"true\" ] && POST_LDCONFIG='/sbin/ldconfig 2>/dev/null || :'\n\necho\necho \"=== Creating spec file ===\"\n\nSPECFILE=\"$WORKDIR/$APPNAME.spec\"\nmkdir -p \"$HOME/rpmbuild/SPECS\" \"$HOME/rpmbuild/SOURCES\"\n\ncat > \"$SPECFILE\" << SPECEOF\n%define app_prefix /opt/${APPNAME}\n%define debug_package %{nil}\n\nName:           ${APPNAME}\nVersion:        ${PACKAGE_VER}\nRelease:        1%{?dist}\nSummary:        ${SUMMARY}\n\nLicense:        ${LICENSE}\nURL:            ${URL}\nSource0:        ${APPNAME}-${PACKAGE_VER}.tar.gz\n\nBuildArch:      x86_64\nBuildRequires:  desktop-file-utils\n\nRequires:       fontconfig, freetype, glib2\nRequires:       libX11, libXcomposite, libXcursor, libXdamage\nRequires:       libXext, libXfixes, libXi, libXrandr\nRequires:       libXrender, libXtst, libXScrnSaver\nRequires:       libdrm, libxcb, nss, nspr\nRequires:       alsa-lib, cups-libs\nRequires:       atk, at-spi2-atk, at-spi2-core\nRequires:       pango, cairo, gtk3, gdk-pixbuf2\nRequires:       libgbm, libxkbcommon, mesa-libEGL\nRequires:       bzip2-libs, systemd-libs\n\n%description\n${SUMMARY}\n\n%prep\n%setup -q\n\n%build\n\n%install\nrm -rf %{buildroot}\n\ninstall -d %{buildroot}%{app_prefix}\ncp -a ${BIN_DIR}/* %{buildroot}%{app_prefix}/\n\ninstall -d %{buildroot}%{_datadir}/applications\ndesktop-file-install --dir=%{buildroot}%{_datadir}/applications \\\n  --set-key=Exec --set-value=\"%{app_prefix}/${LAUNCHER_NAME} %%U\" \\\n  --set-key=Icon --set-value=${APPNAME} \\\n  ${DESKTOP_FILE}\n\ninstall -d %{buildroot}%{_bindir}\nln -sf %{app_prefix}/${LAUNCHER_NAME} %{buildroot}%{_bindir}/${APPNAME}\n\ninstall -d %{buildroot}%{_datadir}/icons/hicolor\n\nif [ -f \"${ICON_FILE}\" ]; then\n  for size in 16 22 24 32 48 64 128 256; do\n    sizedir=%{buildroot}%{_datadir}/icons/hicolor/\\${size}x\\${size}/apps\n    install -d \"\\$sizedir\"\n    install -m644 ${ICON_FILE} \"\\$sizedir/${APPNAME}.png\"\n  done\n  install -d %{buildroot}%{_datadir}/icons/hicolor/scalable/apps\n  install -m644 ${ICON_FILE} %{buildroot}%{_datadir}/icons/hicolor/scalable/apps/${APPNAME}.png\nfi\n\n%files\n%defattr(-,root,root,-)\n%{app_prefix}/\n%{_bindir}/${APPNAME}\n%{_datadir}/applications/${APPNAME}.desktop\n%{_datadir}/icons/hicolor/*/apps/${APPNAME}.png\n\n%post\n${POST_LDCONFIG}\ngtk-update-icon-cache %{_datadir}/icons/hicolor 2>/dev/null || :\n\n%postun\n${POST_LDCONFIG}\ngtk-update-icon-cache %{_datadir}/icons/hicolor 2>/dev/null || :\n\n%changelog\n* $(date \"+%a %b %d %Y\") - ${APPNAME} ${PACKAGE_VER}-1\n- Initial RPM build from AppImage\nSPECEOF\n\necho \"=== Creating source tarball ===\"\n\ncd \"$WORKDIR\"\n# Remove the squashfs-root symlink\nrm -f squashfs-root/.DirIcon 2>/dev/null || true\nmv squashfs-root \"${APPNAME}-${PACKAGE_VER}\"\ntar czf \"$HOME/rpmbuild/SOURCES/${APPNAME}-${PACKAGE_VER}.tar.gz\" \"${APPNAME}-${PACKAGE_VER}\"\n\necho \"=== Building RPM ===\"\ncp \"$SPECFILE\" \"$HOME/rpmbuild/SPECS/\"\nrpmbuild -bb \"$HOME/rpmbuild/SPECS/${APPNAME}.spec\"\n\necho\necho \"=== Done ===\"\nRPMFILE=\"$HOME/rpmbuild/RPMS/x86_64/${APPNAME}-${PACKAGE_VER}-1.el9.x86_64.rpm\"\nif [ -f \"$RPMFILE\" ]; then\n  mkdir -p \"$OUTDIR\"\n  cp \"$RPMFILE\" \"$OUTDIR/\"\n  echo \"RPM created: $OUTDIR/$(basename $RPMFILE)\"\n  ls -lh \"$OUTDIR/$(basename $RPMFILE)\"\nelse\n  echo \"RPM build failed.\"\n  exit 1\nfi\n\necho\necho \"Install with: sudo dnf install $OUTDIR/$(basename $RPMFILE)\"\n", "system_scripts/atualizar.sh": "#!/bin/bash\n\n# Script de atualiza\u00e7\u00e3o do reposit\u00f3rio Amor Animal Mar\u00edlia\n\necho \"--- Iniciando processo de atualiza\u00e7\u00e3o da VM ---\"\n\n# 1. Solicitar confirma\u00e7\u00e3o do usu\u00e1rio\nread -p \"Deseja realmente remover a pasta atual e clonar o reposit\u00f3rio novamente>\n\nif [[ \"$confirmacao\" == \"s\" || \"$confirmacao\" == \"S\" ]]; then\n    \n    # 2. Removendo a pasta antiga\n    echo \"Removendo pasta antiga: amoranimalmarilia...\"\n    sudo rm -Rv amoranimalmarilia\n    \n    # 3. Clonando o reposit\u00f3rio atualizado\n    echo \"Clonando a vers\u00e3o mais recente do GitHub...\"\n    git clone https://github.com/wrhbra2013/amoranimalmarilia.git\n    \n    echo \"--- Processo conclu\u00eddo com sucesso! ---\"\nelse\n    echo \"Opera\u00e7\u00e3o cancelada pelo usu\u00e1rio.\"\nfi\n\n", "system_scripts/auto_fix_powerprofiles_selinux.sh": " #!/bin/bash\n# auto_fix_powerprofiles_selinux.sh\n# Corrige contexto e instala m\u00f3dulo SELinux para power-profiles-daemon\n\nMODULE_NAME=\"my-powerprofiles\"\nAVC_FILE=\"/tmp/${MODULE_NAME}.avc\"\n\necho \"[*] Verificando contexto SELinux de /var/lib/sss/mc...\"\nls -Zd /var/lib/sss/mc\n\necho \"[*] Restaurando contexto padr\u00e3o...\"\nrestorecon -Rv /var/lib/sss/mc\n\necho \"[*] Checando por AVC denials relacionados ao power-profiles-daemon...\"\nausearch -c 'power-profiles-' --raw > \"$AVC_FILE\"\n\nif [ -s \"$AVC_FILE\" ]; then\n    echo \"[*] Removendo m\u00f3dulo antigo (se existir)...\"\n    semodule -r \"$MODULE_NAME\" 2>/dev/null\n\n    echo \"[*] Gerando novo m\u00f3dulo SELinux...\"\n    audit2allow -M \"$MODULE_NAME\" < \"$AVC_FILE\"\n\n    echo \"[*] Instalando m\u00f3dulo com prioridade 400...\"\n    semodule -X 400 -i \"${MODULE_NAME}.pp\"\n\n    echo \"[+] M\u00f3dulo $MODULE_NAME instalado com sucesso.\"\nelse\n    echo \"[!] Nenhum AVC denial encontrado para power-profiles-daemon. Nada a corrigir.\"\nfi\n\n", "system_scripts/build_backup.sh": " #!/bin/bash\n\n# ==============================================================================\n# CONFIGURA\u00c7\u00d5ES GERAIS\n# ==============================================================================\nDATA=$(date +%F)\nISO_BASE=\"OracleLinux-R9-U4-x86_64-dvd.iso\" # <<< ARQUIVO ISO BASE DO ORACLE LINUX 9\nISO_NAME=\"ol9-custom-install-${DATA}.iso\"\nWORKDIR=\"/tmp/custom-iso\"\nROOTFS=\"$WORKDIR/rootfs\" # RootFS para o ambiente Live CD\nRPM_EXTRA=\"./software_rpm\"\nFAVORITOS=\"./favoritos\"\nKICKSTART_FILE=\"kickstart.cfg\"\n\nMNT_BASE=\"$WORKDIR/mnt_base\"\nKERNEL_FILE=\"vmlinuz\"\nINITRD_FILE=\"initrd.img\"\n\n# REPOSIT\u00d3RIOS OFICIAIS (Oracle Linux 9)\nREPO_BASE=\"https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/\"\nREPO_APPSTREAM=\"https://yum.oracle.com/repo/OracleLinux/OL9/appstream/latest/x86_64/\"\nREPO_EPEL=\"https://dl.fedoraproject.org/pub/epel/9/Everything/x86_64/\"\nREPO_RPMFUSION_FREE=\"https://download1.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm\"\nRPMFUSION_RELEASE_PKG=\"$WORKDIR/rpmfusion-release-pkg.rpm\"\n\n# ==============================================================================\n# \ud83e\uddf9 LIMPEZA E DEPEND\u00caNCIAS\n# ==============================================================================\necho \"\ud83e\uddf9 Limpando e preparando diret\u00f3rios...\"\nrm -f ol9-custom-install-*.iso\nrm -rf \"$WORKDIR\"\nmkdir -p \"$ROOTFS\" \"$MNT_BASE\" \"$WORKDIR/LiveOS\" \"$WORKDIR/rpms-extra\"\n\necho \"\ud83d\udce6 Instalando depend\u00eancias essenciais...\"\nsudo dnf install -y rsync xorriso squashfs-tools syslinux isomd5sum pykickstart createrepo_c wget curl dnf-utils\n\nif [ ! -f \"$ISO_BASE\" ]; then\n    echo \"\u274c Erro: O arquivo ISO base ($ISO_BASE) n\u00e3o foi encontrado.\"\n    exit 1\nfi\n\n# ==============================================================================\n# 1. PREPARA\u00c7\u00c3O: DOWNLOADS E C\u00d3PIA DA ESTRUTURA BASE\n# ==============================================================================\necho \"\u2b07\ufe0f Baixando pacote de release do RPM Fusion e montando ISO base...\"\nwget -O \"$RPMFUSION_RELEASE_PKG\" \"$REPO_RPMFUSION_FREE\"\n\nsudo mount -o loop \"$ISO_BASE\" \"$MNT_BASE\"\n\n# Copiar arquivos de boot e estrutura do instalador (EFI, ISOLINUX, images)\ncp \"$MNT_BASE/isolinux/$KERNEL_FILE\" \"$WORKDIR/\"\ncp \"$MNT_BASE/isolinux/$INITRD_FILE\" \"$WORKDIR/\"\nrsync -aAXv \"$MNT_BASE/EFI\" \"$WORKDIR/\"\nrsync -aAXv \"$MNT_BASE/images\" \"$WORKDIR/\"\nrsync -aAXv \"$MNT_BASE/isolinux\" \"$WORKDIR/\"\nmkdir -p \"$WORKDIR/BaseOS\" \"$WORKDIR/AppStream\"\nrsync -aAXv \"$MNT_BASE/BaseOS/repodata\" \"$WORKDIR/BaseOS/\"\nrsync -aAXv \"$MNT_BASE/AppStream/repodata\" \"$WORKDIR/AppStream/\"\n\nsudo umount \"$MNT_BASE\"\n\n# ==============================================================================\n# 2. CRIA\u00c7\u00c3O DO ROOTFS (LIVE CD) DO ZERO\n# ==============================================================================\necho \"\ud83d\udee0\ufe0f Criando um RootFS M\u00cdNIMO para o Live CD com dnf...\"\n\n# 2.1 Instalar pacotes base no RootFS (usando dnf --installroot)\nsudo dnf install -y --installroot=\"$ROOTFS\" \\\n  kernel-core \\\n  dracut \\\n  systemd \\\n  yum \\\n  dnf \\\n  passwd \\\n  bash \\\n  coreutils \\\n  procps \\\n  iproute \\\n  openssh-clients \\\n  @core --exclude=dracut-config-generic\n\n# 2.2 Configurar reposit\u00f3rios e instalar pacotes extras no Live CD\necho \"\u2699\ufe0f Configurando DNF, EPEL e RPM Fusion no Live CD RootFS...\"\n\n# Copiar arquivos necess\u00e1rios para o chroot\ncp /etc/resolv.conf \"$ROOTFS/etc/\"\ncp \"$RPMFUSION_RELEASE_PKG\" \"$ROOTFS/tmp/\"\n\n# Adicionar reposit\u00f3rios b\u00e1sicos para o chroot\nsudo chroot \"$ROOTFS\" /bin/bash <<EOF_CHROOT\n  # Habilitar EPEL (se n\u00e3o foi instalado com dnf --installroot)\n  dnf install -y $REPO_EPEL\n  \n  # Instalar RPM Fusion\n  dnf install -y /tmp/$(basename \"$RPMFUSION_RELEASE_PKG\")\n  \n  # Instalar ambiente gr\u00e1fico m\u00ednimo para o Live CD\n  dnf groupinstall -y \"Minimal Install\"\n  dnf install -y xterm\n  \n  # Instalar favoritos e pacotes extras (se forem necess\u00e1rios no Live CD)\n  mkdir -p /home/usuario/Favoritos\n  \n  dnf clean all\n  rm -f /tmp/$(basename \"$RPMFUSION_RELEASE_PKG\")\nEOF_CHROOT\n\n# 2.3 Incluir arquivos de personaliza\u00e7\u00e3o e pacotes RPM extras\necho \"\ud83d\udcc1 Incluindo favoritos e pacotes RPM extras...\"\ncp -r \"$FAVORITOS\"/* \"$ROOTFS/home/usuario/Favoritos\"\ncp \"$RPM_EXTRA\"/*.rpm \"$WORKDIR/rpms-extra/\"\ncp \"$RPMFUSION_RELEASE_PKG\" \"$WORKDIR/\" # Copiar tamb\u00e9m para a raiz da ISO\n\n# ==============================================================================\n# 3. CRIA\u00c7\u00c3O DO SQUASHFS CUSTOMIZADO (LIVE CD)\n# ==============================================================================\necho \"\ud83d\udddc\ufe0f Compactando rootfs customizado (Live CD)...\"\n# Garantir que /boot e /dev n\u00e3o est\u00e3o no squashfs\nrm -rf \"$ROOTFS/boot\" \"$ROOTFS/dev\" \"$ROOTFS/proc\" \"$ROOTFS/sys\"\nmksquashfs \"$ROOTFS\" \"$WORKDIR/LiveOS/custom.squashfs\" -comp xz -Xbc\n\n# ==============================================================================\n# 4. GERAR ARQUIVO KICKSTART (INSTALA\u00c7\u00c3O)\n# ==============================================================================\necho \"\ud83d\udcdd Gerando arquivo Kickstart com reposit\u00f3rios externos...\"\ncat <<EOF > \"$WORKDIR/$KICKSTART_FILE\"\n#version=RHEL9\ninstall\nlang pt_BR.UTF-8\nkeyboard br-abnt2\ntimezone America/Sao_Paulo\nnetwork --bootproto=dhcp\nrootpw --plaintext senha123\nfirewall --enabled\nselinux --enforcing\nreboot\n\n# DEFINI\u00c7\u00c3O DOS REPOSIT\u00d3RIOS ONLINE PARA O ANACONDA \nrepo --name=\"ol9_baseos\" --baseurl=$REPO_BASE\nrepo --name=\"ol9_appstream\" --baseurl=$REPO_APPSTREAM\nrepo --name=\"epel\" --baseurl=$REPO_EPEL\nurl --url=$REPO_BASE\n\n%packages\n@^graphical-server-environment\ngnome-terminal\nfirefox\n# Adicionar outros pacotes, ex: vlc, htop\n%end\n\n%post\n# 1. Instalar o pacote de release do RPM Fusion\necho \"Instalando RPM Fusion no sistema instalado...\"\ncp /run/install/repo/$(basename \"$RPMFUSION_RELEASE_PKG\") /mnt/sysimage/tmp/\nchroot /mnt/sysimage dnf install -y /tmp/$(basename \"$RPMFUSION_RELEASE_PKG\")\nchroot /mnt/sysimage rm -f /tmp/$(basename \"$RPMFUSION_RELEASE_PKG\")\n\n# 2. Instalar pacotes RPM Extras\necho \"Instalando pacotes extras...\"\ncp -r /run/install/repo/rpms-extra/*.rpm /mnt/sysimage/root/\nchroot /mnt/sysimage dnf install -y /root/*.rpm\nchroot /mnt/sysimage rm -f /root/*.rpm\n%end\nEOF\n\n# ==============================================================================\n# 5. CONFIGURA\u00c7\u00c3O DE BOOT E GERA\u00c7\u00c3O DA ISO\n# ==============================================================================\necho \"\u2699\ufe0f Ajustando isolinux.cfg para op\u00e7\u00f5es Live/Install...\"\nISOCONF=\"$WORKDIR/isolinux/isolinux.cfg\"\n# O kernel/initrd copiado da ISO base ser\u00e1 usado para todos os boots\n\n# Adiciona as op\u00e7\u00f5es de boot customizadas ao arquivo isolinux.cfg\ncat <<EOF >> \"$ISOCONF\"\n\nlabel customlive\n  menu label ^Custom OL9 Live Environment (Minimal)\n  kernel /$KERNEL_FILE\n  append initrd=/$INITRD_FILE root=live:LABEL=OracleLinux rd.live.image quiet\n\nlabel custominstall\n  menu label ^Custom OL9 Installation (Kickstart)\n  kernel /$KERNEL_FILE\n  append initrd=/$INITRD_FILE inst.stage2=hd:LABEL=OracleLinux inst.ks=hd:LABEL=OracleLinux:/$KICKSTART_FILE quiet\n\nlabel livegui\n  menu label ^Live CD com Instalador GUI (OL Padr\u00e3o)\n  kernel /$KERNEL_FILE\n  append initrd=/$INITRD_FILE inst.stage2=hd:LABEL=OracleLinux inst.repo=hd:LABEL=OracleLinux quiet\nEOF\n\n# Gera\u00e7\u00e3o da ISO\necho \"\ud83d\udd25 Gerando imagem ISO h\u00edbrida...\"\nxorriso -as mkisofs \\\n  -isohybrid-mbr \"$WORKDIR/isolinux/isohdpfx.bin\" \\\n  -c isolinux/boot.cat \\\n  -b isolinux/isolinux.bin \\\n  -no-emul-boot -boot-load-size 4 -boot-info-table \\\n  -eltorito-alt-boot \\\n  -e EFI/BOOT/BOOTX64.EFI \\\n  -no-emul-boot \\\n  -V \"OracleLinux\" \\\n  -J -R -T -D \\\n  -r -T \"$WORKDIR\" \\\n  -o \"$ISO_NAME\"\n\nisohybrid \"$ISO_NAME\"\n\necho \"\u2705 ISO h\u00edbrida de Instala\u00e7\u00e3o/Live criada com sucesso: $ISO_NAME\"\n", "system_scripts/build_iso.sh": " #!/bin/bash\nset -e\n\n# ==============================\n# CONFIGURA\u00c7\u00d5ES\n# ==============================\nDATA=$(date +%Y-%m-%d)\nISO_BASE=\"OracleLinux-R9-U6-x86_64-dvd.iso\"\nOUTPUT_ISO=\"OracleLinux-9.6-compacta-${DATA}.iso\"\nSOFTWARE_DIR=\"software_rpm\"\nFAVORITOS_DIR=\"favoritos\"\nKS_FILE=\"ks.cfg\"\nTEMP_REPO_DIR=\"compact_repo\"\nMOUNT_DIR=\"mnt\"\nEXTRACT_DIR=\"iso_extract\"\nEFI_DIR=\"$EXTRACT_DIR/EFI/BOOT\"\n\n# URLs dos reposit\u00f3rios para Oracle Linux 9\nORACLE_BASE_URL=\"https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/x86_64/\"\nEPEL_URL=\"https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm\"\nRPMFUSION_FREE_URL=\"https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm\"\nRPMFUSION_NONFREE_URL=\"https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-9.noarch.rpm\"\n\nREQUIRED_PACKAGES=(\"rsync\" \"createrepo_c\" \"xorriso\" \"syslinux\" \"grub2-tools\" \"grub2-efi-x64\" \"shim-x64\" \"mtools\" \"dnf-plugins-core\")\n\n# ==============================\n# FUN\u00c7\u00d5ES DE LOG\n# ==============================\nSTEP=0\nTOTAL_STEPS=7\n\nlog_step() { STEP=$((STEP+1)); echo -e \"\\n[\\e[1;34m${STEP}/${TOTAL_STEPS}\\e[0m] \ud83d\ude80 $1\"; }\nlog_info() { echo -e \"    \u279c $1\"; }\nlog_done() { echo -e \"    \u2705 $1\"; }\nlog_error() { echo -e \"    \u274c \\e[1;31mERRO: $1\\e[0m\" >&2; exit 1; }\n\n# ==============================\n# FUN\u00c7\u00c3O DE LIMPEZA\n# ==============================\ncleanup() {\n    log_info \"Limpando arquivos tempor\u00e1rios...\"\n    mountpoint -q \"$MOUNT_DIR\" &>/dev/null && sudo umount \"$MOUNT_DIR\"\n    rm -rf \"$MOUNT_DIR\" \"$TEMP_REPO_DIR\" \"$EXTRACT_DIR\" \"$KS_FILE\"\n    log_done \"Limpeza conclu\u00edda.\"\n}\ntrap cleanup EXIT\n\n# ==============================\n# VERIFICA DEPEND\u00caNCIAS\n# ==============================\ncheck_dependencies() {\n    log_step \"Verificando depend\u00eancias...\"\n    local missing=()\n    for pkg in \"${REQUIRED_PACKAGES[@]}\"; do\n        if ! rpm -q \"$pkg\" &>/dev/null; then\n            missing+=(\"$pkg\")\n        fi\n    done\n    if [ ${#missing[@]} -gt 0 ]; then\n        log_info \"Instalando: ${missing[*]}\"\n        sudo dnf install -y \"${missing[@]}\" || log_error \"Falha na instala\u00e7\u00e3o de depend\u00eancias.\"\n    fi\n    log_done \"Depend\u00eancias OK.\"\n}\n\n# ==============================\n# IN\u00cdCIO DO SCRIPT\n# ==============================\ncheck_dependencies\n\n# 1\ufe0f\u20e3 GERA ARQUIVO KICKSTART\nlog_step \"Gerando Kickstart...\"\ncat > \"$KS_FILE\" <<'EOF'\n#version=RHEL9\ninstall\ncdrom\nlang pt_BR.UTF-8\nkeyboard br-abnt2\ntimezone America/Sao_Paulo --isUtc\nrootpw --plaintext oracle\nuser --name=user --password=oracle --plaintext --groups=wheel\nfirewall --enabled\nselinux --enforcing\nnetwork --bootproto=dhcp --device=link --activate\nbootloader --location=mbr\nautopart --type=lvm\nreboot\n\n# Reposit\u00f3rio local com pacotes essenciais\nrepo --name=\"local-repo\" --baseurl=file:///mnt/repo --gpgcheck=0 --enabled=1\n\n%packages\n@^minimal-environment\n@core\n# Pacotes adicionais de reposit\u00f3rios externos\nepel-release\nrpmfusion-free-release\nrpmfusion-nonfree-release\n%end\n\n%post --log=/root/post-install.log\n# Ativa\u00e7\u00e3o dos reposit\u00f3rios\ndnf install -y oraclelinux-release-epl\ndnf install -y https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm\ndnf install -y https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-9.noarch.rpm\n\n# Copia arquivos favoritos\nmkdir -p /home/user/favoritos\ncp -r /mnt/favoritos/* /home/user/favoritos/ || true\nchown -R user:user /home/user/favoritos\n\n# Copia software RPM\nmkdir -p /home/user/software_rpm\ncp -r /mnt/software_rpm/* /home/user/software_rpm/ || true\nchown -R user:user /home/user/software_rpm\n%end\nEOF\nlog_done \"Kickstart criado.\"\n\n# 2\ufe0f\u20e3 MONTA E EXTRAI ISO BASE\nlog_step \"Montando e extraindo ISO base...\"\nmkdir -p \"$MOUNT_DIR\" \"$EXTRACT_DIR\"\nsudo mount -o loop \"$ISO_BASE\" \"$MOUNT_DIR\" || log_error \"Falha ao montar ISO base.\"\nrsync -a --exclude=\"Packages\" \"$MOUNT_DIR\"/ \"$EXTRACT_DIR\"/\nlog_done \"ISO extra\u00edda (sem pacotes).\"\nsudo umount \"$MOUNT_DIR\"\n\n# 3\ufe0f\u20e3 CRIA REPOSIT\u00d3RIO COMPACTO A PARTIR DA ISO BASE\nlog_step \"Criando reposit\u00f3rio de pacotes compacto a partir da ISO base...\"\nmkdir -p \"$TEMP_REPO_DIR\"\n\nlog_info \"Identificando pacotes essenciais dos grupos @core e @minimal-environment...\"\ndeclare -a ESSENTIAL_PACKAGES\n\n# Monta a ISO base para copiar metadados\nlog_info \"Montando ISO para copiar metadados...\"\nsudo mount -o loop \"$ISO_BASE\" \"$MOUNT_DIR\" || log_error \"Falha ao montar ISO base.\"\n\n# Copia os metadados do reposit\u00f3rio da ISO para um diret\u00f3rio tempor\u00e1rio\nmkdir -p \"$TEMP_REPO_DIR/BaseOS/repodata\"\nlog_info \"Copiando metadados da ISO para diret\u00f3rio tempor\u00e1rio...\"\nsudo rsync -a \"$MOUNT_DIR/BaseOS/repodata/\" \"$TEMP_REPO_DIR/BaseOS/repodata/\" || log_error \"Falha ao copiar metadados do reposit\u00f3rio.\"\nsudo umount \"$MOUNT_DIR\"\n\n# Garante que os arquivos tempor\u00e1rios tenham as permiss\u00f5es corretas\nsudo chown -R $USER:$USER \"$TEMP_REPO_DIR\"\n\nfor GROUP in \"core\" \"minimal-environment\"; do\n    log_info \"Obtendo pacotes do grupo: $GROUP\"\n    \n    # Usa o dnf para ler o grupo do reposit\u00f3rio tempor\u00e1rio\n    sudo dnf -c /dev/null --repofrompath=temp_repo,\"file://$TEMP_REPO_DIR/BaseOS\" group info \"$GROUP\" &> group_info.txt\n\n    # Extrai a lista de pacotes a partir da sa\u00edda do dnf\n    PACKAGES=$(grep -A 1000 'Mandatory Packages:' group_info.txt | sed '/^Default Packages/q' | awk '{print $1}')\n    \n    if [ -z \"$PACKAGES\" ]; then\n        PACKAGES=$(grep -A 1000 'Mandatory Packages:' group_info.txt | sed '1,/^$/d' | sed 's/ (.*)//g' | grep -v '^\\s*$' | awk '{print $1}')\n    fi\n\n    if [ -n \"$PACKAGES\" ]; then\n        ESSENTIAL_PACKAGES+=($PACKAGES)\n    fi\ndone\n\nif [ ${#ESSENTIAL_PACKAGES[@]} -gt 0 ]; then\n    ESSENTIAL_PACKAGES=($(printf \"%s\\n\" \"${ESSENTIAL_PACKAGES[@]}\" | sort -u))\nfi\n\nif [ ${#ESSENTIAL_PACKAGES[@]} -eq 0 ]; then\n    log_error \"N\u00e3o foi poss\u00edvel obter a lista de pacotes essenciais da ISO base.\"\nfi\n\nlog_info \"Copiando pacotes da ISO base...\"\nsudo mount -o loop \"$ISO_BASE\" \"$MOUNT_DIR\"\nfor PKG in \"${ESSENTIAL_PACKAGES[@]}\"; do\n    find \"$MOUNT_DIR/BaseOS/Packages\" -type f -name \"$PKG-*.rpm\" -exec cp -t \"$TEMP_REPO_DIR\" {} + || true\ndone\nsudo umount \"$MOUNT_DIR\"\nlog_done \"Pacotes essenciais copiados.\"\n\n# Adiciona pacotes personalizados, se houver\nif [ -d \"$SOFTWARE_DIR\" ] && ls \"$SOFTWARE_DIR\"/*.rpm &>/dev/null; then\n    log_info \"Adicionando pacotes personalizados...\"\n    cp \"$SOFTWARE_DIR\"/*.rpm \"$TEMP_REPO_DIR/\"\n    log_done \"Pacotes personalizados adicionados.\"\nelse\n    log_info \"Nenhum pacote personalizado encontrado.\"\nfi\n\n# Move o reposit\u00f3rio para o diret\u00f3rio de extra\u00e7\u00e3o da ISO e gera os metadados\nmkdir -p \"$EXTRACT_DIR/repo\"\ncp -r \"$TEMP_REPO_DIR\"/* \"$EXTRACT_DIR/repo/\"\ncreaterepo_c \"$EXTRACT_DIR/repo\"\nlog_done \"Reposit\u00f3rio compacto criado e movido.\"\n\n# 4\ufe0f\u20e3 ADICIONA FAVORITOS E SOFTWARE RPM\nlog_step \"Adicionando arquivos favoritos e software RPM...\"\nif [ -d \"$FAVORITOS_DIR\" ] && [ \"$(ls -A $FAVORITOS_DIR)\" ]; then\n    mkdir -p \"$EXTRACT_DIR/$FAVORITOS_DIR\"\n    cp -r \"$FAVORITOS_DIR\"/* \"$EXTRACT_DIR/$FAVORITOS_DIR/\"\n    log_done \"Favoritos adicionados.\"\nelse\n    log_info \"Nenhum favorito encontrado.\"\nfi\n\nif [ -d \"$SOFTWARE_DIR\" ] && [ \"$(ls -A $SOFTWARE_DIR)\" ]; then\n    mkdir -p \"$EXTRACT_DIR/$SOFTWARE_DIR\"\n    cp -r \"$SOFTWARE_DIR\"/* \"$EXTRACT_DIR/$SOFTWARE_DIR/\"\n    log_done \"Software RPM adicionado.\"\nelse\n    log_info \"Nenhum software RPM encontrado.\"\nfi\n\n# 5\ufe0f\u20e3 ADICIONA KICKSTART E CONFIGURA GRUB\nlog_step \"Configurando GRUB2 para BIOS e UEFI...\"\nmkdir -p \"$EXTRACT_DIR/boot/grub\" \"$EFI_DIR\"\n\n# grub.cfg para BIOS\ncat > \"$EXTRACT_DIR/boot/grub/grub.cfg\" <<EOF\nset timeout=5\nset default=0\n\nmenuentry \"Instalar Oracle Linux 9.6\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL96 inst.ks=cdrom:/ks.cfg\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n# grub.cfg para UEFI\ncat > \"$EFI_DIR/grub.cfg\" <<'EOF'\nset timeout=5\nset default=0\n\nmenuentry \"Instalar Oracle Linux 9.6\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=OL96 inst.ks=cdrom:/ks.cfg\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n# Detecta GRUB EFI e shim\nGRUB_PATHS=(\n    \"/usr/lib64/efi/grubx64.efi\"\n    \"/usr/lib/grub/x86_64-efi/monolithic/grubx64.efi\"\n    \"/boot/efi/EFI/BOOT/grubx64.efi\"\n)\nSHIM_PATHS=(\n    \"/usr/lib64/efi/shimx64.efi\"\n    \"/boot/efi/EFI/BOOT/BOOTX64.EFI\"\n)\n\nFOUND_GRUB=\"\"\nfor path in \"${GRUB_PATHS[@]}\"; do\n    [ -f \"$path\" ] && FOUND_GRUB=\"$path\" && break\ndone\n\nFOUND_SHIM=\"\"\nfor path in \"${SHIM_PATHS[@]}\"; do\n    [ -f \"$path\" ] && FOUND_SHIM=\"$path\" && break\ndone\n\nif [ -n \"$FOUND_SHIM\" ]; then\n    log_info \"Usando shim como BOOTX64.EFI: $FOUND_SHIM\"\n    cp \"$FOUND_SHIM\" \"$EFI_DIR/BOOTX64.EFI\"\n    if [ -n \"$FOUND_GRUB\" ]; then\n        cp \"$FOUND_GRUB\" \"$EFI_DIR/grubx64.efi\"\n    else\n        log_error \"shim encontrado, mas grubx64.efi ausente.\"\n    fi\nelif [ -n \"$FOUND_GRUB\" ]; then\n    log_info \"Usando grubx64.efi diretamente como BOOTX64.EFI: $FOUND_GRUB\"\n    cp \"$FOUND_GRUB\" \"$EFI_DIR/BOOTX64.EFI\"\nelse\n    log_error \"Nenhum arquivo EFI encontrado. Instale 'grub2-efi-x64'.\"\nfi\n\ncp \"$KS_FILE\" \"$EXTRACT_DIR/\"\nlog_done \"GRUB2 configurado.\"\n\n# 6\ufe0f\u20e3 GERA ISO H\u00cdBRIDA\nlog_step \"Gerando ISO h\u00edbrida com suporte BIOS e UEFI...\"\nxorriso -as mkisofs \\\n    -o \"$OUTPUT_ISO\" \\\n    -volid OL96 \\\n    -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n    -c isolinux/boot.cat \\\n    -b isolinux/isolinux.bin \\\n    -no-emul-boot \\\n    -boot-load-size 4 \\\n    -boot-info-table \\\n    -eltorito-alt-boot \\\n    -e EFI/BOOT/BOOTX64.EFI \\\n    -no-emul-boot \\\n    \"$EXTRACT_DIR\"\nlog_done \"ISO criada com sucesso: $OUTPUT_ISO\"\n\n# 7\ufe0f\u20e3 FINALIZA\u00c7\u00c3O\nlog_step \"Processo conclu\u00eddo.\"\nlog_done \"ISO personalizada e compacta pronta: $OUTPUT_ISO\"\n", "system_scripts/create_iso.sh": " #!/bin/bash\nset -e\n\n# ==============================================================================\n# CONFIGURA\u00c7\u00d5ES DA ISO E DIRET\u00d3RIOS\n# ==============================================================================\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" &>/dev/null && pwd)\"\ncd \"$SCRIPT_DIR\"\n\n# Definindo o limite de tamanho da ISO em bytes (5 GiB)\nMAX_ISO_SIZE_BYTES=$(( 5 * 1024 * 1024 * 1024 ))\nMAX_ISO_SIZE_HUMAN=\"5 GiB\"\nSAFETY_MARGIN=$(( 150 * 1024 * 1024 )) # Margem de seguran\u00e7a de 150 MB\n\nDATA=$(date +%Y-%m-%d)\nISO_BASE=\"OracleLinux-R9-U4-x86_64-dvd.iso\"\nOUTPUT_ISO=\"OracleLinux-9.6-GUI-Offline-5G-${DATA}.iso\"\nSOFTWARE_DIR=\"software_rpm\"\nFAVORITOS_DIR=\"favoritos\"\nREQUIRED_RPMS_DIR=\"required_rpms\" # Pacotes de EPEL/RPM Fusion para inclus\u00e3o offline\nKS_FILE=\"ks.cfg\"\nCOMPRESSED_REPO_NAME=\"repo.tar.xz\"\n\n# Diret\u00f3rios tempor\u00e1rios\nMOUNT_DIR=$(mktemp -d -t ol9-mnt-XXXXXXXXXX)\nEXTRACT_DIR=$(mktemp -d -t ol9-extract-XXXXXXXXXX)\nTEMP_REPO_DIR=$(mktemp -d -t ol9-repo-XXXXXXXXXX)\nEFI_DIR=\"$EXTRACT_DIR/EFI/BOOT\"\nISOLINUX_DIR=\"$EXTRACT_DIR/isolinux\"\n\n# Depend\u00eancias necess\u00e1rias no HOST (Adicionado 'syslinux' e 'dnf-utils' para MBR/downloads)\nREQUIRED_PACKAGES=(\"rsync\" \"createrepo_c\" \"xorriso\" \"xz\" \"syslinux\" \"dnf-utils\")\n\n# Caminho interno do bin\u00e1rio MBR ap\u00f3s a c\u00f3pia ou fallback\nINTERNAL_ISOHDPFX_BIN=\"$ISOLINUX_DIR/isohdpfx.bin\" \n\n# ==============================================================================\n# FUN\u00c7\u00d5ES DE LOG (Mantidas)\n# ==============================================================================\nSTEP=0\nTOTAL_STEPS=9 # Aumentamos para 9\n\nlog_step() { STEP=$((STEP+1)); echo -e \"\\n[\\e[1;34m${STEP}/${TOTAL_STEPS}\\e[0m] \ud83d\ude80 $1\"; }\nlog_info() { echo -e \"    \u279c $1\"; }\nlog_done() { echo -e \"    \u2705 $1\"; }\nlog_error() { echo -e \"    \u274c \\e[1;31mERRO: $1\\e[0m\" >&2; exit 1; }\nlog_warn() { echo -e \"    \u26a0\ufe0f \\e[1;33mAVISO: $1\\e[0m\"; }\n\n# ==============================================================================\n# FUN\u00c7\u00d5ES PRINCIPAIS DO PROCESSO\n# ==============================================================================\n\n# Novo passo: Baixar RPMs de depend\u00eancias para o reposit\u00f3rio\ndownload_required_rpms() {\n    log_step \"Baixando RPMs de reposit\u00f3rios externos para inclus\u00e3o offline...\"\n    \n    mkdir -p \"$REQUIRED_RPMS_DIR\"\n\n    # Pacotes necess\u00e1rios para configurar reposit\u00f3rios no %post\n    # Usamos dnf download --resolve para garantir que depend\u00eancias essenciais sejam baixadas\n    \n    # Adicionando EPEL release (URL est\u00e1vel)\n    log_info \"Baixando EPEL release e depend\u00eancias...\"\n    sudo dnf download -y --resolve --destdir=\"$REQUIRED_RPMS_DIR\" \"https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm\" || log_warn \"Falha ao baixar EPEL. O Kickstart continuar\u00e1 tentando baixar online.\"\n\n    # Adicionando RPM Fusion (URLs est\u00e1veis)\n    log_info \"Baixando RPM Fusion release (Free e Nonfree) e depend\u00eancias...\"\n    sudo dnf download -y --resolve --destdir=\"$REQUIRED_RPMS_DIR\" \\\n        \"https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm\" \\\n        \"https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-9.noarch.rpm\" || log_warn \"Falha ao baixar RPM Fusion. O Kickstart continuar\u00e1 tentando baixar online.\"\n        \n    log_done \"Downloads de depend\u00eancias de reposit\u00f3rio conclu\u00eddos em $REQUIRED_RPMS_DIR.\"\n}\n\nsetup() {\n    log_step \"Preparando ambiente e verificando depend\u00eancias...\"\n    \n    if [ ! -f \"$ISO_BASE\" ]; then\n        log_error \"Arquivo de ISO base n\u00e3o encontrado: $ISO_BASE.\"\n    fi\n\n    log_info \"Verificando e instalando depend\u00eancias: ${REQUIRED_PACKAGES[*]}...\"\n    local missing=()\n    for pkg in \"${REQUIRED_PACKAGES[@]}\"; do\n        if ! rpm -q \"$pkg\" &>/dev/null; then\n            missing+=(\"$pkg\")\n        fi\n    done\n\n    if [ ${#missing[@]} -gt 0 ]; then\n        log_info \"Instalando depend\u00eancias faltantes: ${missing[*]}\"\n        sudo dnf install -y \"${missing[@]}\" || log_error \"Falha cr\u00edtica na instala\u00e7\u00e3o de depend\u00eancias.\"\n    fi\n    \n    # 2. Copia o bin\u00e1rio MBR para o diret\u00f3rio de extra\u00e7\u00e3o, usando fallback do host\n    if [ ! -f \"$INTERNAL_ISOHDPFX_BIN\" ]; then\n        log_warn \"Bin\u00e1rio MBR (isohdpfx.bin) n\u00e3o encontrado no diret\u00f3rio de extra\u00e7\u00e3o local. Tentando copiar do host...\"\n        if [ -f \"/usr/share/syslinux/isohdpfx.bin\" ]; then\n            mkdir -p \"$ISOLINUX_DIR\"\n            cp \"/usr/share/syslinux/isohdpfx.bin\" \"$INTERNAL_ISOHDPFX_BIN\"\n            log_info \"Bin\u00e1rio MBR copiado do HOST para $INTERNAL_ISOHDPFX_BIN (Fallback OK).\"\n        else\n            log_error \"O bin\u00e1rio MBR isohdpfx.bin n\u00e3o foi encontrado na ISO base. Instale o pacote 'syslinux' ou verifique o caminho da ISO.\"\n        fi\n    fi\n\n    log_done \"Ambiente e depend\u00eancias OK.\"\n}\n\ncleanup() {\n    log_info \"Limpando arquivos tempor\u00e1rios...\"\n    if mountpoint -q \"$MOUNT_DIR\" &>/dev/null; then\n        sudo umount \"$MOUNT_DIR\"\n    fi\n    rm -rf \"$MOUNT_DIR\" \"$TEMP_REPO_DIR\" \"$EXTRACT_DIR\" \"$KS_FILE\"\n    log_done \"Limpeza conclu\u00edda.\"\n}\n\n# 1. GERA\u00c7\u00c3O DO KICKSTART: Configurado para iniciar em modo gr\u00e1fico (GUI)\ngenerate_kickstart() {\n    log_step \"Gerando arquivo Kickstart customizado (Instala\u00e7\u00e3o GUI)...\"\n    cat > \"$KS_FILE\" <<EOF\n#version=RHEL9\ninstall\ncdrom\nlang pt_BR.UTF-8\nkeyboard br-abnt2\ntimezone America/Sao_Paulo --isUtc\nrootpw --plaintext oracle\nuser --name=customuser --password=oracle --plaintext --groups=wheel\nfirewall --enabled\nselinux --enforcing\nnetwork --bootproto=dhcp --device=link --activate\nbootloader --location=all\nautopart --type=lvm\nreboot\n\n# Inicia o instalador em modo gr\u00e1fico (GUI)\n# text \ngraphical\n\n# Reposit\u00f3rio local (descompactado)\nrepo --name=\"local-repo\" --baseurl=file:///mnt/repo --gpgcheck=0 --enabled=1\n\n%packages\n@core\n# Adicione um ambiente de desktop b\u00e1sico para um sistema mais us\u00e1vel p\u00f3s-instala\u00e7\u00e3o\n@server-product-environment\n%end\n\n# =================================================================\n# FASE PRE: Descompacta o reposit\u00f3rio\n# =================================================================\n%pre\nlog_info() { echo -e \"-> \\$1\"; }\nlog_info \"Iniciando descompacta\u00e7\u00e3o do reposit\u00f3rio...\"\nREPO_ARCHIVE=\"/mnt/install/$COMPRESSED_REPO_NAME\"\nREPO_TARGET=\"/mnt/repo\"\nmkdir -p \\$REPO_TARGET\n# Usamos 'tar -xJf' para descompactar o arquivo .tar.xz\ntar -xJf \\$REPO_ARCHIVE -C \\$REPO_TARGET\nlog_info \"Reposit\u00f3rio descompactado em \\$REPO_TARGET.\"\n%end\n\n# =================================================================\n# FASE POST: Configura repos e copia arquivos\n# =================================================================\n%post --log=/root/post-install.log\nlog_info() { echo -e \"-> \\$1\"; }\nlog_info \"Iniciando scripts de p\u00f3s-instala\u00e7\u00e3o...\"\n\n# Os RPMs do EPEL/RPM Fusion j\u00e1 est\u00e3o no reposit\u00f3rio local (/mnt/repo)\n\n# 1. Configura Reposit\u00f3rios Externos (Offline)\nlog_info \"Configurando reposit\u00f3rios EPEL e RPM Fusion (Offline)...\"\n# Busca e instala os pacotes de release do EPEL/RPM Fusion diretamente do reposit\u00f3rio local\n# O 'dnf install' deve ser capaz de encontr\u00e1-los no /mnt/repo\ndnf install -y \\\n    /mnt/repo/epel-release-latest-9.noarch.rpm \\\n    /mnt/repo/rpmfusion-free-release-9.noarch.rpm \\\n    /mnt/repo/rpmfusion-nonfree-release-9.noarch.rpm || log_warn \"Falha ao instalar pacotes de release do reposit\u00f3rio local. Tentando dnf install -y (online).\"\n\n# Instala oraclelinux-release-epl (se necess\u00e1rio)\ndnf install -y oraclelinux-release-epl > /dev/null 2>&1\nlog_info \"Reposit\u00f3rios EPEL e RPM Fusion configurados (parcialmente ou totalmente offline).\"\n\n# 2. Copia Arquivos Customizados (Favoritos e Software)\nCUSTOM_USER=\"customuser\"\nHOME_DIR=\"/home/\\$CUSTOM_USER\"\nlog_info \"Copiando arquivos customizados para \\$HOME_DIR...\"\n# Arquivos customizados est\u00e3o na raiz da ISO (agora /mnt/install)\nfor dir_name in \"favoritos\" \"software_rpm\"; do\n    if [ -d \"/mnt/install/\\$dir_name\" ]; then\n        mkdir -p \"\\$HOME_DIR/\\$dir_name\"\n        cp -r /mnt/install/\\$dir_name/* \"\\$HOME_DIR/\\$dir_name/\" || true\n        chown -R \\$CUSTOM_USER:\\$CUSTOM_USER \"\\$HOME_DIR/\\$dir_name\"\n        log_info \"Arquivos de \\$dir_name copiados.\"\n    fi\ndone\n\n# 3. Limpeza\nrm -f /root/anaconda-ks.cfg\nlog_info \"P\u00f3s-instala\u00e7\u00e3o conclu\u00edda.\"\n\n%end\nEOF\n    log_done \"Kickstart criado em $KS_FILE. (In\u00edcio da instala\u00e7\u00e3o: GUI)\"\n}\n\n# 2. MONTAGEM E EXTRA\u00c7\u00c3O\nmount_and_extract_iso() {\n    log_step \"Montando e extraindo ISO base...\"\n    sudo mount -o loop \"$ISO_BASE\" \"$MOUNT_DIR\" || log_error \"Falha ao montar ISO base.\"\n\n    log_info \"Copiando arquivos essenciais da ISO (excluindo pacotes)...\"\n    rsync -a --exclude=\"Packages\" \"$MOUNT_DIR\"/ \"$EXTRACT_DIR\"/\n\n    log_info \"Copiando pacotes da ISO para o reposit\u00f3rio tempor\u00e1rio...\"\n    rsync -a \"$MOUNT_DIR/BaseOS/Packages/\" \"$TEMP_REPO_DIR/\"\n\n    log_done \"Arquivos base copiados.\"\n    sudo umount \"$MOUNT_DIR\" # Desmonta a ISO base imediatamente ap\u00f3s copiar\n}\n\n# 3. CRIA\u00c7\u00c3O E COMPACTA\u00c7\u00c3O DO REPOSIT\u00d3RIO OFFLINE\ncreate_offline_repo() {\n    log_step \"Criando e compactando reposit\u00f3rio offline (Limite: ${MAX_ISO_SIZE_HUMAN})...\"\n    \n    # 1. Adicionar pacotes customizados e de reposit\u00f3rios (software_rpm + required_rpms)\n    for dir in \"$SOFTWARE_DIR\" \"$REQUIRED_RPMS_DIR\"; do\n        if [ -d \"$dir\" ] && [ \"$(ls -A $dir)\" ]; then\n            log_info \"Adicionando pacotes de $dir ao reposit\u00f3rio...\"\n            cp \"$dir\"/*.rpm \"$TEMP_REPO_DIR/\" || log_warn \"N\u00e3o foi poss\u00edvel copiar RPMs de $dir.\"\n        fi\n    done\n\n    # 2. Gerar metadados\n    log_info \"Gerando metadados do reposit\u00f3rio tempor\u00e1rio...\"\n    createrepo_c \"$TEMP_REPO_DIR\"\n\n    # 3. Compactar\n    log_info \"Compactando reposit\u00f3rio para ${COMPRESSED_REPO_NAME} (usando xz)...\"\n    tar -cJpf \"$EXTRACT_DIR/$COMPRESSED_REPO_NAME\" -C \"$(dirname \"$TEMP_REPO_DIR\")\" \"$(basename \"$TEMP_REPO_DIR\")\"\n    \n    rm -rf \"$TEMP_REPO_DIR\"\n\n    # 4. Checagem de limite (Mantida)\n    COMPRESSED_REPO_SIZE=$(du -sb \"$EXTRACT_DIR/$COMPRESSED_REPO_NAME\" | awk '{print $1}')\n    log_info \"Tamanho do reposit\u00f3rio compactado: $(numfmt --to=iec --format=\"%.1f\" \"$COMPRESSED_REPO_SIZE\")\"\n    \n    CURRENT_ISO_CONTENT_SIZE=$(sudo du -sb \"$EXTRACT_DIR\" | awk '{print $1}')\n    \n    if [ \"$CURRENT_ISO_CONTENT_SIZE\" -gt \"$(( MAX_ISO_SIZE_BYTES - SAFETY_MARGIN ))\" ]; then\n        log_error \"O conte\u00fado da ISO excede o limite de ${MAX_ISO_SIZE_HUMAN}.\"\n    else\n        log_info \"Tamanho total do conte\u00fado (~$(numfmt --to=iec --format=\"%.1f\" \"$CURRENT_ISO_CONTENT_SIZE\")) est\u00e1 dentro do limite.\"\n    fi\n    \n    log_done \"Reposit\u00f3rio compactado e verificado.\"\n}\n\n# 4. ADI\u00c7\u00c3O DE ARQUIVOS CUSTOMIZADOS (Mantido)\nadd_custom_files() {\n    log_step \"Adicionando arquivos personalizados...\"\n    \n    for dir_name in \"$FAVORITOS_DIR\" \"$SOFTWARE_DIR\"; do\n        if [ -d \"$dir_name\" ] && [ \"$(ls -A $dir_name)\" ]; then\n            mkdir -p \"$EXTRACT_DIR/$dir_name\"\n            cp -r \"$dir_name\"/* \"$EXTRACT_DIR/$dir_name/\"\n            log_done \"Arquivos de $dir_name adicionados.\"\n        fi\n    done\n    \n    # O kickstart \u00e9 copiado aqui para a raiz da extra\u00e7\u00e3o\n    cp \"$KS_FILE\" \"$EXTRACT_DIR/\"\n}\n\n# 5. CONFIGURA\u00c7\u00c3O DE BOOT (Inclui 'inst.ks')\nconfigure_bootloaders() {\n    log_step \"Configurando arquivos de boot GRUB2 e ISOLINUX...\"\n    \n    # Arquivos de configura\u00e7\u00e3o de boot (apontando para o Kickstart na raiz)\n    \n    # Par\u00e2metros de boot: inst.stage2=hd:LABEL=OL9 inst.ks=cdrom:/ks.cfg\n    BOOT_PARAMS=\"inst.stage2=hd:LABEL=OL9 inst.ks=cdrom:/ks.cfg\"\n    \n    # BIOS grub.cfg\n    mkdir -p \"$EXTRACT_DIR/boot/grub\"\n    cat > \"$EXTRACT_DIR/boot/grub/grub.cfg\" <<EOF\nset timeout=5\nset default=0\n\nmenuentry \"Instalar Oracle Linux 9.6 Compacto (GUI)\" {\n    linux /images/pxeboot/vmlinuz $BOOT_PARAMS\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n    # UEFI grub.cfg\n    cat > \"$EFI_DIR/grub.cfg\" <<EOF\nset timeout=5\nset default=0\n\nmenuentry \"Instalar Oracle Linux 9.6 Compacto (GUI)\" {\n    linux /images/pxeboot/vmlinuz $BOOT_PARAMS\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n    log_done \"Configura\u00e7\u00e3o de boot finalizada.\"\n}\n\n# 6. GERA\u00c7\u00c3O FINAL DA IMAGEM ISO (HYBRID)\ngenerate_iso() {\n    log_step \"Gerando ISO h\u00edbrida...\"\n    \n    # Agora confiamos que $INTERNAL_ISOHDPFX_BIN foi criado pelo setup (fallback)\n    xorriso -as mkisofs \\\n        -o \"$OUTPUT_ISO\" \\\n        -volid OL9 \\\n        -isohybrid-mbr \"$INTERNAL_ISOHDPFX_BIN\" \\\n        -c isolinux/boot.cat \\\n        -b isolinux/isolinux.bin \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        -eltorito-alt-boot \\\n        -e EFI/BOOT/BOOTX64.EFI \\\n        -no-emul-boot \\\n        \"$EXTRACT_DIR\" || log_error \"Falha ao gerar a ISO. O bin\u00e1rio MBR pode estar faltando.\"\n    log_done \"ISO criada com sucesso: $OUTPUT_ISO\"\n}\n\nfinalize() {\n    log_step \"Processo conclu\u00eddo.\"\n    ISO_SIZE=$(du -h \"$OUTPUT_ISO\" | awk '{print $1}')\n    \n    FINAL_SIZE_BYTES=$(du -s \"$OUTPUT_ISO\" | awk '{print $1 * 1024}')\n\n    if [ \"$FINAL_SIZE_BYTES\" -gt \"$MAX_ISO_SIZE_BYTES\" ]; then\n        log_warn \"A ISO final ($ISO_SIZE) EXCEDEU o limite de ${MAX_ISO_SIZE_HUMAN}. Reduza o conte\u00fado de $SOFTWARE_DIR e $REQUIRED_RPMS_DIR.\"\n    fi\n\n    log_done \"ISO personalizada pronta: $OUTPUT_ISO\"\n    log_done \"Tamanho da imagem: $ISO_SIZE\"\n}\n\n# ==============================================================================\n# FLUXO PRINCIPAL\n# ==============================================================================\ntrap cleanup EXIT\n\n# Novo passo de download antes do setup para garantir que os RPMs de repo estejam prontos\ndownload_required_rpms \n\nsetup\ngenerate_kickstart\nmount_and_extract_iso\ncreate_offline_repo   # Inclui RPMs da ISO + software + releases de repo\nadd_custom_files      # Adiciona favoritos e software_rpm para c\u00f3pia p\u00f3s-instala\u00e7\u00e3o\nconfigure_bootloaders # Configura GRUB para iniciar a GUI do Anaconda\ngenerate_iso\nfinalize\n", "system_scripts/fix-repos-ol9.sh": "#!/bin/bash\n#\n# fix-repos-ol9.sh\n# Script para corrigir reposit\u00f3rios do Oracle Linux 9.7\n# Remove configs antigas, instala reposit\u00f3rios atualizados,\n# desabilita plugins quebrados e limpa o cache do DNF.\n#\n\nset -e\n\nVERMELHO='\\033[0;31m'\nVERDE='\\033[0;32m'\nAMARELO='\\033[1;33m'\nAZUL='\\033[0;34m'\nNC='\\033[0m'\n\nlog_info()  { echo -e \"${AZUL}[INFO]${NC}  $1\"; }\nlog_ok()    { echo -e \"${VERDE}[OK]${NC}    $1\"; }\nlog_warn()  { echo -e \"${AMARELO}[WARN]${NC}  $1\"; }\nlog_erro()  { echo -e \"${VERMELHO}[ERRO]${NC} $1\"; }\n\n###############################################################################\n# Verifica se est\u00e1 rodando como root\n###############################################################################\nif [[ $EUID -ne 0 ]]; then\n    log_erro \"Este script precisa ser executado como root (sudo).\"\n    exit 1\nfi\n\n###############################################################################\n# Verifica se \u00e9 Oracle Linux 9.x\n###############################################################################\nif ! grep -qi \"Oracle Linux\" /etc/oracle-release 2>/dev/null; then\n    log_erro \"Este script \u00e9 exclusivo para Oracle Linux 9.\"\n    exit 1\nfi\n\nVERSAO=$(grep -oP '\\d+\\.\\d+' /etc/oracle-release | head -1)\nlog_info \"Oracle Linux detectado: $VERSAO\"\n\n###############################################################################\n# Backup dos reposit\u00f3rios atuais\n###############################################################################\nBACKUP_DIR=\"/etc/yum.repos.d/backup-$(date +%Y%m%d%H%M%S)\"\nmkdir -p \"$BACKUP_DIR\"\ncp /etc/yum.repos.d/*.repo \"$BACKUP_DIR/\" 2>/dev/null || true\nlog_ok \"Backup dos .repo em: $BACKUP_DIR\"\n\n###############################################################################\n# Remove todos os arquivos .repo existentes (vamos recriar)\n###############################################################################\nrm -f /etc/yum.repos.d/*.repo\nlog_info \"Arquivos .repo antigos removidos.\"\n\n###############################################################################\n# oracle-linux.repo \u2014 reposit\u00f3rios oficiais Oracle Linux 9\n###############################################################################\ncat > /etc/yum.repos.d/oracle-linux.repo << 'REPO'\n[ol9_baseos_latest]\nname=Oracle Linux 9 BaseOS Latest ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_appstream]\nname=Oracle Linux 9 Application Stream ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_UEKR7]\nname=Oracle Linux 9 UEK R7 ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/UEKR7/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_kvm_utils]\nname=Oracle Linux 9 KVM Utilities ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/kvm/utils/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_codeready_builder]\nname=Oracle Linux 9 CodeReady Builder ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/codeready/builder/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\n\n[ol9_distro_builder]\nname=Oracle Linux 9 Distro Builder ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/distro/builder/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\n\n[ol9_optional_latest]\nname=Oracle Linux 9 Optional Latest ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/optional/latest/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=0\nREPO\nlog_ok \"oracle-linux.repo criado com reposit\u00f3rios oficiais.\"\n\n###############################################################################\n# oracle-epel-ol9.repo \u2014 EPEL via Oracle (mais est\u00e1vel para OL9)\n###############################################################################\nif rpm -q oracle-epel-release-el9 &>/dev/null; then\n    log_info \"oracle-epel-release-el9 j\u00e1 instalado. Usando reposit\u00f3rio EPEL do Oracle.\"\n\n    cat > /etc/yum.repos.d/oracle-epel-ol9.repo << 'REPO'\n[ol9_epel]\nname=Oracle Linux 9 EPEL ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/epel/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\nREPO\n    log_ok \"oracle-epel-ol9.repo criado (EPEL via Oracle).\"\nelse\n    log_warn \"oracle-epel-release-el9 N\u00c3O instalado. Instalando...\"\n\n    dnf install -y oracle-epel-release-el9 2>/dev/null || {\n        log_erro \"Falha ao instalar oracle-epel-release-el9 via DNF.\"\n        log_info \"Criando EPEL manual como fallback...\"\n\n        cat > /etc/yum.repos.d/epel.repo << 'REPO'\n[epel]\nname=Extra Packages for Enterprise Linux 9 - $basearch\nmetalink=https://mirrors.fedoraproject.org/metalink?repo=epel-9&arch=$basearch\nenabled=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\ngpgcheck=1\n\n[epel-next]\nname=Extra Packages for Enterprise Linux 9 - Next - $basearch\nmetalink=https://mirrors.fedoraproject.org/metalink?repo=epel-next-9&arch=$basearch\nenabled=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\ngpgcheck=1\nREPO\n\n        log_info \"Baixando chave GPG do EPEL...\"\n        curl -sL https://dl.fedoraproject.org/pub/epel/RPM-GPG-KEY-EPEL-9 \\\n            -o /etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9 2>/dev/null && \\\n            log_ok \"Chave GPG EPEL-9 baixada.\"\n    }\nfi\n\n###############################################################################\n# Desabilita plugins quebrados (ulninfo, spacewalk)\n###############################################################################\nfor PLUGIN in ulninfo spacewalk; do\n    CONF=\"/etc/dnf/plugins/${PLUGIN}.conf\"\n    if [[ -f \"$CONF\" ]]; then\n        if grep -qi \"^enabled\" \"$CONF\" 2>/dev/null; then\n            sed -i 's/^enabled.*/enabled=0/' \"$CONF\"\n        else\n            echo \"enabled=0\" >> \"$CONF\"\n        fi\n        log_ok \"Plugin '$PLUGIN' desabilitado em: $CONF\"\n    fi\ndone\n\n# Fallback: caso os .conf n\u00e3o existam, cria um disable via drop-in\nfor PLUGIN in ulninfo spacewalk; do\n    CONF=\"/etc/dnf/plugins/${PLUGIN}.conf\"\n    if [[ ! -f \"$CONF\" ]]; then\n        mkdir -p /etc/dnf/plugins\n        cat > \"$CONF\" << 'EOF'\n[main]\nenabled=0\nEOF\n        log_ok \"Plugin '$PLUGIN' desabilitado (conf criado do zero).\"\n    fi\ndone\n\n###############################################################################\n# Remove caches inv\u00e1lidos do DNF\n###############################################################################\nlog_info \"Limpando cache do DNF...\"\ndnf clean all 2>/dev/null || true\n\n###############################################################################\n# Testa os reposit\u00f3rios\n###############################################################################\nlog_info \"Testando conectividade dos reposit\u00f3rios...\"\ndnf repolist 2>&1 | grep -E \"^ol9_|^epel\" || true\n\nlog_info \"\"\nlog_ok \"Script conclu\u00eddo!\"\nlog_info \"Reposit\u00f3rios configurados e prontos para uso.\"\nlog_info \"Backup dispon\u00edvel em: $BACKUP_DIR\"\nlog_info \"\"\nlog_info \"Para testar a instala\u00e7\u00e3o de um pacote, execute:\"\nlog_info \"  dnf install -y <pacote>\"\n", "system_scripts/gerar_iso.sh": " #!/bin/bash\n\n# Este script configura reposit\u00f3rios adicionais no Oracle Linux 10 (OL10)\n\necho \"--- 1. Verificando Reposit\u00f3rios Oficiais da Oracle (OL10) ---\"\n\n# Os reposit\u00f3rios ol10_baseos_latest, ol10_appstream e ol10_UEKR8\n# s\u00e3o geralmente habilitados por padr\u00e3o no Oracle Linux.\n# O CodeReady Builder (necess\u00e1rio para depend\u00eancias do RPM Fusion) precisa ser habilitado:\necho \"Habilitando o reposit\u00f3rio CodeReady Builder (ol10_codeready_builder)...\"\nsudo dnf config-manager --enable ol10_codeready_builder\n\n# Atualiza o \u00edndice de pacotes\nsudo dnf check-update\n\necho \"\"\necho \"--- 2. Adicionando Reposit\u00f3rio EPEL (Extra Packages for Enterprise Linux) ---\"\n\n# Instala o pacote de release do EPEL para a vers\u00e3o 10 do Enterprise Linux (EL10)\n# que \u00e9 o upstream do Oracle Linux.\necho \"Instalando o pacote epel-release para EL10...\"\nsudo dnf install -y https://dl.fedoraproject.org/pub/epel/epel-release-latest-10.noarch.rpm\n\n# Habilita o reposit\u00f3rio EPEL mantido pela Oracle, que espelha o EPEL oficial.\n# O pacote acima pode j\u00e1 ter feito isso, mas este comando garante a ativa\u00e7\u00e3o.\necho \"Garantindo que o reposit\u00f3rio EPEL da Oracle esteja habilitado (ol10_developer_EPEL)...\"\nsudo dnf config-manager --enable ol10_developer_EPEL\n\necho \"\"\necho \"--- 3. Adicionando Reposit\u00f3rios RPM Fusion (Free e Non-free) ---\"\n\n# O RPM Fusion usa a vers\u00e3o principal do RHEL (10) para encontrar o RPM correto.\n# A vari\u00e1vel $(rpm -E %rhel) resolve para '10'.\necho \"Instalando RPM Fusion Free e Non-free para EL10...\"\nsudo dnf install -y --nogpgcheck \\\n  https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-$(rpm -E %rhel).noarch.rpm \\\n  https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-$(rpm -E %rhel).noarch.rpm\n\necho \"\"\necho \"--- 4. Conclus\u00e3o e Limpeza ---\"\n\n# Limpa o cache do DNF e verifica a lista de reposit\u00f3rios ativados.\necho \"Limpando o cache do DNF e listando reposit\u00f3rios habilitados...\"\nsudo dnf clean all\nsudo dnf repolist\n\necho \"\"\necho \"Configura\u00e7\u00e3o de reposit\u00f3rios conclu\u00edda no Oracle Linux 10!\"\necho \"Execute 'sudo dnf upgrade' para atualizar o sistema com os novos pacotes.\"\n", "system_scripts/gerar_iso_ol10.sh": " #!/bin/bash\nset -e\n\n# ==============================================================================\n# CONFIGURA\u00c7\u00d5ES GLOBAIS\n# ==============================================================================\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" &>/dev/null && pwd)\"\ncd \"$SCRIPT_DIR\"\n\nDATA=$(date +%Y-%m-%d)\nISO_BASE=\"OracleLinux-R10-U0-x86_64-dvd.iso\" \nOUTPUT_ISO=\"OracleLinux-10.1-hibrido-custom-${DATA}.iso\" \nSOFTWARE_DIR=\"software_rpm\"\nFAVORITOS_DIR=\"favoritos\"\nKS_FILE=\"ks.cfg\"\nVOL_ID=\"OL10CUSTOM\" \n\n# Diret\u00f3rios tempor\u00e1rios\nMOUNT_DIR=$(mktemp -d -t ol-mnt-XXXXXXXXXX)\nEXTRACT_DIR=$(mktemp -d -t ol-extract-XXXXXXXXXX)\n# ... (Resto dos diret\u00f3rios)\n\n# Depend\u00eancias necess\u00e1rias para a m\u00e1quina host\nREQUIRED_PACKAGES=(\"rsync\" \"createrepo_c\" \"xorriso\" \"syslinux\" \"grub2-tools\" \"mtools\")\n\n# ==============================================================================\n# FUN\u00c7\u00d5ES DE LOG\n# ==============================================================================\nSTEP=0\nTOTAL_STEPS=9 # Reintroduzimos o passo de verifica\u00e7\u00e3o/download\n\nlog_step() { STEP=$((STEP+1)); echo -e \"\\n[\\e[1;34m${STEP}/${TOTAL_STEPS}\\e[0m] \ud83d\ude80 $1\"; }\nlog_info() { echo -e \"    \u279c $1\"; }\nlog_done() { echo -e \"    \u2705 $1\"; }\nlog_error() { echo -e \"    \u274c \\e[1;31mERRO: $1\\e[0m\" >&2; exit 1; }\n\n# ==============================================================================\n# FUN\u00c7\u00d5ES DE AMBIENTE E LIMPEZA\n# ==============================================================================\n\nsetup() {\n    log_step \"Preparando ambiente e verificando depend\u00eancias...\"\n    \n    if [ ! -f \"$ISO_BASE\" ]; then\n        log_error \"Arquivo de ISO base n\u00e3o encontrado: $ISO_BASE. Baixe a ISO e coloque-a no mesmo diret\u00f3rio do script.\"\n    fi\n\n    local missing=()\n    for pkg in \"${REQUIRED_PACKAGES[@]}\"; do\n        if ! rpm -q \"$pkg\" &>/dev/null; then\n            missing+=(\"$pkg\")\n        fi\n    done\n\n    if [ ${#missing[@]} -gt 0 ]; then\n        log_info \"Instalando depend\u00eancias: ${missing[*]}\"\n        sudo dnf install -y \"${missing[@]}\" || log_error \"Falha na instala\u00e7\u00e3o de depend\u00eancias.\"\n    fi\n    log_done \"Ambiente e depend\u00eancias OK.\"\n}\n\ncleanup() {\n    log_info \"Limpando arquivos tempor\u00e1rios...\"\n    if mountpoint -q \"$MOUNT_DIR\" &>/dev/null; then\n        sudo umount \"$MOUNT_DIR\"\n    fi\n    rm -rf \"$MOUNT_DIR\" \"$EXTRACT_DIR\"\n    log_done \"Limpeza conclu\u00edda.\"\n}\n\n# ==============================================================================\n# KICKSTART (KS.CFG)\n# ==============================================================================\n\ngenerate_kickstart() {\n    log_step \"Gerando arquivo Kickstart (ks.cfg)...\"\n    cat > \"$KS_FILE\" <<'EOF'\n#version=RHEL10\ninstall\ncdrom\nlang pt_BR.UTF-8\nkeyboard br-abnt2\ntimezone America/Sao_Paulo --isUtc\nrootpw --plaintext oracle\nuser --name=user --password=oracle --plaintext --groups=wheel\nfirewall --enabled\nselinux --enforcing\nnetwork --bootproto=dhcp --device=link --activate\nbootloader --location=mbr\nautopart --type=lvm\nreboot\n\n%packages\n@^minimal-environment\n@core\n# Adicione outros grupos ou pacotes se o download condicional nao for suficiente.\n%end\n\n%post --log=/root/post-install.log\necho \"--- Iniciando script post-install customizado ---\"\n\n# Repositorios extras (requerem internet na maquina alvo)\necho \"Instalando reposit\u00f3rios extras (EPEL, RPM Fusion) - REQUER INTERNET...\"\ndnf install -y oraclelinux-release-epl\ndnf install -y https://download.fedoraproject.org/pub/epel/epel-release-latest-10.noarch.rpm\ndnf install -y https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-10.noarch.rpm https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-10.noarch.rpm\n\n# Copia arquivos favoritos\necho \"Copiando arquivos de favoritos...\"\nmkdir -p /home/user/favoritos\ncp -r /mnt/favoritos/* /home/user/favoritos/ || true\nchown -R user:user /home/user/favoritos\n\n# Copia software RPM (localizado fora do repo principal)\necho \"Copiando software RPM personalizado...\"\nmkdir -p /home/user/software_rpm\ncp -r /mnt/software_rpm/* /home/user/software_rpm/ || true\nchown -R user:user /home/user/software_rpm\necho \"--- Script post-install conclu\u00eddo ---\"\n%end\nEOF\n    log_done \"Kickstart criado em $KS_FILE.\"\n}\n\n# ==============================================================================\n# PREPARA\u00c7\u00c3O DO REPOSIT\u00d3RIO E ARQUIVOS\n# ==============================================================================\n\nmount_and_extract_iso() {\n    log_step \"Montando e extraindo ISO base...\"\n    sudo mount -o loop \"$ISO_BASE\" \"$MOUNT_DIR\" || log_error \"Falha ao montar ISO base.\"\n\n    log_info \"Copiando **todos** os arquivos da ISO base para extra\u00e7\u00e3o em $EXTRACT_DIR...\"\n    rsync -a \"$MOUNT_DIR\"/ \"$EXTRACT_DIR\"/\n    \n    log_info \"Movendo pacotes BaseOS/Packages para o diret\u00f3rio de reposit\u00f3rio customizado (/repo/Packages)...\"\n    local TARGET_PACKAGES_DIR=\"$EXTRACT_DIR/repo/Packages\"\n    mkdir -p \"$TARGET_PACKAGES_DIR\"\n    \n    # Move todos os RPMs da BaseOS/Packages para o novo local\n    rsync -a \"$EXTRACT_DIR/BaseOS/Packages/\" \"$TARGET_PACKAGES_DIR/\"\n    \n    # Remove BaseOS/AppStream/Packages originais para evitar conflito\n    rm -rf \"$EXTRACT_DIR/BaseOS\" \"$EXTRACT_DIR/AppStream\"\n\n    # Desmonta a ISO, a partir de agora todos os passos usam $EXTRACT_DIR\n    sudo umount \"$MOUNT_DIR\"\n    log_done \"Arquivos da ISO base copiados e ISO desmontada com sucesso.\"\n}\n\nensure_essential_packages() {\n    log_step \"Verificando e baixando depend\u00eancias essenciais (se faltarem na ISO)...\"\n    \n    local TARGET_PACKAGES_DIR=\"$EXTRACT_DIR/repo/Packages\"\n    \n    # Os pacotes que devem ser garantidos para evitar falhas no kickstart minimal\n    local ESSENTIAL_PACKAGES=(\"@minimal-environment\" \"@core\" \"kernel-uek\" \"dracut-config-generic\") \n\n    log_info \"Tentando baixar pacotes essenciais (e depend\u00eancias) para: ${ESSENTIAL_PACKAGES[*]}\"\n    log_info \"Se o pacote j\u00e1 existir, ele ser\u00e1 ignorado.\"\n\n    # O DNF tenta baixar pacotes (e suas depend\u00eancias) que N\u00c3O EST\u00c3O instalados no --installroot.\n    # Como o --installroot \u00e9 um diret\u00f3rio de disco real, o erro de 'rpmdb open failed' \u00e9 evitado.\n    # O --installroot usa os pacotes de $TARGET_PACKAGES_DIR como base para resolver depend\u00eancias.\n    sudo dnf download \\\n        --installroot=\"$TARGET_PACKAGES_DIR\" \\\n        --downloaddir=\"$TARGET_PACKAGES_DIR\" \\\n        --resolve \\\n        --allowerasing \\\n        --nobest \\\n        \"${ESSENTIAL_PACKAGES[@]}\" || log_error \"Falha ao baixar pacotes essenciais. Verifique a conectividade e os reposit\u00f3rios da sua m\u00e1quina host.\"\n\n    log_done \"Verifica\u00e7\u00e3o de pacotes conclu\u00edda. Arquivos adicionais baixados (se necess\u00e1rio).\"\n}\n\ncreate_offline_repo() {\n    log_step \"Criando metadados (repodata) para o reposit\u00f3rio customizado...\"\n    \n    local TARGET_PACKAGES_DIR=\"$EXTRACT_DIR/repo/Packages\"\n    \n    if [ -d \"$SOFTWARE_DIR\" ] && [ \"$(ls -A $SOFTWARE_DIR)\" ]; then\n        log_info \"Adicionando pacotes RPM personalizados de $SOFTWARE_DIR...\"\n        cp \"$SOFTWARE_DIR\"/*.rpm \"$TARGET_PACKAGES_DIR/\" || true\n    else\n        log_info \"Nenhum pacote RPM personalizado encontrado para adicionar.\"\n    fi\n\n    log_info \"Gerando metadados do reposit\u00f3rio (repodata) em $EXTRACT_DIR/repo...\"\n    createrepo_c \"$EXTRACT_DIR/repo\"\n    log_done \"Reposit\u00f3rio offline criado e atualizado.\"\n}\n\nadd_custom_files() {\n    log_step \"Adicionando arquivos personalizados (Favoritos e RPMs) para a m\u00eddia...\"\n    \n    if [ -d \"$FAVORITOS_DIR\" ] && [ \"$(ls -A $FAVORITOS_DIR)\" ]; then\n        mkdir -p \"$EXTRACT_DIR/$FAVORITOS_DIR\"\n        cp -r \"$FAVORITOS_DIR\"/* \"$EXTRACT_DIR/$FAVORITOS_DIR/\"\n        log_info \"Arquivos de favoritos adicionados.\"\n    else\n        log_info \"Nenhum arquivo de favoritos encontrado.\"\n    fi\n\n    if [ -d \"$SOFTWARE_DIR\" ] && [ \"$(ls -A $SOFTWARE_DIR)\" ]; then\n        mkdir -p \"$EXTRACT_DIR/$SOFTWARE_DIR\"\n        log_info \"Diret\u00f3rio de software RPM adicionado (para acesso f\u00e1cil p\u00f3s-instala\u00e7\u00e3o).\"\n    else\n        log_info \"Nenhum diret\u00f3rio de software RPM encontrado.\"\n    fi\n}\n\n# ==============================================================================\n# CONFIGURA\u00c7\u00c3O DE BOOT (UEFI/MBR e MENU GRUB)\n# ==============================================================================\n\nconfigure_bootloaders() {\n    log_step \"Configurando GRUB2 para BIOS e UEFI...\"\n    \n    log_info \"Criando estrutura de diret\u00f3rios para boot...\"\n\n    # Configura arquivos UEFI/EFI\n    mkdir -p \"$EFI_DIR\"\n    \n    # Configura arquivos BIOS/ISOLINUX\n    mkdir -p \"$ISOLINUX_DIR\"\n    \n    # ----------------------------------------------------------------------\n    # grub.cfg para BIOS\n    # ----------------------------------------------------------------------\n    mkdir -p \"$EXTRACT_DIR/boot/grub\"\n    cat > \"$EXTRACT_DIR/boot/grub/grub.cfg\" <<EOF\nset timeout=10\nset default=0\n\nmenuentry \"1. Instalar Oracle Linux 10 (Modo Grafico/Manual)\" {\n    # Inicia o instalador grafico (Anaconda).\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID\n    initrd /images/pxeboot/initrd.img\n}\n\nmenuentry \"2. Instalacao Automatizada (Kickstart)\" {\n    # Inicia a instalacao automatica usando o ks.cfg.\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID inst.ks=cdrom:/ks.cfg\n    initrd /images/pxeboot/initrd.img\n}\n\nmenuentry \"3. Troubleshooting\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID inst.expert\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n    # ----------------------------------------------------------------------\n    # grub.cfg para UEFI\n    # ----------------------------------------------------------------------\n    cat > \"$EFI_DIR/grub.cfg\" <<EOF\nset timeout=10\nset default=0\n\nmenuentry \"1. Instalar Oracle Linux 10 (Modo Grafico/Manual)\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID\n    initrd /images/pxeboot/initrd.img\n}\n\nmenuentry \"2. Instalacao Automatizada (Kickstart)\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID inst.ks=cdrom:/ks.cfg\n    initrd /images/pxeboot/initrd.img\n}\n\nmenuentry \"3. Troubleshooting\" {\n    linux /images/pxeboot/vmlinuz inst.stage2=hd:LABEL=$VOL_ID inst.expert\n    initrd /images/pxeboot/initrd.img\n}\nEOF\n\n    cp \"$KS_FILE\" \"$EXTRACT_DIR/\"\n    log_done \"Bootloaders configurados. Volume ID: $VOL_ID\"\n}\n\n# ==============================================================================\n# GERA\u00c7\u00c3O DA ISO\n# ==============================================================================\n\ngenerate_iso() {\n    log_step \"Gerando ISO h\u00edbrida...\"\n    # xorriso -volid usa o r\u00f3tulo necess\u00e1rio para o bootloader (OL10CUSTOM)\n    # Assumimos que o isohdpfx.bin padr\u00e3o do syslinux \u00e9 suficiente.\n    xorriso -as mkisofs \\\n        -o \"$OUTPUT_ISO\" \\\n        -volid \"$VOL_ID\" \\\n        -isohybrid-mbr /usr/share/syslinux/isohdpfx.bin \\\n        -c isolinux/boot.cat \\\n        -b isolinux/isolinux.bin \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        -boot-info-table \\\n        -eltorito-alt-boot \\\n        -e EFI/BOOT/BOOTX64.EFI \\\n        -no-emul-boot \\\n        \"$EXTRACT_DIR\" || log_error \"Falha ao gerar a ISO.\"\n    log_done \"ISO criada com sucesso: $OUTPUT_ISO\"\n}\n\nfinalize() {\n    log_step \"Processo conclu\u00eddo.\"\n    ISO_SIZE=$(du -h \"$OUTPUT_ISO\" | awk '{print $1}')\n    log_done \"ISO personalizada pronta: $OUTPUT_ISO\"\n    log_done \"Tamanho da imagem: $ISO_SIZE\"\n    echo \"--------------------------------------------------------\"\n    echo \"A ISO \u00e9 robusta: pacotes essenciais foram verificados/baixados.\"\n    echo \"A configuracao de repositorios extras (EPEL/Fusion)\"\n    echo \"no Kickstart requer conexao de internet durante a instalacao.\"\n    echo \"--------------------------------------------------------\"\n}\n\n# ==============================================================================\n# FLUXO PRINCIPAL\n# ==============================================================================\ntrap cleanup EXIT\n\nsetup\ngenerate_kickstart\nmount_and_extract_iso # Monta, copia TUDO e desmonta\nensure_essential_packages # Baixa pacotes faltantes do Oracle Linux 10\ncreate_offline_repo\nadd_custom_files\nconfigure_bootloaders # Trabalha apenas com arquivos extra\u00eddos\ngenerate_iso\nfinalize\n", "system_scripts/gerar_iso_ol9.sh": " #!/bin/bash\n# ----------------------------------------------------\n# SCRIPT DE CRIA\u00c7\u00c3O DE ISO H\u00cdBRIDA OL 9.6: CLONE COM SQUASHFS E REPOSIT\u00d3RIOS\n# OBJETIVO: Criar uma ISO Live/Restore a partir do sistema atual (SquashFS)\n# \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0incluindo pacotes e reposit\u00f3rios extras em um Tarball de Dados.\n# ----------------------------------------------------\n\n# Define a cor verde para mensagens de sucesso e informativo\nGREEN='\\033[0;32m'\nRED='\\033[0;31m'\nNC='\\033[0m' # No Color\n\n# ====================================================\n# 1. CONFIGURA\u00c7\u00c3O GLOBAL (AJUSTE AQUI)\n# ====================================================\nISO_WORK_DIR=\"/tmp/custom_ol_iso\"\nLIVE_ROOT_DIR=\"${ISO_WORK_DIR}/LiveOS\"\nDATA_ROOT_DIR=\"${ISO_WORK_DIR}/install_data\"\nVOLUME_ID=\"OL9_CUSTOM_LIVE\"\n\n# --- Nomes de Arquivos ---\nSQUASHFS_FILE=\"squashfs.img\"\nDATA_TARBALL=\"ol_data.tar.gz\"\n\n# --- Caminhos de Origem/Destino ---\nCUSTOM_RPM_SOURCE=\"software_rpm\" \nCUSTOM_FILES_SOURCE=\"favoritos\" \nCUSTOM_RPM_DEST=\"/opt/custom_data/software_rpm\"\nCUSTOM_FILES_DEST=\"/opt/custom_data/files\"\n\n# --- Caminhos de Ferramentas e Boot ---\nISOHYBRID_MBR_FILE=\"/usr/share/syslinux/isohdpfx.bin\"\nGRUB_EFI_BOOTLOADER=\"/boot/efi/EFI/ol/grubx64.efi\"\n\n# --- Sa\u00edda Final ---\nDATE_TAG=$(date +%Y%m%d_%H%M)\nOUTPUT_ISO_NAME=\"Oracle_Linux_9.6_Custom_Live_${DATE_TAG}.iso\"\n\n# Lista de diret\u00f3rios/arquivos a excluir do backup do sistema raiz (SquashFS)\n# O '*' \u00e9 crucial para excluir todos os subdiret\u00f3rios de /home\nEXCLUDES=(\n    /proc/* /sys/* /dev/* /run/* /proc/kcore /proc/iomem\n    /mnt/* /tmp/* /media/* /lost+found\n    /boot/* /var/cache/*\n    /home/* # <--- INCLUS\u00c3O DA EXCLUS\u00c3O DA PASTA /HOME\n    ${ISO_WORK_DIR}/* )\n\n# ====================================================\n# 2. FUN\u00c7\u00d5ES DE VERIFICA\u00c7\u00c3O E LIMPEZA (CORRIGIDO AQUI)\n# ====================================================\n\ncheck_dependencies() {\n    echo -e \"${GREEN}Verificando depend\u00eancias essenciais: xorriso, mksquashfs, dracut...${NC}\"\n    local dependencies=\"xorriso mksquashfs dracut tar cp date ls bash grub2-install\"\n    local missing=0\n\n    for dep in $dependencies; do\n        if ! command -v $dep &> /dev/null; then\n            echo -e \"${RED}ERRO: Depend\u00eancia '$dep' n\u00e3o encontrada. Instale-a via DNF.${NC}\"\n            missing=1\n        fi\n    done\n\n    # === NOVO CHECK E INSTALA\u00c7\u00c3O DE M\u00d3DULO LIVE DO DRACUT ===\n    echo -e \"\\n${GREEN}Verificando m\u00f3dulo 'live' do dracut (pacote dracut-live)...${NC}\"\n    if ! dnf list installed dracut-live &> /dev/null; then\n        echo -e \"${RED}PACOTE AUSENTE: 'dracut-live' \u00e9 necess\u00e1rio para o boot Live. (Causa do erro anterior).${NC}\"\n        echo -e \"Tentando instalar 'dracut-live' via DNF...\"\n        # Tenta instalar o pacote. 'sudo' \u00e9 necess\u00e1rio, assumindo que o usu\u00e1rio tem permiss\u00e3o.\n        sudo dnf install -y dracut-live\n        \n        if [ $? -ne 0 ]; then\n            echo -e \"${RED}ERRO FATAL: Falha ao instalar 'dracut-live'. Verifique os reposit\u00f3rios ou permiss\u00f5es sudo.${NC}\"\n            missing=1\n        else\n            echo -e \"${GREEN}Pacote 'dracut-live' instalado com sucesso.${NC}\"\n        fi\n    else\n        echo -e \"${GREEN}Pacote 'dracut-live' j\u00e1 instalado. OK.${NC}\"\n    fi\n    # =========================================================\n    \n    if [ ! -f \"$ISOHYBRID_MBR_FILE\" ]; then\n        echo -e \"${RED}ERRO: Arquivo MBR (${ISOHYBRID_MBR_FILE}) n\u00e3o encontrado. Instale 'syslinux-nonboot'.${NC}\"\n        missing=1\n    fi\n    \n    if [ $missing -ne 0 ]; then\n        echo -e \"\\n${RED}Existem depend\u00eancias ausentes ou falha na instala\u00e7\u00e3o. Por favor, corrija o problema e execute novamente.${NC}\"\n        exit 1\n    fi\n    echo -e \"\\n${GREEN}Todas as depend\u00eancias (incluindo 'dracut-live') OK.${NC}\"\n}\n\nprepare_environment() {\n    echo -e \"\\n--- 1/6. PREPARA\u00c7\u00c3O E LIMPEZA DE AMBIENTE ---\"\n    if [ -d \"${ISO_WORK_DIR}\" ]; then\n        echo \"Limpando diret\u00f3rio de trabalho antigo: ${ISO_WORK_DIR}\"\n        rm -rf \"${ISO_WORK_DIR}\"\n    fi\n    echo \"Criando nova estrutura de trabalho b\u00e1sica...\"\n    mkdir -p \"${LIVE_ROOT_DIR}\"\n    mkdir -p \"${DATA_ROOT_DIR}\"\n    mkdir -p \"${ISO_WORK_DIR}/boot/grub\"\n    mkdir -p \"${ISO_WORK_DIR}/EFI/BOOT\"\n    mkdir -p \"${ISO_WORK_DIR}/etc\"\n    echo -e \"${GREEN}Estrutura de diret\u00f3rios criada com sucesso.${NC}\"\n}\n\n# ====================================================\n# 3. FASE DE CLONAGEM (SQUASHFS)\n# ====================================================\n\ncreate_squashfs() {\n    echo -e \"\\n--- 2/6. CLONAGEM DO SISTEMA EM SQUASHFS ---\"\n    echo \"Iniciando compacta\u00e7\u00e3o do sistema raiz (/) em ${SQUASHFS_FILE}...\"\n    echo \"Usando compress\u00e3o XZ e excluindo diret\u00f3rios virtuais, caches e A PASTA HOME.\"\n\n    # Comando corrigido: o argumento de exclus\u00e3o (-e) \u00e9 posicional\n    mksquashfs / \"${LIVE_ROOT_DIR}/${SQUASHFS_FILE}\" -comp xz -e \"${EXCLUDES[@]}\"\n\n    if [ $? -ne 0 ]; then\n        echo -e \"${RED}ERRO: Falha ao criar a imagem SquashFS. Verifique os logs do mksquashfs.${NC}\"\n        exit 1\n    fi\n    echo -e \"${GREEN}Imagem SquashFS (${SQUASHFS_FILE}) criada com sucesso.${NC}\"\n}\n\n# ====================================================\n# 4. FASE DE DADOS E REPOSIT\u00d3RIOS\n# ====================================================\n\ncreate_data_tarball() {\n    echo -e \"\\n--- 3/6. CONFIGURA\u00c7\u00c3O DE REPOSIT\u00d3RIOS E TARBALL DE DADOS ---\"\n\n    # 4.1. Criar Arquivo de Reposit\u00f3rio (OL 9.x)\n    local REPO_FILE=\"${ISO_WORK_DIR}/etc/ol_custom_repos.repo\"\n    echo \"-> Criando arquivo de reposit\u00f3rio '$REPO_FILE' com URLs do OL/EL 9.\"\n    \n    cat << EOF_REPO > \"$REPO_FILE\"\n# Reposit\u00f3rios para o Ambiente Live/Instala\u00e7\u00e3o (Oracle Linux 9.x)\n[ol_custom_rpms]\nname=Custom RPMs (Local)\nbaseurl=file://${CUSTOM_RPM_DEST}\nenabled=1\ngpgcheck=0\n\n[ol_appstream]\nname=Oracle Linux 9 AppStream\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/x86_64/\nenabled=1\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\n\n[epel]\nname=Extra Packages for Enterprise Linux 9 - \\$basearch\nbaseurl=https://download.fedoraproject.org/pub/epel/9/Everything/\\$basearch\nenabled=1\ngpgcheck=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\n\n[rpmfusion-free]\nname=RPM Fusion for EL 9 - Free - \\$basearch\nbaseurl=http://download1.rpmfusion.org/free/el/9/Everything/\\$basearch/os/\nenabled=1\ngpgcheck=0\nEOF_REPO\n\n    # Copiar o arquivo de reposit\u00f3rio e chaves GPG (assumindo que existam no host)\n    mkdir -p \"${DATA_ROOT_DIR}/etc/yum.repos.d\"\n    cp \"$REPO_FILE\" \"${DATA_ROOT_DIR}/etc/yum.repos.d/ol_custom_repos.repo\"\n    \n    # 4.2. Preparar Conte\u00fado\n    echo \"-> Copiando pacotes RPMs de '$CUSTOM_RPM_SOURCE' para inclus\u00e3o...\"\n    mkdir -p \"${DATA_ROOT_DIR}${CUSTOM_RPM_DEST}\"\n    if [ -d \"$CUSTOM_RPM_SOURCE\" ]; then\n        cp -rv \"$CUSTOM_RPM_SOURCE\"/* \"${DATA_ROOT_DIR}${CUSTOM_RPM_DEST}/\"\n    else\n        echo \"    AVISO: Diret\u00f3rio de RPMs (${CUSTOM_RPM_SOURCE}) n\u00e3o encontrado.\"\n    fi\n\n    echo \"-> Copiando arquivos de p\u00f3s-instala\u00e7\u00e3o de '$CUSTOM_FILES_SOURCE'...\"\n    mkdir -p \"${DATA_ROOT_DIR}${CUSTOM_FILES_DEST}\"\n    if [ -d \"$CUSTOM_FILES_SOURCE\" ]; then\n        cp -rv \"$CUSTOM_FILES_SOURCE\"/* \"${DATA_ROOT_DIR}${CUSTOM_FILES_DEST}/\"\n    else\n        echo \"    AVISO: Diret\u00f3rio de arquivos extras (${CUSTOM_FILES_SOURCE}) n\u00e3o encontrado.\"\n    fi\n\n    # 4.3. Criar o Tarball de Dados\n    echo \"-> Criando tarball de dados ${DATA_TARBALL} na raiz da ISO.\"\n    tar -czvf \"${ISO_WORK_DIR}/${DATA_TARBALL}\" -C \"${DATA_ROOT_DIR}\" .\n    echo -e \"${GREEN}Tarball de dados criado com sucesso: ${ISO_WORK_DIR}/${DATA_TARBALL}${NC}\"\n}\n\n# ====================================================\n# 5. FASE DE BOOT E DRACUT\n# ====================================================\n\nconfigure_boot() {\n    echo -e \"\\n--- 4/6. CONFIGURA\u00c7\u00c3O DE BOOT (Kernel, Initramfs e GRUB) ---\"\n    CURRENT_KERNEL_VERSION=$(uname -r)\n    KERNEL=\"/boot/vmlinuz-${CURRENT_KERNEL_VERSION}\"\n\n    # 5.1. Copiar Kernel e Initramfs (do sistema atual)\n    echo \"-> Kernel do sistema (v. ${CURRENT_KERNEL_VERSION}) ser\u00e1 usado para o boot Live.\"\n    if [ ! -f \"$KERNEL\" ]; then\n        echo -e \"${RED}ERRO: Kernel (${KERNEL}) n\u00e3o encontrado. Abortando.${NC}\"\n        exit 1\n    fi\n    cp \"$KERNEL\" \"${ISO_WORK_DIR}/boot/vmlinuz\"\n\n    # 5.2. Gerar Initramfs Customizado com Suporte a Live/SquashFS\n    CUSTOM_INITRAMFS=\"${ISO_WORK_DIR}/boot/initrd.img\"\n    echo \"-> Gerando novo Initramfs customizado com m\u00f3dulo 'live' via dracut...\"\n    \n    # Esta linha agora deve funcionar, pois 'dracut-live' foi verificado/instalado.\n    dracut --force --no-host-only --add \"live\" \"$CUSTOM_INITRAMFS\" \"$CURRENT_KERNEL_VERSION\"\n\n    if [ $? -ne 0 ]; then\n        echo -e \"${RED}ERRO: Falha ao gerar o initramfs com dracut. O boot Live falhar\u00e1.${NC}\"\n        exit 1\n    fi\n    echo -e \"${GREEN}Initramfs com suporte Live gerado com sucesso.${NC}\"\n\n    # 5.3. Configura\u00e7\u00e3o do GRUB e Bootloader EFI\n    echo \"-> Copiando bootloader EFI e configurando GRUB...\"\n    if [ -f \"$GRUB_EFI_BOOTLOADER\" ]; then\n        cp \"$GRUB_EFI_BOOTLOADER\" \"${ISO_WORK_DIR}/EFI/BOOT/grubx64.efi\"\n    else\n        echo \"    AVISO: Bootloader EFI (${GRUB_EFI_BOOTLOADER}) n\u00e3o encontrado. Boot UEFI pode falhar.\"\n    fi\n\n    # Criar o Arquivo de Configura\u00e7\u00e3o do GRUB\n    local BOOT_DIR=\"${ISO_WORK_DIR}/boot\"\n    cat << EOF_GRUB_LIVE > \"$BOOT_DIR/grub/grub.cfg\"\nset default=\"0\"\nset timeout=10\n\nmenuentry \"Oracle Linux 9.6 Live & Restore (Live) [Volume ID: ${VOLUME_ID}]\" {\n    linux /boot/vmlinuz rd.live.image root=live:LABEL=${VOLUME_ID} rootfstype=auto ro quiet splash\n    initrd /boot/initrd.img\n}\nEOF_GRUB_LIVE\n\n    # Usar o mesmo grub.cfg para o boot UEFI\n    cp \"$BOOT_DIR/grub/grub.cfg\" \"${ISO_WORK_DIR}/EFI/BOOT/grub.cfg\"\n    echo -e \"${GREEN}Configura\u00e7\u00e3o de boot GRUB finalizada.${NC}\"\n}\n\n# ====================================================\n# 6. FASE DE SCRIPT DE SETUP\n# ====================================================\n\ncreate_setup_script() {\n    echo -e \"\\n--- 5/6. CRIA\u00c7\u00c3O DO SCRIPT DE CONFIGURA\u00c7\u00c3O (initial_setup.sh) ---\"\n    local SETUP_SCRIPT_PATH=\"${ISO_WORK_DIR}/initial_setup.sh\"\n\n    # O script assume que o DATA_TARBALL est\u00e1 na raiz da ISO montada.\n    cat << EOF_SETUP > \"$SETUP_SCRIPT_PATH\"\n#!/bin/bash\n# Script de Configura\u00e7\u00e3o Inicial (Execute DENTRO DO AMBIENTE LIVE)\n\nDATA_TARBALL_PATH=\"/${DATA_TARBALL}\"\n\necho \"--- IN\u00cdCIO DO SCRIPT DE CONFIGURA\u00c7\u00c3O CUSTOMIZADO ---\"\n\nif [ ! -f \"\\$DATA_TARBALL_PATH\" ]; then\n    echo \"ERRO: O arquivo de dados (\\$DATA_TARBALL_PATH) n\u00e3o foi encontrado na raiz da ISO.\"\n    echo \"PASSO 1 FALHOU: Certifique-se de que a ISO foi montada corretamente.\"\n    exit 1\nfi\n\n# 1. Extrair Dados (RPMs, Scripts, Reposit\u00f3rios)\necho \"PASSO 2: Extraindo dados extras para /tmp/live_data...\"\nmkdir -p /tmp/live_data\ntar -xzvpf \"\\$DATA_TARBALL_PATH\" -C /tmp/live_data\n\n# 2. Copiar Arquivo de Reposit\u00f3rio e Linkar Reposit\u00f3rio Local\necho \"PASSO 3: Copiando reposit\u00f3rios e montando o diret\u00f3rio de dados local...\"\ncp -rv /tmp/live_data/etc/yum.repos.d/* /etc/yum.repos.d/\nmkdir -p /opt/custom_data\n# Monta o diret\u00f3rio de dados extra\u00eddos no caminho que o reposit\u00f3rio local espera\nmount --bind /tmp/live_data/install_data/opt/custom_data /opt/custom_data\n\n# 3. Instala\u00e7\u00e3o de Pacotes Customizados\necho \"PASSO 4: Instalando pacotes RPMs customizados via DNF...\"\n# Instala pacotes do reposit\u00f3rio customizado, re-habilitando reposit\u00f3rios oficiais importantes\ndnf clean all\ndnf install -y /opt/custom_data/software_rpm/*.rpm --disablerepo=\\* --enablerepo=ol_custom_rpms,ol_appstream,epel,rpmfusion-free\n\n# 4. Executar Scripts de P\u00f3s-Instala\u00e7\u00e3o\necho \"PASSO 5: Executando scripts de p\u00f3s-instala\u00e7\u00e3o...\"\nSCRIPTS_DIR=\"/opt/custom_data/files/scripts\"\nif [ -d \"\\$SCRIPTS_DIR\" ]; then\n    find \"\\$SCRIPTS_DIR\" -type f -executable -print -exec {} \\;\nfi\n\n# 5. Limpar e Finalizar\necho \"PASSO 6: Limpando montagens tempor\u00e1rias...\"\numount /opt/custom_data\nrm -rf /tmp/live_data\necho \"Configura\u00e7\u00e3o inicial conclu\u00edda. O ambiente Live est\u00e1 pronto.\"\nEOF_SETUP\n\n    chmod +x \"$SETUP_SCRIPT_PATH\"\n    echo -e \"${GREEN}Script de setup '$SETUP_SCRIPT_PATH' criado e pronto para uso no Live CD.${NC}\"\n}\n\n# ====================================================\n# 7. FASE DE GERA\u00c7\u00c3O DA ISO\n# ====================================================\n\ngenerate_iso() {\n    echo -e \"\\n--- 6/6. GERA\u00c7\u00c3O DA IMAGEM ISO H\u00cdBRIDA ---\"\n    echo \"Iniciando xorriso para criar a ISO h\u00edbrida (UEFI + MBR/BIOS)...\"\n\n    xorriso -as mkisofs \\\n        -iso-level 3 \\\n        -full-iso9660-filenames \\\n        -volid \"$VOLUME_ID\" \\\n        \\\n        -eltorito-boot boot/grub/grub.cfg \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        \\\n        -eltorito-alt-boot \\\n        -e EFI/BOOT/grubx64.efi \\\n        -no-emul-boot \\\n        -boot-load-size 4 \\\n        \\\n        -isohybrid-mbr \"$ISOHYBRID_MBR_FILE\" \\\n        -o \"$OUTPUT_ISO_NAME\" \\\n        \"$ISO_WORK_DIR\"\n\n    if [ $? -ne 0 ]; then\n        echo -e \"${RED}ERRO: Falha ao gerar a imagem ISO. Verifique os logs do xorriso.${NC}\"\n        exit 1\n    fi\n\n    echo -e \"\\n====================================================\"\n    echo -e \"${GREEN}SUCESSO! A imagem ISO h\u00edbrida Live est\u00e1 pronta:${NC}\"\n    echo -e \"--> $(pwd)/${OUTPUT_ISO_NAME}\"\n    echo -e \"ID do Volume (Label): ${VOLUME_ID}\"\n    echo -e \"====================================================\\n\"\n}\n\n# ====================================================\n# FLUXO PRINCIPAL DE EXECU\u00c7\u00c3O\n# ====================================================\n\ncheck_dependencies\nprepare_environment\ncreate_squashfs\ncreate_data_tarball\nconfigure_boot\ncreate_setup_script\ngenerate_iso\n", "system_scripts/llm.sh": "#!/usr/bin/env bash\n# =============================================================================\n# llm.sh \u2014 IA local OFFLINE (llama.cpp) para Oracle Linux 9.8\n# -----------------------------------------------------------------------------\n# Hardware alvo: Intel Celeron N2808 (2 nucleos, SEM AVX), 3.3 GB RAM.\n# Por isso usamos llama.cpp compilado nativo (funciona sem AVX) e modelos\n# pequenos quantizados (Q4). NAO use Ollama aqui: ele costuma exigir AVX e\n# trava com \"Illegal instruction\" nesta CPU.\n#\n# Uso (rode como usuario NORMAL, NAO como root \u2014 usa sudo so p/ instalar pacotes):\n#   ./llm.sh install          # dependencias + compila + baixa modelos leves\n#   ./llm.sh doctor           # diagnostico do hardware/ambiente\n#   ./llm.sh list             # lista modelos do catalogo e o que ja foi baixado\n#   ./llm.sh pull <alias>     # baixa um modelo do catalogo\n#   ./llm.sh run  <alias> [-p \"prompt\"] [outras flags do llama-cli]\n#   ./llm.sh chat <alias>     # conversa interativa (modo -cnv)\n#   ./llm.sh serve <alias> [--port 8080]   # servidor com API OpenAI\n#   ./llm.sh bench <alias>    # mede tokens/s nesta maquina\n#   ./llm.sh update           # git pull + recompila\n#   ./llm.sh paths            # mostra onde esta cada coisa\n#\n# Variaveis:\n#   LLM_HOME   (padrao: $HOME/llama.cpp)   onde compilar\n#   MODELS_DIR (padrao: $HOME/models)      onde ficam os .gguf\n#   THREADS    (padrao: nproc)             threads de inferencia\n#   CTX        (padrao: 2048)              tamanho de contexto\n#   JOBS       (padrao: nproc)             paralelismo da compilacao\n#\n# Instalado automaticamente tambem um atalho em ~/.local/bin/llm (se existir).\n# =============================================================================\nset -euo pipefail\n\n# ---- config -----------------------------------------------------------------\nLLM_HOME=\"${LLM_HOME:-$HOME/llama.cpp}\"\nMODELS_DIR=\"${MODELS_DIR:-$HOME/models}\"\nLLAMA_BIN=\"$LLM_HOME/build/bin\"\nTHREADS=\"${THREADS:-$(nproc 2>/dev/null || echo 2)}\"\nCTX=\"${CTX:-2048}\"\nJOBS=\"${JOBS:-$(nproc 2>/dev/null || echo 2)}\"\nSELF=\"$(readlink -f \"$0\")\"\nSCRIPT_DIR=\"$(dirname \"$SELF\")\"\n\n# catalogo: alias|repo_huggingface|arquivo.gguf|tamanho_aprox_GB\nCATALOG=\"qwen0.5b|Qwen/Qwen2.5-0.5B-Instruct-GGUF|qwen2.5-0.5b-instruct-q4_k_m.gguf|0.4\nllama1b|bartowski/Llama-3.2-1B-Instruct-GGUF|Llama-3.2-1B-Instruct-Q4_K_M.gguf|0.8\nqwen1.5b|Qwen/Qwen2.5-1.5B-Instruct-GGUF|qwen2.5-1.5b-instruct-q4_k_m.gguf|1.0\nsmollm2|HuggingFaceTB/SmolLM2-360M-Instruct-GGUF|smollm2-360m-instruct-q8_0.gguf|0.4\nphi4mini|unsloth/Phi-4-mini-instruct-GGUF|Phi-4-mini-instruct-Q4_K_M.gguf|2.4\nphi3mini|microsoft/Phi-3-mini-4k-instruct-gguf|Phi-3-mini-4k-instruct-q4.gguf|2.2\"\nDEFAULT_MODELS=\"qwen0.5b llama1b qwen1.5b\"\n\n# ---- helpers ----------------------------------------------------------------\nsay()  { printf '\\033[1;36m== %s\\033[0m\\n' \"$*\"; }\nwarn() { printf '\\033[1;33mAVISO: %s\\033[0m\\n' \"$*\" >&2; }\ndie()  { printf '\\033[1;31mERRO: %s\\033[0m\\n' \"$*\" >&2; exit 1; }\n\n# executa como root: direto se ja root, senao via sudo\nasroot() { if [ \"$(id -u)\" -eq 0 ]; then \"$@\"; else sudo \"$@\"; fi; }\n\ncatalog_line() {\n  printf '%s\\n' \"$CATALOG\" | awk -F'|' -v a=\"$1\" '$1==a{print; f=1} END{exit(f?0:1)}'\n}\nmodel_file() { catalog_line \"$1\" | cut -d'|' -f3; }\nmodel_repo() { catalog_line \"$1\" | cut -d'|' -f2; }\nmodel_size() { catalog_line \"$1\" | cut -d'|' -f4; }\nmodel_path() { printf '%s/%s' \"$MODELS_DIR\" \"$(model_file \"$1\")\"; }\n\n# resolve o binario do llama.cpp (nomes mudam entre versoes)\nllama_exe() {\n  local name=\"$1\"\n  if [ -x \"$LLAMA_BIN/$name\" ]; then printf '%s' \"$LLAMA_BIN/$name\"; return; fi\n  case \"$name\" in\n    llama-cli) [ -x \"$LLAMA_BIN/main\" ] && { printf '%s' \"$LLAMA_BIN/main\"; return; } ;;\n  esac\n  printf ''   # nao encontrado\n}\n\nrequire_built() {\n  if [ -z \"$(llama_exe llama-cli)\" ]; then\n    die \"llama.cpp ainda nao compilado. Rode:  $0 install\"\n  fi\n}\n\n# ---- subcomandos ------------------------------------------------------------\n\ncmd_deps() {\n  say \"Instalando dependencias de build (cmake, gcc-c++, make, git)\"\n  asroot dnf install -y cmake gcc gcc-c++ make git\n  say \"Dependencias OK\"\n}\n\ncmd_build() {\n  say \"Compilando llama.cpp em $LLM_HOME (nativo, sem AVX)\"\n  mkdir -p \"$(dirname \"$LLM_HOME\")\"\n  if [ -d \"$LLM_HOME/.git\" ]; then\n    git -C \"$LLM_HOME\" pull --ff-only || warn \"git pull falhou; usando codigo atual\"\n  else\n    git clone --depth 1 https://github.com/ggerganov/llama.cpp \"$LLM_HOME\"\n  fi\n  cmake -S \"$LLM_HOME\" -B \"$LLM_HOME/build\" \\\n        -DGGML_NATIVE=ON -DCMAKE_BUILD_TYPE=Release -DLLAMA_CURL=OFF\n  cmake --build \"$LLM_HOME/build\" -j\"$JOBS\" \\\n        --target llama-cli llama-server llama-bench\n  say \"Build concluido: $(llama_exe llama-cli || echo '??')\"\n}\n\ncmd_pull() {\n  local alias=\"${1:?uso: $0 pull <alias>}\"\n  catalog_line \"$alias\" >/dev/null || die \"alias desconhecido: $alias (veja: $0 list)\"\n  local repo file dest url\n  repo=\"$(model_repo \"$alias\")\"; file=\"$(model_file \"$alias\")\"; dest=\"$MODELS_DIR/$file\"\n  mkdir -p \"$MODELS_DIR\"\n  if [ -s \"$dest\" ]; then\n    say \"Ja existe: $dest ($(du -h \"$dest\" | cut -f1))\"\n    return 0\n  fi\n  url=\"https://huggingface.co/$repo/resolve/main/$file?download=true\"\n  say \"Baixando $alias -> $dest\"\n  wget -c -O \"$dest.part\" \"$url\"\n  mv -f \"$dest.part\" \"$dest\"\n  say \"Pronto: $(du -h \"$dest\" | cut -f1)  ($dest)\"\n}\n\ncmd_install() {\n  cmd_deps\n  cmd_build\n  local m\n  for m in $DEFAULT_MODELS; do cmd_pull \"$m\"; done\n  # atalho conveniente\n  if [ -d \"$HOME/.local/bin\" ] && [ -w \"$HOME/.local/bin\" ]; then\n    ln -sf \"$SELF\" \"$HOME/.local/bin/llm\"\n    say \"Atalho criado: ~/.local/bin/llm\"\n    case \":$PATH:\" in *\":$HOME/.local/bin:\"*) ;; *)\n      warn \"~/.local/bin nao esta no PATH \u2014 adicione: export PATH=\\\"\\$HOME/.local/bin:\\$PATH\\\"\" ;;\n    esac\n  fi\n  cmd_doctor\n  say \"TUDO PRONTO. Teste:  $0 run qwen0.5b -p \\\"Ola!\\\"\"\n}\n\ncmd_list() {\n  printf '%-10s %-8s %-10s %s\\n' \"ALIAS\" \"TAM.\" \"STATUS\" \"REPO\"\n  local line a s\n  while IFS='|' read -r a repo file s; do\n    [ -n \"$a\" ] || continue\n    local st=\"nao baixado\"\n    [ -s \"$MODELS_DIR/$file\" ] && st=\"OK ($(du -h \"$MODELS_DIR/$file\" | cut -f1))\"\n    printf '%-10s %-8s %-10s %s\\n' \"$a\" \"~${s}G\" \"$st\" \"$repo\"\n  done <<< \"$CATALOG\"\n}\n\ncheck_ram() {\n  local alias=\"$1\" f=\"\" need_kb avail_kb\n  f=\"$(model_path \"$alias\")\"\n  [ -s \"$f\" ] || return 0\n  need_kb=$(( $(stat -c %s \"$f\" 2>/dev/null || echo 0) / 1024 ))\n  avail_kb=$(( $(awk '/MemAvailable/{print $2}' /proc/meminfo) ))\n  if [ \"$need_kb\" -gt \"$avail_kb\" ]; then\n    warn \"modelo ~$((need_kb/1024))MB > RAM disponivel ~$((avail_kb/1024))MB \u2014 vai usar swap e ficar LENTO.\"\n    warn \"se travar, use um modelo menor (qwen0.5b) ou reduza o contexto: CTX=1024 $0 run $alias\"\n  fi\n}\n\ncmd_run() {\n  local alias=\"${1:?uso: $0 run <alias> [flags]}\"; shift || true\n  require_built\n  local f; f=\"$(model_path \"$alias\")\"\n  catalog_line \"$alias\" >/dev/null || die \"alias desconhecido: $alias (veja: $0 list)\"\n  [ -s \"$f\" ] || die \"modelo nao baixado. Rode:  $0 pull $alias\"\n  check_ram \"$alias\"\n  exec \"$(llama_exe llama-cli)\" -m \"$f\" -t \"$THREADS\" -c \"$CTX\" \"$@\"\n}\n\ncmd_chat() { cmd_run \"$@\"; }   # interativo quando sem -p: o llama-cli entra em modo conversa\n\ncmd_serve() {\n  local alias=\"${1:?uso: $0 serve <alias> [--port 8080]}\"; shift || true\n  require_built\n  local f port=8080; f=\"$(model_path \"$alias\")\"\n  catalog_line \"$alias\" >/dev/null || die \"alias desconhecido: $alias (veja: $0 list)\"\n  [ -s \"$f\" ] || die \"modelo nao baixado. Rode:  $0 pull $alias\"\n  check_ram \"$alias\"\n  local exe; exe=\"$(llama_exe llama-server)\"\n  [ -n \"$exe\" ] || die \"llama-server nao encontrado no build\"\n  say \"API em http://127.0.0.1:$port  (modelo: $alias, ctx=$CTX, threads=$THREADS)\"\n  exec \"$exe\" -m \"$f\" -t \"$THREADS\" -c \"$CTX\" --host 127.0.0.1 --port \"$port\" \"$@\"\n}\n\ncmd_bench() {\n  local alias=\"${1:?uso: $0 bench <alias>}\"\n  require_built\n  local f; f=\"$(model_path \"$alias\")\"\n  [ -s \"$f\" ] || die \"modelo nao baixado. Rode:  $0 pull $alias\"\n  local exe; exe=\"$(llama_exe llama-bench)\"\n  [ -n \"$exe\" ] || exe=\"$(llama_exe llama-cli)\"\n  exec \"$exe\" -m \"$f\" -t \"$THREADS\" -p 64 -n 32 -r 1\n}\n\ncmd_update() { cmd_build; }\n\ncmd_paths() {\n  cat <<EOF\nLLM_HOME   : $LLM_HOME\nMODELS_DIR : $MODELS_DIR\nllama-cli  : $(llama_exe llama-cli || echo '(nao compilado)')\nllama-server: $(llama_exe llama-server || echo '(nao compilado)')\nthreads    : $THREADS\nctx        : $CTX\nEOF\n}\n\ncmd_doctor() {\n  say \"Diagnostico\"\n  echo \"CPU        : $(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ //')\"\n  echo \"Nucleos    : $(nproc)\"\n  echo \"Flags CPU  : $(grep -m1 flags /proc/cpuinfo | grep -oE 'avx2|avx|sse4_2|f16c|fma' | tr '\\n' ' ' || echo '(sem AVX)')\"\n  echo \"RAM        : $(awk '/MemTotal/{t=$2} /MemAvailable/{a=$2} END{printf \"%.1f GB total, %.1f GB disponivel\", t/1048576, a/1048576}' /proc/meminfo)\"\n  echo \"Disco (/)  : $(df -h / | awk 'NR==2{print $4\" livres\"}')\"\n  echo \"Build dir  : $LLM_HOME\"\n  echo \"Modelos dir: $MODELS_DIR\"\n  local cli; cli=\"$(llama_exe llama-cli || true)\"\n  [ -n \"$cli\" ] || cli=\"NAO COMPILADO (rode: $0 install)\"\n  echo \"llama-cli  : $cli\"\n  local gg=0\n  if [ -d \"$MODELS_DIR\" ]; then\n    gg=\"$(find \"$MODELS_DIR\" -maxdepth 1 -name '*.gguf' 2>/dev/null | wc -l)\"\n  fi\n  echo \"Modelos    : $gg arquivo(s) .gguf baixado(s)\"\n  if ! grep -q avx /proc/cpuinfo; then\n    warn \"Esta CPU nao tem AVX \u2014 use llama.cpp (este script). Ollama provavelmente falha aqui.\"\n  fi\n}\n\nusage() {\n  sed -n '2,40p' \"$SELF\" | sed 's/^# \\{0,1\\}//'\n}\n\n# ---- dispatch ---------------------------------------------------------------\ncase \"${1:-}\" in\n  install) cmd_install ;;\n  deps)    cmd_deps ;;\n  build)   cmd_build ;;\n  pull)    shift; cmd_pull \"$@\" ;;\n  list)    cmd_list ;;\n  run)     shift; cmd_run \"$@\" ;;\n  chat)    shift; cmd_chat \"$@\" ;;\n  serve)   shift; cmd_serve \"$@\" ;;\n  bench)   shift; cmd_bench \"$@\" ;;\n  update)  cmd_update ;;\n  paths)   cmd_paths ;;\n  doctor)  cmd_doctor ;;\n  \"\"|-h|--help|help) usage ;;\n  *) die \"comando desconhecido: $1 (use: $0 help)\" ;;\nesac\n", "system_scripts/manager_repo_sh": "#!/bin/bash\n\nREPO_DIR=\"/etc/yum.repos.d\"\n\nfunction listar_repos() {\n    echo \"\ud83d\udd0d Reposit\u00f3rios habilitados:\"\n    dnf repolist\n    echo \"\"\n    echo \"\ud83d\udcc1 Arquivos .repo dispon\u00edveis em $REPO_DIR:\"\n    ls $REPO_DIR\n}\n\nfunction desativar_repo() {\n    read -p \"Digite o ID do reposit\u00f3rio que deseja desativar (ex: ol9_baseos_latest): \" REPO_ID\n    sudo dnf config-manager --set-disabled \"$REPO_ID\"\n    echo \"\u2705 Reposit\u00f3rio '$REPO_ID' desativado.\"\n}\n\nfunction excluir_repo() {\n    read -p \"Digite o nome do arquivo .repo que deseja excluir (ex: oracle-linux.repo): \" REPO_FILE\n    if [ -f \"$REPO_DIR/$REPO_FILE\" ]; then\n        read -p \"\u26a0\ufe0f Tem certeza que deseja excluir '$REPO_FILE'? [s/N]: \" CONFIRMA\n        if [[ \"$CONFIRMA\" =~ ^[Ss]$ ]]; then\n            sudo rm \"$REPO_DIR/$REPO_FILE\"\n            echo \"\ud83d\uddd1\ufe0f Arquivo '$REPO_FILE' exclu\u00eddo com sucesso.\"\n        else\n            echo \"\u274c Exclus\u00e3o cancelada.\"\n        fi\n    else\n        echo \"\ud83d\udeab Arquivo n\u00e3o encontrado: $REPO_FILE\"\n    fi\n}\n\nwhile true; do\n    echo \"\"\n    echo \"========= MENU DE GERENCIAMENTO DE REPOSIT\u00d3RIOS =========\"\n    echo \"1\ufe0f\u20e3 Listar reposit\u00f3rios\"\n    echo \"2\ufe0f\u20e3 Desativar reposit\u00f3rio\"\n    echo \"3\ufe0f\u20e3 Excluir arquivo .repo\"\n    echo \"4\ufe0f\u20e3 Sair\"\n    echo \"==========================================================\"\n    read -p \"Escolha uma op\u00e7\u00e3o [1-4]: \" OPCAO\n\n    case $OPCAO in\n        1) listar_repos ;;\n        2) desativar_repo ;;\n        3) excluir_repo ;;\n        4) echo \"\ud83d\udc4b Saindo...\"; break ;;\n        *) echo \"\u274c Op\u00e7\u00e3o inv\u00e1lida. Tente novamente.\" ;;\n    esac\ndone\n\n", "system_scripts/manut.sh": "#!/bin/bash\n\n# --- Configura\u00e7\u00f5es ---\nAPP_NAME=\"amoranimal\"\nREPO_DIR=\"amoranimalmarilia\"\n\necho \"==============================================\"\necho \"   SCRIPT DE MANUTEN\u00c7\u00c3O: $APP_NAME\"\necho \"==============================================\"\n\n# 1. Entrada do Usu\u00e1rio\nread -p \"Deseja iniciar a manuten\u00e7\u00e3o completa (NPM + PM2 + Nginx)? (s/n): \" inic>\n\nif [[ \"$iniciar\" != \"s\" && \"$iniciar\" != \"S\" ]]; then\n    echo \"Opera\u00e7\u00e3o cancelada.\"\n    exit 0\nfi\n\n# 2. Atualiza\u00e7\u00e3o de Depend\u00eancias\necho -e \"\\n[1/4] Verificando depend\u00eancias (npm install)...\"\ncd ~/$REPO_DIR || { echo \"Erro: Pasta $REPO_DIR n\u00e3o encontrada.\"; exit 1; }\n\nif npm install; then\n    echo \"\u2714 Depend\u00eancias atualizadas com sucesso.\"\nelse\n    echo \"\u2716 Erro ao instalar m\u00f3dulos. Verifique o arquivo package.json.\"\n    exit 1\nfi\n\n# 3. Reinicializa\u00e7\u00e3o do PM2\necho -e \"\\n[2/4] Reiniciando inst\u00e2ncia no PM2...\"\npm2 restart $APP_NAME || pm2 start index.js --name $APP_NAME\n\n# 4. Verifica\u00e7\u00e3o do Nginx\necho -e \"\\n[3/4] Analisando status do Nginx...\"\nif sudo nginx -t; then\n    echo \"\u2714 Configura\u00e7\u00e3o do Nginx est\u00e1 \u00edntegra.\"\n    sudo systemctl reload nginx\n    echo \"\u2714 Nginx recarregado.\"\nelse\n    echo \"\u2716 Erro na configura\u00e7\u00e3o do Nginx! Verifique /etc/nginx/sites-available/\"\nfi\n\n# 5. An\u00e1lise de Logs\necho -e \"\\n[4/4] Abrindo logs do PM2 para an\u00e1lise (Pressione Ctrl+C para sair)..>\necho \"Aguardando 3 segundos antes de exibir logs...\"\nsleep 3\npm2 logs $APP_NAME --lines 20\n\n", "system_scripts/mgc.sh": "#!/bin/bash\n\nUSER=\"debian\"\nHOST=\"201.54.22.122\"\n\nEMBEDDED_KEY_B64=\"\"\n\nrestore_key() {\n    local key_file\n    key_file=$(mktemp /tmp/ssh_key_XXXXXX)\n    echo \"$EMBEDDED_KEY_B64\" | openssl base64 -d -A > \"$key_file\" 2>/dev/null\n    if [[ $? -ne 0 ]]; then\n        echo \"ERRO: Falha ao decodificar a chave embutida\" >&2\n        exit 1\n    fi\n    chmod 600 \"$key_file\"\n    echo \"$key_file\"\n}\n\nconnect() {\n    local key_file\n    key_file=$(restore_key)\n    ssh -i \"$key_file\" -o PasswordAuthentication=no -o StrictHostKeyChecking=accept-new -o ConnectTimeout=5 \"$USER@$HOST\"\n    local rc=$?\n    rm -f \"$key_file\"\n    exit $rc\n}\n\ndownload() {\n    local key_file remote_path local_path\n    key_file=$(restore_key)\n    remote_path=\"${1:-}\"\n    local_path=\"${2:-.}\"\n\n    if [[ -z \"$remote_path\" ]]; then\n        read -rp \"Caminho do arquivo no servidor: \" remote_path\n        read -rp \"Destino local (Enter para o diretorio atual): \" local_path\n        local_path=\"${local_path:-.}\"\n    fi\n\n    scp -i \"$key_file\" -o PasswordAuthentication=no -o StrictHostKeyChecking=accept-new -o ConnectTimeout=5 \"$USER@$HOST:$remote_path\" \"$local_path\"\n\n    local rc=$?\n    rm -f \"$key_file\"\n    exit $rc\n}\n\narquitetura() {\n    local key_file\n    key_file=$(restore_key)\n    ssh -i \"$key_file\" -o PasswordAuthentication=no -o StrictHostKeyChecking=accept-new -o ConnectTimeout=5 \"$USER@$HOST\" '\n        echo \"== Arquitetura ==\"\n        uname -m; uname -r\n        lscpu | grep -E \"Architecture|CPU\\(s\\)|Model name\" | head -5\n        echo \"== Memoria ==\"\n        free -h | grep -E \"Mem|Swap\"\n        echo \"== Disco ==\"\n        df -h / | tail -1\n        echo \"== Uptime / Load ==\"\n        uptime\n        echo \"== Containers ==\"\n        docker ps --format \"{{.Names}}\\t{{.Image}}\" 2>/dev/null || sudo docker ps --format \"{{.Names}}\\t{{.Image}}\" 2>/dev/null\n        echo \"== Docker imagens ==\"\n        docker image ls --format \"{{.Repository}}:{{.Tag}}\\t{{.Size}}\" 2>/dev/null || sudo docker image ls --format \"{{.Repository}}:{{.Tag}}\\t{{.Size}}\" 2>/dev/null\n    '\n\n    local rc=$?\n    rm -f \"$key_file\"\n    exit $rc\n}\n\ndisco() {\n    local key_file\n    key_file=$(restore_key)\n    ssh -i \"$key_file\" -o PasswordAuthentication=no -o StrictHostKeyChecking=accept-new -o ConnectTimeout=5 \"$USER@$HOST\" '\n        echo \"== Uso geral ==\"\n        df -h /\n        echo \"\"\n        echo \"== Top 15 maiores diretorios (raiz) ==\"\n        sudo du -h --max-depth=1 / 2>/dev/null | sort -rh | head -15\n        echo \"\"\n        echo \"== /var detalhado ==\"\n        sudo du -h --max-depth=2 /var 2>/dev/null | sort -rh | head -15\n        echo \"\"\n        echo \"== Docker volumes ==\"\n        docker system df -v 2>/dev/null | head -30 || sudo docker system df -v 2>/dev/null | head -30\n        echo \"\"\n        echo \"== Docker images detalhado ==\"\n        docker images --format \"{{.Repository}}:{{.Tag}}\\t{{.Size}}\\t{{.CreatedSince}}\" 2>/dev/null || sudo docker images --format \"{{.Repository}}:{{.Tag}}\\t{{.Size}}\\t{{.CreatedSince}}\" 2>/dev/null\n        echo \"\"\n        echo \"== Containers (logs grandes) ==\"\n        for c in $(docker ps -q 2>/dev/null); do\n            name=$(docker inspect --format \"{{.Name}}\" $c 2>/dev/null)\n            size=$(docker inspect --format \"{{.LogPath}}\" $c 2>/dev/null | xargs sudo du -h 2>/dev/null | tail -1)\n            echo \"$name -> log: $size\"\n        done\n    '\n\n    local rc=$?\n    rm -f \"$key_file\"\n    exit $rc\n}\n\narquivos() {\n    local action=\"${1:-}\"\n    local key_file=\"$HOME/.ssh/mgc_key\"\n    local mount_dir=\"$HOME/servidor_mgc\"\n\n    if [[ \"$action\" == \"desmontar\" || \"$action\" == \"umount\" ]]; then\n        if mountpoint -q \"$mount_dir\"; then\n            fusermount -u \"$mount_dir\" && echo \"Desmontado: $mount_dir\"\n        else\n            echo \"Nada montado em $mount_dir\"\n        fi\n        exit $?\n    fi\n\n    mkdir -p \"$(dirname \"$key_file\")\"\n    if [[ ! -s \"$key_file\" ]]; then\n        echo \"$EMBEDDED_KEY_B64\" | openssl base64 -d -A > \"$key_file\" 2>/dev/null\n        chmod 600 \"$key_file\"\n    fi\n\n    command -v thunar >/dev/null 2>&1 || { echo \"ERRO: thunar nao encontrado\" >&2; exit 1; }\n\n    if command -v sshfs >/dev/null 2>&1; then\n        mkdir -p \"$mount_dir\"\n        if ! mountpoint -q \"$mount_dir\"; then\n            sshfs -o IdentityFile=\"$key_file\" \\\n                  -o PasswordAuthentication=no \\\n                  -o StrictHostKeyChecking=accept-new \\\n                  -o ConnectTimeout=5 \\\n                  -o reconnect,ServerAliveInterval=15 \\\n                  \"$USER@$HOST:/home/$USER\" \"$mount_dir\" || { echo \"ERRO: falha ao montar via sshfs\" >&2; exit 1; }\n        fi\n        echo \"Servidor montado em: $mount_dir\"\n        thunar \"$mount_dir\" >/dev/null 2>&1 &\n    else\n        echo \"sshfs ausente; usando sftp:// via GVFS (requer gvfs-backends)\"\n        thunar \"sftp://$USER@$HOST/\" >/dev/null 2>&1 &\n    fi\n    exit 0\n}\n\ncase \"${1:-}\" in\n    download|dl|-d|--download)\n        download \"$2\" \"$3\"\n        ;;\n    arquitetura|arch|-a|--arquitetura)\n        arquitetura\n        ;;\n    disco|disk|-g|--disco)\n        disco\n        ;;\n    arquivos|files|-t|--thunar)\n        arquivos \"$2\"\n        ;;\n    *)\n        connect\n        ;;\nesac\n", "system_scripts/node.sh": " #!/bin/bash\n\n# =====================================================================\n# SCRIPT DE PROVISIONAMENTO: Git, Node.js, PostgreSQL, Nginx e PM2\n# Ambiente: Ubuntu/Debian\n# =====================================================================\n\n# --- Vari\u00e1veis de Configura\u00e7\u00e3o Padr\u00e3o ---\nNODE_VERSION=\"20\"               # Vers\u00e3o LTS do Node.js\nAPP_USER=\"deploy_user\"          # Usu\u00e1rio n\u00e3o-root para rodar a aplica\u00e7\u00e3o\nAPP_DIR=\"/home/$APP_USER/app\"   # Diret\u00f3rio onde a aplica\u00e7\u00e3o ser\u00e1 clonada\n\n# --- Fun\u00e7\u00f5es de Utilidade ---\n\n# Fun\u00e7\u00e3o para exibir mensagem de erro e sair\ndie() {\n    echo -e \"\\n\\033[1;31mERRO: $1\\033[0m\" >&2\n    exit 1\n}\n\n# Fun\u00e7\u00e3o para exibir mensagem de sucesso\nok() {\n    echo -e \"\\033[1;32mSUCESSO: $1\\033[0m\"\n}\n\n# Fun\u00e7\u00e3o para verificar o c\u00f3digo de sa\u00edda do \u00faltimo comando\ncheck_error() {\n    if [ $? -ne 0 ]; then\n        die \"Falha na etapa anterior. Saindo.\"\n    fi\n}\n\n# --- ETAPA 0: Coletar Entradas do Usu\u00e1rio ---\necho \"--------------------------------------------------------\"\necho \"--- Configura\u00e7\u00e3o de Deploy para Node.js ---\"\necho \"--------------------------------------------------------\"\n\n# 1. URL do Reposit\u00f3rio Git\nread -p \"1/5. URL do Reposit\u00f3rio GIT (Ex: https://github.com/user/repo.git): \" GIT_REPO_URL\n[ -z \"$GIT_REPO_URL\" ] && die \"A URL do reposit\u00f3rio Git \u00e9 obrigat\u00f3ria.\"\n\n# 2. Nome do Arquivo de Entrada\nread -p \"2/5. Nome do arquivo principal da aplica\u00e7\u00e3o Node.js (Ex: index.js ou server.js): \" NODE_ENTRY_FILE\n[ -z \"$NODE_ENTRY_FILE\" ] && die \"O nome do arquivo de entrada \u00e9 obrigat\u00f3rio.\"\n\n# 3. Dom\u00ednio/IP P\u00fablico\nread -p \"3/5. Seu Dom\u00ednio ou IP P\u00fablico (Ex: meuapp.com): \" DOMAIN\n[ -z \"$DOMAIN\" ] && die \"O Dom\u00ednio ou IP n\u00e3o pode ser vazio.\"\n\n# 4. Porta do Backend\nread -p \"4/5. PORTA local da sua aplica\u00e7\u00e3o Node.js (Ex: 3000): \" APP_PORT\nAPP_PORT=${APP_PORT:-3000} # Padr\u00e3o para 3000\n\n# 5. Senha do Banco de Dados\nread -sp \"5/5. Defina a senha para o usu\u00e1rio 'app_user' do PostgreSQL: \" DB_PASSWORD\necho \"\"\n[ -z \"$DB_PASSWORD\" ] && die \"A senha do banco de dados n\u00e3o pode ser vazia.\"\n\n# Nome do Banco de Dados/Usu\u00e1rio (Padr\u00f5es)\nDB_USER=\"app_user\"\nDB_NAME=\"app_db\"\nAPP_NAME=$(basename \"$GIT_REPO_URL\" .git) # Usa o nome do reposit\u00f3rio como nome do processo PM2\n\n\n# --- ETAPA 1: Configura\u00e7\u00e3o Inicial do Sistema ---\necho -e \"\\n## 1. Configurando o sistema...\"\nsudo apt update\nsudo apt install -y curl wget git nginx postgresql postgresql-contrib\ncheck_error\nok \"Pacotes b\u00e1sicos (Git, Nginx, PostgreSQL) instalados.\"\n\n# Cria um usu\u00e1rio n\u00e3o-root se n\u00e3o existir (melhor pr\u00e1tica de seguran\u00e7a)\nif ! id -u \"$APP_USER\" >/dev/null 2>&1; then\n    sudo adduser --disabled-password --gecos \"\" \"$APP_USER\"\n    ok \"Usu\u00e1rio '$APP_USER' criado.\"\nfi\n\n# Cria o diret\u00f3rio de aplica\u00e7\u00e3o\nsudo mkdir -p \"$APP_DIR\"\nsudo chown -R \"$APP_USER:$APP_USER\" \"/home/$APP_USER\"\n\n\n# --- ETAPA 2: Instala\u00e7\u00e3o do Node.js e PM2 ---\necho -e \"\\n## 2. Instalando Node.js (LTS v$NODE_VERSION) e PM2...\"\ncurl -fsSL https://deb.nodesource.com/setup_$NODE_VERSION.x | sudo -E bash -\nsudo apt install -y nodejs\ncheck_error\nsudo npm install pm2 -g\ncheck_error\nok \"Node.js e PM2 instalados.\"\n\n\n# --- ETAPA 3: Clonagem do Projeto e Instala\u00e7\u00e3o de Depend\u00eancias ---\necho -e \"\\n## 3. Clonando projeto Git e instalando depend\u00eancias...\"\n\n# Executa as a\u00e7\u00f5es como o usu\u00e1rio n\u00e3o-root\nsudo -u \"$APP_USER\" bash << EOF\n    # Vai para o diret\u00f3rio\n    cd $APP_DIR\n\n    # Clona o reposit\u00f3rio\n    git clone $GIT_REPO_URL .\n    \n    # Instala as depend\u00eancias\n    npm install\nEOF\ncheck_error\nok \"Projeto clonado e depend\u00eancias instaladas em $APP_DIR.\"\n\n\n# --- ETAPA 4: Configura\u00e7\u00e3o do PostgreSQL ---\necho -e \"\\n## 4. Configurando Usu\u00e1rio e Banco de Dados no PostgreSQL...\"\n\n# Cria o usu\u00e1rio e o banco de dados\nsudo -u postgres psql -c \"CREATE USER $DB_USER WITH ENCRYPTED PASSWORD '$DB_PASSWORD';\"\ncheck_error\nsudo -u postgres psql -c \"CREATE DATABASE $DB_NAME OWNER $DB_USER;\"\ncheck_error\n\nok \"Usu\u00e1rio '$DB_USER' e Banco de Dados '$DB_NAME' criados. **Lembre-se de configurar as vari\u00e1veis de ambiente PG no seu app.**\"\n\n\n# --- ETAPA 5: Configura\u00e7\u00e3o e In\u00edcio do PM2 ---\necho -e \"\\n## 5. Configurando e iniciando o PM2...\"\n\n# Inicia a aplica\u00e7\u00e3o Node.js com PM2 (executado como o usu\u00e1rio de aplica\u00e7\u00e3o)\nsudo -u \"$APP_USER\" pm2 start \"$APP_DIR/$NODE_ENTRY_FILE\" --name \"$APP_NAME\" --interpreter node -- start\ncheck_error\n\n# Configura o PM2 para iniciar automaticamente ap\u00f3s o reboot\nsudo env PATH=$PATH:/usr/bin pm2 startup systemd -u $APP_USER --hp /home/$APP_USER\nsudo pm2 save\nok \"Aplica\u00e7\u00e3o '$APP_NAME' iniciada com PM2 e configurada para auto-inicializa\u00e7\u00e3o.\"\n\n\n# --- ETAPA 6: Configura\u00e7\u00e3o do Nginx (Proxy Reverso) ---\necho -e \"\\n## 6. Configurando Nginx para $DOMAIN na porta $APP_PORT...\"\n\nNGINX_CONF=\"/etc/nginx/sites-available/$DOMAIN\"\nNGINX_SITES_ENABLED=\"/etc/nginx/sites-enabled\"\n\n# Cria o arquivo de configura\u00e7\u00e3o do Virtual Host\nsudo cat > \"$NGINX_CONF\" <<EOF\nserver {\n    listen 80;\n    server_name $DOMAIN www.$DOMAIN;\n\n    location / {\n        # Proxy Reverso para a porta onde o PM2 est\u00e1 rodando (a porta do seu Node.js)\n        proxy_pass http://localhost:$APP_PORT;\n        \n        # Headers essenciais\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade \\$http_upgrade;\n        proxy_set_header Connection 'upgrade';\n        proxy_set_header Host \\$host;\n        proxy_cache_bypass \\$http_upgrade;\n    }\n}\nEOF\n\n# Habilitar e Testar o Nginx\nsudo rm -f \"$NGINX_SITES_ENABLED/default\" 2>/dev/null\nsudo ln -s \"$NGINX_CONF\" \"$NGINX_SITES_ENABLED/\"\ncheck_error \"Falha ao criar o link simb\u00f3lico do Nginx.\"\n\nsudo nginx -t\ncheck_error \"Sintaxe do Nginx falhou. Verifique $NGINX_CONF.\"\n\nsudo systemctl restart nginx\ncheck_error \"Falha ao reiniciar Nginx.\"\nok \"Nginx configurado e ativo, expondo $DOMAIN na porta 80.\"\n\n\n# --- ETAPA 7: Configura\u00e7\u00e3o do Firewall (UFW) ---\necho -e \"\\n## 7. Configurando Firewall (UFW)...\"\nsudo ufw allow 'Nginx HTTP'\nsudo ufw enable\nok \"Porta 80 (HTTP) liberada no UFW.\"\n\n\n# --- Instru\u00e7\u00f5es Finais ---\necho -e \"\\n=============================================================\"\necho -e \"--- DEPLOY CONCLU\u00cdDO! ---\"\necho -e \"=============================================================\"\necho -e \"Sua aplica\u00e7\u00e3o Node.js est\u00e1 rodando em $APP_DIR, gerenciada pelo PM2.\"\necho -e \"O Nginx a est\u00e1 expondo publicamente em \\033[1;34mhttp://$DOMAIN\\033[0m\"\necho \"\"\n\necho -e \"\\033[1;33mPR\u00d3XIMOS PASSOS CR\u00cdTICOS:\\033[0m\"\necho \"1. **Vari\u00e1veis de Ambiente**: Verifique se seu aplicativo est\u00e1 lendo as vari\u00e1veis de ambiente necess\u00e1rias (como a porta '$APP_PORT' e as credenciais do PostgreSQL) e ajuste-as dentro do seu projeto, se necess\u00e1rio.\"\necho \"   - Usu\u00e1rio PG: $DB_USER\"\necho \"   - Senha PG: $DB_PASSWORD\"\necho \"   - Banco PG: $DB_NAME\"\necho \"\"\necho \"2. **PM2 Logs**: Monitore sua aplica\u00e7\u00e3o para garantir que iniciou corretamente:\"\necho \"   \\033[1m$ pm2 logs $APP_NAME\\033[0m\"\necho \"-------------------------------------------------------------\"\n", "system_scripts/ol9-audit-otimizar.sh": "#!/bin/bash\n#\n# Auditoria + Otimizacao Oracle Linux 9 + XFCE4\n# Hardware: Celeron N2808 / 2.8GB RAM / HDD 5400rpm\n# Uso: sudo ./ol9-audit-otimizar.sh [--apply]\n#\n# Sem --apply: apenas diagnostico\n# Com  --apply: aplica as otimizacoes\n\nset -euo pipefail\n\nR='\\033[0;31m'; G='\\033[0;32m'; Y='\\033[1;33m'; C='\\033[0;36m'; B='\\033[1m'; N='\\033[0m'\ninfo()  { echo -e \" ${C}*${N} $1\"; }\nok()    { echo -e \" ${G}*${N} $1\"; }\nwarn()  { echo -e \" ${Y}*${N} $1\"; }\nerr()   { echo -e \" ${R}*${N} $1\"; }\ntitle() { echo -e \"\\n${B}--- $1 ---${N}\"; }\n\n[[ $EUID -ne 0 ]] && { err \"Execute como root (sudo).\"; exit 1; }\n\nAPPLY=false\n[[ \"${1:-}\" == \"--apply\" ]] && APPLY=true\n\n# ============================================================\n# RELATORIO DE AUDITORIA\n# ============================================================\necho \"\"\necho \"============================================================\"\necho \"  AUDITORIA DE SISTEMA - Oracle Linux 9\"\necho \"============================================================\"\necho \"  Data: $(date '+%Y-%m-%d %H:%M')\"\necho \"  Host: $(hostname)\"\necho \"\"\n\ntitle \"SISTEMA OPERACIONAL\"\ncat /etc/oracle-release 2>/dev/null\nuname -r\necho \"Uptime: $(uptime -p | sed 's/up //')\"\n\ntitle \"HARDWARE\"\necho \"CPU: $(lscpu | grep 'Model name' | cut -d: -f2 | xargs)\"\necho \"Cores: $(nproc) (sem HyperThreading)\"\necho \"RAM total: $(free -h | awk '/Mem:/{print $2}')\"\necho \"RAM usada: $(free -h | awk '/Mem:/{print $3}')\"\necho \"RAM disponivel: $(free -h | awk '/Mem:/{print $7}')\"\necho \"Disco: $(lsblk -d -o MODEL /dev/sda 2>/dev/null | tail -1) - HDD 5400rpm\"\nERROS_DISCO=$(smartctl -H /dev/sda 2>/dev/null | grep -c \"PASSED\" || echo \"0\")\necho \"SMART: $(smartctl -H /dev/sda 2>/dev/null | grep 'health' || echo 'nao disponivel')\"\n\ntitle \"MEMORIA SWAP\"\nswapon --show --raw 2>/dev/null | awk 'NR>1{printf \"  %s %s (usado: %s)\\n\", $1, $2, $4}'\necho \"Swappiness: $(cat /proc/sys/vm/swappiness)\"\necho \"ZRAM alg: $(cat /sys/block/zram0/comp_algorithm 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\"\n\ntitle \"I/O SCHEDULER\"\necho \"sda: $(cat /sys/block/sda/queue/scheduler 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\"\n\ntitle \"TOP 5 PROCESSOS POR RAM\"\nps aux --sort=-%mem 2>/dev/null | awk 'NR<=5{printf \"  %-6s %-5s %-5s %s\\n\", $1, $2, $4\"%\", $11}'\n\ntitle \"SERVICOS ATIVOS RELEVANTES\"\nfor s in postgresql bluetooth avahi-daemon firewalld cups smartd mcelog ModemManager; do\n    status=$(systemctl is-enabled \"$s\" 2>/dev/null || echo \"n/a\")\n    active=$(systemctl is-active \"$s\" 2>/dev/null || echo \"n/a\")\n    echo \"  $s: enabled=$status active=$active\"\ndone\n\ntitle \"ERROS NO LOG (ULTIMAS 24h)\"\njournalctl -p 3 -b --since \"24 hours ago\" --no-pager 2>/dev/null | grep -c \".\" 2>/dev/null || true\necho \"  Total de erros no boot atual: $(journalctl -p 3 -b --no-pager 2>/dev/null | wc -l)\"\n\necho \"\"\njournalctl -p 3 -b --no-pager 2>/dev/null | awk -F': ' '{print $2}' | sort | uniq -c | sort -rn | head -8\necho \"\"\n\ntitle \"PROBLEMA CRITICO: LD_LIBRARY_PATH poluido pelo VS Code AppImage\"\necho \"  Afeta: dnf, systemctl, sed, e outros binarios do sistema\"\necho \"  Sintoma: 'libselinux.so.1: no version information available'\"\necho \"  Sintoma: 'liblzma.so.5: version XZ_5.2 not found' (quebra dnf)\"\necho \"\"\n\ntitle \"RESUMO DA AUDITORIA\"\necho \"  Hardware: Celeron N2808 + 2.8GB RAM + HDD 5400rpm\"\necho \"  RAM: CRITICA - apenas 640MB disponivel com uso normal\"\necho \"  Disco: LENTO - HDD 5400rpm sem SSD\"\necho \"  I/O scheduler: mq-deadline (ruim para HDD, melhor usar BFQ)\"\necho \"  Swappiness: 70 (agressivo, causa I/O desnecessario)\"\necho \"  Swap sda3 (3.9GB): NAO UTILIZADA (prioridade -3)\"\necho \"  PostgreSQL: rodando sem necessidade aparente (desktop)\"\necho \"  Bluetooth: ativo com erros de frame\"\necho \"  AppImage: contaminando LD_LIBRARY_PATH e quebrando ferramentas\"\n\nif [[ \"$APPLY\" == false ]]; then\n    echo \"\"\n    echo \"============================================================\"\n    echo \"  Para APLICAR as otimizacoes, execute com --apply\"\n    echo \"    sudo $0 --apply\"\n    echo \"============================================================\"\n    exit 0\nfi\n\n# ============================================================\n# APLICAR OTIMIZACOES\n# ============================================================\necho \"\"\necho \"============================================================\"\necho \"  APLICANDO OTIMIZACOES\"\necho \"============================================================\"\necho \"\"\n\n# --- 1. Swappiness: reduz para 10 (menos swapping em RAM escassa) ---\ntitle \"1. Ajustando swappiness para 10\"\nsysctl -w vm.swappiness=10\necho \"vm.swappiness=10\" > /etc/sysctl.d/90-swappiness.conf\nok \"swappiness=10 (era 70)\"\n\n# --- 2. I/O scheduler: BFQ para HDD ---\ntitle \"2. Trocando I/O scheduler para BFQ\"\necho mq-deadline > /sys/block/sda/queue/scheduler 2>/dev/null || true\ncat > /etc/udev/rules.d/60-io-scheduler.rules << 'RULE'\nACTION==\"add|change\", KERNEL==\"sd*\", ATTR{queue/rotational}==\"1\", ATTR{queue/scheduler}=\"bfq\"\nRULE\n# Aplica ja no boot atual via grub\nif ! grep -q \"elevator=bfq\" /etc/default/grub 2>/dev/null; then\n    sed -i 's/GRUB_CMDLINE_LINUX=\"/GRUB_CMDLINE_LINUX=\"elevator=bfq /' /etc/default/grub\n    grub2-mkconfig -o /boot/grub2/grub.cfg 2>/dev/null || true\nfi\n# Tenta aplicar agora\necho bfq > /sys/block/sda/queue/scheduler 2>/dev/null || true\nSCHED=$(cat /sys/block/sda/queue/scheduler 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\nok \"scheduler BFQ aplicado (atual: $SCHED)\"\n\n# --- 3. Reduzir crashkernel (reserva 448MB para kdump, desnecessario em desktop) ---\ntitle \"3. Reduzindo crashkernel para recuperar RAM\"\nCURRENT_CRASH=$(grep -oP 'crashkernel=\\S+' /proc/cmdline 2>/dev/null || echo \"n/a\")\nif echo \"$CURRENT_CRASH\" | grep -q \"448M\"; then\n    sed -i 's/crashkernel=1G-64G:448M,64G-:512M/crashkernel=128M/g' /etc/default/grub\n    grub2-mkconfig -o /boot/grub2/grub.cfg 2>/dev/null || true\n    ok \"crashkernel reduzido de 448M -> 128M (libera 320MB)\"\n    warn \"Reinicie o sistema para aplicar: sudo reboot\"\n    # Tenta liberar ja (se kexec for suportado)\n    if command -v kexec &>/dev/null; then\n        warn \"Use 'sudo kexec -l /boot/vmlinuz-\\$(uname -r) --initrd=/boot/initramfs-\\$(uname -r).img --reuse-cmdline && sudo kexec -e' para reboot rapido\"\n    fi\nelse\n    ok \"crashkernel ja ajustado ($CURRENT_CRASH)\"\nfi\n\n# --- 4. VFS cache pressure: menos agressivo com pouca RAM ---\ntitle \"4. Ajustando cache pressure\"\nsysctl -w vm.vfs_cache_pressure=50\necho \"vm.vfs_cache_pressure=50\" > /etc/sysctl.d/90-cache-pressure.conf\nok \"vfs_cache_pressure=50 (era 100)\"\n\n# --- 4. Limpar swap sda3 e recriar como filesystem (recupera 3.9GB) ---\ntitle \"5. Recuperando particao swap sda3 (3.9GB nao utilizada)\"\nif swapon --show | grep -q \"/dev/sda3\"; then\n    swapoff /dev/sda3 2>/dev/null || true\nfi\n# Verifica se realmente nao esta em uso\nUSED_SDA3=$(swapon --show --raw 2>/dev/null | awk '/sda3/{print $4}')\nif [[ \"$USED_SDA3\" == \"0\" ]] || [[ -z \"$USED_SDA3\" ]]; then\n    warn \"Particao /dev/sda3: swap desativada. Para converte-la em ext4:\"\n    echo \"    umount /dev/sda3 2>/dev/null; swapoff /dev/sda3 2>/dev/null\"\n    echo \"    mke2fs -t ext4 /dev/sda3\"\n    echo \"    e ajuste o /etc/fstab\"\n    echo \"  (Nao executado automaticamente - risco de perda de dados)\"\n    # Remove do fstab para nao montar no boot\n    sed -i '/sda3/d' /etc/fstab 2>/dev/null || true\n    ok \"sda3 removida do fstab (swap desativada)\"\nelse\n    ok \"sda3 mantida como swap (esta em uso)\"\nfi\n\n# --- 6. Desativar servicos desnecessarios ---\ntitle \"6. Desativando servicos nao essenciais (bluetooth mantido)\"\n\nif systemctl is-enabled postgresql &>/dev/null; then\n    systemctl stop postgresql 2>/dev/null || true\n    systemctl disable postgresql 2>/dev/null || true\n    ok \"postgresql desativado\"\nfi\n\nif systemctl is-enabled bluetooth &>/dev/null; then\n    systemctl enable bluetooth 2>/dev/null || true\n    systemctl start bluetooth 2>/dev/null || true\n    ok \"bluetooth mantido ativo na inicializacao\"\nfi\n\n# Corrige erro de frame do bluetooth (btusb)\ntitle \"6b. Corrigindo erro de frame do bluetooth\"\nif lsmod | grep -q btusb 2>/dev/null; then\n    rmmod btusb 2>/dev/null || true\n    sleep 1\n    modprobe btusb 2>/dev/null || true\n    ok \"btusb recarregado (corrige frame reassembly failed)\"\nfi\n# Desativa USB autosuspend para o adaptador bluetooth\nfor dev in /sys/bus/usb/devices/*/power/control; do\n    if [[ -f \"$dev\" ]]; then\n        echo on > \"$dev\" 2>/dev/null || true\n    fi\ndone\nok \"USB autosuspend desativado para dispositivos Bluetooth\"\n# Cria regra udev para persistir a correcao\ncat > /etc/udev/rules.d/81-bluetooth-fix.rules << 'RULE'\n# Corrige erro de frame do bluetooth - desativa autosuspend\nACTION==\"add\", SUBSYSTEM==\"usb\", ATTR{idVendor}==\"*\", ATTR{idProduct}==\"*\", ATTR{power/control}=\"on\"\nRULE\nudevadm control --reload-rules 2>/dev/null || true\nok \"Regra udev criada para evitar autosuspend do Bluetooth\"\n\nif systemctl is-enabled avahi-daemon &>/dev/null; then\n    systemctl stop avahi-daemon 2>/dev/null || true\n    systemctl disable avahi-daemon 2>/dev/null || true\n    ok \"avahi-daemon desativado\"\nfi\n\nif systemctl is-enabled mcelog &>/dev/null; then\n    systemctl stop mcelog 2>/dev/null || true\n    systemctl disable mcelog 2>/dev/null || true\n    ok \"mcelog desativado (CPU sem suporte a MCA extendido)\"\nfi\n\n# firewalld: manter se precisar de firewall, mas pode trocar por nftables mais leve\nif systemctl is-enabled firewalld &>/dev/null; then\n    warn \"firewalld ativo (mantido - firewall de rede)\"\n    # Apenas sugestao\nfi\n\n# --- 7. Configurar ZRAM para melhor compressao ---\ntitle \"7. Otimizando ZRAM\"\nALG_ATUAL=$(cat /sys/block/zram0/comp_algorithm 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\nif [[ \"$ALG_ATUAL\" != \"zstd\" ]]; then\n    warn \"ZRAM atual: $ALG_ATUAL. zstd tem melhor compressao mas usa mais CPU.\"\n    echo \"  Para trocar: echo zstd | sudo tee /sys/block/zram0/comp_algorithm\"\n    echo \"  (Requer desativar zram primeiro. Nao aplicado automaticamente)\"\nfi\n# Ajusta max_comp_streams = numero de CPUs\necho \"$(nproc)\" > /sys/block/zram0/max_comp_streams 2>/dev/null || true\nok \"max_comp_streams = $(nproc)\"\n\n# --- 8. Limitar politicas de energia para evitar throttling ---\ntitle \"8. Ajustando governor da CPU para desktop responsivo\"\nGOV=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo \"n/a\")\nif [[ \"$GOV\" != \"performance\" ]] && [[ \"$GOV\" != \"schedutil\" ]]; then\n    echo performance | tee /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor 2>/dev/null || true\n    ok \"CPU governor ajustado para 'performance' (via sysfs - temporario)\"\n    warn \"Para persistir: instale 'tuned' com profile 'throughput-performance' ou 'latency-performance'\"\nelse\n    ok \"CPU governor: $GOV (ok)\"\nfi\n\n# --- 9. Limitar dirty pages para evitar travamentos com HDD lento ---\ntitle \"9. Ajustando dirty page writeback\"\nsysctl -w vm.dirty_ratio=10\nsysctl -w vm.dirty_background_ratio=3\necho \"vm.dirty_ratio=10\" > /etc/sysctl.d/90-dirty.conf\necho \"vm.dirty_background_ratio=3\" >> /etc/sysctl.d/90-dirty.conf\nok \"dirty_ratio=10, dirty_background_ratio=3 (era 20/10)\"\n\n# --- 10. Fix LD_LIBRARY_PATH pollution do VS Code AppImage ---\ntitle \"10. Corrigindo contaminacao do LD_LIBRARY_PATH\"\nBASHRC=\"${HOME}/.bashrc\"\nif [[ -f \"$BASHRC\" ]]; then\n    if ! grep -q \"system_ld_path\" \"$BASHRC\" 2>/dev/null; then\n        cat >> \"$BASHRC\" << 'FIX'\n\n# Fix: limpa LD_LIBRARY_PATH de caminhos AppImage (VS Code) para comandos do sistema\nsystem_sed() { LD_LIBRARY_PATH=\"$(echo \"$LD_LIBRARY_PATH\" | tr ':' '\\n' | grep -v '\\.mount_' | tr '\\n' ':')\" command sed \"$@\"; }\nsystem_dnf() { LD_LIBRARY_PATH=\"$(echo \"$LD_LIBRARY_PATH\" | tr ':' '\\n' | grep -v '\\.mount_' | tr '\\n' ':')\" command dnf \"$@\"; }\nsystemctl() { LD_LIBRARY_PATH=\"$(echo \"$LD_LIBRARY_PATH\" | tr ':' '\\n' | grep -v '\\.mount_' | tr '\\n' ':')\" command systemctl \"$@\"; }\nalias dnf='system_dnf'\nalias systemctl='systemctl'\nalias sed='system_sed'\nFIX\n        ok \"Alias de seguranca adicionados ao ~/.bashrc\"\n        warn \"Recarregue: source ~/.bashrc\"\n    else\n        ok \"Alias ja existentes no ~/.bashrc\"\n    fi\nfi\n\n# --- 11. Cache DNF otimizado ---\ntitle \"11. Otimizando metadados DNF\"\nif command -v dnf &>/dev/null; then\n    # Limita cache para nao encher o HDD\n    mkdir -p /etc/dnf\n    if ! grep -q \"keepcache\" /etc/dnf/dnf.conf 2>/dev/null; then\n        echo \"keepcache=0\" >> /etc/dnf/dnf.conf\n        ok \"DNF keepcache=0 (nao acumula pacotes baixados)\"\n    fi\n    dnf clean all 2>/dev/null || true\n    ok \"Cache DNF limpo\"\nfi\n\n# --- 12. Sugestao de SSD (a maior otimizacao possivel) ---\ntitle \"12. RECOMENDACAO DE HARDWARE\"\necho \"\"\necho \"  A otimizacao de software mais impactful seria um SSD:\"\necho \"    - Um SSD SATA III de 240GB/480GB custa ~R\\$120-200\"\necho \"    - Boot em segundos vs minutos\"\necho \"    - LibreOffice abre em 3s vs 15s+ em HDD\"\necho \"    - swap via SSD e viavel, reduzindo necessidade de RAM\"\necho \"\"\necho \"  2a recomendacao: upgrade de RAM para 8GB (DDR3L-1333 SODIMM)\"\necho \"    - SODIMM DDR3L compativel com Bay Trail\"\necho \"    - 8GB custa ~R\\$80-120 usado\"\necho \"    - Permite rodar Firefox + VSCode + LibreOffice simultaneamente\"\necho \"\"\n\n# ============================================================\necho \"============================================================\"\necho \"  RESUMO DAS OTIMIZACOES APLICADAS\"\necho \"============================================================\"\necho \"\"\necho \"  Aplicado:\"\necho \"    - crashkernel: 448M -> 128M (+320 MB livres, reinicio necessario)\"\necho \"    - swappiness 70 -> 10 (menos swap no HDD)\"\necho \"    - I/O scheduler: mq-deadline -> BFQ (melhor para HDD)\"\necho \"    - vfs_cache_pressure: 100 -> 50\"\necho \"    - dirty_ratio: 20% -> 10% (evita travamentos)\"\necho \"    - sda3 swap removida do fstab (recupera 3.9GB)\"\necho \"    - PostgreSQL desativado\"\necho \"    - Bluetooth mantido ativo e erro de frame corrigido (btusb reload + udev)\"\necho \"    - Avahi desativado\"\necho \"    - Aliases no ~/.bashrc (protecao contra AppImage)\"\necho \"    - CPU governor: performance (sessao atual)\"\necho \"\"\necho \"  Manual (risco de perda de dados):\"\necho \"    - Formatar sda3 como ext4 e montar como /tmp ou /var/cache\"\necho \"\"\necho \"  Hardware (recomendado):\"\necho \"    - Trocar HDD por SSD SATA III (maior ganho possivel)\"\necho \"    - Upgrade RAM para 8GB DDR3L\"\necho \"\"\necho \"  Scripts uteis neste diretorio:\"\necho \"    - setup-xfce-tiling.sh (tiling XFCE)\"\necho \"    - ol9-full-setup.sh (repos + codecs + apps)\"\necho \"============================================================\"\n", "system_scripts/ol9-full-setup.sh": "#!/bin/bash\n\n# Configuracao completa: Oracle Linux 9 + EPEL + RPM Fusion + XFCE + LibreOffice + Codecs\n# Sem --nobest nem --skip-broken: repositorios corretos eliminam dependencias quebradas\n\nset -euo pipefail\n\nR='\\033[0;31m'; G='\\033[0;32m'; Y='\\033[1;33m'; C='\\033[0;36m'; N='\\033[0m'\ninfo()  { echo -e \"${C}[INFO]${N}  $1\"; }\nok()    { echo -e \"${G}[OK]${N}    $1\"; }\nwarn()  { echo -e \"${Y}[WARN]${N}  $1\"; }\nerr()   { echo -e \"${R}[ERRO]${N} $1\"; }\n\n[[ $EUID -ne 0 ]] && { err \"Execute como root (sudo).\"; exit 1; }\n[[ ! -f /etc/oracle-release ]] && { err \"Apenas Oracle Linux 9.\"; exit 1; }\nVERSAO=$(grep -oP '\\d+\\.\\d+' /etc/oracle-release | head -1)\ninfo \"Oracle Linux $VERSAO detectado\"\n\n# Backup limpo dos repos atuais\nBACKUP=\"/etc/yum.repos.d/backup-$(date +%Y%m%d%H%M%S)\"\nmkdir -p \"$BACKUP\"\ncp /etc/yum.repos.d/*.repo \"$BACKUP/\" 2>/dev/null || true\nok \"Backup dos repos atuais em: $BACKUP\"\nrm -f /etc/yum.repos.d/*.repo\n\n# ============================================================\n# 1. Oracle Linux repos (BaseOS + AppStream + CRB + UEK)\n# ============================================================\ncat > /etc/yum.repos.d/oracle-linux.repo << 'REPO'\n[ol9_baseos_latest]\nname=Oracle Linux 9 BaseOS Latest ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/baseos/latest/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_appstream]\nname=Oracle Linux 9 Application Stream ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/appstream/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\n\n[ol9_codeready_builder]\nname=Oracle Linux 9 CodeReady Builder ($basearch)\nbaseurl=https://yum.oracle.com/repo/OracleLinux/OL9/codeready/builder/$basearch/\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-oracle\ngpgcheck=1\nenabled=1\nREPO\nok \"Oracle Linux repos: BaseOS + AppStream + CRB\"\n\n# ============================================================\n# 2. EPEL (via Oracle mirror - mais estavel e compativel)\n# ============================================================\ninfo \"Instalando EPEL...\"\nif dnf install -y oracle-epel-release-el9 &>/dev/null; then\n    ok \"EPEL via Oracle mirror\"\nelse\n    warn \"Oracle EPEL mirror falhou. Usando EPEL upstream...\"\n    cat > /etc/yum.repos.d/epel.repo << 'REPO'\n[epel]\nname=Extra Packages for Enterprise Linux 9 - $basearch\nmetalink=https://mirrors.fedoraproject.org/metalink?repo=epel-9&arch=$basearch\nenabled=1\ngpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\ngpgcheck=1\nREPO\n    curl -sL https://dl.fedoraproject.org/pub/epel/RPM-GPG-KEY-EPEL-9 \\\n        -o /etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-9\n    ok \"EPEL upstream configurado\"\nfi\n\n# Exclui ffmpeg do EPEL para nao conflitar com versao mais completa do RPM Fusion\nREPO_FILE=$(ls /etc/yum.repos.d/*epel*.repo 2>/dev/null | head -1)\nif [[ -n \"$REPO_FILE\" ]]; then\n    if ! grep -q \"exclude=\" \"$REPO_FILE\" 2>/dev/null; then\n        # Injeta exclude no primeiro repo section\n        sed -i '/^\\[epel\\]/,/^\\[/{/^enabled=/a\\exclude=ffmpeg* libavcodec* libavdevice* libavfilter* libavformat* libavutil* libpostproc* libswresample* libswscale*' \"$REPO_FILE}\" 2>/dev/null\n        # Fallback: adiciona ao final\n        if ! grep -q \"exclude=ffmpeg\" \"$REPO_FILE\" 2>/dev/null; then\n            echo -e \"\\n[epel]\\nexclude=ffmpeg*\" >> \"$REPO_FILE\"\n        fi\n    fi\n    ok \"EPEL configurado para excluir ffmpeg (evita conflito com RPM Fusion)\"\nfi\n\n# ============================================================\n# 3. RPM Fusion (Free + Nonfree)\n# ============================================================\ninfo \"Instalando RPM Fusion...\"\ndnf install -y --nogpgcheck \\\n    https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm \\\n    https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-9.noarch.rpm\nok \"RPM Fusion Free + Nonfree\"\n\n# ============================================================\n# 4. Sincroniza e atualiza\n# ============================================================\ninfo \"Sincronizando repositorios e atualizando sistema...\"\ndnf makecache\ndnf update -y\nok \"Cache e sistema atualizados\"\n\n# ============================================================\n# 5. Window Manager - XFCE\n# ============================================================\ninfo \"Instalando XFCE...\"\nif dnf group install -y \"Xfce\" &>/dev/null; then\n    ok \"XFCE via grupo 'Xfce'\"\nelse\n    dnf install -y \\\n        xfce4-session xfce4-panel xfce4-whiskermenu-plugin \\\n        xfce4-terminal xfdesktop xfwm4 thunar \\\n        xfce4-notifyd xfce4-power-manager xfce4-screenshooter \\\n        xfce4-taskmanager mousepad parole ristretto\n    ok \"XFCE via pacotes individuais\"\nfi\n\n# ============================================================\n# 6. LibreOffice\n# ============================================================\ninfo \"Instalando LibreOffice...\"\ndnf install -y \\\n    libreoffice \\\n    libreoffice-langpack-pt-BR \\\n    libreoffice-calc \\\n    libreoffice-writer \\\n    libreoffice-impress\nok \"LibreOffice + pt-BR\"\n\n# ============================================================\n# 7. Codecs de audio e video\n# ============================================================\ninfo \"Instalando codecs multimedia...\"\ndnf install -y \\\n    ffmpeg ffmpeg-libs \\\n    gstreamer1-plugins-base gstreamer1-plugins-good \\\n    gstreamer1-plugins-bad-free gstreamer1-plugins-good-extras \\\n    gstreamer1-plugins-bad-free-extras gstreamer1-plugins-ugly-free \\\n    gstreamer1-libav \\\n    gstreamer1-plugins-ugly \\\n    gstreamer1-plugins-bad-freeworld \\\n    vlc \\\n    x264 x265 \\\n    libvpx \\\n    opus-tools flac lame-libs vorbis-tools \\\n    libdvdcss libdvdread libdvdnav \\\n    sox\nok \"Codecs instalados\"\n\n# ============================================================\n# 8. Utilitarios\n# ============================================================\ninfo \"Instalando utilitarios...\"\ndnf install -y \\\n    curl wget git htop \\\n    unzip bzip2 p7zip p7zip-plugins \\\n    file-roller \\\n    firefox \\\n    keepassxc \\\n    cabextract\nok \"Utilitarios instalados\"\n\n# ============================================================\necho \"\"\necho \"================================================\"\necho \"  Instalacao concluida sem erros de dependencia!\"\necho \"================================================\"\necho \"  Repos: Oracle Linux Base/AppStream/CRB\"\necho \"         EPEL (Oracle mirror)\"\necho \"         RPM Fusion Free + Nonfree\"\necho \"\"\necho \"  Sistema atualizado sem --nobest nem --skip-broken\"\necho \"\"\necho \"  XFCE  - Window Manager\"\necho \"  LibreOffice (pt-BR)\"\necho \"  Codecs: ffmpeg, gstreamer (ugly+bad-freeworld),\"\necho \"          VLC, x264, x265, libdvdcss\"\necho \"================================================\"\n", "system_scripts/oracle_config.sh": "#!/bin/bash\n\n# Nome do script: config_ol9.sh\n# Descri\u00e7\u00e3o: Instala EPEL, RPM Fusion e atualiza o sistema no Oracle Linux 9.x\n# Requer execu\u00e7\u00e3o como root (sudo)\n\necho \"\ud83d\ude80 Iniciando configura\u00e7\u00e3o do sistema Oracle Linux 9.5...\"\n\n# --- 1. Verifica\u00e7\u00e3o de Permiss\u00e3o ---\nif [ \"$EUID\" -ne 0 ]; then\n  echo \"\u274c Este script deve ser executado como root. Use 'sudo ./config_ol9.sh'\"\n  exit 1\nfi\n\n# --- 2. Instala\u00e7\u00e3o do Reposit\u00f3rio EPEL ---\necho \"---\"\necho \"\u2705 1/4: Instalando o reposit\u00f3rio EPEL...\"\ndnf install -y oracle-epel-release-el9\nif [ $? -ne 0 ]; then\n  echo \"\u274c Falha ao instalar o pacote 'oracle-epel-release-el9'. Abortando.\"\n  exit 1\nfi\necho \"EPEL configurado com sucesso.\"\n\n# --- 3. Habilitar CRB (CodeReady Linux Builder) e Instalar RPM Fusion ---\necho \"---\"\necho \"\u2705 2/4: Habilitando CRB e instalando RPM Fusion...\"\n\n# Habilita o CRB, necess\u00e1rio para algumas depend\u00eancias do RPM Fusion\ndnf config-manager --enable ol9_codeready_builder\n\n# Instala os pacotes de configura\u00e7\u00e3o RPM Fusion (Free e Nonfree)\n# O uso de --nogpgcheck \u00e9 comum para este tipo de instala\u00e7\u00e3o inicial de reposit\u00f3rios\ndnf install -y --nogpgcheck \\\n  https://mirrors.rpmfusion.org/free/el/rpmfusion-free-release-9.noarch.rpm \\\n  https://mirrors.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-9.noarch.rpm\n\nif [ $? -ne 0 ]; then\n  echo \"\u26a0\ufe0f Aviso: Falha ao instalar os pacotes RPM Fusion. Prosseguindo para a atualiza\u00e7\u00e3o.\"\nfi\necho \"RPM Fusion configurado (se a instala\u00e7\u00e3o foi bem-sucedida).\"\n\n# --- 4. Atualiza\u00e7\u00e3o do Cache DNF ---\necho \"---\"\necho \"\u2705 3/4: Limpando o cache e sincronizando reposit\u00f3rios...\"\ndnf clean all\ndnf makecache\necho \"Cache DNF atualizado.\"\n\n# --- 5. Atualiza\u00e7\u00e3o Completa do Sistema ---\necho \"---\"\necho \"\u2705 4/4: Iniciando a atualiza\u00e7\u00e3o completa do sistema (dnf update)...\"\ndnf update -y\n\nif [ $? -ne 0 ]; then\n  echo \"\u274c A atualiza\u00e7\u00e3o do sistema falhou. Verifique as mensagens de erro acima.\"\n  exit 1\nfi\n\n# --- 6. Conclus\u00e3o ---\necho \"---\"\necho \"\ud83c\udf89 Configura\u00e7\u00e3o e atualiza\u00e7\u00e3o conclu\u00eddas com sucesso!\"\necho \"Os reposit\u00f3rios EPEL e RPM Fusion foram instalados e o sistema est\u00e1 atualizado.\"\n\n# Fim do script\n", "system_scripts/otimizar-gnome.sh": " #!/bin/bash\n# gnome-manager-full.sh \u2014 Oracle Linux 9.7\n# Unico arquivo: Diagn\u00f3stico, Aplica\u00e7\u00e3o Autom\u00e1tica e Restaura\u00e7\u00e3o\nset -euo pipefail\n\nLOGDIR=\"$HOME/.local/share/gnome-optimize\"\nmkdir -p \"$LOGDIR\"\n\n# ---------------------------------------------------------\n# CONFIGURA\u00c7\u00c3O: Edite esta lista para definir o que desativar\n# Formato: tipo:nome (user-svc, system-svc, ext, autostart)\n# ---------------------------------------------------------\nread -r -d '' TARGETS <<EOF || true\nuser-svc:tracker-miner-fs.service\nuser-svc:tracker-extract.service\nuser-svc:gsd-wacom.service\nsystem-svc:cups.service\nsystem-svc:abrt-journal-core.service\next:ding@rastersoft.com\nautostart:true\nEOF\n\n# ---- Helpers ----\nopen_log(){\n    UNDO_LOG=\"$LOGDIR/undo-$(date +%Y%m%d-%H%M%S).log\"\n    echo \"# Log de restaura\u00e7\u00e3o\" > \"$UNDO_LOG\"\n}\n\nlog_cmd(){ echo \"$*\" >> \"$UNDO_LOG\"; }\n\nsafe_run(){\n    echo \"+ $*\"\n    bash -c \"$*\" || echo \"  ! Falha ignorada\"\n}\n\n# ---- L\u00f3gica de Otimiza\u00e7\u00e3o ----\napply(){\n    echo \"--- Iniciando Otimiza\u00e7\u00e3o Autom\u00e1tica ---\"\n    sudo -v # Valida sudo uma vez\n    open_log\n\n    while IFS= read -r line; do\n        [[ \"$line\" =~ ^#.*$ ]] || [[ -z \"$line\" ]] && continue\n        type=\"${line%%:*}\"; val=\"${line#*:}\"\n\n        case \"$type\" in\n            user-svc)\n                if systemctl --user is-enabled \"$val\" &>/dev/null; then\n                    log_cmd \"systemctl --user unmask $val; systemctl --user enable --now $val\"\n                fi\n                safe_run \"systemctl --user disable --now $val &>/dev/null; systemctl --user mask $val\"\n                ;;\n            system-svc)\n                if systemctl is-enabled \"$val\" &>/dev/null; then\n                    log_cmd \"sudo systemctl unmask $val; sudo systemctl enable --now $val\"\n                fi\n                safe_run \"sudo systemctl disable --now $val &>/dev/null; sudo systemctl mask $val\"\n                ;;\n            ext)\n                log_cmd \"gnome-extensions enable $val\"\n                safe_run \"gnome-extensions disable $val\"\n                ;;\n            autostart)\n                mkdir -p ~/.config/autostart-disabled\n                for f in ~/.config/autostart/*.desktop; do\n                    [ -e \"$f\" ] || continue\n                    log_cmd \"mv ~/.config/autostart-disabled/$(basename \"$f\") ~/.config/autostart/\"\n                    mv \"$f\" ~/.config/autostart-disabled/\n                done\n                ;;\n        esac\n    done <<< \"$TARGETS\"\n    \n    echo -e \"\\nPronto! Log de restaura\u00e7\u00e3o criado em: $UNDO_LOG\"\n}\n\n# ---- L\u00f3gica de Restaura\u00e7\u00e3o ----\nrestore(){\n    local last_log\n    last_log=$(ls -t \"$LOGDIR\"/undo-*.log 2>/dev/null | head -n 1)\n    \n    if [[ -z \"$last_log\" ]]; then\n        echo \"Erro: Nenhum log encontrado em $LOGDIR\"\n        exit 1\n    fi\n\n    echo \"Restaurando do log: $last_log\"\n    sudo -v\n    while IFS= read -r line; do\n        [[ \"$line\" =~ ^#.*$ ]] || [[ -z \"$line\" ]] && continue\n        safe_run \"$line\"\n    done < \"$last_log\"\n    echo \"Restaura\u00e7\u00e3o conclu\u00edda.\"\n}\n\n# ---- Menu Simples ----\ncase \"${1:-}\" in\n    apply)   apply ;;\n    restore) restore ;;\n    *) echo \"Uso: $0 {apply|restore}\"; exit 1 ;;\nesac\n", "system_scripts/otimizar-xfce.sh": "#!/bin/bash\n#\n# otimizar-xfce.sh \u2014 Otimiza XFCE + sistema completo (Oracle Linux 9)\n# Uso: ./otimizar-xfce.sh                    # diagnostico\n#       sudo ./otimizar-xfce.sh --apply       # aplicar otimizacoes\n#       sudo ./otimizar-xfce.sh --apply --yes # auto-instalar pacotes sem perguntar\n#\n# Sem argumentos: diagnostico completo + sugestoes\n# --apply: aplica todas as otimizacoes com seguranca e rollback\n\nset -euo pipefail\n\nR='\\033[0;31m'; G='\\033[0;32m'; Y='\\033[1;33m'; C='\\033[0;36m'; B='\\033[1m'; N='\\033[0m'\ninfo()  { echo -e \" ${C}*${N} $1\"; }\nok()    { echo -e \" ${G}*${N} $1\"; }\nwarn()  { echo -e \" ${Y}*${N} $1\"; }\nerr()   { echo -e \" ${R}*${N} $1\"; }\ntitle() { echo -e \"\\n${B}--- $1 ---${N}\"; }\n\nAPPLY=false; YES=false\nfor arg in \"$@\"; do\n    [[ \"$arg\" == \"--apply\" ]] && APPLY=true\n    [[ \"$arg\" == \"--yes\" ]]   && YES=true\ndone\n\nLOGDIR=\"$HOME/.local/share/xfce-optimize\"\nmkdir -p \"$LOGDIR\"\nUNDO_LOG=\"$LOGDIR/undo-$(date +%Y%m%d-%H%M%S).log\"\nOPERATIONS_LOG=\"$LOGDIR/operations-$(date +%Y%m%d-%H%M%S).log\"\necho \"# Log de restauracao $(date)\" > \"$UNDO_LOG\"\necho \"# Operacoes aplicadas $(date)\" > \"$OPERATIONS_LOG\"\nlog_cmd(){ echo \"$*\" >> \"$UNDO_LOG\"; }\nlog_op(){ echo \"[$(date '+%H:%M:%S')] $*\" >> \"$OPERATIONS_LOG\"; }\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# AUTO-INSTALL: baixa pacotes faltantes via dnf (ou wget)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nREQUIRED_PKGS=()\nPKG_INSTALLED=0\n\ncheck_pkg() {\n    rpm -q \"$1\" &>/dev/null && return 0\n    REQUIRED_PKGS+=(\"$1\")\n    return 1\n}\n\ninstall_pkgs() {\n    [[ ${#REQUIRED_PKGS[@]} -eq 0 ]] && return\n    if ! command -v dnf &>/dev/null; then\n        err \"dnf nao encontrado. Instale manualmente: ${REQUIRED_PKGS[*]}\"\n        return\n    fi\n    if [[ \"$YES\" == false ]]; then\n        echo \"\"\n        warn \"Pacotes necessarios nao instalados: ${REQUIRED_PKGS[*]}\"\n        read -rp \"  Deseja instalar via dnf? [s/N] \" resp\n        [[ \"$resp\" =~ ^[Ss]$ ]] || { info \"Pulei instalacao.\"; return; }\n    fi\n    for pkg in \"${REQUIRED_PKGS[@]}\"; do\n        info \"Instalando $pkg...\"\n        dnf install -y \"$pkg\" 2>/dev/null || {\n            warn \"Falha ao instalar $pkg via dnf. Tentando via wget...\"\n            _install_fallback \"$pkg\"\n        }\n    done\n    PKG_INSTALLED=1\n}\n\n# Fallback: baixa RPM manualmente (caso dnf esteja corrompido)\n_install_fallback() {\n    local pkg=\"$1\" url\n    case \"$pkg\" in\n        lm_sensors)     url=\"https://dl.fedoraproject.org/pub/epel/9/Everything/x86_64/Packages/l/lm_sensors-3.6.0-17.el9.x86_64.rpm\" ;;\n        preload)        warn \"preload nao disponivel no OL9. Pule.\"; return ;;\n        *)              warn \"Nao sei baixar $pkg manualmente.\"; return ;;\n    esac\n    local tmpdir=$(mktemp -d)\n    wget -q \"$url\" -P \"$tmpdir\" && dnf install -y \"$tmpdir\"/*.rpm 2>/dev/null || \\\n        warn \"Falha ao instalar $pkg manualmente.\"\n    rm -rf \"$tmpdir\"\n}\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# DETECCAO XFCE\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nif [[ \"${XDG_CURRENT_DESKTOP:-}\" != \"XFCE\" ]] && [[ \"${XDG_SESSION_DESKTOP:-}\" != \"XFCE\" ]]; then\n    warn \"XFCE nao detectado (atual: ${XDG_CURRENT_DESKTOP:-desconhecido})\"\nfi\n\n# ============================================================\n# DIAGNOSTICO COMPLETO\n# ============================================================\necho \"\"\necho \"============================================================\"\necho \"  DIAGNOSTICO XFCE + SISTEMA\"\necho \"============================================================\"\necho \"  Data: $(date '+%Y-%m-%d %H:%M')\"\necho \"  Host: $(hostname)\"\necho \"  Desktop: ${XDG_CURRENT_DESKTOP:-N/A}\"\necho \"\"\n\nSYS_BOOT=$(uptime -s 2>/dev/null | cut -d' ' -f1)\nINFO_LOG=\"$LOGDIR/diagnostico-$(date +%Y%m%d-%H%M%S).log\"\n\ntitle \"SISTEMA OPERACIONAL\"\ncat /etc/oracle-release 2>/dev/null || cat /etc/os-release 2>/dev/null | head -4\necho \"  Kernel: $(uname -r)\"\necho \"  Uptime: $(uptime -p | sed 's/up //')\"\necho \"  Boot:   $SYS_BOOT\"\n\ntitle \"HARDWARE\"\necho \"  CPU: $(lscpu | grep 'Model name' | cut -d: -f2 | xargs)\"\necho \"  Cores: $(nproc)\"\necho \"  RAM total: $(free -h | awk '/Mem:/{print $2}')\"\necho \"  RAM usada: $(free -h | awk '/Mem:/{print $3}')\"\necho \"  RAM disp.: $(free -h | awk '/Mem:/{print $7}')\"\necho \"  Swap total: $(free -h | awk '/Swap:/{print $2}')\"\necho \"  Swap usado: $(free -h | awk '/Swap:/{print $3}')\"\necho \"  Disco: $(df -h / | awk 'NR==2{print $4\" livres de \"$2\" (\"$5\" usado)\"}')\"\n\ntitle \"BOOT TIME (systemd-analyze)\"\nsystemd-analyze 2>/dev/null | sed 's/^/  /'\necho \"  Top 5 servicos mais lentos:\"\nsystemd-analyze blame 2>/dev/null | head -5 | sed 's/^/    /'\nKDUMP_TIME=$(systemd-analyze blame 2>/dev/null | grep kdump | head -1)\n[[ -n \"$KDUMP_TIME\" ]] && warn \"  kdump.service: $KDUMP_TIME (maior vilao do boot!)\"\n\ntitle \"TRANSPARENT HUGE PAGES (THP)\"\nTHP=$(cat /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\necho \"  THP: $THP\"\nif [[ \"$THP\" == \"always\" ]]; then\n    warn \"  THP='always' fragmenta memoria em sistemas com <4GB RAM\"\n    echo \"    Recomendado: madvise (echo madvise > /sys/kernel/mm/transparent_hugepage/enabled)\"\nfi\n\ntitle \"ZRAM\"\nif command -v zramctl &>/dev/null; then\n    zramctl 2>/dev/null | tail -n+2 | while read line; do\n        echo \"  $line\"\n    done\n    ZRAM_ALGO=$(zramctl 2>/dev/null | awk 'NR==2{print $2}')\n    echo \"  Algoritmo: ${ZRAM_ALGO:-n/a}\"\n    [[ -n \"$ZRAM_ALGO\" && \"$ZRAM_ALGO\" != \"zstd\" ]] && \\\n        warn \"  Algoritmo '$ZRAM_ALGO' \u2014 trocar para 'zstd' comprime ~15% melhor\"\nelse\n    echo \"  zramctl nao encontrado\"\nfi\n\ntitle \"MOUNT OPTIONS (/)\"\nMOUNT_OPTS=$(findmnt -no OPTIONS / 2>/dev/null)\necho \"  Opcoes: $MOUNT_OPTS\"\nif [[ \"$MOUNT_OPTS\" != *noatime* ]]; then\n    warn \"  'noatime' nao ativo \u2014 adicionar economiza escritas em HDD\"\nfi\n\ntitle \"XFCE - COMPOSITOR\"\nif command -v xfconf-query &>/dev/null; then\n    COMPOSITOR=$(xfconf-query -c xfwm4 -p /general/use_compositing 2>/dev/null || echo \"n/a\")\n    echo \"  Compositor: $([ \"$COMPOSITOR\" == \"true\" ] && echo 'ativado' || echo 'desativado')\"\n    if [[ \"$COMPOSITOR\" == \"true\" ]]; then\n        SHOW_CORE=$(xfconf-query -c xfwm4 -p /general/show_dock_shadows 2>/dev/null || echo \"n/a\")\n        echo \"  Shadows: ${SHOW_CORE:-n/a}\"\n        CYCLE_RAISE=$(xfconf-query -c xfwm4 -p /general/raise_on_click 2>/dev/null || echo \"n/a\")\n        echo \"  Raise on click: ${CYCLE_RAISE:-n/a}\"\n    fi\nelse\n    warn \"xfconf-query nao encontrado\"\nfi\n\ntitle \"XFCE - GERENCIADOR DE JANELAS\"\nif command -v xfconf-query &>/dev/null; then\n    TILE=$(xfconf-query -c xfwm4 -p /general/tile_on_move 2>/dev/null || echo \"n/a\")\n    echo \"  Tiling on move: ${TILE}\"\n    WORKSPACES=$(xfconf-query -c xfwm4 -p /general/workspace_count 2>/dev/null || echo \"4\")\n    echo \"  Workspaces: ${WORKSPACES}\"\nfi\n\ntitle \"XFCE - PAINEL\"\nif command -v xfconf-query &>/dev/null; then\n    for i in $(xfconf-query -c xfce4-panel -l 2>/dev/null | grep -oP '/plugins/plugin-\\d+' | sort -u); do\n        NAME=$(xfconf-query -c xfce4-panel -p \"$i\" 2>/dev/null || true)\n        [[ -n \"$NAME\" ]] && echo \"  $i: $NAME\"\n    done 2>/dev/null | head -15\nfi\n\ntitle \"APPS DE INICIO AUTOMATICO\"\nSTARTUP_DIR=\"$HOME/.config/autostart\"\nif [[ -d \"$STARTUP_DIR\" ]]; then\n    for f in \"$STARTUP_DIR\"/*.desktop; do\n        [[ -f \"$f\" ]] || continue\n        NAME=$(grep -m1 '^Name=' \"$f\" 2>/dev/null | cut -d= -f2)\n        echo \"  ${NAME:-$(basename \"$f\" .desktop)}\"\n    done\nelse\n    echo \"  Nenhum\"\nfi\n\ntitle \"MEMORIA E SWAP\"\necho \"  RAM: $(free -h | awk '/Mem:/{printf \"%s total, %s usada, %s disponivel\", $2, $3, $7}')\"\nSWAPPINESS=$(cat /proc/sys/vm/swappiness 2>/dev/null || echo \"n/a\")\necho \"  Swappiness: ${SWAPPINESS}\"\necho \"  Swap: $(swapon --show 2>/dev/null | wc -l) dispositivo(s)\"\n[[ -n \"$SWAPPINESS\" && \"$SWAPPINESS\" -gt 60 ]] && \\\n    warn \"  Swappiness=${SWAPPINESS} alto para HDD \u2014 recomendado: 10\"\n\ntitle \"TOP 8 PROCESSOS POR RAM\"\nps aux --sort=-%mem 2>/dev/null | awk 'NR<=8{printf \"  %-6s %-5s %-5s %s\\n\", $1, $2, $4\"%\", $11}'\n\ntitle \"SERVICOS ATIVOS RELEVANTES\"\nfor s in kdump.service xfce4-screensaver power-profiles-daemon accounts-daemon \\\n         cups bluetooth avahi-daemon firewalld smartd ModemManager \\\n         postgresql mongod redis NetworkManager-wait-online; do\n    enabled=$(systemctl is-enabled \"$s\" 2>/dev/null || echo \"n/a\")\n    active=$(systemctl is-active \"$s\" 2>/dev/null || echo \"n/a\")\n    [[ \"$enabled\" == \"enabled\" ]] && warn \"  $s: enabled=$enabled active=$active\" || \\\n        echo \"  $s: enabled=$enabled active=$active\"\ndone\n\ntitle \"TEMPERATURA DA CPU\"\nif command -v sensors &>/dev/null; then\n    sensors 2>/dev/null | grep -E '^Core|^Package|temp[0-9]' | head -5 | sed 's/^/  /'\nelse\n    echo \"  lm-sensors nao instalado\"\n    check_pkg lm_sensors\nfi\n\ntitle \"ERROS NO LOG (BOOT ATUAL)\"\nERR_COUNT=$(journalctl -p 3 -b --no-pager 2>/dev/null | wc -l || echo \"0\")\necho \"  Total de erros: ${ERR_COUNT}\"\n(( ERR_COUNT > 0 )) && \\\n    journalctl -p 3 -b --no-pager 2>/dev/null | awk -F': ' '{print $2}' | sort | uniq -c | sort -rn | head -5 | sed 's/^/  /'\n\ntitle \"OOM (OUT OF MEMORY)\"\nOOM_COUNT=$(journalctl -b -t oom-kill --no-pager 2>/dev/null | wc -l || echo \"0\")\necho \"  OOM kills: ${OOM_COUNT}\"\n(( OOM_COUNT > 0 )) && err \"VISAO: eventos OOM detectados!\" || ok \"Sem OOM\"\n\ntitle \"CRASHES XFCE\"\nfor proc in xfwm4 xfdesktop xfce4-panel; do\n    n=$(journalctl -b \"_COMM=$proc\" --no-pager 2>/dev/null | grep -ci \"crash\\|segfault\\|abort\\|signal\" || echo \"0\")\n    echo \"  $proc: ${n} eventos\"\ndone\n\ntitle \"PRESSURE STALL INFORMATION (PSI)\"\nfor metric in cpu memory io; do\n    [[ -f \"/proc/pressure/$metric\" ]] && \\\n        awk \"{printf \\\"  %s: %s\\n\\\", \\\"$metric\\\", \\$0}\" \"/proc/pressure/$metric\" 2>/dev/null || \\\n        echo \"  $metric: n/a (kernel sem CONFIG_PSI)\"\ndone\n\n# ============================================================\n# Salvar diagnostico em log\n# ============================================================\n{\n    echo \"=== DIAGNOSTICO $(date) ===\"\n    echo \"Host: $(hostname)\"\n    echo \"Kernel: $(uname -r)\"\n    echo \"RAM: $(free -h | awk '/Mem:/{print $2\" total, \"$3\" used, \"$7\" avail\"}')\"\n    echo \"DISK: $(df -h / | awk 'NR==2{print $4\" free of \"$2}')\"\n    echo \"SWAPPINESS: $(cat /proc/sys/vm/swappiness 2>/dev/null || echo n/a)\"\n    echo \"THP: $(cat /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\"\n    echo \"Boot time: $(systemd-analyze 2>/dev/null | head -1)\"\n    echo \"CPU: $(lscpu | grep 'Model name' | cut -d: -f2 | xargs)\"\n} > \"$INFO_LOG\"\n\n# ============================================================\n# PROPOSTA DE MELHORIAS\n# ============================================================\necho \"\"\necho \"============================================================\"\necho \"  PROPOSTA DE MELHORIAS\"\necho \"============================================================\"\necho \"\"\n\nRAM_TOTAL=$(free -m | awk '/Mem:/{print int($2)}')\nRAM_LIVRE=$(free -m | awk '/Mem:/{print int($7)}')\n\n# 1. RAM\necho \" ${B}1. MEMORIA RAM${N}\"\nPERC=$((RAM_LIVRE * 100 / RAM_TOTAL))\n(( RAM_TOTAL < 3072 )) && \\\n    warn \"RAM total (${RAM_TOTAL}MB) abaixo de 3GB. Upgrade para 8GB DDR3L recomendado.\" || \\\n    (( RAM_TOTAL < 6144 )) && \\\n    warn \"RAM total (${RAM_TOTAL}MB) abaixo de 6GB.\" || \\\n    ok \"RAM total (${RAM_TOTAL}MB) OK\"\n(( PERC < 15 )) && err \"RAM livre: ${PERC}% (${RAM_LIVRE}MB) \u2014 CRITICO\" || \\\n    (( PERC < 25 )) && warn \"RAM livre: ${PERC}% (${RAM_LIVRE}MB)\" || \\\n    ok \"RAM livre: ${PERC}% (${RAM_LIVRE}MB) - OK\"\n\n# 2. Swap + swappiness\ntitle \"2. SWAP + SWAPPINESS\"\nSWAP_SIZE=$(free -m | awk '/Swap:/{print int($2)}')\nSWAP_USED=$(free -m | awk '/Swap:/{print int($3)}')\n(( SWAP_SIZE == 0 )) && warn \"Sem swap configurada!\" || \\\n    (( SWAP_USED > SWAP_SIZE * 80 / 100 )) && warn \"Swap ${SWAP_USED}/${SWAP_SIZE}MB (>80%!)\"\n(( SWAPPINESS > 60 )) && \\\n    warn \"Swappiness=${SWAPPINESS} alto demais para HDD. sysctl vm.swappiness=10\"\n\n# 3. Compositor\ntitle \"3. COMPOSITOR XFCE\"\nif [[ \"${COMPOSITOR:-false}\" == \"true\" ]]; then\n    (( RAM_TOTAL < 4000 )) && \\\n        warn \"Compositor ativo \u2014 desative (xfconf-query ... use_compositing false)\" || \\\n        info \"Compositor ativo (RAM suficiente)\"\nelse\n    ok \"Compositor desativado\"\nfi\n\n# 4. Servicos (inclui kdump como prioridade)\ntitle \"4. SERVICOS (PRIORIDADE: KDUMP)\"\nif systemctl is-enabled kdump.service 2>/dev/null | grep -q \"^enabled$\"; then\n    kdump_time=$(systemd-analyze blame 2>/dev/null | grep kdump | awk '{print $1}')\n    err \"kdump.service ativo \u2014 adiciona ~${kdump_time:-60s} ao boot!\"\n    echo \"    systemctl mask kdump.service  # economia de ~${kdump_time:-60s}\"\nfi\n\ntitle \"   Servicos nao essenciais\"\nfor s_desc in \"cups:impressao\" \"bluetooth:Bluetooth\" \"avahi-daemon:descoberta\" \\\n              \"ModemManager:modem\" \"mcelog:MCA\" \"accounts-daemon:contas\" \\\n              \"power-profiles-daemon:energia\" \"postgresql:banco\" \"mongod:banco\" \\\n              \"redis:caching\" \"NetworkManager-wait-online:espera rede\"; do\n    svc=\"${s_desc%%:*}\"; desc=\"${s_desc#*:}\"\n    systemctl is-enabled \"$svc\" 2>/dev/null | grep -q \"enabled\" && \\\n        warn \"$svc: ativo ($desc)\" && echo \"    systemctl disable --now $svc\"\ndone\n\n# 5. Startup apps + screensaver\ntitle \"5. APPS DE INICIO\"\nif [[ -d \"$STARTUP_DIR\" ]]; then\n    for f in \"$STARTUP_DIR\"/*.desktop; do\n        [[ -f \"$f\" ]] || continue\n        NAME=$(grep -m1 '^Name=' \"$f\" 2>/dev/null || basename \"$f\" .desktop)\n        warn \"${NAME} inicia automaticamente\"\n    done\nfi\ncommand -v xfce4-screensaver &>/dev/null && \\\n    warn \"xfce4-screensaver ativo (~30-50MB RAM)\"\n\n# 6. THP\ntitle \"6. TRANSPARENT HUGE PAGES\"\nTHP_CUR=$(cat /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\n[[ \"$THP_CUR\" == \"always\" ]] && \\\n    warn \"THP='always' \u2014 trocar para 'madvise' reduz fragmentacao de RAM\" && \\\n    echo \"    echo madvise | tee /sys/kernel/mm/transparent_hugepage/enabled\"\n\n# 7. ZRAM\ntitle \"7. ZRAM (COMPRESSAO)\"\nif command -v zramctl &>/dev/null; then\n    ZRAM_ALGO=$(zramctl 2>/dev/null | awk 'NR==2{print $2}')\n    [[ -n \"$ZRAM_ALGO\" && \"$ZRAM_ALGO\" != \"zstd\" ]] && \\\n        warn \"ZRAM algoritmo='$ZRAM_ALGO' \u2014 trocar para 'zstd'\" && \\\n        echo \"    echo zstd | tee /sys/block/zram0/comp_algorithm\"\nfi\n\n# 8. noatime\ntitle \"8. MOUNT OPTIONS\"\nMOUNT_OPTS=$(findmnt -no OPTIONS / 2>/dev/null)\n[[ \"$MOUNT_OPTS\" != *noatime* ]] && \\\n    warn \"Falta 'noatime' em / \u2014 adicionar em /etc/fstab reduz escrita em HDD\"\n\n# 9. I/O scheduler\ntitle \"9. I/O SCHEDULER\"\nDISK_TYPE=\"SSD\"\nif [[ -f /sys/block/sda/queue/rotational ]] && [[ \"$(cat /sys/block/sda/queue/rotational)\" == \"1\" ]]; then\n    DISK_TYPE=\"HDD\"\n    SCHED=$(cat /sys/block/sda/queue/scheduler 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\n    echo \"  Disco: HDD 5400rpm (ST500LT012)\"\n    echo \"  Scheduler: ${SCHED}\"\n    [[ \"$SCHED\" != \"bfq\" ]] && warn \"Trocar para BFQ: echo bfq > /sys/block/sda/queue/scheduler\"\nfi\n\n# 10. Erros\ntitle \"10. SYSLOG\"\n(( ERR_COUNT > 50 )) && warn \"${ERR_COUNT} erros no boot\"\n(( OOM_COUNT > 0 )) && err \"${OOM_COUNT} eventos OOM!\"\n\n# 11. Boot time\ntitle \"11. ANALISE DE BOOT\"\necho \"  Boot total: $(systemd-analyze 2>/dev/null | grep -oP '^Startup finished in .*' || echo 'n/a')\"\necho \"  Para grafico: systemd-analyze plot > boot.svg\"\n\n# 12. Hardware\ntitle \"12. RECOMENDACOES DE HARDWARE\"\n(( RAM_TOTAL < 4096 )) && echo \"  - Upgrade RAM: 8GB DDR3L SODIMM (~R\\$80-120)\"\n[[ \"$DISK_TYPE\" == \"HDD\" ]] && echo \"  - Upgrade SSD: SATA III 240GB (~R\\$120-200) \u2014 maior ganho possivel\"\n\n# ============================================================\n# APLICAR OTIMIZACOES (--apply)\n# ============================================================\nif [[ \"$APPLY\" == false ]]; then\n    echo \"\"\n    echo \"============================================================\"\n    echo \"  Para APLICAR as otimizacoes: sudo $0 --apply [--yes]\"\n    echo \"============================================================\"\n    echo \"\"\n    echo \"  Log: $INFO_LOG\"\n    # Instalar pacotes mesmo sem --apply se --yes\n    [[ \"$YES\" == true ]] && install_pkgs\n    exit 0\nfi\n\n# \u2500\u2500 MODO APPLY \u2500\u2500\necho \"\"\necho \"============================================================\"\necho \"  APLICANDO OTIMIZACOES\"\necho \"============================================================\"\necho \"\"\n\nif [[ $EUID -ne 0 ]]; then\n    err \"Modo --apply requer root (sudo).\"\n    exit 1\nfi\n\n# Instalar pacotes necessarios antes das alteracoes\ninstall_pkgs\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 1. Swappiness\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"1. Swappiness\"\nCURRENT_SWAP=$(cat /proc/sys/vm/swappiness 2>/dev/null || echo \"70\")\nif (( CURRENT_SWAP > 10 )); then\n    sysctl -w vm.swappiness=10\n    echo \"vm.swappiness=10\" > /etc/sysctl.d/90-swappiness.conf\n    log_cmd \"sysctl -w vm.swappiness=$CURRENT_SWAP; rm -f /etc/sysctl.d/90-swappiness.conf\"\n    ok \"swappiness $CURRENT_SWAP -> 10\"\n    log_op \"swappiness: $CURRENT_SWAP -> 10\"\nelse\n    ok \"swappiness ja em $CURRENT_SWAP\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 2. kdump.service (MAIOR VILAO DO BOOT)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"2. kdump.service\"\nif systemctl is-enabled kdump.service 2>/dev/null | grep -q \"^enabled$\"; then\n    KDUMP_ACTIVE=$(systemctl is-active kdump.service 2>/dev/null || echo \"unknown\")\n    systemctl mask kdump.service 2>/dev/null || true\n    log_cmd \"systemctl unmask kdump.service; systemctl enable kdump.service\"\n    ok \"kdump.service mascarado (economia de ~60s no boot!)\"\n    log_op \"kdump.service mascarado\"\n    if [[ \"$KDUMP_ACTIVE\" == \"active\" ]]; then\n        warn \"kdump ainda rodando nesta sessao. Efetivo no proximo boot.\"\n    fi\nelse\n    ok \"kdump.service ja desativado\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 3. THP: always -> madvise\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"3. Transparent Huge Pages\"\nTHP_CUR=$(cat /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null | grep -oP '\\[\\K[^\\]]+')\nif [[ \"$THP_CUR\" == \"always\" ]]; then\n    echo madvise | tee /sys/kernel/mm/transparent_hugepage/enabled >/dev/null 2>/dev/null || true\n    log_cmd \"echo always > /sys/kernel/mm/transparent_hugepage/enabled\"\n    ok \"THP: always -> madvise (menos fragmentacao de RAM)\"\n    log_op \"THP: always -> madvise\"\n    # Persistir via tuned ou udev\n    if ! grep -q \"transparent_hugepage\" /etc/tuned/active_profile 2>/dev/null; then\n        cat > /etc/udev/rules.d/99-thp-madvise.rules << 'RULE'\nACTION==\"add\", SUBSYSTEM==\"cpu\", ATTR{online}==\"1\", RUN+=\"/bin/sh -c 'echo madvise > /sys/kernel/mm/transparent_hugepage/enabled'\"\nRULE\n        ok \"Regra udev criada para persistir THP=madvise\"\n        log_op \"Regra udev 99-thp-madvise.rules criada\"\n        log_cmd \"rm -f /etc/udev/rules.d/99-thp-madvise.rules\"\n    fi\nelse\n    ok \"THP ja em madvise\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 4. ZRAM: algoritmo zstd\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"4. ZRAM (algoritmo zstd)\"\nif command -v zramctl &>/dev/null; then\n    ZRAM_ALGO=$(zramctl 2>/dev/null | awk 'NR==2{print $2}')\n    ZRAM_DEV=$(zramctl 2>/dev/null | awk 'NR==2{print $1}')\n    if [[ -n \"$ZRAM_ALGO\" && \"$ZRAM_ALGO\" != \"zstd\" && -n \"$ZRAM_DEV\" ]]; then\n        # Troca algoritmo: precisa desativar, trocar, reativar\n        swapoff \"$ZRAM_DEV\" 2>/dev/null || true\n        echo zstd > /sys/block/zram0/comp_algorithm 2>/dev/null || warn \"zstd nao suportado pelo hardware\"\n        swapon \"$ZRAM_DEV\" 2>/dev/null || true\n        log_cmd \"swapoff $ZRAM_DEV; echo $ZRAM_ALGO > /sys/block/zram0/comp_algorithm; swapon $ZRAM_DEV\"\n        ok \"ZRAM: $ZRAM_ALGO -> zstd (compressao ~15% melhor)\"\n        log_op \"ZRAM algoritmo: $ZRAM_ALGO -> zstd\"\n    else\n        ok \"ZRAM ja em zstd ou indisponivel\"\n    fi\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 5. Compositor XFCE desativado (se RAM < 4GB)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"5. Compositor XFCE\"\nif (( RAM_TOTAL < 4000 )); then\n    COMP_OLD=$(xfconf-query -c xfwm4 -p /general/use_compositing 2>/dev/null || echo \"false\")\n    if [[ \"$COMP_OLD\" == \"true\" ]]; then\n        xfconf-query -c xfwm4 -p /general/use_compositing -s false\n        log_cmd \"xfconf-query -c xfwm4 -p /general/use_compositing -s true\"\n        ok \"Compositor XFCE desativado (~80MB RAM liberada)\"\n        log_op \"Compositor XFCE desativado\"\n    else\n        ok \"Compositor ja desativado\"\n    fi\nelse\n    ok \"RAM >= 4GB, compositor mantido\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 6. Servicos nao essenciais (inclui kdump ja feito)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"6. Servicos nao essenciais\"\nSERVICES_DISABLE=(\n    \"cups:impressao\"\n    \"avahi-daemon:descoberta de rede\"\n    \"ModemManager:modem\"\n    \"mcelog:MCA\"\n    \"accounts-daemon:contas\"\n    \"NetworkManager-wait-online:espera rede\"\n    \"postgresql:banco\"\n    \"mongod:banco\"\n    \"redis:caching\"\n)\nfor s_desc in \"${SERVICES_DISABLE[@]}\"; do\n    svc=\"${s_desc%%:*}\"; desc=\"${s_desc#*:}\"\n    if systemctl is-enabled \"$svc\" 2>/dev/null | grep -q \"^enabled$\"; then\n        if [[ \"$svc\" == \"NetworkManager-wait-online\" ]]; then\n            systemctl mask \"$svc\" 2>/dev/null || true\n            log_cmd \"systemctl unmask $svc\"\n        else\n            systemctl disable --now \"$svc\" 2>/dev/null || true\n            log_cmd \"systemctl enable --now $svc\"\n        fi\n        ok \"$svc desativado ($desc)\"\n        log_op \"$svc desativado ($desc)\"\n    else\n        info \"$svc ja desativado\"\n    fi\ndone\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 7. Apps de inicio\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"7. Apps de inicio automatico\"\nif [[ -d \"$STARTUP_DIR\" ]]; then\n    mkdir -p \"$STARTUP_DIR/disabled\"\n    for f in \"$STARTUP_DIR\"/*.desktop; do\n        [[ -f \"$f\" ]] || continue\n        NAME=$(grep -m1 '^Name=' \"$f\" 2>/dev/null || basename \"$f\" .desktop)\n        mv \"$f\" \"$STARTUP_DIR/disabled/\"\n        log_cmd \"mv \\\"$STARTUP_DIR/disabled/$(basename \"$f\")\\\" \\\"$STARTUP_DIR/\\\"\"\n        ok \"${NAME} movido para disabled/\"\n        log_op \"${NAME} movido para disabled/\"\n    done\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 8. xfce4-screensaver\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"8. xfce4-screensaver\"\nif command -v xfce4-screensaver &>/dev/null; then\n    if xfconf-query -c xfce4-screensaver -p /saver/enabled -s false &>/dev/null; then\n        log_cmd \"xfconf-query -c xfce4-screensaver -p /saver/enabled -s true\"\n        ok \"xfce4-screensaver desativado\"\n        log_op \"xfce4-screensaver desativado\"\n    elif xfconf-query -c xfce4-screensaver -l 2>/dev/null | grep -q \"/saver/enabled\"; then\n        info \"xfce4-screensaver ja desativado\"\n    else\n        xfconf-query -c xfce4-screensaver -n -p /saver/enabled -t bool -s false 2>/dev/null || true\n        log_cmd \"xfconf-query -c xfce4-screensaver -p /saver/enabled -s true\"\n        ok \"xfce4-screensaver desativado (propriedade criada)\"\n        log_op \"xfce4-screensaver desativado\"\n    fi\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 9. Reduzir workspaces\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"9. Workspaces\"\nWS_OLD=$(xfconf-query -c xfwm4 -p /general/workspace_count 2>/dev/null || echo \"4\")\nif (( WS_OLD > 4 )); then\n    xfconf-query -c xfwm4 -p /general/workspace_count -s 4\n    log_cmd \"xfconf-query -c xfwm4 -p /general/workspace_count -s $WS_OLD\"\n    ok \"Workspaces: $WS_OLD -> 4\"\n    log_op \"Workspaces: $WS_OLD -> 4\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 10. VFS cache pressure\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"10. Cache de disco (vfs_cache_pressure)\"\nCACHE_OLD=$(cat /proc/sys/vm/vfs_cache_pressure 2>/dev/null || echo \"100\")\nif (( CACHE_OLD > 50 )); then\n    sysctl -w vm.vfs_cache_pressure=50\n    echo \"vm.vfs_cache_pressure=50\" > /etc/sysctl.d/90-cache-pressure.conf\n    log_cmd \"sysctl -w vm.vfs_cache_pressure=$CACHE_OLD; rm -f /etc/sysctl.d/90-cache-pressure.conf\"\n    ok \"vfs_cache_pressure $CACHE_OLD -> 50\"\n    log_op \"vfs_cache_pressure: $CACHE_OLD -> 50\"\nelse\n    info \"vfs_cache_pressure ja em $CACHE_OLD\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 11. Dirty page writeback (ajustado para HDD)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"11. Dirty page writeback\"\nDR_OLD=$(cat /proc/sys/vm/dirty_ratio 2>/dev/null || echo \"20\")\nif (( DR_OLD > 10 )); then\n    sysctl -w vm.dirty_ratio=10\n    echo \"vm.dirty_ratio=10\" > /etc/sysctl.d/90-dirty.conf\n    log_cmd \"sysctl -w vm.dirty_ratio=$DR_OLD\"\nfi\nDBR_OLD=$(cat /proc/sys/vm/dirty_background_ratio 2>/dev/null || echo \"10\")\nif (( DBR_OLD > 3 )); then\n    sysctl -w vm.dirty_background_ratio=3\n    echo \"vm.dirty_background_ratio=3\" >> /etc/sysctl.d/90-dirty.conf\n    log_cmd \"sysctl -w vm.dirty_background_ratio=$DBR_OLD\"\n    ok \"Dirty writeback: $DR_OLD->10, bg $DBR_OLD->3\"\n    log_op \"Dirty writeback: ratio $DR_OLD->10, bg $DBR_OLD->3\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 12. CPU governor (ja em performance, mas assegura)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"12. CPU governor\"\nif [[ -d /sys/devices/system/cpu/cpu0/cpufreq ]]; then\n    GOV=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo \"\")\n    if [[ \"$GOV\" != \"performance\" && \"$GOV\" != \"schedutil\" ]]; then\n        echo performance | tee /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor >/dev/null 2>/dev/null || true\n        log_cmd \"echo $GOV | tee /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor\"\n        ok \"CPU governor: $GOV -> performance\"\n        log_op \"CPU governor: $GOV -> performance\"\n    else\n        ok \"CPU governor ja em $GOV\"\n    fi\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 13. Ionice: Xorg com prioridade de I/O\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"13. Ionice (prioridade I/O)\"\nXORG_PID=$(pidof Xorg 2>/dev/null || pidof X 2>/dev/null || echo \"\")\nif [[ -n \"$XORG_PID\" ]]; then\n    ionice -c 1 -n 0 -p \"$XORG_PID\" 2>/dev/null && \\\n        ok \"Xorg (PID $XORG_PID) com ionice REALTIME\" && \\\n        log_op \"Xorg (PID $XORG_PID) ionice REALTIME\" || \\\n        warn \"Nao foi possivel alterar ionice do Xorg\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 14. Limpar cache DNF\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"14. Cache DNF\"\ncommand -v dnf &>/dev/null && dnf clean all 2>/dev/null && ok \"Cache DNF limpo\" && log_op \"Cache DNF limpo\" || true\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 15. Protecao LD_LIBRARY_PATH\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"15. Protecao LD_LIBRARY_PATH\"\nBASHRC=\"${HOME}/.bashrc\"\nif [[ -f \"$BASHRC\" ]] && ! grep -q \"system_ld_path\" \"$BASHRC\" 2>/dev/null; then\n    cat >> \"$BASHRC\" << 'FIX'\n\n# Fix: limpa LD_LIBRARY_PATH de AppImage para comandos do sistema\nsystem_ld_path() {\n    local cmd=\"$1\"; shift\n    LD_LIBRARY_PATH=\"$(echo \"$LD_LIBRARY_PATH\" | tr ':' '\\n' | grep -v '\\.mount_' | tr '\\n' ':')\" command \"$cmd\" \"$@\"\n}\nalias dnf='system_ld_path dnf'\nalias sed='system_ld_path sed'\nalias systemctl='system_ld_path systemctl'\nFIX\n    ok \"Alias de seguranca adicionados ao ~/.bashrc\"\n    log_op \"Aliad system_ld_path adicionados ao ~/.bashrc\"\n    warn \"Recarregue: source ~/.bashrc\"\nelse\n    ok \"Alias ja existentes\"\nfi\n\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n# 16. Sugerir noatime (manual, edita fstab)\n# \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ntitle \"16. noatime (montagem)\"\nCUR_OPTS=$(findmnt -no OPTIONS / 2>/dev/null)\nif [[ \"$CUR_OPTS\" != *noatime* ]]; then\n    warn \"'noatime' nao ativo em /.\"\n    echo \"    Edite /etc/fstab: substitua 'defaults' por 'defaults,noatime' na linha do /\"\n    echo \"    Depois: mount -o remount /\"\n    echo \"    OU agora: mount -o remount,noatime /\"\n    log_cmd \"sed -i 's/noatime//g' /etc/fstab # remove noatime (restaura)\"\nfi\n\n# \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\necho \"\"\necho \"============================================================\"\necho \"  RESUMO DAS OTIMIZACOES APLICADAS\"\necho \"============================================================\"\necho \"\"\necho \"  Aplicado automaticamente:\"\necho \"    - kdump.service mascarado (economia ~60s no boot!)\"\necho \"    - swappiness: 70 -> 10\"\necho \"    - THP: always -> madvise (menos fragmentacao RAM)\"\necho \"    - ZRAM: lzo-rle -> zstd (compressao melhor)\"\necho \"    - Compositor XFCE desativado (se RAM < 4GB)\"\necho \"    - Servicos nao essenciais desativados\"\necho \"    - Apps de inicio movidos para disabled/\"\necho \"    - xfce4-screensaver desativado\"\necho \"    - Workspaces reduzidos (se > 4)\"\necho \"    - vfs_cache_pressure: 100 -> 50\"\necho \"    - dirty_ratio: 20% -> 10%, bg 10% -> 3%\"\necho \"    - CPU governor mantido/ajustado\"\necho \"    - Xorg com ionice REALTIME\"\necho \"    - Cache DNF limpo\"\necho \"    - Protecao LD_LIBRARY_PATH ~/.bashrc\"\necho \"\"\necho \"  Log de operacoes: $OPERATIONS_LOG\"\necho \"  Log de restauracao: $UNDO_LOG\"\necho \"  Para restaurar TUDO: bash $UNDO_LOG\"\necho \"\"\necho \"  RECOMENDACOES PENDENTES (manual):\"\necho \"    - Adicionar 'noatime' em /etc/fstab (mount -o remount,noatime /)\"\necho \"    - Upgrade RAM para 8GB DDR3L\"\necho \"    - Upgrade HDD -> SSD SATA III (maior impacto)\"\necho \"    - sudo systemd-analyze plot > boot.svg (ver grafico de boot)\"\necho \"============================================================\"\n", "system_scripts/remove_old_kernels.sh": "#!/bin/bash\n#\n# remove-old-kernels.sh\n# Safely remove old kernels on Oracle Linux 9.6\n# Keeps the current kernel and one previous version\n\nset -euo pipefail\n\necho \"=== Current running kernel: $(uname -r) ===\"\necho \"Listing installed kernels...\"\nrpm -qa | grep '^kernel' | grep -v 'headers\\|devel\\|tools' | sort -V\n\necho\necho \"Removing old kernels, keeping the latest 2...\"\nsudo dnf remove -y $(dnf repoquery --installonly --latest-limit=-2 -q)\n\necho\necho \"Cleaning up cached packages...\"\nsudo dnf clean all\nsudo rm -rf /var/cache/dnf\n\necho\necho \"Done! Remaining kernels:\"\nrpm -qa | grep '^kernel' | grep -v 'headers\\|devel\\|tools' | sort -V\n", "system_scripts/setup-performance.sh": "#!/usr/bin/env bash\n# =============================================================================\n# setup-performance.sh\n# -----------------------------------------------------------------------------\n# Reproduz as alteracoes de memoria/desempenho/boot aplicadas no Oracle Linux 9.8\n# (UEK 6.12). IDEMPOTENTE: pode rodar varias vezes sem efeito colateral.\n#\n# Uso:\n#   sudo ./setup-performance.sh\n#\n# Etapas aplicadas:\n#   1) /etc/sysctl.d/99-performance.conf      vm.swappiness=15 e vm.vfs_cache_pressure=50\n#   2) /etc/systemd/system/zram-swap.service  swap zram (SEM \"Before=swap.target\",\n#                                             que causava ciclo de ordenacao no systemd)\n#   3) kdump desabilitado + crashkernel removido (libera ~448 MiB no reboot)\n#   4) sysstat instalado e com coleta ativa   (historico sar/rpm de desempenho)\n#   5) NetworkManager wifi.powersave=2        (power-save do Wi-Fi desligado)\n#   6) Video Intel i915                       remove \"rhgb\" (mantem \"quiet\") e aplica\n#                                             i915.enable_psr=0 i915.enable_fbc=0\n#   7) GRUB timeout                           GRUB_TIMEOUT=1 / TIMEOUT_STYLE=menu\n#   8) Console serial ttyS0                   menu do GRUB + console=ttyS0 no kernel\n#                                             + getty de login (DO_SERIAL=no p/ pular)\n#   9) NVRAM EFI                              remove entradas mortas (rEFInd/rede/\n#                                             genericas) e deixa Oracle Linux + fallback\n#  10) backlight intel_backlight              regra udev + valor salvo (painel aceso)\n#  11) journald persistente (opcional)        logs sobrevivem a reboot  PERSIST_JOURNALD=yes\n#  12) fsck                                   checagem no proximo boot (DO_FSCK=auto|yes|no)\n# =============================================================================\n#\n# Variaveis de ambiente (yes/no) para PULAR etapas:\n#   DO_VIDEO=no            pula a etapa 6\n#   DO_GRUB_TIMEOUT=no     pula a etapa 7\n#   DO_SERIAL=no           pula a etapa 8 (console serial)\n#   DO_EFI=no              pula a etapa 9\n#   DO_BACKLIGHT=no        pula a etapa 10\n#   PERSIST_JOURNALD=yes   ativa a etapa 11 (padrao: no)\n#   DO_FSCK=yes|auto|no    etapa 12 (padrao: auto = so agenda se algum fs estiver sujo)\n#   INSTALL_SYSSTAT=no     pula a instalacao do sysstat\n#   ZRAM_SIZE=2G           tamanho do zram (padrao: 1G)\n#   SERIAL_PORT=ttyS0      porta serial da etapa 8 (padrao: ttyS0)\n#   SERIAL_SPEED=115200    velocidade da serial da etapa 8 (padrao: 115200)\n#\n# Exemplo:\n#   sudo DO_EFI=no ./setup-performance.sh\n# =============================================================================\nset -euo pipefail\n\n# ---- pre-requisitos ---------------------------------------------------------\nif [ \"$(id -u)\" -ne 0 ]; then\n  echo \"ERRO: execute com sudo:  sudo $0\" >&2\n  exit 1\nfi\n\n# ---- opcoes ----------------------------------------------------------------\nZRAM_SIZE=\"${ZRAM_SIZE:-1G}\"\nDO_VIDEO=\"${DO_VIDEO:-yes}\"\nDO_GRUB_TIMEOUT=\"${DO_GRUB_TIMEOUT:-yes}\"\nDO_SERIAL=\"${DO_SERIAL:-yes}\"\nSERIAL_PORT=\"${SERIAL_PORT:-ttyS0}\"\nSERIAL_SPEED=\"${SERIAL_SPEED:-115200}\"\nDO_EFI=\"${DO_EFI:-yes}\"\nDO_BACKLIGHT=\"${DO_BACKLIGHT:-yes}\"\nDO_FSCK=\"${DO_FSCK:-auto}\"\nPERSIST_JOURNALD=\"${PERSIST_JOURNALD:-no}\"\nINSTALL_SYSSTAT=\"${INSTALL_SYSSTAT:-yes}\"\n\nSYSCTL_FILE=/etc/sysctl.d/99-performance.conf\nZRAM_UNIT=/etc/systemd/system/zram-swap.service\nSYSSTAT_CFG=/etc/sysconfig/sysstat\nGRUB_FILE=/etc/default/grub\nKCMD=/etc/kernel/cmdline\nTS=\"$(date '+%Y-%m-%d %H:%M:%S')\"\necho \">>> setup-performance.sh iniciado em $TS (zram=${ZRAM_SIZE})\"\n\n# helper: aplica uma lista de args numa linha GRUB_CMDLINE_LINUX=\"...\"\ngrub_cmdline_set() {\n  # uso: grub_cmdline_set \"remover=rhgb|quiet\" \"adicionar=i915.foo=1\"\n  local cur new tok want remove_list add_list\n  # NAO removemos \"quiet\" (decisao do usuario): apenas \"rhgb\" e removido.\n  remove_list=\"rhgb\"\n  add_list=\"i915.enable_psr=0 i915.enable_fbc=0\"\n  cur=\"$(sed -n 's/^GRUB_CMDLINE_LINUX=\"\\(.*\\)\"/\\1/p' \"$GRUB_FILE\" 2>/dev/null || true)\"\n  new=\"\"\n  for tok in $cur; do\n    case \" $remove_list \" in *\" $tok \"*) continue ;; esac\n    new=\"${new:+$new }$tok\"\n  done\n  for want in $add_list; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  sed -i \"s|^GRUB_CMDLINE_LINUX=.*|GRUB_CMDLINE_LINUX=\\\"$new\\\"|\" \"$GRUB_FILE\"\n}\n\n# helper: adiciona tokens (idempotente) em GRUB_CMDLINE_LINUX, preservando o resto\ngrub_cmdline_add() {\n  local cur new want\n  cur=\"$(sed -n 's/^GRUB_CMDLINE_LINUX=\"\\(.*\\)\"/\\1/p' \"$GRUB_FILE\" 2>/dev/null || true)\"\n  new=\"$cur\"\n  for want in \"$@\"; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  sed -i \"s|^GRUB_CMDLINE_LINUX=.*|GRUB_CMDLINE_LINUX=\\\"$new\\\"|\" \"$GRUB_FILE\"\n}\n\n# helper: adiciona tokens (idempotente) em /etc/kernel/cmdline (kernels futuros)\nkcmdline_add() {\n  local f=\"$KCMD\" cur new want\n  [ -f \"$f\" ] || return 0\n  cur=\"$(tr '\\n' ' ' < \"$f\")\"\n  new=\"$cur\"\n  for want in \"$@\"; do\n    case \" $new \" in *\" $want \"*) ;; *) new=\"${new:+$new }$want\" ;; esac\n  done\n  printf '%s\\n' \"$(printf '%s' \"$new\" | sed -E 's/[[:space:]]+/ /g; s/^ //; s/ $//')\" > \"$f\"\n}\n\n# helper: garante dono root, permissao 0644 e contexto SELinux correto do arquivo\nfixfile() {\n  local f=\"$1\"\n  [ -e \"$f\" ] || return 0\n  chown root:root \"$f\" 2>/dev/null || true\n  chmod 0644 \"$f\" 2>/dev/null || true\n  if command -v restorecon >/dev/null 2>&1; then\n    restorecon -F \"$f\" >/dev/null 2>&1 || true\n  fi\n}\n\n# =============================================================================\n# 1) sysctl de memoria ---------------------------------------------------------\n# =============================================================================\necho\necho \"== [1/12] sysctl -> $SYSCTL_FILE\"\ncat > \"$SYSCTL_FILE\" <<'EOF'\n# Tuning de mem\u00f3ria (setup-performance.sh)\n# swappiness < 30  -> menos uso de swap; mant\u00e9m p\u00e1ginas an\u00f4nimas na RAM\n# vfs_cache_pressure < 100 -> mant\u00e9m mais page cache de inodes/dentries\nvm.swappiness=15\nvm.vfs_cache_pressure=50\nEOF\nfixfile \"$SYSCTL_FILE\"\nsysctl --system >/dev/null 2>&1 || true\necho \"   ativo: vm.swappiness=$(sysctl -n vm.swappiness) | vm.vfs_cache_pressure=$(sysctl -n vm.vfs_cache_pressure)\"\n\n# =============================================================================\n# 2) zram swap (corrigido: sem Before=swap.target -> evita ciclo de ordenacao) -\n# =============================================================================\necho\necho \"== [2/12] zram-swap -> $ZRAM_UNIT (${ZRAM_SIZE}, prioridade 200)\"\ncat > \"$ZRAM_UNIT\" <<EOF\n[Unit]\nDescription=ZRAM swap (${ZRAM_SIZE}, prioridade 200)\nAfter=local-fs.target\nDocumentation=man:zramctl(8)\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStartPre=-/sbin/modprobe zram\nExecStartPre=-/bin/sh -c 'if [ -e /sys/block/zram0 ] && [ \"\\$(cat /sys/block/zram0/disksize 2>/dev/null || echo 0)\" != \"0\" ]; then /sbin/modprobe -r zram&&/sbin/modprobe zram; fi'\nExecStartPre=/bin/sh -c 'echo ${ZRAM_SIZE} > /sys/block/zram0/disksize'\nExecStart=/sbin/mkswap /dev/zram0\nExecStart=/sbin/swapon -p 200 /dev/zram0\nExecStop=/sbin/swapoff /dev/zram0\nExecStopPost=-/sbin/modprobe -r zram\n\n[Install]\nWantedBy=multi-user.target\nEOF\nfixfile \"$ZRAM_UNIT\"\nsystemctl daemon-reload\nsystemctl enable zram-swap.service >/dev/null 2>&1 || true\nsystemctl restart zram-swap.service\necho \"   estado: $(systemctl is-active zram-swap.service)\"\necho \"   swap ativo:\"\nswapon --show | sed 's/^/      /'\n\n# =============================================================================\n# 3) kdump desabilitado + crashkernel removido (libera RAM no proximo boot) ----\n# =============================================================================\necho\necho \"== [3/12] kdump / crashkernel\"\nif systemctl is-enabled kdump 2>/dev/null | grep -q enabled; then\n  systemctl disable --now kdump || true\n  echo \"   kdump desabilitado (reserva crashkernel s\u00f3 libera ~448 MiB ap\u00f3s REBOOT)\"\nelse\n  echo \"   kdump j\u00e1 desabilitado\"\nfi\n\n[ -f \"$GRUB_FILE\" ] && cp -a \"$GRUB_FILE\" \"${GRUB_FILE}.bak.$(date +%F)\" 2>/dev/null || true\n[ -f \"$KCMD\" ]     && cp -a \"$KCMD\"     \"${KCMD}.bak.$(date +%F)\"     2>/dev/null || true\nsed -ri 's/([[:space:]]|\")crashkernel=[^\"[:space:]]+/\\1/' \"$GRUB_FILE\"\n[ -f \"$KCMD\" ] && sed -ri 's/crashkernel=[^[:space:]]+//' \"$KCMD\" || true\n\nif command -v grubby >/dev/null 2>&1; then\n  grubby --update-kernel=ALL --remove-args=crashkernel 2>&1 | sed 's/^/   grubby: /' || true\nelse\n  command -v grub2-mkconfig >/dev/null 2>&1 && grub2-mkconfig -o /boot/grub2/grub.cfg || true\nfi\necho \"   GRUB_CMDLINE_LINUX: $(grep -o 'GRUB_CMDLINE_LINUX=.*' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\nif grep -qs crashkernel /boot/loader/entries/*.conf 2>/dev/null; then\n  echo \"   AVISO: ainda h\u00e1 crashkernel em /boot/loader/entries \u2014 confira p\u00f3s-reboot\"\nelse\n  echo \"   ok: nenhum entry BLS com crashkernel\"\nfi\n\n# =============================================================================\n# 4) sysstat (historico de desempenho) ----------------------------------------\n# =============================================================================\necho\necho \"== [4/12] sysstat\"\nif [ \"${INSTALL_SYSSTAT}\" = \"yes\" ] && ! rpm -q sysstat >/dev/null 2>&1; then\n  if command -v dnf >/dev/null 2>&1; then\n    dnf -y install sysstat 2>&1 | tail -3\n  else\n    yum -y install sysstat 2>&1 | tail -3\n  fi\nelse\n  echo \"   sysstat j\u00e1 instalado ou pulado\"\nfi\nif [ -f \"$SYSSTAT_CFG\" ]; then\n  sed -i 's/^ENABLED=.*/ENABLED=\"true\"/' \"$SYSSTAT_CFG\" 2>/dev/null || true\n  grep -q '^ENABLED=' \"$SYSSTAT_CFG\" || echo 'ENABLED=\"true\"' >> \"$SYSSTAT_CFG\"\nfi\nsystemctl enable --now sysstat.service       >/dev/null 2>&1 || true\nsystemctl enable --now sysstat-collect.timer 2>/dev/null || true\nsystemctl enable --now sysstat-summary.timer 2>/dev/null || true\necho \"   timers: $(systemctl is-active sysstat-collect.timer 2>/dev/null || true)\"\n\n# =============================================================================\n# 5) Wi-Fi power-save desligado (latencia/rede) -------------------------------\n# =============================================================================\necho\necho \"== [5/12] NetworkManager wifi.powersave=2\"\nNM=/etc/NetworkManager/conf.d/default-wifi-powersave-on.conf\nif [ -d /etc/NetworkManager/conf.d ]; then\n  cat > \"$NM\" <<'EOF'\n[connection]\nwifi.powersave = 2\nEOF\n  fixfile \"$NM\"\n  systemctl reload NetworkManager 2>/dev/null || true\n  echo \"   $NM gravado\"\nelse\n  echo \"   NetworkManager ausente \u2014 etapa ignorada\"\nfi\n\n# =============================================================================\n# 6) Video Intel i915 (remove \"rhgb\"; \"quiet\" e mantido) -----------------------\n# =============================================================================\necho\necho \"== [6/12] video i915 + remover 'rhgb' (mantem 'quiet')\"\nif [ \"${DO_VIDEO}\" = \"yes\" ]; then\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --remove-args=\"rhgb\" 2>&1 | sed 's/^/   grubby: /' || true\n    grubby --update-kernel=ALL --args=\"i915.enable_psr=0 i915.enable_fbc=0\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  grub_cmdline_set\n  echo \"   GRUB_CMDLINE_LINUX: $(grep -o 'GRUB_CMDLINE_LINUX=.*' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   kernel padrao: $(grubby --default-kernel 2>/dev/null || echo n/a)\"\nelse\n  echo \"   pulado (DO_VIDEO=no)\"\nfi\n\n# =============================================================================\n# 7) GRUB timeout curto -------------------------------------------------------\n# =============================================================================\necho\necho \"== [7/12] GRUB timeout=1\"\nif [ \"${DO_GRUB_TIMEOUT}\" = \"yes\" ] && [ -f \"$GRUB_FILE\" ]; then\n  sed -i 's/^GRUB_TIMEOUT=.*/GRUB_TIMEOUT=1/' \"$GRUB_FILE\"\n  if grep -q '^GRUB_TIMEOUT_STYLE=' \"$GRUB_FILE\"; then\n    sed -i 's/^GRUB_TIMEOUT_STYLE=.*/GRUB_TIMEOUT_STYLE=menu/' \"$GRUB_FILE\"\n  else\n    echo 'GRUB_TIMEOUT_STYLE=menu' >> \"$GRUB_FILE\"\n  fi\n  command -v grub2-mkconfig >/dev/null 2>&1 && grub2-mkconfig -o /boot/grub2/grub.cfg >/dev/null 2>&1 || true\n  echo \"   $(grep -E '^GRUB_TIMEOUT(_STYLE)?=' \"$GRUB_FILE\" | tr '\\n' ' ')\"\nelse\n  echo \"   pulado (DO_GRUB_TIMEOUT=no)\"\nfi\n\n# =============================================================================\n# 8) console serial ttyS0 (menu GRUB + kernel console + getty de login) --------\n# =============================================================================\necho\necho \"== [8/12] console serial ${SERIAL_PORT} (${SERIAL_SPEED} 8N1)\"\nif [ \"${DO_SERIAL}\" = \"yes\" ]; then\n  SERIAL_CONSOLE_ARGS=\"console=tty0 console=${SERIAL_PORT},${SERIAL_SPEED}n8\"\n\n  # 8a) saida do menu do GRUB na serial, mantendo o console de video\n  if [ -f \"$GRUB_FILE\" ]; then\n    if grep -q '^GRUB_TERMINAL=' \"$GRUB_FILE\"; then\n      sed -i 's|^GRUB_TERMINAL=.*|GRUB_TERMINAL=\"console serial\"|' \"$GRUB_FILE\"\n    else\n      # GRUB_TERMINAL tem prioridade; comenta GRUB_TERMINAL_OUTPUT p/ evitar conflito\n      sed -i 's|^GRUB_TERMINAL_OUTPUT=.*|# &|' \"$GRUB_FILE\"\n      echo 'GRUB_TERMINAL=\"console serial\"' >> \"$GRUB_FILE\"\n    fi\n    if grep -q '^GRUB_SERIAL_COMMAND=' \"$GRUB_FILE\"; then\n      sed -i \"s|^GRUB_SERIAL_COMMAND=.*|GRUB_SERIAL_COMMAND=\\\"serial --speed=${SERIAL_SPEED} --unit=0 --word=8 --parity=no --stop=1\\\"|\" \"$GRUB_FILE\"\n    else\n      echo \"GRUB_SERIAL_COMMAND=\\\"serial --speed=${SERIAL_SPEED} --unit=0 --word=8 --parity=no --stop=1\\\"\" >> \"$GRUB_FILE\"\n    fi\n  fi\n\n  # 8b) parametros do kernel: BLS (kernel atual) + /etc/kernel/cmdline (futuros)\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --args=\"$SERIAL_CONSOLE_ARGS\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  kcmdline_add $SERIAL_CONSOLE_ARGS\n  grub_cmdline_add $SERIAL_CONSOLE_ARGS\n\n  # 8c) regenera o grub.cfg para aplicar GRUB_TERMINAL/GRUB_SERIAL_COMMAND no menu\n  if command -v grub2-mkconfig >/dev/null 2>&1; then\n    grub2-mkconfig -o /boot/grub2/grub.cfg >/dev/null 2>&1 || true\n  fi\n\n  # 8d) getty de login na serial (login ja disponivel sem reboot)\n  systemctl enable --now \"serial-getty@${SERIAL_PORT}.service\" >/dev/null 2>&1 || true\n\n  echo \"   menu GRUB ..... $(grep -E '^GRUB_TERMINAL=' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   serial cmd .... $(grep -E '^GRUB_SERIAL_COMMAND=' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\n  echo \"   kernel console  $(grep -ho 'console=[^ ]*' /boot/loader/entries/*.conf 2>/dev/null | sort -u | tr '\\n' ' ')\"\n  echo \"   getty ......... $(systemctl is-enabled \"serial-getty@${SERIAL_PORT}.service\" 2>/dev/null || echo n/a) / $(systemctl is-active \"serial-getty@${SERIAL_PORT}.service\" 2>/dev/null || echo n/a)\"\n  echo \"   (reboot necessario para o menu e o console do kernel valerem)\"\nelse\n  echo \"   pulado (DO_SERIAL=no)\"\nfi\n\n# =============================================================================\n# 9) NVRAM EFI: remover entradas mortas (rEFInd/rede/genericas) ---------------\n# =============================================================================\necho\necho \"== [9/12] limpeza NVRAM EFI\"\nif [ \"${DO_EFI}\" = \"yes\" ] && command -v efibootmgr >/dev/null 2>&1; then\n  keep=\"$(efibootmgr 2>/dev/null | awk '/^BootCurrent:/{print $2}')\"\n  [ -n \"$keep\" ] || keep=\"$(efibootmgr -v 2>/dev/null | awk '/SHIMX64.EFI/{print $1}' | sed 's/Boot//; s/\\*//' | head -1)\"\n  echo \"   mantendo BootCurrent=$keep\"\n  while read -r num rest; do\n    clean=\"${num#Boot}\"; clean=\"${clean%\\*}\"\n    [ \"$clean\" = \"$keep\" ] && continue\n    case \"$rest\" in\n      *rEFInd*|*\"EFI Shell\"*|*IP4*|*IP6*|*PXE*|*VenHw*)\n        echo \"   removendo $num ($rest)\"\n        efibootmgr -b \"$clean\" -B >/dev/null 2>&1 || true\n        ;;\n    esac\n  done < <(efibootmgr -v 2>/dev/null | grep -E '^Boot[0-9A-Fa-f]{4}')\n\n  order=\"$keep\"\n  for b in $(efibootmgr 2>/dev/null | awk '/^Boot[0-9A-Fa-f]{4}\\*/{print $1}' | sed 's/Boot//; s/\\*//'); do\n    [ \"$b\" = \"$keep\" ] && continue\n    order=\"${order:+$order,}$b\"\n  done\n  [ -n \"$order\" ] && efibootmgr -o \"$order\" >/dev/null 2>&1 || true\n  efibootmgr -t 1 >/dev/null 2>&1 || true\n  echo \"   depois:\"\n  efibootmgr 2>/dev/null | grep -E \"BootCurrent|Timeout|BootOrder|^Boot\" | sed 's/^/      /'\nelse\n  echo \"   pulado (DO_EFI=no ou efibootmgr ausente)\"\nfi\n\n# =============================================================================\n# 10) backlight intel_backlight (painel aceso desde o inicio do boot) ---------\n# =============================================================================\necho\necho \"== [10/12] backlight intel_backlight\"\nBL_DIR=/sys/class/backlight/intel_backlight\nBL_RULE=/etc/udev/rules.d/99-backlight-brightness.rules\nif [ \"${DO_BACKLIGHT}\" = \"yes\" ] && [ -d \"$BL_DIR\" ]; then\n  bl_max=\"$(cat \"$BL_DIR/max_brightness\" 2>/dev/null || echo 0)\"\n  if [ \"${bl_max:-0}\" -gt 0 ] 2>/dev/null; then\n    bl_val=$(( bl_max * 77 / 100 ))\n    cat > \"$BL_RULE\" <<EOF\n# Forca o brilho do painel logo que o dispositivo de backlight aparece (setup-performance.sh).\n# Valor atual: ${bl_val}/${bl_max} (~77%). Ajuste conforme necessario.\nACTION==\"add\", SUBSYSTEM==\"backlight\", KERNEL==\"intel_backlight\", ATTR{brightness}=\"${bl_val}\"\nEOF\n    fixfile \"$BL_RULE\"\n    udevadm control --reload-rules 2>/dev/null || true\n    echo \"$bl_val\" > \"$BL_DIR/brightness\" 2>/dev/null || true\n    /usr/lib/systemd/systemd-backlight save backlight:intel_backlight 2>/dev/null || true\n    echo \"   brilho fixado em ${bl_val}/${bl_max} + $BL_RULE\"\n  else\n    echo \"   max_brightness indisponivel \u2014 etapa ignorada\"\n  fi\nelse\n  echo \"   pulado (DO_BACKLIGHT=no ou interface ausente)\"\nfi\n\n# =============================================================================\n# 11) journald persistente (opcional) -----------------------------------------\n# =============================================================================\necho\necho \"== [11/12] journald\"\nJOURNAL_DIR=/var/log/journal\nif [ \"${PERSIST_JOURNALD}\" = \"yes\" ]; then\n  mkdir -p \"$JOURNAL_DIR\"\n  chown root:systemd-journal \"$JOURNAL_DIR\" 2>/dev/null || true\n  chmod 2755 \"$JOURNAL_DIR\" 2>/dev/null || true\n  command -v restorecon >/dev/null 2>&1 && restorecon -RF \"$JOURNAL_DIR\" >/dev/null 2>&1 || true\n  systemctl restart systemd-journald 2>/dev/null || true\n  echo \"   journald persistente ativado em $JOURNAL_DIR\"\nelse\n  echo \"   pulado (PERSIST_JOURNALD=no) \u2014 logs ficam s\u00f3 em /run (perdem no reboot)\"\nfi\n\n# =============================================================================\n# 12) fsck (auto|yes|no) \u2014 checagem no proximo boot --------------------------\n# =============================================================================\n# DO_FSCK=auto (padrao): s\u00f3 agenda se algum ext4 estiver sujo\n# DO_FSCK=yes           : agenda checagem completa no proximo boot\n# DO_FSCK=no            : n\u00e3o faz nada (s\u00f3 relat\u00f3rio de estado)\necho\necho \"== [12/12] fsck (modo: ${DO_FSCK})\"\nFSCK_DEVS=\"$(lsblk -rno NAME,FSTYPE 2>/dev/null | awk '$2==\"ext4\"{print \"/dev/\"$1}')\"\nneed_fsck=no\nfor dev in $FSCK_DEVS; do\n  st=\"$(dumpe2fs -h \"$dev\" 2>/dev/null | awk '/Filesystem state/{print $NF}' || true)\"\n  echo \"   $dev: ${st:-n/a}\"\n  [ \"${st:-}\" != \"clean\" ] && need_fsck=yes\ndone\nif [ \"${DO_FSCK}\" = \"no\" ]; then\n  echo \"   pulado (DO_FSCK=no)\"\nelif [ \"${DO_FSCK}\" = \"yes\" ] || [ \"$need_fsck\" = \"yes\" ]; then\n  if command -v grubby >/dev/null 2>&1; then\n    grubby --update-kernel=ALL --args=\"fsck.mode=force fsck.repair=yes\" 2>&1 | sed 's/^/   grubby: /' || true\n  fi\n  echo \"   AGENDADO: fsck.mode=force fsck.repair=yes no proximo boot.\"\n  echo \"   (pode demorar no HDD; remova depois com:)\" \n  echo \"     sudo grubby --update-kernel=ALL --remove-args=\\\"fsck.mode=force fsck.repair=yes\\\"\"\nelse\n  echo \"   nada a fazer: filesystems limpos (use DO_FSCK=yes para for\u00e7ar)\"\nfi\n\n# =============================================================================\n# resumo -----------------------------------------------------------------------\n# =============================================================================\necho\necho \"==================================================================\"\necho \" RESUMO (${ZRAM_SIZE}):\"\necho \"   sysctl mem\u00f3ria ....... $(sysctl -n vm.swappiness 2>/dev/null)/15 e $(sysctl -n vm.vfs_cache_pressure 2>/dev/null)/50\"\necho \"   zram ................. $(swapon --show | awk '$1==\"/dev/zram0\"{print $2,$3,$4; f=1} END{if(!f)print \"N\u00c3O ATIVO!\"}')\"\necho \"   kdump ................ $(systemctl is-enabled kdump 2>/dev/null || true)\"\necho \"   sar/sysstat .......... $(command -v sar >/dev/null 2>&1 && echo 'instalado' || echo 'ausente') | coleta: $(systemctl is-active sysstat-collect.timer 2>/dev/null || true)\"\necho \"   video i915 ........... $(grep -o 'i915.enable_psr=0' \"$GRUB_FILE\" >/dev/null 2>&1 && echo 'parametros aplicados' || echo 'n/a')\"\necho \"   GRUB timeout ......... $(grep -oE 'GRUB_TIMEOUT=[0-9]+' \"$GRUB_FILE\" 2>/dev/null || echo n/a)\"\necho \"   serial console ....... $(systemctl is-enabled \"serial-getty@${SERIAL_PORT}.service\" >/dev/null 2>&1 && echo \"getty@${SERIAL_PORT} ok\" || echo 'n/a') | $(grep -ho \"console=${SERIAL_PORT}[^ ]*\" /boot/loader/entries/*.conf 2>/dev/null | sort -u | tr '\\n' ' ')\"\necho \"   EFI .................. $(efibootmgr 2>/dev/null | awk '/^BootOrder:/{print $2}' || echo n/a)\"\necho \"   backlight ............ $(cat \"$BL_DIR/brightness\" 2>/dev/null || echo n/a)/$(cat \"$BL_DIR/max_brightness\" 2>/dev/null || echo n/a)\"\necho \"   journald ............. $([ -d /var/log/journal ] && echo 'persistente' || echo 'vol\u00e1til (/run)')\"\necho \"   fsck ................. $(grep -qs 'fsck.mode=force' /boot/loader/entries/*.conf 2>/dev/null && echo 'agendado p/ pr\u00f3ximo boot' || echo 'n\u00e3o agendado')\"\necho \"   REBOOT pendente? ..... crashkernel removido do boot ir\u00e1 liberar ~448 MiB de RAM\"\necho \"==================================================================\"\nexit 0\n", "system_scripts/setup-xfce-tiling.sh": "#!/bin/bash\n\n# Ativa window tiling no XFCE4 (mouse + teclado)\n# For\u00e7a tiling left/right via xdotool para sobrepor qualquer aplicativo (Firefox, etc.)\n\nset -euo pipefail\n\necho \"[1/3] Verificando dependencias...\"\nfor cmd in xfconf-query xdotool xprop xrandr; do\n    if ! command -v $cmd &>/dev/null; then\n        echo \"Erro: $cmd nao encontrado. Instale-o primeiro.\"\n        exit 1\n    fi\ndone\n\necho \"[2/3] Ativando tiling com mouse...\"\nxfconf-query -c xfwm4 -p /general/tile_on_move -s true 2>/dev/null || \\\n    xfconf-query -c xfwm4 -p /general/tile_on_move -n -t bool -s true\n\nxfconf-query -c xfwm4 -p /general/tile_on_move_centered -s false 2>/dev/null || \\\n    xfconf-query -c xfwm4 -p /general/tile_on_move_centered -n -t bool -s false\n\necho \"[3/3] Configurando atalhos de teclado (com override total via xdotool)...\"\n\nBINDIR=\"${HOME}/.local/bin\"\nmkdir -p \"$BINDIR\"\n\n# --- Tile Left ---\ncat > \"$BINDIR/xfce-tile-left.sh\" << 'XFCE_TILE_LEFT'\n#!/bin/bash\nset -euo pipefail\n\nWIN=$(xdotool getactivewindow 2>/dev/null) || exit 1\n\n# Ignora se for a \u00e1rea de trabalho\nif xprop -id \"$WIN\" _NET_WM_WINDOW_TYPE 2>/dev/null | grep -q _NET_WM_WINDOW_TYPE_DESKTOP; then\n    exit 0\nfi\n\n# Workarea global (exclui pain\u00e9is)\nread -r WA_X WA_Y WA_W WA_H <<< \"$(xprop -root _NET_WORKAREA | awk -F'= ' '{print $2}' | tr ',' ' ')\"\nWA_X=${WA_X:-0}; WA_Y=${WA_Y:-0}; WA_W=${WA_W:-1920}; WA_H=${WA_H:-1080}\n\n# Pega posi\u00e7\u00e3o da janela para descobrir em qual monitor est\u00e1\nWIN_X=$(xdotool getwindowgeometry \"$WIN\" 2>/dev/null | awk '/Position:/{print $2}' | cut -d',' -f1)\nWIN_X=${WIN_X:-0}\nCENTER=$((WIN_X + WA_X))\n\n# Acha o monitor onde a janela est\u00e1 centrada\nMON_X=0; MON_W=$WA_W\nwhile read -r line; do\n    [[ \"$line\" != *\" connected\"* ]] && continue\n    RECT=$(echo \"$line\" | grep -oP '\\d+x\\d+\\+\\d+\\+\\d+')\n    [[ -z \"$RECT\" ]] && continue\n    MX=$(echo \"$RECT\" | cut -d'+' -f2)\n    MY=$(echo \"$RECT\" | cut -d'+' -f3)\n    MW=$(echo \"$RECT\" | cut -d'x' -f1)\n    MH=$(echo \"$RECT\" | cut -d'x' -f2 | cut -d'+' -f1)\n    if (( CENTER >= MX && CENTER < MX + MW )); then\n        MON_X=$MX; MON_Y=$MY; MON_W=$MW; MON_H=$MH\n        break\n    fi\ndone < <(xrandr --current)\n\nHALF=$((MON_W / 2))\n\nxdotool windowmove \"$WIN\" \"$MON_X\" \"$MON_Y\"\nxdotool windowsize \"$WIN\" \"$HALF\" \"$MON_H\"\nXFCE_TILE_LEFT\nchmod +x \"$BINDIR/xfce-tile-left.sh\"\n\n# --- Tile Right ---\ncat > \"$BINDIR/xfce-tile-right.sh\" << 'XFCE_TILE_RIGHT'\n#!/bin/bash\nset -euo pipefail\n\nWIN=$(xdotool getactivewindow 2>/dev/null) || exit 1\n\nif xprop -id \"$WIN\" _NET_WM_WINDOW_TYPE 2>/dev/null | grep -q _NET_WM_WINDOW_TYPE_DESKTOP; then\n    exit 0\nfi\n\nread -r WA_X WA_Y WA_W WA_H <<< \"$(xprop -root _NET_WORKAREA | awk -F'= ' '{print $2}' | tr ',' ' ')\"\nWA_X=${WA_X:-0}; WA_Y=${WA_Y:-0}; WA_W=${WA_W:-1920}; WA_H=${WA_H:-1080}\n\nWIN_X=$(xdotool getwindowgeometry \"$WIN\" 2>/dev/null | awk '/Position:/{print $2}' | cut -d',' -f1)\nWIN_X=${WIN_X:-0}\nCENTER=$((WIN_X + WA_X))\n\nMON_X=0; MON_W=$WA_W\nwhile read -r line; do\n    [[ \"$line\" != *\" connected\"* ]] && continue\n    RECT=$(echo \"$line\" | grep -oP '\\d+x\\d+\\+\\d+\\+\\d+')\n    [[ -z \"$RECT\" ]] && continue\n    MX=$(echo \"$RECT\" | cut -d'+' -f2)\n    MY=$(echo \"$RECT\" | cut -d'+' -f3)\n    MW=$(echo \"$RECT\" | cut -d'x' -f1)\n    MH=$(echo \"$RECT\" | cut -d'x' -f2 | cut -d'+' -f1)\n    if (( CENTER >= MX && CENTER < MX + MW )); then\n        MON_X=$MX; MON_Y=$MY; MON_W=$MW; MON_H=$MH\n        break\n    fi\ndone < <(xrandr --current)\n\nHALF=$((MON_W / 2))\n\nxdotool windowmove \"$WIN\" \"$((MON_X + HALF))\" \"$MON_Y\"\nxdotool windowsize \"$WIN\" \"$HALF\" \"$MON_H\"\nXFCE_TILE_RIGHT\nchmod +x \"$BINDIR/xfce-tile-right.sh\"\n\n# Remove atalhos XFWM antigos (que s\u00e3o interceptados por apps)\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Left\" -r 2>/dev/null || true\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Right\" -r 2>/dev/null || true\n\n# Registra os scripts como comandos customizados (n\u00e3o passam pelo XFWM)\nxfconf-query -c xfce4-keyboard-shortcuts -p /commands/custom/\"<Super>Left\" -n -t string -s \"$BINDIR/xfce-tile-left.sh\" 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /commands/custom/\"<Super>Left\" -t string -s \"$BINDIR/xfce-tile-left.sh\"\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /commands/custom/\"<Super>Right\" -n -t string -s \"$BINDIR/xfce-tile-right.sh\" 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /commands/custom/\"<Super>Right\" -t string -s \"$BINDIR/xfce-tile-right.sh\"\n\n# Manter os demais atalhos XFWM (up/down/cantos) que geralmente n\u00e3o tem conflito\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Up\" -n -t string -s tile_up_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Up\" -t string -s tile_up_key\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Down\" -n -t string -s tile_down_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Super>Down\" -t string -s tile_down_key\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Left\" -n -t string -s tile_top_left_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Left\" -t string -s tile_top_left_key\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Right\" -n -t string -s tile_top_right_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Right\" -t string -s tile_top_right_key\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Down\" -n -t string -s tile_bottom_left_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Down\" -t string -s tile_bottom_left_key\n\nxfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Up\" -n -t string -s tile_bottom_right_key 2>/dev/null || \\\n    xfconf-query -c xfce4-keyboard-shortcuts -p /xfwm4/custom/\"<Primary><Super>Up\" -t string -s tile_bottom_right_key\n\necho \"\"\necho \"Pronto! Efeitos aplicados:\"\necho \"  - Tiling por arrasto (bordas da tela)\"\necho \"  - Super + <-/->        : tile left/right (via xdotool - sobrepoe qualquer app)\"\necho \"  - Super + cima/baixo   : tile top/bottom\"\necho \"  - Super + Ctrl + setas : tile nos cantos\"\necho \"\"\necho \"Diferente do XFWM padrao, Super+Left/Right usa xdotool diretamente,\"\necho \"entao funciona mesmo no Firefox, terminal, etc.\"\necho \"Scripts instalados em: $BINDIR/xfce-tile-{left,right}.sh\"\n", "system_scripts/setup-zram.sh": "#!/bin/bash\nset -e\n\ncat > /etc/sysctl.d/90-swappiness.conf <<'CONF'\nvm.swappiness=10\nCONF\nsysctl -w vm.swappiness=10\n\ncat > /etc/systemd/zram-generator.conf <<'CONF'\n[zram0]\nzram-fraction = 0.75\nmax-zram-size = 8192\ncompression-algorithm = zstd\nCONF\n\nsystemctl restart systemd-zram-setup@zram0\necho zstd > /sys/block/zram0/comp_algorithm 2>/dev/null || true\n\nswapon -p 100 /dev/zram0 2>/dev/null || true\n\nsed -i 's/^UUID=2b485078-24d1-4f23-9538-807a056f3d99 none                    swap    defaults        0 0$/#UUID=2b485078-24d1-4f23-9538-807a056f3d99 none                    swap    defaults        0 0/' /etc/fstab\nsed -i 's|^/swapfile none swap sw 0 0$|#/swapfile none swap sw 0 0|' /etc/fstab\n\nswapoff /swapfile 2>/dev/null || true\nswapoff /dev/sda3 2>/dev/null || true\n\necho \"zram configurado com zstd, swappiness=10, swaps de disco desativados. Status:\"\nzramctl\nfree -m\ncat /proc/swaps\n", "system_scripts/update-appimages.sh": "#!/usr/bin/env bash\nset -uo pipefail\n\nLOGFILE=\"$HOME/.cache/update-appimages.log\"\nDESKTOP_DIR=\"$HOME/.local/share/applications\"\n\nMODE=\"update\"\ncase \"${1:-}\" in\n    --menu) MODE=\"menu\"; shift ;;\n    --status) MODE=\"status\"; shift ;;\n    --uninstall) MODE=\"uninstall\"; UNINSTALL_APP=\"${2:-}\"; shift 2 ;;\n    --register) MODE=\"register\"; shift ;;\n    --links) MODE=\"links\"; shift ;;\n    --panel) MODE=\"panel\"; shift ;;\nesac\n\nAPP_DIR=\"${1:-$HOME/Applications}\"\nmkdir -p \"$APP_DIR\" \"$(dirname \"$LOGFILE\")\" \"$DESKTOP_DIR\"\n\n# Apps data: repo|filter|filename|label|desktop|icon|mime|icon_url|release_tag|type|install_url\n#\n# type: \"appimage\" (default, baixa do GitHub) ou \"curl\" (executa script de instalacao)\n# Para type=curl, repo/filter sao ignorados e a versao vem do proprio instalador.\nAPPS_DATA=(\n    \"srevinsaju/firefox-appimage|firefox-devedition|firefox-developer.AppImage|Firefox Developer Edition|firefox-developer-edition.desktop|firefox-developer-edition|x-scheme-handler/http;x-scheme-handler/https;text/html||firefox-devedition|appimage|\"\n    \"ivan-hc/MS-Edge-appimage|Microsoft-Edge-stable|microsoft-edge.AppImage|Microsoft Edge|microsoft-edge.desktop|microsoft-edge|application/pdf;application/xhtml+xml;image/webp;text/html;text/xml;x-scheme-handler/http;x-scheme-handler/https||continuous|appimage|\"\n    \"ungoogled-software/ungoogled-chromium-portablelinux|x86_64.AppImage|ungoogled-chromium.AppImage|Chromium (ungoogled)|chromium-appimage.desktop|chromium|x-scheme-handler/http;x-scheme-handler/https;text/html|||appimage|\"\n    \"VSCodium/vscodium|x86_64.AppImage|VSCodium.AppImage|VSCodium|codium-appimage.desktop|vscodium|text/plain;text/x-python;text/x-c;text/html;application/json|https://raw.githubusercontent.com/VSCodium/vscodium/master/icons/stable/codium_clt.svg||appimage|\"\n    \"||opencode|OpenCode (CLI)|opencode-cli.desktop|opencode-cli|text/plain|||curl|https://opencode.ai/v2/install\"\n)\n\n# Comandos curtos -> symlinks criados em $BIN_DIR (padrao ~/.local/bin).\n# Chave = campo \"filename\" do app (ou \"opencode\" p/ o CLI). Valor = um ou mais\n# nomes separados por espaco. Sem entrada = nao cria atalho.\ndeclare -A APP_COMMANDS=(\n    [\"firefox-developer.AppImage\"]=\"firefox-dev firefox-developer\"\n    [\"microsoft-edge.AppImage\"]=\"edge microsoft-edge\"\n    [\"ungoogled-chromium.AppImage\"]=\"chromium ungoogled-chromium\"\n    [\"VSCodium.AppImage\"]=\"codium vscodium\"\n)\n# Onde criar os atalhos. Pode sobrescrever:  BIN_DIR=/usr/local/bin ./update-appimages.sh --links\nBIN_DIR=\"${BIN_DIR:-$HOME/.local/bin}\"\n\n# \u2500\u2500 Instalador via curl (CLI) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninstall_curl_app() {\n    local url=\"$1\"\n    local retries=\"${INSTALL_RETRIES:-3}\"\n    local attempt\n\n    [[ -n \"$url\" ]] || return 1\n\n    for attempt in $(seq 1 \"$retries\"); do\n        log \"Executando instalador (tentativa $attempt/$retries): $url\"\n        # O instalador baixa o binario em background; --retry cobre a conexao\n        # com a registry, que e onde costuma cair em rede instavel.\n        if curl -fsSL --retry 3 --retry-delay 5 --retry-all-errors \"$url\" | bash; then\n            return 0\n        fi\n        sleep 5\n    done\n\n    fetch_err=\"falha ao executar instalador apos $retries tentativas\"\n    return 1\n}\n\n[[ \"$MODE\" != \"update\" ]] && exec > >(tee -a \"$LOGFILE\")\nlog() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"; }\n\n# IPs conhecidos do GitHub API (DNS local resolve para IP invalido)\nGH_API_IPS=(\"140.82.112.5\" \"140.82.113.5\" \"140.82.114.5\" \"140.82.116.5\")\nGH_RESOLVE=\"\"\nfor ip in \"${GH_API_IPS[@]}\"; do\n    GH_RESOLVE+=\" --resolve api.github.com:443:$ip\"\ndone\n\n# Curl antigo (OL9 base, 7.76) nao conhece --retry-max-delay (alias novo):\n# detecta o flag suportado para manter compatibilidade.\nRETRY_MAX_FLAG=\"--retry-max-time\"\ncurl --help all 2>/dev/null | grep -q -- '--retry-max-delay' && RETRY_MAX_FLAG=\"--retry-max-delay\"\n\nfetch_release() {\n    local repo=\"$1\" filter=\"$2\" tag=\"${3:-}\"\n    local json\n    local api_url=\"https://api.github.com/repos/$repo/releases/latest\"\n    [[ -n \"$tag\" ]] && api_url=\"https://api.github.com/repos/$repo/releases/tags/$tag\"\n\n    # Tentar API com --resolve (contorna DNS invalido)\n    json=$(curl -sL $GH_RESOLVE --connect-timeout 10 --max-time 20 \\\n        \"$api_url\" 2>&1) || {\n        if [[ -z \"$tag\" ]]; then\n            # Fallback: scraping da pagina HTML (funciona para alguns repos)\n            fetch_release_html \"$repo\" \"$filter\" && return 0\n        fi\n        fetch_err=\"API e fallback HTML falharam\"\n        return 1\n    }\n\n    VERSION=$(echo \"$json\" | python3 -c \"import json,sys; print(json.load(sys.stdin).get('tag_name',''))\" 2>/dev/null) || VERSION=\"\"\n    URL=$(echo \"$json\" | python3 -c \"\nimport json,sys\nfor a in json.load(sys.stdin).get('assets', []):\n    if '$filter' in a['name'] and 'zsync' not in a['name']:\n        print(a['browser_download_url'])\n        break\n\" 2>/dev/null) || URL=\"\"\n\n    if [[ -z \"$URL\" ]]; then\n        fetch_err=\"nenhum asset encontrado para: $filter\"\n        return 1\n    fi\n\n    # Canais com tag fixa (ex: firefox-devedition): a versao vem do nome do asset\n    if [[ -n \"$tag\" ]]; then\n        VERSION=$(basename \"$URL\" | sed 's/\\.AppImage$//')\n    fi\n}\n\nfetch_release_html() {\n    local repo=\"$1\" filter=\"$2\" tag=\"${3:-}\"\n\n    local release_url=\"https://github.com/$repo/releases/latest\"\n    [[ -n \"$tag\" ]] && release_url=\"https://github.com/$repo/releases/tag/$tag\"\n\n    local page_url\n    page_url=$(curl -sL --connect-timeout 10 --max-time 20 \\\n        -o /dev/null -w '%{url_effective}' \\\n        \"$release_url\") || return 1\n\n    VERSION=$(echo \"$page_url\" | sed 's|.*/tag/||')\n    [[ -z \"$VERSION\" ]] && return 1\n\n    local html\n    html=$(curl -sL --connect-timeout 10 --max-time 20 \"$page_url\") || return 1\n\n    local path\n    path=$(echo \"$html\" | python3 -c \"\nimport sys, re\nhtml = sys.stdin.read()\nrepo = '$repo'\nf = '$filter'\nfor m in re.finditer(r'href=\\\"([^\\\"]+?)\\\"', html):\n    u = m.group(1)\n    if repo in u and '/releases/download/' in u and f in u and 'zsync' not in u:\n        print(u)\n        break\n\" 2>/dev/null) || return 1\n\n    [[ -z \"$path\" ]] && return 1\n\n    if [[ \"$path\" == https://* ]]; then\n        URL=\"$path\"\n    else\n        URL=\"https://github.com$path\"\n    fi\n}\n\ndownload_app() {\n    local url=\"$1\" output=\"$2\"\n    local start elapsed bytes total_size\n    local retries=\"${DOWNLOAD_RETRIES:-8}\"\n\n    # Mostrar tamanho do arquivo antes de baixar\n    # -L: segue o redirect do GitHub (sem -L o content-length vem 0)\n    total_size=$(curl -sIL --connect-timeout 10 --max-time 15 \"$url\" 2>/dev/null \\\n        | grep -i '^content-length:' | tail -1 | awk '{print $2}' | tr -d '\\r ')\n    if [[ -n \"$total_size\" ]]; then\n        echo \"  Tamanho: $(numfmt --to=iec \"$total_size\")\"\n    fi\n\n    # Descarta .part de um download anterior que nao bate com o tamanho\n    # esperado (ex: arquivo corrompido ou URL mudou).\n    if [[ -f \"$output.part\" && -n \"$total_size\" ]]; then\n        local part_size\n        part_size=$(stat -c%s \"$output.part\" 2>/dev/null || echo 0)\n        if (( part_size > total_size )); then\n            echo \"  .part anterior invalido, descartando\"\n            rm -f \"$output.part\"\n        fi\n    fi\n\n    start=$(date +%s%N)\n    # -C -        : retoma de onde parou (arquivo .part preservado entre execucoes)\n    # --retry     : repete em erro de transitorio\n    # --speed-*   : aborta se a conexao travar (curl 28) em vez de esperar eternamente\n    if ! curl -L --connect-timeout 10 --progress-bar \\\n        -C - \\\n        --retry \"$retries\" \\\n        --retry-delay 5 \\\n        $RETRY_MAX_FLAG 60 \\\n        --retry-all-errors \\\n        --speed-time 60 --speed-limit 1024 \\\n        -o \"$output.part\" \"$url\"; then\n        # Mantem o .part: a proxima execucao retoma de onde parou.\n        fetch_err=\"download falhou (parcial preservado em $(basename \"$output\").part)\"\n        return 1\n    fi\n    elapsed=$(( ($(date +%s%N) - start) / 1000000 )) # ms\n\n    # Validacao de integridade: confere tamanho antes de instalar\n    if [[ -n \"$total_size\" ]]; then\n        local got\n        got=$(stat -c%s \"$output.part\" 2>/dev/null || echo 0)\n        if [[ \"$got\" != \"$total_size\" ]]; then\n            echo \"  Tamanho invalido: esperado $total_size, obtido $got\"\n            fetch_err=\"download incompleto (parcial preservado para retomar)\"\n            return 1\n        fi\n    fi\n\n    chmod +x \"$output.part\"\n    mv \"$output.part\" \"$output\"\n\n    bytes=$(stat -c%s \"$output\" 2>/dev/null)\n    if [[ \"$elapsed\" -gt 0 && -n \"$bytes\" && \"$bytes\" -gt 0 ]]; then\n        local speed=$(( bytes * 1000 / elapsed ))\n        DOWNLOAD_SPEED=\"$(numfmt --to=iec \"$speed\")/s\"\n        DOWNLOAD_SIZE=\"$bytes\"\n    fi\n}\n\ninstall_desktop() {\n    local name=\"$1\" exec=\"$2\" file=\"$3\" icon=\"$4\" mime=\"$5\"\n    cat > \"$DESKTOP_DIR/$file\" <<-EOF\n[Desktop Entry]\nType=Application\nName=$name\nExec=$exec %F\nIcon=$icon\nTerminal=false\nCategories=Development;Network;WebBrowser;\nMimeType=$mime\nStartupNotify=true\nEOF\n    chmod 644 \"$DESKTOP_DIR/$file\"\n}\n\ndownload_icon() {\n    local url=\"$1\" icon_name=\"$2\"\n    [[ -z \"$url\" || -z \"$icon_name\" ]] && return 1\n\n    local ext\n    ext=$(basename \"$url\" | sed 's/.*\\.//')\n    [[ -z \"$ext\" || \"$ext\" == \"$(basename \"$url\")\" ]] && ext=\"png\"\n\n    mkdir -p \"$HOME/.local/share/icons\"\n    local output=\"$HOME/.local/share/icons/${icon_name}.${ext}\"\n    curl -sL --connect-timeout 10 --max-time 20 \"$url\" -o \"$output\" 2>/dev/null && [[ -s \"$output\" ]] && return 0\n    rm -f \"$output\"\n    return 1\n}\n\ndownload_icon_from_repo() {\n    local repo=\"$1\" icon_name=\"$2\"\n    [[ -z \"$repo\" ]] && return 1\n\n    local base=\"https://raw.githubusercontent.com/$repo\"\n    local paths=(\n        \"main/.DirIcon\"\n        \"main/icon.png\"\n        \"main/icon.svg\"\n        \"main/logo.png\"\n        \"main/logo.svg\"\n        \"main/assets/icon.png\"\n        \"main/assets/icon.svg\"\n        \"main/src/resources/linux/${icon_name}.png\"\n        \"main/chrome/app/theme/${icon_name}/linux/product_logo_256.png\"\n        \"master/.DirIcon\"\n        \"master/icon.png\"\n        \"master/icon.svg\"\n        \"master/logo.png\"\n        \"master/logo.svg\"\n        \"master/assets/icon.png\"\n        \"master/assets/icon.svg\"\n        \"master/src/resources/linux/${icon_name}.png\"\n        \"master/chrome/app/theme/${icon_name}/linux/product_logo_256.png\"\n        \"dev/.DirIcon\"\n        \"dev/icon.png\"\n        \"dev/icon.svg\"\n    )\n\n    for path in \"${paths[@]}\"; do\n        local url=\"$base/$path\"\n        local http_code\n        http_code=$(curl -sI --connect-timeout 5 --max-time 10 \"$url\" 2>/dev/null | head -1 | awk '{print $2}')\n        if [[ \"$http_code\" == \"200\" || \"$http_code\" == \"302\" ]]; then\n            local ext=\"${path##*.}\"\n            mkdir -p \"$HOME/.local/share/icons\"\n            curl -sL --connect-timeout 10 --max-time 20 \"$url\" -o \"$HOME/.local/share/icons/${icon_name}.${ext}\" 2>/dev/null && return 0\n        fi\n    done\n\n    return 1\n}\n\ninstall_icon() {\n    local appimage=\"$1\" icon_name=\"$2\" repo=\"${3:-}\" icon_url=\"${4:-}\"\n    [[ -n \"$icon_name\" ]] || return 1\n\n    local existing\n    existing=$(find \"$HOME/.local/share/icons\" -maxdepth 1 -name \"${icon_name}.*\" 2>/dev/null | head -1)\n    [[ -n \"$existing\" ]] && return 0\n\n    if [[ -f \"$appimage\" ]]; then\n        local tmpdir icon_src\n        tmpdir=$(mktemp -d)\n        (cd \"$tmpdir\" && \"$appimage\" --appimage-extract) >/dev/null 2>&1 || {\n            rm -rf \"$tmpdir\"\n            try_download \"$icon_url\" \"$icon_name\" \"$repo\" && return 0\n            return 1\n        }\n\n        local root=\"$tmpdir/squashfs-root\"\n\n        if [[ -f \"$root/.DirIcon\" ]]; then\n            icon_src=\"$root/.DirIcon\"\n        else\n            icon_src=$(find \"$root\" -name \"${icon_name}.png\" -o -name \"${icon_name}.svg\" 2>/dev/null | head -1)\n        fi\n\n        if [[ -z \"$icon_src\" ]]; then\n            icon_src=$(find \"$root\" -name \"*.png\" 2>/dev/null | head -1)\n        fi\n\n        if [[ -n \"$icon_src\" ]]; then\n            # .DirIcon costuma ser um symlink: resolver para obter a extensao real\n            if [[ \"$(basename \"$icon_src\")\" == \".DirIcon\" ]]; then\n                local real_icon\n                real_icon=$(readlink -f \"$icon_src\") || real_icon=\"$icon_src\"\n                icon_src=\"$real_icon\"\n            fi\n            local ext=\"${icon_src##*.}\"\n            mkdir -p \"$HOME/.local/share/icons\"\n            cp \"$icon_src\" \"$HOME/.local/share/icons/${icon_name}.${ext}\"\n            rm -rf \"$tmpdir\"\n            return 0\n        fi\n\n        rm -rf \"$tmpdir\"\n    fi\n\n    try_download \"$icon_url\" \"$icon_name\" \"$repo\" && return 0\n    return 1\n}\n\ntry_download() {\n    local icon_url=\"$1\" icon_name=\"$2\" repo=\"$3\"\n    if [[ -n \"$icon_url\" ]]; then\n        download_icon \"$icon_url\" \"$icon_name\" && return 0\n    fi\n    if [[ -n \"$repo\" ]]; then\n        download_icon_from_repo \"$repo\" \"$icon_name\" && return 0\n    fi\n    return 1\n}\n\n# \u2500\u2500 Painel XFCE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nPANEL_DIR=\"$HOME/.config/xfce4/panel\"\nPANEL_XML=\"$HOME/.config/xfce4/xfconf/xfce-perchannel-xml/xfce4-panel.xml\"\n\nensure_panel_launchers() {\n    PANEL_ADDED=0\n    [[ -d \"$PANEL_DIR\" ]] || { echo \"  Painel XFCE nao encontrado ($PANEL_DIR)\"; return 0; }\n    [[ -f \"$PANEL_XML\" ]] || { echo \"  Config do painel nao encontrada ($PANEL_XML)\"; return 0; }\n\n    local toadd=()\n    local entry repo filter filename label desktop icon mime icon_url release_tag atype aurl\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        [[ \"$atype\" == \"curl\" ]] && continue\n        local output=\"$APP_DIR/$filename\"\n        [[ -f \"$output\" ]] || continue\n\n        local pinned=\"\" f\n        shopt -s nullglob\n        for f in \"$PANEL_DIR\"/launcher-*/*.desktop; do\n            [[ -f \"$f\" ]] || continue\n            if grep -q \"^X-XFCE-Source=file://$DESKTOP_DIR/$desktop$\" \"$f\" 2>/dev/null; then\n                pinned=1\n                break\n            fi\n            local fname_label fname_exec\n            fname_label=$(grep -m1 '^Name=' \"$f\" 2>/dev/null | sed 's|^Name=||')\n            fname_exec=$(grep -m1 '^Exec=' \"$f\" 2>/dev/null | sed 's|^Exec=||;s| *%F$||')\n            if [[ -n \"$fname_label\" ]] && {\n                [[ \"$fname_label\" == \"$label\" ]] ||\n                [[ \"${label,,}\" == *\"${fname_label,,}\"* ]] ||\n                [[ \"${fname_label,,}\" == *\"${label,,}\"* ]]; }; then\n                pinned=1\n                break\n            fi\n            if [[ \"$fname_exec\" == \"$APP_DIR/$filename\" ]]; then\n                pinned=1\n                break\n            fi\n        done\n        shopt -u nullglob\n        [[ -z \"$pinned\" ]] || continue\n\n        toadd+=(\"$desktop|$DESKTOP_DIR/$desktop|$label\")\n    done\n\n    [[ ${#toadd[@]} -eq 0 ]] && { PANEL_ADDED=0; return 0; }\n\n    echo \"  Adicionando launchers novos no painel XFCE...\"\n\n    # Ler config (somente leitura) para descobrir proximo id de plugin e painel alvo\n    local meta\n    meta=$(python3 - \"$PANEL_XML\" 2>&1 <<'PY'\nimport re, sys, xml.etree.ElementTree as ET\n\ntree = ET.parse(sys.argv[1])\nroot = tree.getroot()\n\ndef props(el, name):\n    return [c for c in list(el) if c.get('name') == name]\n\nplugins = props(root, 'plugins')\npanels = props(root, 'panels')\nif not plugins or not panels:\n    print('', file=sys.stderr)\n    sys.exit(1)\nplugins, panels = plugins[0], panels[0]\n\nplugin_map = {}\nfor p in list(plugins):\n    m = re.fullmatch(r'plugin-(\\d+)', p.get('name') or '')\n    if m:\n        plugin_map[int(m.group(1))] = p\n\npanel_elms = [c for c in list(panels) if c.tag == 'property'\n              and (c.get('name') or '').startswith('panel-')]\n\ndef panel_ids(pp):\n    ids = []\n    for pi in props(pp, 'plugin-ids'):\n        for v in list(pi):\n            if v.tag == 'value':\n                ids.append(int(v.get('value')))\n    return ids\n\nused = set(plugin_map)\nfor pp in panel_elms:\n    used |= set(panel_ids(pp))\n\ntarget = None\nfor pp in panel_elms:\n    if any(i in plugin_map and plugin_map[i].get('value') == 'launcher'\n           for i in panel_ids(pp)):\n        target = pp\n        break\nif target is None and panel_elms:\n    target = max(panel_elms, key=lambda pp: len(panel_ids(pp)))\nif target is None:\n    print('', file=sys.stderr)\n    sys.exit(1)\n\ntarget_num = re.fullmatch(r'panel-(\\d+)', target.get('name')).group(1)\nnext_id = max(used) + 1 if used else 1\nprint('%d|%s|%s' % (next_id, target_num,\n                    ' '.join(str(i) for i in panel_ids(target))))\nPY\n    ) || [[ \"$meta\" =~ ^[0-9]+\\|panel-[0-9]+\\| ]] || {\n        echo \"  Erro ao ler config do painel\"\n        PANEL_ADDED=0\n        return 1\n    }\n\n    local next_id panel_target cur_ids\n    IFS='|' read -r next_id panel_target cur_ids <<< \"$meta\"\n\n    local item desktop src label ldir fname ok=0\n    for item in \"${toadd[@]}\"; do\n        desktop=\"${item%%|*}\"\n        label=\"${item##*|}\"\n        src=\"$DESKTOP_DIR/$desktop\"\n        ldir=\"$PANEL_DIR/launcher-$next_id\"\n        fname=\"$next_id.desktop\"\n\n        mkdir -p \"$ldir\"\n        cat \"$src\" > \"$ldir/$fname\"\n        if ! grep -q '^X-XFCE-Source=' \"$ldir/$fname\" 2>/dev/null; then\n            echo \"X-XFCE-Source=file://$src\" >> \"$ldir/$fname\"\n        fi\n        chmod 644 \"$ldir/$fname\"\n\n        xfconf-query -c xfce4-panel -p \"/plugins/plugin-$next_id\" \\\n            -n -t string -s launcher &&\n        xfconf-query -c xfce4-panel -p \"/plugins/plugin-$next_id/items\" \\\n            -n -a -t string -s \"$fname\" || {\n            echo \"  Painel XFCE: erro ao registrar plugin-$next_id ($label)\"\n            PANEL_ADDED=0\n            return 1\n        }\n\n        cur_ids=\"$cur_ids $next_id\"\n        echo \"  Painel XFCE: $label fixado no painel\"\n        ok=1\n        next_id=$((next_id + 1))\n    done\n\n    # Atualizar plugin-ids do painel alvo com os novos plugins\n    local args=(-c xfce4-panel -p \"/panels/panel-$panel_target/plugin-ids\")\n    local i\n    for i in $cur_ids; do\n        args+=(-t int -s \"$i\")\n    done\n    xfconf-query \"${args[@]}\" || {\n        echo \"  Painel XFCE: erro ao atualizar plugin-ids do painel-$panel_target\"\n        PANEL_ADDED=0\n        return 1\n    }\n\n    [[ \"$ok\" -eq 1 ]] && PANEL_ADDED=1\n    return 0\n}\n\nsync_panel_launchers() {\n    PANEL_ADDED=0\n    [[ -d \"$PANEL_DIR\" ]] || { echo \"  Painel XFCE nao encontrado ($PANEL_DIR)\"; return 0; }\n\n    local updated=0\n    shopt -s nullglob\n    for launcher in \"$PANEL_DIR\"/launcher-*; do\n        for f in \"$launcher\"/*.desktop; do\n            [[ -f \"$f\" ]] || continue\n\n            local source\n            source=$(grep '^X-XFCE-Source=' \"$f\" 2>/dev/null | head -1 | sed 's|^X-XFCE-Source=||')\n            [[ -n \"$source\" ]] || continue\n\n            for entry in \"${APPS_DATA[@]}\"; do\n                IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n                [[ \"$atype\" == \"curl\" ]] && continue\n                [[ \"$source\" == \"file://$DESKTOP_DIR/$desktop\" ]] || continue\n\n                local output=\"$APP_DIR/$filename\"\n                [[ -f \"$output\" ]] || continue\n\n                local comment=\"\" wmclass=\"\"\n                comment=$(grep '^Comment=' \"$f\" | head -1 | sed 's|^Comment=||' 2>/dev/null)\n                wmclass=$(grep '^StartupWMClass=' \"$f\" | head -1 | sed 's|^StartupWMClass=||' 2>/dev/null)\n\n                {\n                    echo \"[Desktop Entry]\"\n                    echo \"Type=Application\"\n                    echo \"Name=$label\"\n                    [[ -n \"$comment\" ]] && echo \"Comment=$comment\"\n                    echo \"Exec=$output %F\"\n                    echo \"Icon=$icon\"\n                    echo \"Terminal=false\"\n                    echo \"Categories=Development;Network;WebBrowser;\"\n                    echo \"MimeType=$mime\"\n                    echo \"StartupNotify=true\"\n                    [[ -n \"$wmclass\" ]] && echo \"StartupWMClass=$wmclass\"\n                    echo \"X-XFCE-Source=$source\"\n                } > \"$f\"\n                chmod 644 \"$f\"\n\n                echo \"  Painel XFCE: $f atualizado\"\n                updated=1\n                break\n            done\n        done\n    done\n    shopt -u nullglob\n\n    ensure_panel_launchers\n\n    if [[ \"$updated\" -eq 1 || \"$PANEL_ADDED\" -eq 1 ]] && command -v xfce4-panel &>/dev/null; then\n        xfce4-panel -r 2>/dev/null || true\n        echo \"  Painel XFCE reiniciado para aplicar as mudancas\"\n    fi\n    return 0\n}\n\n# \u2500\u2500 Status / List \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nlist_installed() {\n    echo \"\"\n    echo \"\u2550\u2550\u2550 Apps Instalados \u2550\u2550\u2550\"\n    echo \"\"\n    local found=0\n    local outdated=0\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        local vfile=\"$output.version\"\n        if [[ -f \"$output\" ]]; then\n            found=1\n            local version=\"\"\n            [[ -f \"$vfile\" ]] && version=$(cat \"$vfile\")\n            echo \"  $label\"\n            echo \"    Arquivo: $filename ($(numfmt --to=iec \"$(stat -c%s \"$output\" 2>/dev/null)\" 2>/dev/null || echo \"?\"))\"\n            if [[ -n \"$version\" ]]; then\n                echo \"    Versao: $version\"\n            elif [[ \"$atype\" == \"curl\" ]] && command -v \"$output\" >/dev/null 2>&1; then\n                echo \"    Versao: $(\"$output\" --version 2>/dev/null | head -1)\"\n            else\n                echo \"    Versao: desconhecida\"\n            fi\n        fi\n    done\n    [[ \"$found\" -eq 0 ]] && echo \"  Nenhum AppImage instalado em $APP_DIR\"\n    echo \"\"\n}\n\n# \u2500\u2500 Uninstall \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nuninstall_app() {\n    local target_label=\"$1\"\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime atype aurl <<< \"$entry\"\n        if [[ \"$label\" == \"$target_label\" ]]; then\n            local output\n            if [[ \"$atype\" == \"curl\" ]]; then\n                output=\"$HOME/.opencode/bin/opencode\"\n            else\n                output=\"$APP_DIR/$filename\"\n            fi\n            local vfile=\"$output.version\"\n            local removed=0\n\n            if [[ -f \"$output\" ]]; then\n                rm -f \"$output\" && echo \"  Removido: $output\" && removed=1\n            fi\n            if [[ -f \"$vfile\" ]]; then\n                rm -f \"$vfile\" && echo \"  Removido: $vfile\"\n            fi\n            if [[ -f \"$DESKTOP_DIR/$desktop\" ]]; then\n                rm -f \"$DESKTOP_DIR/$desktop\" && echo \"  Removido: $DESKTOP_DIR/$desktop\"\n            fi\n\n            local icon_file\n            icon_file=$(find \"$HOME/.local/share/icons\" -maxdepth 1 -name \"${icon}.*\" 2>/dev/null | head -1)\n            if [[ -n \"$icon_file\" ]]; then\n                rm -f \"$icon_file\" && echo \"  Removido: $icon_file\"\n            fi\n\n            # Atalhos de nome curto (se houver)\n            local names=\"${APP_COMMANDS[$filename]:-}\"\n            local n\n            for n in $names; do\n                if [[ -L \"$HOME/.local/bin/$n\" ]]; then\n                    rm -f \"$HOME/.local/bin/$n\" && echo \"  Removido: ~/.local/bin/$n\"\n                fi\n            done\n\n            if [[ \"$removed\" -eq 0 ]]; then\n                echo \"  '$label' nao esta instalado.\"\n            else\n                echo \"  '$label' desinstalado com sucesso.\"\n            fi\n            return 0\n        fi\n    done\n    echo \"  App '$target_label' nao encontrado.\"\n}\n\nuninstall_menu() {\n    local installed=()\n    local labels=()\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        if [[ -f \"$output\" ]]; then\n            installed+=(\"$entry\")\n            labels+=(\"$label\")\n        fi\n    done\n\n    if [[ ${#installed[@]} -eq 0 ]]; then\n        echo \"\"\n        echo \"Nenhum app instalado para desinstalar.\"\n        return\n    fi\n\n    echo \"\"\n    echo \"\u2550\u2550\u2550 Desinstalar App \u2550\u2550\u2550\"\n    echo \"\"\n    for i in \"${!labels[@]}\"; do\n        echo \"  $((i+1))) ${labels[$i]}\"\n    done\n    echo \"  q) Cancelar\"\n    echo \"\"\n    read -rp \"Escolha um app para desinstalar: \" choice\n\n    [[ \"$choice\" == \"q\" ]] && return\n\n    if [[ \"$choice\" =~ ^[0-9]+$ ]] && [[ \"$choice\" -ge 1 ]] && [[ \"$choice\" -le ${#labels[@]} ]]; then\n        local idx=$((choice-1))\n        local label=\"${labels[$idx]}\"\n        echo \"\"\n        read -rp \"Tem certeza que deseja desinstalar '$label'? (s/N): \" confirm\n        if [[ \"$confirm\" == \"s\" || \"$confirm\" == \"S\" ]]; then\n            uninstall_app \"$label\"\n        else\n            echo \"Cancelado.\"\n        fi\n    else\n        echo \"Opcao invalida.\"\n    fi\n}\n\n# \u2500\u2500 Menu \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nshow_menu() {\n    while true; do\n        echo \"\"\n        echo \"\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\n        echo \"\u2551      Gerenciador de AppImages        \u2551\"\n        echo \"\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\n        echo \"\"\n        echo \"1) Atualizar todos os apps\"\n        echo \"2) Registrar no sistema (usuario)\"\n        echo \"3) Listar apps instalados e status\"\n        echo \"4) Desinstalar um app\"\n        echo \"5) Atualizar lancadores no painel XFCE\"\n        echo \"6) Criar/atualizar atalhos (comandos)\"\n        echo \"7) Sair\"\n        echo \"\"\n        read -rp \"Escolha uma opcao: \" choice\n\n        case \"$choice\" in\n            1) update_all ;;\n            2) register_system ;;\n            3) list_installed ;;\n            4) uninstall_menu ;;\n            5) sync_panel_launchers ;;\n            6) ensure_commands ;;\n            7) echo \"\"; exit 0 ;;\n            *) echo \"Opcao invalida.\" ;;\n        esac\n        echo \"\"\n        read -rp \"Pressione Enter para continuar...\"\n    done\n}\n\n# \u2500\u2500 Comandos (symlinks curtos em $BIN_DIR) \u2500\u2500\u2500\u2500\u2500\n\n# Cria atalhos de nome curto (ex: chromium, edge) apontando para os AppImages.\n# Nomes vindos de APP_COMMANDS. Idempotente: atualiza o alvo se ja existir.\nensure_commands() {\n    local dir=\"${BIN_DIR:-$HOME/.local/bin}\"\n    mkdir -p \"$dir\"\n\n    local made=() skipped=()\n    local entry repo filter filename label desktop icon mime icon_url release_tag atype aurl\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        [[ -f \"$output\" ]] || continue\n\n        local names=\"${APP_COMMANDS[$filename]:-}\"\n        [[ -n \"$names\" ]] || continue\n\n        local n\n        for n in $names; do\n            # Nunca sobrescreve um arquivo real (so symlink antigo ou ausente)\n            if [[ -e \"$dir/$n\" && ! -L \"$dir/$n\" ]]; then\n                skipped+=(\"$n\")\n                continue\n            fi\n            ln -sfn \"$output\" \"$dir/$n\"\n            made+=(\"$n\")\n        done\n    done\n\n    [[ ${#made[@]} -gt 0 ]] && echo \"  Atalhos em $dir: ${made[*]}\"\n    [[ ${#skipped[@]} -gt 0 ]] && echo \"  (nao sobrescritos, ja existem e nao sao symlink): ${skipped[*]}\"\n    return 0\n}\n\n# \u2500\u2500 Register (sistema, sem sudo) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nregister_system() {\n    echo \"\"\n    echo \"Registrando AppImages no sistema (usuario)...\"\n    mkdir -p \"$DESKTOP_DIR\" \"$HOME/.local/share/icons\" \"$HOME/.local/bin\"\n    echo \"\"\n\n    local FAIL=0\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n\n        if [[ \"$atype\" == \"curl\" ]]; then\n            # App instalado por script (nao e AppImage)\n            local cli_bin=\"$HOME/.opencode/bin/opencode\"\n            echo \"--- $label ---\"\n            if [[ -f \"$cli_bin\" ]]; then\n                echo \"  ja instalado ($(\"$cli_bin\" --version 2>/dev/null | head -1))\"\n            else\n                echo \"  nao instalado \u2014 use: Atualizar todos os apps\"\n            fi\n            if [[ -n \"$desktop\" && -f \"$DESKTOP_DIR/$desktop\" ]]; then\n                echo \"  .desktop: $DESKTOP_DIR/$desktop\"\n            fi\n            echo \"\"\n            continue\n        fi\n\n        local output=\"$APP_DIR/$filename\"\n        if [[ ! -f \"$output\" ]]; then\n            echo \"  $label: nao instalado (pulando)\"\n            continue\n        fi\n\n        echo \"--- $label ---\"\n        chmod +x \"$output\" 2>/dev/null || true\n        install_desktop \"$label\" \"$output\" \"$desktop\" \"$icon\" \"$mime\"\n        echo \"  .desktop: $DESKTOP_DIR/$desktop\"\n        if install_icon \"$output\" \"$icon\" \"$repo\" \"$icon_url\"; then\n            echo \"  Icone instalado\"\n        else\n            echo \"  Icone nao instalado\"\n        fi\n        ln -sf \"$output\" \"$HOME/.local/bin/$filename\" && echo \"  Symlink: ~/.local/bin/$filename\"\n        echo \"\"\n    done\n\n    ensure_commands\n\n    command -v update-desktop-database &>/dev/null && update-desktop-database \"$DESKTOP_DIR\" 2>/dev/null || true\n    command -v gtk-update-icon-cache &>/dev/null && gtk-update-icon-cache \"$HOME/.local/share/icons\" 2>/dev/null || true\n\n    case \":$PATH:\" in\n        *\":$HOME/.local/bin:\"*) : ;;\n        *) export PATH=\"$HOME/.local/bin:$PATH\" ;;\n    esac\n    if ! grep -q 'HOME/.local/bin' \"$HOME/.bashrc\" 2>/dev/null; then\n        echo 'export PATH=\"$HOME/.local/bin:$PATH\"' >> \"$HOME/.bashrc\"\n        echo \"  ~/.local/bin adicionado ao PATH (arquivo ~/.bashrc atualizado)\"\n    fi\n\n    echo \"Pronto. Apps visiveis no menu e no terminal (reabra a sessao se necessario).\"\n    echo \"\"\n    sync_panel_launchers\n    return \"$FAIL\"\n}\n\n# \u2500\u2500 Main \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nupdate_all() {\n    echo \"\"\n    echo \"Atualizador de AppImages \u2014 $(date '+%Y-%m-%d %H:%M:%S')\"\n    echo \"Diretorio: $APP_DIR\"\n    echo \"\"\n\n    local FAIL=0\n\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        echo \"--- $label ---\"\n\n        # \u2500\u2500 Apps instalados via script (curl) \u2500\u2500\n        if [[ \"$atype\" == \"curl\" ]]; then\n            local cli_bin=\"$HOME/.opencode/bin/opencode\"\n            local cli_vfile=\"$HOME/.opencode/bin/opencode.version\"\n\n            printf \"  Instalador... \"\n            if install_curl_app \"$aurl\"; then\n                if [[ -x \"$cli_bin\" ]]; then\n                    VERSION=$(\"$cli_bin\" --version 2>/dev/null | head -1)\n                    echo \"$VERSION\" > \"$cli_vfile\"\n                    echo \"OK ($VERSION)\"\n                else\n                    echo \"FALHOU (binario nao encontrado em $cli_bin)\"\n                    FAIL=1\n                fi\n            else\n                echo \"FALHOU (${fetch_err:-erro desconhecido})\"\n                FAIL=1\n                continue\n            fi\n\n            if [[ -n \"$desktop\" ]]; then\n                install_desktop \"$label\" \"$cli_bin\" \"$desktop\" \"$icon\" \"$mime\"\n                echo \"  .desktop criado\"\n            fi\n            echo \"\"\n            continue\n        fi\n\n        printf \"  Release... \"\n        VERSION=\"\" URL=\"\" fetch_err=\"\"\n        if fetch_release \"$repo\" \"$filter\" \"$release_tag\"; then\n            echo \"$VERSION\"\n        else\n            echo \"FALHOU ($fetch_err)\"\n            FAIL=1\n            continue\n        fi\n\n        local output=\"$APP_DIR/$filename\"\n        local vfile=\"$output.version\"\n\n        if [[ -f \"$vfile\" ]] && [[ \"$(cat \"$vfile\")\" == \"$VERSION\" ]] && [[ -f \"$output\" ]]; then\n            echo \"  Ja atualizado ($VERSION)\"\n            # Garante que vers\u00e3o seja salva mesmo se arquivo antigo n\u00e3o tinha .version\n            echo \"$VERSION\" > \"$vfile\"\n        else\n            echo \"  Baixando... \"\n            if download_app \"$URL\" \"$output\"; then\n                echo \"  OK ($(numfmt --to=iec \"$DOWNLOAD_SIZE\") em ${DOWNLOAD_SPEED:-?})\"\n                echo \"$VERSION\" > \"$vfile\"\n            else\n                echo \"  FALHOU\"\n                FAIL=1\n                continue\n            fi\n        fi\n\n        install_desktop \"$label\" \"$output\" \"$desktop\" \"$icon\" \"$mime\"\n        echo \"  .desktop criado\"\n        if [[ -f \"$output\" ]]; then\n            install_icon \"$output\" \"$icon\" \"$repo\" \"$icon_url\" && echo \"  Icone instalado\" || echo \"  Icone nao instalado\"\n        fi\n\n        if command -v xdg-settings &>/dev/null; then\n            case \"$label\" in\n                \"Firefox Developer Edition\")\n                    xdg-settings set default-web-browser \"$desktop\" 2>/dev/null || true\n                    ;;\n            esac\n        fi\n\n        echo \"\"\n    done\n\n    command -v update-desktop-database &>/dev/null && update-desktop-database \"$DESKTOP_DIR\" 2>/dev/null || true\n    command -v gtk-update-icon-cache &>/dev/null && gtk-update-icon-cache \"$HOME/.local/share/icons\" 2>/dev/null || true\n\n    ensure_commands\n\n    echo \"\"\n    echo \"---\"\n    echo \"Sincronizando lancadores do painel XFCE...\"\n    sync_panel_launchers\n\n    echo \"---\"\n    echo \"Status: $([ \"$FAIL\" -eq 0 ] && echo \"Sucesso\" || echo \"Falha em algum item\")\"\n    echo \"Log: $LOGFILE\"\n    return \"$FAIL\"\n}\n\n# \u2500\u2500 Entrypoint \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ncase \"$MODE\" in\n    menu) show_menu ;;\n    status) list_installed ;;\n    uninstall) uninstall_app \"$UNINSTALL_APP\" ;;\n    register) register_system ;;\n    links) ensure_commands ;;\n    panel) sync_panel_launchers ;;\n    update) update_all ;;\nesac\n", "system_scripts/xrandr-config.sh": "#!/usr/bin/env bash\n\nLOG_FILE=\"$HOME/.local/share/xrandr-config.log\"\nPRESETS_DIR=\"$HOME/.local/share/xrandr-presets\"\nmkdir -p \"$(dirname \"$LOG_FILE\")\" \"$PRESETS_DIR\"\n\nlog() {\n    local msg=\"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"\n    echo \"$msg\" | tee -a \"$LOG_FILE\"\n}\n\nget_outputs() {\n    xrandr --query 2>/dev/null | awk '/ connected/ {print $1}'\n}\n\nget_modes() {\n    local output=\"$1\"\n    xrandr --query 2>/dev/null | sed -n \"/^$output/,/^[^ ]/p\" | grep -E '^\\s+[0-9]+x[0-9]+' | awk '{print $1}' | sort -u\n}\n\nlist_outputs() {\n    echo\n    echo \"=== DISPLAYS DETECTADOS ===\"\n    xrandr --query 2>/dev/null | while read -r line; do\n        if echo \"$line\" | grep -q \" connected\"; then\n            local out=$(echo \"$line\" | awk '{print $1}')\n            local res=$(echo \"$line\" | awk '{print $3}')\n            printf \"  \\e[1;32m%s\\e[0m  %s\\n\" \"$out\" \"$res\"\n        elif echo \"$line\" | grep -q \" disconnected\"; then\n            local out=$(echo \"$line\" | awk '{print $1}')\n            printf \"  \\e[1;31m%s\\e[0m  desconectado\\n\" \"$out\"\n        fi\n    done\n    echo\n}\n\nlist_modes() {\n    local output=\"$1\"\n    echo\n    echo \"=== RESOLUCOES DISPONIVEIS: $output ===\"\n    local i=1\n    while IFS= read -r mode; do\n        printf \"  %2d) %s\\n\" \"$i\" \"$mode\"\n        i=$((i + 1))\n    done < <(get_modes \"$output\")\n    echo\n}\n\nmirror() {\n    local primary=\"$1\" secondary=\"$2\" mode=\"$3\"\n    log \"MIRROR: $secondary -> $primary @ $mode\"\n    xrandr --output \"$secondary\" --same-as \"$primary\" --mode \"$mode\"\n    log \"OK: mirror $primary <- $secondary ($mode)\"\n}\n\nextend() {\n    local primary=\"$1\" secondary=\"$2\" dir=\"$3\" mode=\"$4\"\n    log \"EXTEND: $secondary $dir de $primary @ $mode\"\n    xrandr --output \"$secondary\" --mode \"$mode\" \"--$dir-of\" \"$primary\"\n    log \"OK: extend $secondary $dir de $primary ($mode)\"\n}\n\nsingle() {\n    local output=\"$1\" mode=\"$2\"\n    log \"SINGLE: apenas $output @ $mode\"\n    local others=()\n    for o in $(get_outputs); do\n        [ \"$o\" != \"$output\" ] && others+=(\"$o\")\n    done\n    xrandr --output \"$output\" --mode \"$mode\"\n    for o in \"${others[@]}\"; do\n        xrandr --output \"$o\" --off\n    done\n    log \"OK: single $output ($mode), demais desligados\"\n}\n\nturn_off() {\n    local output=\"$1\"\n    log \"OFF: $output\"\n    xrandr --output \"$output\" --off\n    log \"OK: $output desligado\"\n}\n\npreset_save() {\n    local name=\"$1\"\n    local file=\"$PRESETS_DIR/$name.conf\"\n    > \"$file\"\n    for o in $(get_outputs); do\n        local state line\n        line=$(xrandr --query 2>/dev/null | grep \"^$o \")\n        state=$(echo \"$line\" | awk '{print $2}')\n        if [ \"$state\" = \"connected\" ]; then\n            local res=$(echo \"$line\" | awk '{print $3}' | cut -d+ -f1)\n            local pos=$(echo \"$line\" | awk '{print $3}' | grep -o '+[0-9]++[0-9]' | tr '+' ' ')\n            local primary=\"\"\n            echo \"$line\" | grep -q \"primary\" && primary=\"--primary\"\n            echo \"$o $res $primary\" >> \"$file\"\n        fi\n    done\n    log \"PRESET SALVO: $name\"\n}\n\npreset_load() {\n    local name=\"$1\"\n    local file=\"$PRESETS_DIR/$name.conf\"\n    [ ! -f \"$file\" ] && { error \"Preset '$name' nao encontrado\"; return 1; }\n\n    for o in $(get_outputs); do\n        xrandr --output \"$o\" --off 2>/dev/null\n    done\n\n    while read -r output res primary; do\n        [ -z \"$output\" ] && continue\n        xrandr --output \"$output\" --mode \"$res\" $primary 2>/dev/null\n    done < \"$file\"\n\n    # re-apply mirror/positions\n    local first_out=\"\" first_res=\"\"\n    while read -r output res primary; do\n        [ -z \"$first_out\" ] && { first_out=\"$output\"; first_res=\"$res\"; continue; }\n        xrandr --output \"$output\" --same-as \"$first_out\" --mode \"$res\" 2>/dev/null\n    done < \"$file\"\n\n    log \"PRESET CARREGADO: $name\"\n    xrandr --query 2>/dev/null | grep \" connected\" | tee -a \"$LOG_FILE\"\n}\n\npreset_list() {\n    shopt -s nullglob\n    local files=(\"$PRESETS_DIR\"/*.conf)\n    shopt -u nullglob\n    [ ${#files[@]} -eq 0 ] && return\n    for f in \"${files[@]}\"; do\n        basename \"$f\" .conf\n    done\n}\n\npreset_save_current() {\n    local name\n    read -rp \"Nome do preset: \" name\n    [ -z \"$name\" ] && { error \"Nome invalido\"; return; }\n    preset_save \"$name\"\n    echo -e \"\\e[1;32mPreset '$name' salvo!\\e[0m\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\npreset_load_menu() {\n    shopt -s nullglob\n    local files=(\"$PRESETS_DIR\"/*.conf)\n    shopt -u nullglob\n    if [ ${#files[@]} -eq 0 ]; then\n        error \"Nenhum preset salvo\"\n        sleep 1\n        return\n    fi\n    echo\n    echo \"--- PRESETS DISPONIVEIS ---\"\n    local i=1 names=()\n    for f in \"${files[@]}\"; do\n        local n\n        n=$(basename \"$f\" .conf)\n        names+=(\"$n\")\n        echo \"  $i) $n\"\n        i=$((i + 1))\n    done\n    read -rp \"Escolha o numero: \" sel\n    if [[ \"$sel\" =~ ^[0-9]+$ ]] && [ \"$sel\" -ge 1 ] && [ \"$sel\" -le ${#names[@]} ]; then\n        preset_load \"${names[$((sel - 1))]}\"\n        echo -e \"\\e[1;32mPreset '${names[$((sel - 1))]}' carregado!\\e[0m\"\n    else\n        error \"Opcao invalida\"\n    fi\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nquick_hdmi_full() {\n    log \"QUICK: HDMI 1920x1080 + eDP mirror\"\n    local edp_mode=\"1366x768\"\n    xrandr --output eDP-1 --off 2>/dev/null\n    xrandr --output HDMI-1 --mode 1920x1080 2>/dev/null\n    xrandr --output eDP-1 --same-as HDMI-1 --mode \"$edp_mode\" 2>/dev/null\n    log \"OK: HDMI 1920x1080 espelhando eDP-1 $edp_mode\"\n    xrandr --query | grep \" connected\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nquick_hdmi_1360() {\n    log \"QUICK: HDMI 1360x768 + eDP mirror\"\n    local edp_mode=\"1366x768\"\n    xrandr --output eDP-1 --off 2>/dev/null\n    xrandr --output HDMI-1 --mode 1360x768 2>/dev/null\n    xrandr --output eDP-1 --same-as HDMI-1 --mode \"$edp_mode\" 2>/dev/null\n    log \"OK: HDMI 1360x768 espelhando eDP-1 $edp_mode\"\n    xrandr --query | grep \" connected\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nerror() {\n    echo -e \"\\e[1;31mERRO: $*\\e[0m\" >&2\n}\n\nmenu_principal() {\n    local outputs\n    mapfile -t outputs < <(get_outputs)\n    [ ${#outputs[@]} -eq 0 ] && { error \"Nenhum display detectado\"; exit 1; }\n\n    while true; do\n        clear\n        echo \"==========================================\"\n        echo \"       CONFIGURACAO DE VIDEO (XRANDR)     \"\n        echo \"==========================================\"\n        list_outputs\n        echo \"ESCOLHA UMA OPCAO:\"\n        echo\n        echo \"  QUICK CONFIGS:\"\n        echo \"  hdmi_best) HDMI 1920x1080 + eDP mirror (full HD)\"\n        echo \"  edp_best)  HDMI 1360x768 + eDP mirror (resolucao interna)\"\n        echo \"  ---\"\n        echo \"  1) Espelhar (mirror)\"\n        echo \"  2) Estender (extend)\"\n        echo \"  3) Apenas um display (single)\"\n        echo \"  4) Desligar um display\"\n        echo \"  5) Auto-detect (--auto)\"\n        echo \"  6) Carregar preset\"\n        echo \"  7) Salvar preset atual\"\n        echo \"  8) Sair\"\n        echo\n        read -rp \"Opcao: \" opt\n\n        case \"$opt\" in\n            hdmi_best) quick_hdmi_full ;;\n            edp_best)  quick_hdmi_1360 ;;\n            1) menu_mirror \"${outputs[@]}\" ;;\n            2) menu_extend \"${outputs[@]}\" ;;\n            3) menu_single \"${outputs[@]}\" ;;\n            4) menu_off \"${outputs[@]}\" ;;\n            5) auto_detect \"${outputs[@]}\" ;;\n            6) preset_load_menu ;;\n            7) preset_save_current ;;\n            8) log \"Saindo\"; exit 0 ;;\n            *) error \"Opcao invalida\"; sleep 1 ;;\n        esac\n    done\n}\n\nescolher_output() {\n    local prompt=\"$1\"; shift\n    local outputs=(\"$@\")\n    local i=1\n    for o in \"${outputs[@]}\"; do\n        echo \"  $i) $o\"\n        i=$((i + 1))\n    done\n    read -rp \"$prompt: \" sel\n    if [[ \"$sel\" =~ ^[0-9]+$ ]] && [ \"$sel\" -ge 1 ] && [ \"$sel\" -le ${#outputs[@]} ]; then\n        echo \"${outputs[$((sel - 1))]}\"\n    else\n        return 1\n    fi\n}\n\nescolher_modo() {\n    local output=\"$1\"\n    local modes=()\n    while IFS= read -r m; do\n        modes+=(\"$m\")\n    done < <(get_modes \"$output\")\n    [ ${#modes[@]} -eq 0 ] && { error \"Nenhum modo encontrado para $output\"; return 1; }\n\n    list_modes \"$output\"\n    read -rp \"Escolha o numero da resolucao (Enter=primeira): \" sel\n    if [ -z \"$sel\" ]; then\n        echo \"${modes[0]}\"\n    elif [[ \"$sel\" =~ ^[0-9]+$ ]] && [ \"$sel\" -ge 1 ] && [ \"$sel\" -le ${#modes[@]} ]; then\n        echo \"${modes[$((sel - 1))]}\"\n    else\n        error \"Selecao invalida\"\n        return 1\n    fi\n}\n\nmenu_mirror() {\n    local outputs=(\"$@\")\n    [ ${#outputs[@]} -lt 2 ] && { error \"Precisa de pelo menos 2 displays para espelhar\"; sleep 1; return; }\n    echo\n    echo \"--- ESPELHAR ---\"\n    echo \"Display principal (origem):\"\n    local primary\n    primary=$(escolher_output \"Numero\" \"${outputs[@]}\") || return\n    local secundarios=()\n    for o in \"${outputs[@]}\"; do [ \"$o\" != \"$primary\" ] && secundarios+=(\"$o\"); done\n    echo \"Display para espelhar:\"\n    local secondary\n    secondary=$(escolher_output \"Numero\" \"${secundarios[@]}\") || return\n    local mode\n    mode=$(escolher_modo \"$primary\") || return\n    mirror \"$primary\" \"$secondary\" \"$mode\"\n    log \"MENU: mirror concluido\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nmenu_extend() {\n    local outputs=(\"$@\")\n    [ ${#outputs[@]} -lt 2 ] && { error \"Precisa de pelo menos 2 displays para estender\"; sleep 1; return; }\n    echo\n    echo \"--- ESTENDER ---\"\n    echo \"Display principal:\"\n    local primary\n    primary=$(escolher_output \"Numero\" \"${outputs[@]}\") || return\n    local secundarios=()\n    for o in \"${outputs[@]}\"; do [ \"$o\" != \"$primary\" ] && secundarios+=(\"$o\"); done\n    echo \"Display secundario:\"\n    local secondary\n    secondary=$(escolher_output \"Numero\" \"${secundarios[@]}\") || return\n    local mode\n    mode=$(escolher_modo \"$secondary\") || return\n    echo \"Direcao: 1) right-of  2) left-of  3) above  4) below\"\n    read -rp \"Opcao (1-4): \" dir\n    case \"$dir\" in\n        1) d=\"right\" ;;\n        2) d=\"left\" ;;\n        3) d=\"above\" ;;\n        4) d=\"below\" ;;\n        *) d=\"right\" ;;\n    esac\n    extend \"$primary\" \"$secondary\" \"$d\" \"$mode\"\n    log \"MENU: extend concluido\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nmenu_single() {\n    local outputs=(\"$@\")\n    echo\n    echo \"--- APENAS UM DISPLAY ---\"\n    local target\n    target=$(escolher_output \"Numero do display que ficara ativo\" \"${outputs[@]}\") || return\n    local mode\n    mode=$(escolher_modo \"$target\") || return\n    single \"$target\" \"$mode\"\n    log \"MENU: single concluido\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nmenu_off() {\n    local outputs=(\"$@\")\n    [ ${#outputs[@]} -lt 1 ] && return\n    echo\n    echo \"--- DESLIGAR DISPLAY ---\"\n    local target\n    target=$(escolher_output \"Numero do display para desligar\" \"${outputs[@]}\") || return\n    turn_off \"$target\"\n    log \"MENU: desligado\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nauto_detect() {\n    log \"AUTO: xrandr --auto\"\n    xrandr --auto\n    log \"OK: auto-detect concluido\"\n    read -rp \"Pressione Enter para continuar...\"\n}\n\nif ! command -v xrandr &>/dev/null; then\n    error \"xrandr nao encontrado. Instale com: sudo dnf install xorg-x11-server-utils\"\n    exit 1\nfi\n\nmenu_principal \"$@\"\n", "update-appimages.sh": "#!/usr/bin/env bash\nset -uo pipefail\n\nLOGFILE=\"$HOME/.cache/update-appimages.log\"\nDESKTOP_DIR=\"$HOME/.local/share/applications\"\n\nMODE=\"update\"\ncase \"${1:-}\" in\n    --menu) MODE=\"menu\"; shift ;;\n    --status) MODE=\"status\"; shift ;;\n    --uninstall) MODE=\"uninstall\"; UNINSTALL_APP=\"${2:-}\"; shift 2 ;;\n    --register) MODE=\"register\"; shift ;;\n    --links) MODE=\"links\"; shift ;;\n    --panel) MODE=\"panel\"; shift ;;\nesac\n\nAPP_DIR=\"${1:-$HOME/Applications}\"\nmkdir -p \"$APP_DIR\" \"$(dirname \"$LOGFILE\")\" \"$DESKTOP_DIR\"\n\n# Apps data: repo|filter|filename|label|desktop|icon|mime|icon_url|release_tag|type|install_url\n#\n# type: \"appimage\" (default, baixa do GitHub) ou \"curl\" (executa script de instalacao)\n# Para type=curl, repo/filter sao ignorados e a versao vem do proprio instalador.\nAPPS_DATA=(\n    \"srevinsaju/firefox-appimage|firefox-devedition|firefox-developer.AppImage|Firefox Developer Edition|firefox-developer-edition.desktop|firefox-developer-edition|x-scheme-handler/http;x-scheme-handler/https;text/html||firefox-devedition|appimage|\"\n    \"ivan-hc/MS-Edge-appimage|Microsoft-Edge-stable|microsoft-edge.AppImage|Microsoft Edge|microsoft-edge.desktop|microsoft-edge|application/pdf;application/xhtml+xml;image/webp;text/html;text/xml;x-scheme-handler/http;x-scheme-handler/https||continuous|appimage|\"\n    \"ungoogled-software/ungoogled-chromium-portablelinux|x86_64.AppImage|ungoogled-chromium.AppImage|Chromium (ungoogled)|chromium-appimage.desktop|chromium|x-scheme-handler/http;x-scheme-handler/https;text/html|||appimage|\"\n    \"VSCodium/vscodium|x86_64.AppImage|VSCodium.AppImage|VSCodium|codium-appimage.desktop|vscodium|text/plain;text/x-python;text/x-c;text/html;application/json|https://raw.githubusercontent.com/VSCodium/vscodium/master/icons/stable/codium_clt.svg||appimage|\"\n    \"||opencode|OpenCode (CLI)|opencode-cli.desktop|opencode-cli|text/plain|||curl|https://opencode.ai/v2/install\"\n)\n\n# Comandos curtos -> symlinks criados em $BIN_DIR (padrao ~/.local/bin).\n# Chave = campo \"filename\" do app (ou \"opencode\" p/ o CLI). Valor = um ou mais\n# nomes separados por espaco. Sem entrada = nao cria atalho.\ndeclare -A APP_COMMANDS=(\n    [\"firefox-developer.AppImage\"]=\"firefox-dev firefox-developer\"\n    [\"microsoft-edge.AppImage\"]=\"edge microsoft-edge\"\n    [\"ungoogled-chromium.AppImage\"]=\"chromium ungoogled-chromium\"\n    [\"VSCodium.AppImage\"]=\"codium vscodium\"\n)\n# Onde criar os atalhos. Pode sobrescrever:  BIN_DIR=/usr/local/bin ./update-appimages.sh --links\nBIN_DIR=\"${BIN_DIR:-$HOME/.local/bin}\"\n\n# \u2500\u2500 Instalador via curl (CLI) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ninstall_curl_app() {\n    local url=\"$1\"\n    local retries=\"${INSTALL_RETRIES:-3}\"\n    local attempt\n\n    [[ -n \"$url\" ]] || return 1\n\n    for attempt in $(seq 1 \"$retries\"); do\n        log \"Executando instalador (tentativa $attempt/$retries): $url\"\n        # O instalador baixa o binario em background; --retry cobre a conexao\n        # com a registry, que e onde costuma cair em rede instavel.\n        if curl -fsSL --retry 3 --retry-delay 5 --retry-all-errors \"$url\" | bash; then\n            return 0\n        fi\n        sleep 5\n    done\n\n    fetch_err=\"falha ao executar instalador apos $retries tentativas\"\n    return 1\n}\n\n# Menu e interativo (nao duplica no log); os demais modos sempre registram.\n[[ \"$MODE\" != \"menu\" ]] && exec > >(tee -a \"$LOGFILE\")\nlog() { echo \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\"; }\n\n# IPs conhecidos do GitHub API (DNS local resolve para IP invalido)\nGH_API_IPS=(\"140.82.112.5\" \"140.82.113.5\" \"140.82.114.5\" \"140.82.116.5\")\nGH_RESOLVE=\"\"\nfor ip in \"${GH_API_IPS[@]}\"; do\n    GH_RESOLVE+=\" --resolve api.github.com:443:$ip\"\ndone\n\n# Curl antigo (OL9 base, 7.76) nao conhece --retry-max-delay (alias novo):\n# detecta o flag suportado para manter compatibilidade.\nRETRY_MAX_FLAG=\"--retry-max-time\"\ncurl --help all 2>/dev/null | grep -q -- '--retry-max-delay' && RETRY_MAX_FLAG=\"--retry-max-delay\"\n\nfetch_release() {\n    local repo=\"$1\" filter=\"$2\" tag=\"${3:-}\"\n    local json\n    local api_url=\"https://api.github.com/repos/$repo/releases/latest\"\n    [[ -n \"$tag\" ]] && api_url=\"https://api.github.com/repos/$repo/releases/tags/$tag\"\n\n    # Tentar API com --resolve (contorna DNS invalido)\n    json=$(curl -sL $GH_RESOLVE --connect-timeout 10 --max-time 20 \\\n        \"$api_url\" 2>&1) || {\n        if [[ -z \"$tag\" ]]; then\n            # Fallback: scraping da pagina HTML (funciona para alguns repos)\n            fetch_release_html \"$repo\" \"$filter\" && return 0\n        fi\n        fetch_err=\"API e fallback HTML falharam\"\n        return 1\n    }\n\n    VERSION=$(echo \"$json\" | python3 -c \"import json,sys; print(json.load(sys.stdin).get('tag_name',''))\" 2>/dev/null) || VERSION=\"\"\n    URL=$(echo \"$json\" | python3 -c \"\nimport json,sys\nfor a in json.load(sys.stdin).get('assets', []):\n    if '$filter' in a['name'] and 'zsync' not in a['name']:\n        print(a['browser_download_url'])\n        break\n\" 2>/dev/null) || URL=\"\"\n\n    if [[ -z \"$URL\" ]]; then\n        fetch_err=\"nenhum asset encontrado para: $filter\"\n        return 1\n    fi\n\n    # Canais com tag fixa (ex: firefox-devedition): a versao vem do nome do asset\n    if [[ -n \"$tag\" ]]; then\n        VERSION=$(basename \"$URL\" | sed 's/\\.AppImage$//')\n    fi\n}\n\nfetch_release_html() {\n    local repo=\"$1\" filter=\"$2\" tag=\"${3:-}\"\n\n    local release_url=\"https://github.com/$repo/releases/latest\"\n    [[ -n \"$tag\" ]] && release_url=\"https://github.com/$repo/releases/tag/$tag\"\n\n    local page_url\n    page_url=$(curl -sL --connect-timeout 10 --max-time 20 \\\n        -o /dev/null -w '%{url_effective}' \\\n        \"$release_url\") || return 1\n\n    VERSION=$(echo \"$page_url\" | sed 's|.*/tag/||')\n    [[ -z \"$VERSION\" ]] && return 1\n\n    local html\n    html=$(curl -sL --connect-timeout 10 --max-time 20 \"$page_url\") || return 1\n\n    local path\n    path=$(echo \"$html\" | python3 -c \"\nimport sys, re\nhtml = sys.stdin.read()\nrepo = '$repo'\nf = '$filter'\nfor m in re.finditer(r'href=\\\"([^\\\"]+?)\\\"', html):\n    u = m.group(1)\n    if repo in u and '/releases/download/' in u and f in u and 'zsync' not in u:\n        print(u)\n        break\n\" 2>/dev/null) || return 1\n\n    [[ -z \"$path\" ]] && return 1\n\n    if [[ \"$path\" == https://* ]]; then\n        URL=\"$path\"\n    else\n        URL=\"https://github.com$path\"\n    fi\n}\n\n# Confere se o AppImage e realmente utilizavel, nao apenas se o tamanho bate.\n# Extrai o AppRun do squashfs/dwarfs interno: um arquivo corrompido pela\n# retomada costuma manter o tamanho certo (Content-Length) e falhar aqui.\nvalidate_appimage() {\n    local file=\"$1\"\n    local tmpdir rc valid=1\n\n    # Resolve para caminho absoluto: a extracao roda dentro de $tmpdir.\n    file=$(readlink -f \"$file\" 2>/dev/null) || return 1\n    [[ -f \"$file\" ]] || return 1\n\n    tmpdir=$(mktemp -d)\n    ( cd \"$tmpdir\" && timeout 120 \"$file\" --appimage-extract AppRun >/dev/null 2>&1 )\n    rc=$?\n\n    if [[ \"$rc\" -eq 0 && -s \"$tmpdir/squashfs-root/AppRun\" ]]; then\n        valid=0\n    fi\n\n    rm -rf \"$tmpdir\"\n    return \"$valid\"\n}\n\ndownload_app() {\n    local url=\"$1\" output=\"$2\"\n    local start elapsed bytes total_size\n    local retries=\"${DOWNLOAD_RETRIES:-8}\"\n    local attempt\n\n    # Mostrar tamanho do arquivo antes de baixar\n    # -L: segue o redirect do GitHub (sem -L o content-length vem 0)\n    total_size=$(curl -sIL --connect-timeout 10 --max-time 15 \"$url\" 2>/dev/null \\\n        | grep -i '^content-length:' | tail -1 | awk '{print $2}' | tr -d '\\r ')\n    if [[ -n \"$total_size\" ]]; then\n        echo \"  Tamanho: $(numfmt --to=iec \"$total_size\")\"\n    fi\n\n    # Descarta .part de um download anterior que nao bate com o tamanho\n    # esperado (ex: arquivo corrompido ou URL mudou).\n    if [[ -f \"$output.part\" && -n \"$total_size\" ]]; then\n        local part_size\n        part_size=$(stat -c%s \"$output.part\" 2>/dev/null || echo 0)\n        if (( part_size > total_size )); then\n            echo \"  .part anterior invalido, descartando\"\n            rm -f \"$output.part\"\n        fi\n    fi\n\n    for attempt in 1 2; do\n        start=$(date +%s%N)\n        # -C -        : retoma de onde parou (arquivo .part preservado entre execucoes)\n        # --retry     : repete em erro de transitorio\n        # --speed-*   : aborta se a conexao travar (curl 28) em vez de esperar eternamente\n        if ! curl -L --connect-timeout 10 --progress-bar \\\n            -C - \\\n            --retry \"$retries\" \\\n            --retry-delay 5 \\\n            $RETRY_MAX_FLAG 60 \\\n            --retry-all-errors \\\n            --speed-time 60 --speed-limit 1024 \\\n            -o \"$output.part\" \"$url\"; then\n            # Mantem o .part: a proxima execucao retoma de onde parou.\n            fetch_err=\"download falhou (parcial preservado em $(basename \"$output\").part)\"\n            return 1\n        fi\n        elapsed=$(( ($(date +%s%N) - start) / 1000000 )) # ms\n\n        # Validacao de integridade: confere tamanho antes de instalar\n        if [[ -n \"$total_size\" ]]; then\n            local got\n            got=$(stat -c%s \"$output.part\" 2>/dev/null || echo 0)\n            if [[ \"$got\" != \"$total_size\" ]]; then\n                echo \"  Tamanho invalido: esperado $total_size, obtido $got\"\n                fetch_err=\"download incompleto (parcial preservado para retomar)\"\n                return 1\n            fi\n        fi\n\n        chmod +x \"$output.part\"\n\n        # Tamanho certo nao garante conteudo integro: retomar de um .part\n        # danificado gera arquivo corrompido com o tamanho esperado. Nesse\n        # caso descarta o parcial e baixa de novo do zero.\n        if validate_appimage \"$output.part\"; then\n            mv \"$output.part\" \"$output\"\n            break\n        fi\n\n        rm -f \"$output.part\"\n        if [[ \"$attempt\" -lt 2 ]]; then\n            echo \"  AppImage corrompido apos a retomada, baixando novamente do zero...\"\n            continue\n        fi\n        fetch_err=\"AppImage corrompido (tamanho ok, conteudo invalido)\"\n        return 1\n    done\n\n    bytes=$(stat -c%s \"$output\" 2>/dev/null)\n    if [[ \"$elapsed\" -gt 0 && -n \"$bytes\" && \"$bytes\" -gt 0 ]]; then\n        local speed=$(( bytes * 1000 / elapsed ))\n        DOWNLOAD_SPEED=\"$(numfmt --to=iec \"$speed\")/s\"\n        DOWNLOAD_SIZE=\"$bytes\"\n    fi\n}\n\ninstall_desktop() {\n    local name=\"$1\" exec=\"$2\" file=\"$3\" icon=\"$4\" mime=\"$5\"\n    cat > \"$DESKTOP_DIR/$file\" <<-EOF\n[Desktop Entry]\nType=Application\nName=$name\nExec=$exec %F\nIcon=$icon\nTerminal=false\nCategories=Development;Network;WebBrowser;\nMimeType=$mime\nStartupNotify=true\nEOF\n    chmod 644 \"$DESKTOP_DIR/$file\"\n}\n\ndownload_icon() {\n    local url=\"$1\" icon_name=\"$2\"\n    [[ -z \"$url\" || -z \"$icon_name\" ]] && return 1\n\n    local ext\n    ext=$(basename \"$url\" | sed 's/.*\\.//')\n    [[ -z \"$ext\" || \"$ext\" == \"$(basename \"$url\")\" ]] && ext=\"png\"\n\n    mkdir -p \"$HOME/.local/share/icons\"\n    local output=\"$HOME/.local/share/icons/${icon_name}.${ext}\"\n    curl -sL --connect-timeout 10 --max-time 20 \"$url\" -o \"$output\" 2>/dev/null && [[ -s \"$output\" ]] && return 0\n    rm -f \"$output\"\n    return 1\n}\n\ndownload_icon_from_repo() {\n    local repo=\"$1\" icon_name=\"$2\"\n    [[ -z \"$repo\" ]] && return 1\n\n    local base=\"https://raw.githubusercontent.com/$repo\"\n    local paths=(\n        \"main/.DirIcon\"\n        \"main/icon.png\"\n        \"main/icon.svg\"\n        \"main/logo.png\"\n        \"main/logo.svg\"\n        \"main/assets/icon.png\"\n        \"main/assets/icon.svg\"\n        \"main/src/resources/linux/${icon_name}.png\"\n        \"main/chrome/app/theme/${icon_name}/linux/product_logo_256.png\"\n        \"master/.DirIcon\"\n        \"master/icon.png\"\n        \"master/icon.svg\"\n        \"master/logo.png\"\n        \"master/logo.svg\"\n        \"master/assets/icon.png\"\n        \"master/assets/icon.svg\"\n        \"master/src/resources/linux/${icon_name}.png\"\n        \"master/chrome/app/theme/${icon_name}/linux/product_logo_256.png\"\n        \"dev/.DirIcon\"\n        \"dev/icon.png\"\n        \"dev/icon.svg\"\n    )\n\n    for path in \"${paths[@]}\"; do\n        local url=\"$base/$path\"\n        local http_code\n        http_code=$(curl -sI --connect-timeout 5 --max-time 10 \"$url\" 2>/dev/null | head -1 | awk '{print $2}')\n        if [[ \"$http_code\" == \"200\" || \"$http_code\" == \"302\" ]]; then\n            local ext=\"${path##*.}\"\n            mkdir -p \"$HOME/.local/share/icons\"\n            curl -sL --connect-timeout 10 --max-time 20 \"$url\" -o \"$HOME/.local/share/icons/${icon_name}.${ext}\" 2>/dev/null && return 0\n        fi\n    done\n\n    return 1\n}\n\ninstall_icon() {\n    local appimage=\"$1\" icon_name=\"$2\" repo=\"${3:-}\" icon_url=\"${4:-}\"\n    [[ -n \"$icon_name\" ]] || return 1\n\n    local existing\n    existing=$(find \"$HOME/.local/share/icons\" -maxdepth 1 -name \"${icon_name}.*\" 2>/dev/null | head -1)\n    [[ -n \"$existing\" ]] && return 0\n\n    if [[ -f \"$appimage\" ]]; then\n        local tmpdir icon_src\n        tmpdir=$(mktemp -d)\n        (cd \"$tmpdir\" && \"$appimage\" --appimage-extract) >/dev/null 2>&1 || {\n            rm -rf \"$tmpdir\"\n            try_download \"$icon_url\" \"$icon_name\" \"$repo\" && return 0\n            return 1\n        }\n\n        local root=\"$tmpdir/squashfs-root\"\n\n        if [[ -f \"$root/.DirIcon\" ]]; then\n            icon_src=\"$root/.DirIcon\"\n        else\n            icon_src=$(find \"$root\" -name \"${icon_name}.png\" -o -name \"${icon_name}.svg\" 2>/dev/null | head -1)\n        fi\n\n        if [[ -z \"$icon_src\" ]]; then\n            icon_src=$(find \"$root\" -name \"*.png\" 2>/dev/null | head -1)\n        fi\n\n        if [[ -n \"$icon_src\" ]]; then\n            # .DirIcon costuma ser um symlink: resolver para obter a extensao real\n            if [[ \"$(basename \"$icon_src\")\" == \".DirIcon\" ]]; then\n                local real_icon\n                real_icon=$(readlink -f \"$icon_src\") || real_icon=\"$icon_src\"\n                icon_src=\"$real_icon\"\n            fi\n            local ext=\"${icon_src##*.}\"\n            mkdir -p \"$HOME/.local/share/icons\"\n            cp \"$icon_src\" \"$HOME/.local/share/icons/${icon_name}.${ext}\"\n            rm -rf \"$tmpdir\"\n            return 0\n        fi\n\n        rm -rf \"$tmpdir\"\n    fi\n\n    try_download \"$icon_url\" \"$icon_name\" \"$repo\" && return 0\n    return 1\n}\n\ntry_download() {\n    local icon_url=\"$1\" icon_name=\"$2\" repo=\"$3\"\n    if [[ -n \"$icon_url\" ]]; then\n        download_icon \"$icon_url\" \"$icon_name\" && return 0\n    fi\n    if [[ -n \"$repo\" ]]; then\n        download_icon_from_repo \"$repo\" \"$icon_name\" && return 0\n    fi\n    return 1\n}\n\n# \u2500\u2500 Painel XFCE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nPANEL_DIR=\"$HOME/.config/xfce4/panel\"\nPANEL_XML=\"$HOME/.config/xfce4/xfconf/xfce-perchannel-xml/xfce4-panel.xml\"\n\nensure_panel_launchers() {\n    PANEL_ADDED=0\n    [[ -d \"$PANEL_DIR\" ]] || { echo \"  Painel XFCE nao encontrado ($PANEL_DIR)\"; return 0; }\n    [[ -f \"$PANEL_XML\" ]] || { echo \"  Config do painel nao encontrada ($PANEL_XML)\"; return 0; }\n\n    local toadd=()\n    local entry repo filter filename label desktop icon mime icon_url release_tag atype aurl\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        [[ \"$atype\" == \"curl\" ]] && continue\n        local output=\"$APP_DIR/$filename\"\n        [[ -f \"$output\" ]] || continue\n\n        local pinned=\"\" f\n        shopt -s nullglob\n        for f in \"$PANEL_DIR\"/launcher-*/*.desktop; do\n            [[ -f \"$f\" ]] || continue\n            if grep -q \"^X-XFCE-Source=file://$DESKTOP_DIR/$desktop$\" \"$f\" 2>/dev/null; then\n                pinned=1\n                break\n            fi\n            local fname_label fname_exec\n            fname_label=$(grep -m1 '^Name=' \"$f\" 2>/dev/null | sed 's|^Name=||')\n            fname_exec=$(grep -m1 '^Exec=' \"$f\" 2>/dev/null | sed 's|^Exec=||;s| *%F$||')\n            if [[ -n \"$fname_label\" ]] && {\n                [[ \"$fname_label\" == \"$label\" ]] ||\n                [[ \"${label,,}\" == *\"${fname_label,,}\"* ]] ||\n                [[ \"${fname_label,,}\" == *\"${label,,}\"* ]]; }; then\n                pinned=1\n                break\n            fi\n            if [[ \"$fname_exec\" == \"$APP_DIR/$filename\" ]]; then\n                pinned=1\n                break\n            fi\n        done\n        shopt -u nullglob\n        [[ -z \"$pinned\" ]] || continue\n\n        toadd+=(\"$desktop|$DESKTOP_DIR/$desktop|$label\")\n    done\n\n    [[ ${#toadd[@]} -eq 0 ]] && { PANEL_ADDED=0; return 0; }\n\n    echo \"  Adicionando launchers novos no painel XFCE...\"\n\n    # Ler config (somente leitura) para descobrir proximo id de plugin e painel alvo\n    local meta\n    meta=$(python3 - \"$PANEL_XML\" 2>&1 <<'PY'\nimport re, sys, xml.etree.ElementTree as ET\n\ntree = ET.parse(sys.argv[1])\nroot = tree.getroot()\n\ndef props(el, name):\n    return [c for c in list(el) if c.get('name') == name]\n\nplugins = props(root, 'plugins')\npanels = props(root, 'panels')\nif not plugins or not panels:\n    print('', file=sys.stderr)\n    sys.exit(1)\nplugins, panels = plugins[0], panels[0]\n\nplugin_map = {}\nfor p in list(plugins):\n    m = re.fullmatch(r'plugin-(\\d+)', p.get('name') or '')\n    if m:\n        plugin_map[int(m.group(1))] = p\n\npanel_elms = [c for c in list(panels) if c.tag == 'property'\n              and (c.get('name') or '').startswith('panel-')]\n\ndef panel_ids(pp):\n    ids = []\n    for pi in props(pp, 'plugin-ids'):\n        for v in list(pi):\n            if v.tag == 'value':\n                ids.append(int(v.get('value')))\n    return ids\n\nused = set(plugin_map)\nfor pp in panel_elms:\n    used |= set(panel_ids(pp))\n\ntarget = None\nfor pp in panel_elms:\n    if any(i in plugin_map and plugin_map[i].get('value') == 'launcher'\n           for i in panel_ids(pp)):\n        target = pp\n        break\nif target is None and panel_elms:\n    target = max(panel_elms, key=lambda pp: len(panel_ids(pp)))\nif target is None:\n    print('', file=sys.stderr)\n    sys.exit(1)\n\ntarget_num = re.fullmatch(r'panel-(\\d+)', target.get('name')).group(1)\nnext_id = max(used) + 1 if used else 1\nprint('%d|%s|%s' % (next_id, target_num,\n                    ' '.join(str(i) for i in panel_ids(target))))\nPY\n    ) || [[ \"$meta\" =~ ^[0-9]+\\|panel-[0-9]+\\| ]] || {\n        echo \"  Erro ao ler config do painel\"\n        PANEL_ADDED=0\n        return 1\n    }\n\n    local next_id panel_target cur_ids\n    IFS='|' read -r next_id panel_target cur_ids <<< \"$meta\"\n\n    local item desktop src label ldir fname ok=0\n    for item in \"${toadd[@]}\"; do\n        desktop=\"${item%%|*}\"\n        label=\"${item##*|}\"\n        src=\"$DESKTOP_DIR/$desktop\"\n        ldir=\"$PANEL_DIR/launcher-$next_id\"\n        fname=\"$next_id.desktop\"\n\n        mkdir -p \"$ldir\"\n        cat \"$src\" > \"$ldir/$fname\"\n        if ! grep -q '^X-XFCE-Source=' \"$ldir/$fname\" 2>/dev/null; then\n            echo \"X-XFCE-Source=file://$src\" >> \"$ldir/$fname\"\n        fi\n        chmod 644 \"$ldir/$fname\"\n\n        xfconf-query -c xfce4-panel -p \"/plugins/plugin-$next_id\" \\\n            -n -t string -s launcher &&\n        xfconf-query -c xfce4-panel -p \"/plugins/plugin-$next_id/items\" \\\n            -n -a -t string -s \"$fname\" || {\n            echo \"  Painel XFCE: erro ao registrar plugin-$next_id ($label)\"\n            PANEL_ADDED=0\n            return 1\n        }\n\n        cur_ids=\"$cur_ids $next_id\"\n        echo \"  Painel XFCE: $label fixado no painel\"\n        ok=1\n        next_id=$((next_id + 1))\n    done\n\n    # Atualizar plugin-ids do painel alvo com os novos plugins\n    local args=(-c xfce4-panel -p \"/panels/panel-$panel_target/plugin-ids\")\n    local i\n    for i in $cur_ids; do\n        args+=(-t int -s \"$i\")\n    done\n    xfconf-query \"${args[@]}\" || {\n        echo \"  Painel XFCE: erro ao atualizar plugin-ids do painel-$panel_target\"\n        PANEL_ADDED=0\n        return 1\n    }\n\n    [[ \"$ok\" -eq 1 ]] && PANEL_ADDED=1\n    return 0\n}\n\nsync_panel_launchers() {\n    PANEL_ADDED=0\n    [[ -d \"$PANEL_DIR\" ]] || { echo \"  Painel XFCE nao encontrado ($PANEL_DIR)\"; return 0; }\n\n    local updated=0\n    shopt -s nullglob\n    for launcher in \"$PANEL_DIR\"/launcher-*; do\n        for f in \"$launcher\"/*.desktop; do\n            [[ -f \"$f\" ]] || continue\n\n            local source\n            source=$(grep '^X-XFCE-Source=' \"$f\" 2>/dev/null | head -1 | sed 's|^X-XFCE-Source=||')\n            [[ -n \"$source\" ]] || continue\n\n            for entry in \"${APPS_DATA[@]}\"; do\n                IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n                [[ \"$atype\" == \"curl\" ]] && continue\n                [[ \"$source\" == \"file://$DESKTOP_DIR/$desktop\" ]] || continue\n\n                local output=\"$APP_DIR/$filename\"\n                [[ -f \"$output\" ]] || continue\n\n                local comment=\"\" wmclass=\"\"\n                comment=$(grep '^Comment=' \"$f\" | head -1 | sed 's|^Comment=||' 2>/dev/null)\n                wmclass=$(grep '^StartupWMClass=' \"$f\" | head -1 | sed 's|^StartupWMClass=||' 2>/dev/null)\n\n                {\n                    echo \"[Desktop Entry]\"\n                    echo \"Type=Application\"\n                    echo \"Name=$label\"\n                    [[ -n \"$comment\" ]] && echo \"Comment=$comment\"\n                    echo \"Exec=$output %F\"\n                    echo \"Icon=$icon\"\n                    echo \"Terminal=false\"\n                    echo \"Categories=Development;Network;WebBrowser;\"\n                    echo \"MimeType=$mime\"\n                    echo \"StartupNotify=true\"\n                    [[ -n \"$wmclass\" ]] && echo \"StartupWMClass=$wmclass\"\n                    echo \"X-XFCE-Source=$source\"\n                } > \"$f\"\n                chmod 644 \"$f\"\n\n                echo \"  Painel XFCE: $f atualizado\"\n                updated=1\n                break\n            done\n        done\n    done\n    shopt -u nullglob\n\n    ensure_panel_launchers\n\n    if [[ \"$updated\" -eq 1 || \"$PANEL_ADDED\" -eq 1 ]] && command -v xfce4-panel &>/dev/null; then\n        xfce4-panel -r 2>/dev/null || true\n        echo \"  Painel XFCE reiniciado para aplicar as mudancas\"\n    fi\n    return 0\n}\n\n# \u2500\u2500 Status / List \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nlist_installed() {\n    echo \"\"\n    echo \"\u2550\u2550\u2550 Apps Instalados \u2550\u2550\u2550\"\n    echo \"\"\n    local found=0\n    local outdated=0\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        local vfile=\"$output.version\"\n        if [[ -f \"$output\" ]]; then\n            found=1\n            local version=\"\"\n            [[ -f \"$vfile\" ]] && version=$(cat \"$vfile\")\n            echo \"  $label\"\n            echo \"    Arquivo: $filename ($(numfmt --to=iec \"$(stat -c%s \"$output\" 2>/dev/null)\" 2>/dev/null || echo \"?\"))\"\n            if [[ -n \"$version\" ]]; then\n                echo \"    Versao: $version\"\n            elif [[ \"$atype\" == \"curl\" ]] && command -v \"$output\" >/dev/null 2>&1; then\n                echo \"    Versao: $(\"$output\" --version 2>/dev/null | head -1)\"\n            else\n                echo \"    Versao: desconhecida\"\n            fi\n        fi\n    done\n    [[ \"$found\" -eq 0 ]] && echo \"  Nenhum AppImage instalado em $APP_DIR\"\n    echo \"\"\n}\n\n# \u2500\u2500 Uninstall \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nuninstall_app() {\n    local target_label=\"$1\"\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime atype aurl <<< \"$entry\"\n        if [[ \"$label\" == \"$target_label\" ]]; then\n            local output\n            if [[ \"$atype\" == \"curl\" ]]; then\n                output=\"$HOME/.opencode/bin/opencode\"\n            else\n                output=\"$APP_DIR/$filename\"\n            fi\n            local vfile=\"$output.version\"\n            local removed=0\n\n            if [[ -f \"$output\" ]]; then\n                rm -f \"$output\" && echo \"  Removido: $output\" && removed=1\n            fi\n            if [[ -f \"$vfile\" ]]; then\n                rm -f \"$vfile\" && echo \"  Removido: $vfile\"\n            fi\n            if [[ -f \"$DESKTOP_DIR/$desktop\" ]]; then\n                rm -f \"$DESKTOP_DIR/$desktop\" && echo \"  Removido: $DESKTOP_DIR/$desktop\"\n            fi\n\n            local icon_file\n            icon_file=$(find \"$HOME/.local/share/icons\" -maxdepth 1 -name \"${icon}.*\" 2>/dev/null | head -1)\n            if [[ -n \"$icon_file\" ]]; then\n                rm -f \"$icon_file\" && echo \"  Removido: $icon_file\"\n            fi\n\n            # Atalhos de nome curto (se houver)\n            local names=\"${APP_COMMANDS[$filename]:-}\"\n            local n\n            for n in $names; do\n                if [[ -L \"$HOME/.local/bin/$n\" ]]; then\n                    rm -f \"$HOME/.local/bin/$n\" && echo \"  Removido: ~/.local/bin/$n\"\n                fi\n            done\n\n            if [[ \"$removed\" -eq 0 ]]; then\n                echo \"  '$label' nao esta instalado.\"\n            else\n                echo \"  '$label' desinstalado com sucesso.\"\n            fi\n            return 0\n        fi\n    done\n    echo \"  App '$target_label' nao encontrado.\"\n}\n\nuninstall_menu() {\n    local installed=()\n    local labels=()\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        if [[ -f \"$output\" ]]; then\n            installed+=(\"$entry\")\n            labels+=(\"$label\")\n        fi\n    done\n\n    if [[ ${#installed[@]} -eq 0 ]]; then\n        echo \"\"\n        echo \"Nenhum app instalado para desinstalar.\"\n        return\n    fi\n\n    echo \"\"\n    echo \"\u2550\u2550\u2550 Desinstalar App \u2550\u2550\u2550\"\n    echo \"\"\n    for i in \"${!labels[@]}\"; do\n        echo \"  $((i+1))) ${labels[$i]}\"\n    done\n    echo \"  q) Cancelar\"\n    echo \"\"\n    read -rp \"Escolha um app para desinstalar: \" choice\n\n    [[ \"$choice\" == \"q\" ]] && return\n\n    if [[ \"$choice\" =~ ^[0-9]+$ ]] && [[ \"$choice\" -ge 1 ]] && [[ \"$choice\" -le ${#labels[@]} ]]; then\n        local idx=$((choice-1))\n        local label=\"${labels[$idx]}\"\n        echo \"\"\n        read -rp \"Tem certeza que deseja desinstalar '$label'? (s/N): \" confirm\n        if [[ \"$confirm\" == \"s\" || \"$confirm\" == \"S\" ]]; then\n            uninstall_app \"$label\"\n        else\n            echo \"Cancelado.\"\n        fi\n    else\n        echo \"Opcao invalida.\"\n    fi\n}\n\n# \u2500\u2500 Menu \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nshow_menu() {\n    while true; do\n        echo \"\"\n        echo \"\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557\"\n        echo \"\u2551      Gerenciador de AppImages        \u2551\"\n        echo \"\u255a\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255d\"\n        echo \"\"\n        echo \"1) Atualizar todos os apps\"\n        echo \"2) Registrar no sistema (usuario)\"\n        echo \"3) Listar apps instalados e status\"\n        echo \"4) Desinstalar um app\"\n        echo \"5) Atualizar lancadores no painel XFCE\"\n        echo \"6) Criar/atualizar atalhos (comandos)\"\n        echo \"7) Sair\"\n        echo \"\"\n        read -rp \"Escolha uma opcao: \" choice\n\n        case \"$choice\" in\n            1) update_all ;;\n            2) register_system ;;\n            3) list_installed ;;\n            4) uninstall_menu ;;\n            5) sync_panel_launchers ;;\n            6) ensure_commands ;;\n            7) echo \"\"; exit 0 ;;\n            *) echo \"Opcao invalida.\" ;;\n        esac\n        echo \"\"\n        read -rp \"Pressione Enter para continuar...\"\n    done\n}\n\n# \u2500\u2500 Comandos (symlinks curtos em $BIN_DIR) \u2500\u2500\u2500\u2500\u2500\n\n# Cria atalhos de nome curto (ex: chromium, edge) apontando para os AppImages.\n# Nomes vindos de APP_COMMANDS. Idempotente: atualiza o alvo se ja existir.\nensure_commands() {\n    local dir=\"${BIN_DIR:-$HOME/.local/bin}\"\n    mkdir -p \"$dir\"\n\n    local made=() skipped=()\n    local entry repo filter filename label desktop icon mime icon_url release_tag atype aurl\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n\n        local output\n        if [[ \"$atype\" == \"curl\" ]]; then\n            output=\"$HOME/.opencode/bin/opencode\"\n        else\n            output=\"$APP_DIR/$filename\"\n        fi\n        [[ -f \"$output\" ]] || continue\n\n        local names=\"${APP_COMMANDS[$filename]:-}\"\n        [[ -n \"$names\" ]] || continue\n\n        local n\n        for n in $names; do\n            # Nunca sobrescreve um arquivo real (so symlink antigo ou ausente)\n            if [[ -e \"$dir/$n\" && ! -L \"$dir/$n\" ]]; then\n                skipped+=(\"$n\")\n                continue\n            fi\n            ln -sfn \"$output\" \"$dir/$n\"\n            made+=(\"$n\")\n        done\n    done\n\n    [[ ${#made[@]} -gt 0 ]] && echo \"  Atalhos em $dir: ${made[*]}\"\n    [[ ${#skipped[@]} -gt 0 ]] && echo \"  (nao sobrescritos, ja existem e nao sao symlink): ${skipped[*]}\"\n    return 0\n}\n\n# \u2500\u2500 Register (sistema, sem sudo) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nregister_system() {\n    echo \"\"\n    echo \"Registrando AppImages no sistema (usuario)...\"\n    mkdir -p \"$DESKTOP_DIR\" \"$HOME/.local/share/icons\" \"$HOME/.local/bin\"\n    echo \"\"\n\n    local FAIL=0\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n\n        if [[ \"$atype\" == \"curl\" ]]; then\n            # App instalado por script (nao e AppImage)\n            local cli_bin=\"$HOME/.opencode/bin/opencode\"\n            echo \"--- $label ---\"\n            if [[ -f \"$cli_bin\" ]]; then\n                echo \"  ja instalado ($(\"$cli_bin\" --version 2>/dev/null | head -1))\"\n            else\n                echo \"  nao instalado \u2014 use: Atualizar todos os apps\"\n            fi\n            if [[ -n \"$desktop\" && -f \"$DESKTOP_DIR/$desktop\" ]]; then\n                echo \"  .desktop: $DESKTOP_DIR/$desktop\"\n            fi\n            echo \"\"\n            continue\n        fi\n\n        local output=\"$APP_DIR/$filename\"\n        if [[ ! -f \"$output\" ]]; then\n            echo \"  $label: nao instalado (pulando)\"\n            continue\n        fi\n\n        echo \"--- $label ---\"\n        chmod +x \"$output\" 2>/dev/null || true\n        install_desktop \"$label\" \"$output\" \"$desktop\" \"$icon\" \"$mime\"\n        echo \"  .desktop: $DESKTOP_DIR/$desktop\"\n        if install_icon \"$output\" \"$icon\" \"$repo\" \"$icon_url\"; then\n            echo \"  Icone instalado\"\n        else\n            echo \"  Icone nao instalado\"\n        fi\n        ln -sf \"$output\" \"$HOME/.local/bin/$filename\" && echo \"  Symlink: ~/.local/bin/$filename\"\n        echo \"\"\n    done\n\n    ensure_commands\n\n    command -v update-desktop-database &>/dev/null && update-desktop-database \"$DESKTOP_DIR\" 2>/dev/null || true\n    command -v gtk-update-icon-cache &>/dev/null && gtk-update-icon-cache \"$HOME/.local/share/icons\" 2>/dev/null || true\n\n    case \":$PATH:\" in\n        *\":$HOME/.local/bin:\"*) : ;;\n        *) export PATH=\"$HOME/.local/bin:$PATH\" ;;\n    esac\n    if ! grep -q 'HOME/.local/bin' \"$HOME/.bashrc\" 2>/dev/null; then\n        echo 'export PATH=\"$HOME/.local/bin:$PATH\"' >> \"$HOME/.bashrc\"\n        echo \"  ~/.local/bin adicionado ao PATH (arquivo ~/.bashrc atualizado)\"\n    fi\n\n    echo \"Pronto. Apps visiveis no menu e no terminal (reabra a sessao se necessario).\"\n    echo \"\"\n    sync_panel_launchers\n    return \"$FAIL\"\n}\n\n# \u2500\u2500 Main \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nupdate_all() {\n    echo \"\"\n    echo \"Atualizador de AppImages \u2014 $(date '+%Y-%m-%d %H:%M:%S')\"\n    echo \"Diretorio: $APP_DIR\"\n    echo \"\"\n\n    local FAIL=0\n\n    for entry in \"${APPS_DATA[@]}\"; do\n        IFS='|' read -r repo filter filename label desktop icon mime icon_url release_tag atype aurl <<< \"$entry\"\n        echo \"--- $label ---\"\n\n        # \u2500\u2500 Apps instalados via script (curl) \u2500\u2500\n        if [[ \"$atype\" == \"curl\" ]]; then\n            local cli_bin=\"$HOME/.opencode/bin/opencode\"\n            local cli_vfile=\"$HOME/.opencode/bin/opencode.version\"\n\n            printf \"  Instalador... \"\n            if install_curl_app \"$aurl\"; then\n                if [[ -x \"$cli_bin\" ]]; then\n                    VERSION=$(\"$cli_bin\" --version 2>/dev/null | head -1)\n                    echo \"$VERSION\" > \"$cli_vfile\"\n                    echo \"OK ($VERSION)\"\n                else\n                    echo \"FALHOU (binario nao encontrado em $cli_bin)\"\n                    FAIL=1\n                fi\n            else\n                echo \"FALHOU (${fetch_err:-erro desconhecido})\"\n                FAIL=1\n                continue\n            fi\n\n            if [[ -n \"$desktop\" ]]; then\n                install_desktop \"$label\" \"$cli_bin\" \"$desktop\" \"$icon\" \"$mime\"\n                echo \"  .desktop criado\"\n            fi\n            echo \"\"\n            continue\n        fi\n\n        printf \"  Release... \"\n        VERSION=\"\" URL=\"\" fetch_err=\"\"\n        if fetch_release \"$repo\" \"$filter\" \"$release_tag\"; then\n            echo \"$VERSION\"\n        else\n            echo \"FALHOU ($fetch_err)\"\n            FAIL=1\n            continue\n        fi\n\n        local output=\"$APP_DIR/$filename\"\n        local vfile=\"$output.version\"\n\n        if [[ -f \"$vfile\" ]] && [[ \"$(cat \"$vfile\")\" == \"$VERSION\" ]] && [[ -f \"$output\" ]]; then\n            echo \"  Ja atualizado ($VERSION)\"\n            # Garante que vers\u00e3o seja salva mesmo se arquivo antigo n\u00e3o tinha .version\n            echo \"$VERSION\" > \"$vfile\"\n        else\n            echo \"  Baixando... \"\n            if download_app \"$URL\" \"$output\"; then\n                echo \"  OK ($(numfmt --to=iec \"$DOWNLOAD_SIZE\") em ${DOWNLOAD_SPEED:-?})\"\n                echo \"$VERSION\" > \"$vfile\"\n            else\n                echo \"  FALHOU\"\n                FAIL=1\n                continue\n            fi\n        fi\n\n        install_desktop \"$label\" \"$output\" \"$desktop\" \"$icon\" \"$mime\"\n        echo \"  .desktop criado\"\n        if [[ -f \"$output\" ]]; then\n            install_icon \"$output\" \"$icon\" \"$repo\" \"$icon_url\" && echo \"  Icone instalado\" || echo \"  Icone nao instalado\"\n        fi\n\n        if command -v xdg-settings &>/dev/null; then\n            case \"$label\" in\n                \"Firefox Developer Edition\")\n                    xdg-settings set default-web-browser \"$desktop\" 2>/dev/null || true\n                    ;;\n            esac\n        fi\n\n        echo \"\"\n    done\n\n    command -v update-desktop-database &>/dev/null && update-desktop-database \"$DESKTOP_DIR\" 2>/dev/null || true\n    command -v gtk-update-icon-cache &>/dev/null && gtk-update-icon-cache \"$HOME/.local/share/icons\" 2>/dev/null || true\n\n    ensure_commands\n\n    echo \"\"\n    echo \"---\"\n    echo \"Sincronizando lancadores do painel XFCE...\"\n    sync_panel_launchers\n\n    echo \"---\"\n    echo \"Status: $([ \"$FAIL\" -eq 0 ] && echo \"Sucesso\" || echo \"Falha em algum item\")\"\n    echo \"Log: $LOGFILE\"\n    return \"$FAIL\"\n}\n\n# \u2500\u2500 Entrypoint \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\ncase \"$MODE\" in\n    menu) show_menu ;;\n    status) list_installed ;;\n    uninstall) uninstall_app \"$UNINSTALL_APP\" ;;\n    register) register_system ;;\n    links) ensure_commands ;;\n    panel) sync_panel_launchers ;;\n    update) update_all ;;\nesac\n", "update-docs.sh": "#!/bin/bash\n# update-docs.sh \u2014 Regenera a documentacao e opcionalmente faz commit\n# Uso: ./update-docs.sh [--commit]\n\nset -euo pipefail\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\ncd \"$SCRIPT_DIR\"\n\necho \"==> Verificando Python...\"\nif ! command -v python3 &>/dev/null; then\n  echo \"ERRO: python3 nao encontrado\"\n  exit 1\nfi\n\necho \"==> Escaneando scripts .sh no repositorio...\"\nSH_COUNT=$(find . -name \"*.sh\" -not -path \"./.git/*\" -not -path \"./docs/*\" | wc -l)\necho \"    Encontrados: $SH_COUNT scripts\"\n\necho \"==> Gerando documentacao...\"\npython3 generate-docs.py\n\necho \"==> Verificando alteracoes no git...\"\nif git diff --quiet docs/ 2>/dev/null; then\n  echo \"    Nenhuma alteracao detectada na pasta docs/\"\nelse\n  CHANGED=$(git diff --stat docs/ | tail -1)\n  echo \"    Alteracoes: $CHANGED\"\nfi\n\nif [[ \"${1:-}\" == \"--commit\" ]]; then\n  echo \"==> Fazendo commit das alteracoes...\"\n  git add docs/\n  git commit -m \"docs: auto-update \u2014 $SH_COUNT scripts documentados\" --no-verify\n  echo \"==> Commit realizado com sucesso!\"\n  echo \"    Para enviar ao remote: git push\"\nelse\n  echo \"\"\n  echo \"==> Pronto! Para commitar as alteracoes, rode:\"\n  echo \"    ./update-docs.sh --commit\"\nfi\n\necho \"\"\necho \"==> Abrindo docs/index.html...\"\nif command -v xdg-open &>/dev/null; then\n  xdg-open \"$SCRIPT_DIR/docs/index.html\" 2>/dev/null &\nelif command -v open &>/dev/null; then\n  open \"$SCRIPT_DIR/docs/index.html\" 2>/dev/null &\nfi\n", "vm_scripts/control.sh": "#!/bin/bash\n\n# --- Configura\u00e7\u00f5es ---\nAPP_NAME=\"amoranimal\"\nREPO_URL=\"https://github.com/wrhbra2013/amoranimalmarilia.git\"\nREPO_DIR=\"amoranimalmarilia\"\nDOMAIN=\"amoranimal.ong.br\"   # ajuste para o dom\u00ednio configurado no Certbot\n\n# Cores\nVERDE='\\033[0;32m'\nAMARELO='\\033[1;33m'\nVERMELHO='\\033[0;31m'\nNC='\\033[0m'\n\n# --- Fun\u00e7\u00f5es ---\n\ngerenciar_repositorio() {\n    if [ -d \"$REPO_DIR\" ]; then\n        echo -e \"${AMARELO}A pasta '$REPO_DIR' j\u00e1 existe.${NC}\"\n        echo \"1) Atualizar via Git Pull\"\n        echo \"2) Apagar e clonar do zero\"\n        echo \"3) Pular\"\n        read -p \"Escolha: \" opcao_repo\n\n        case $opcao_repo in\n            1) cd \"$REPO_DIR\" && git pull && cd .. ;;\n            2) sudo rm -rf \"$REPO_DIR\" && git clone \"$REPO_URL\" ;;\n            *) echo \"Etapa pulada.\" ;;\n        esac\n    else\n        echo -e \"${AMARELO}Clonando reposit\u00f3rio pela primeira vez...${NC}\"\n        git clone \"$REPO_URL\"\n    fi\n}\n\nverificar_git() {\n    echo -e \"\\n${AMARELO}[Git] Verificando atualiza\u00e7\u00f5es...${NC}\"\n    cd \"$REPO_DIR\" || { echo -e \"${VERMELHO}Erro: Pasta n\u00e3o encontrada.${NC}\"; return 1; }\n    git fetch\n    LOCAL=$(git rev-parse HEAD)\n    REMOTO=$(git rev-parse @{u})\n    if [ \"$LOCAL\" = \"$REMOTO\" ]; then\n        echo -e \"${VERDE}\u2714 C\u00f3digo atualizado.${NC}\"\n    else\n        echo -e \"${AMARELO}Atualiza\u00e7\u00f5es encontradas. Baixando...${NC}\"\n        git pull\n    fi\n    cd ..\n}\n\ninstalar_dependencias() {\n    echo -e \"\\n${AMARELO}[NPM] Instalando depend\u00eancias...${NC}\"\n    cd \"$REPO_DIR\" && npm install && cd ..\n    echo -e \"${VERDE}\u2714 Depend\u00eancias OK.${NC}\"\n}\n\nreiniciar_pm2() {\n    echo -e \"\\n${AMARELO}[PM2] Reiniciando aplica\u00e7\u00e3o...${NC}\"\n    pm2 restart $APP_NAME || pm2 start index.js --name $APP_NAME\n    echo -e \"${VERDE}\u2714 PM2 OK.${NC}\"\n}\n\nvalidar_nginx() {\n    echo -e \"\\n${AMARELO}[Nginx] Validando configura\u00e7\u00e3o...${NC}\"\n    if sudo nginx -t; then\n        sudo systemctl reload nginx\n        echo -e \"${VERDE}\u2714 Nginx recarregado.${NC}\"\n    else\n        echo -e \"${VERMELHO}\u2716 Erro no Nginx.${NC}\"\n    fi\n}\n\nmostrar_logs() {\n    echo -e \"\\n${AMARELO}[Logs] Exibindo logs...${NC}\"\n    pm2 logs $APP_NAME --lines 15\n}\n\nverificar_certbot() {\n    echo -e \"\\n${AMARELO}[Certbot] Verificando certificado...${NC}\"\n    if sudo certbot certificates | grep -q \"$DOMAIN\"; then\n        EXPIRACAO=$(sudo certbot certificates | grep \"Expiry Date\" | head -n1 | cut -d: -f2)\n        echo \"Data de expira\u00e7\u00e3o: $EXPIRACAO\"\n        echo -e \"${AMARELO}Se faltar menos de 30 dias, ser\u00e1 renovado automaticamente.${NC}\"\n    else\n        echo -e \"${VERMELHO}\u2716 Nenhum certificado encontrado para $DOMAIN.${NC}\"\n    fi\n}\n\nrenovar_certbot() {\n    echo -e \"\\n${AMARELO}[Certbot] Renovando certificado...${NC}\"\n    if sudo certbot renew --quiet; then\n        echo -e \"${VERDE}\u2714 Certificado renovado.${NC}\"\n        sudo systemctl reload nginx\n        echo -e \"${VERDE}\u2714 Nginx recarregado com novo certificado.${NC}\"\n    else\n        echo -e \"${VERMELHO}\u2716 Erro ao renovar certificado.${NC}\"\n    fi\n}\n\n# --- Menu Principal ---\nclear\necho -e \"${VERDE}==============================================\"\necho -e \"      SISTEMA DE MANUTEN\u00c7\u00c3O AMOR ANIMAL\"\necho -e \"==============================================${NC}\"\necho \"1) Fluxo Completo (Repo -> NPM -> PM2 -> Nginx -> Certificado -> Logs)\"\necho \"2) Gerenciar Reposit\u00f3rio\"\necho \"3) Atualizar C\u00f3digo (Git Pull)\"\necho \"4) Instalar Depend\u00eancias (NPM)\"\necho \"5) Reiniciar App (PM2)\"\necho \"6) Validar Webserver (Nginx)\"\necho \"7) Verificar Certificado (Certbot)\"\necho \"8) Renovar Certificado (Certbot)\"\necho \"9) Ver Logs\"\necho \"0) Sair\"\necho \"----------------------------------------------\"\nread -p \"Selecione uma op\u00e7\u00e3o: \" opcao\n\ncase $opcao in\n    1) gerenciar_repositorio && instalar_dependencias && reiniciar_pm2 && validar_nginx && verificar_certbot && renovar_certbot && mostrar_logs ;;\n    2) gerenciar_repositorio ;;\n    3) verificar_git ;;\n    4) instalar_dependencias ;;\n    5) reiniciar_pm2 ;;\n    6) validar_nginx ;;\n    7) verificar_certbot ;;\n    8) renovar_certbot ;;\n    9) mostrar_logs ;;\n    0) exit 0 ;;\n    *) echo \"Op\u00e7\u00e3o inv\u00e1lida.\" ;;\nesac\n", "vm_scripts/restore-snapshot-disable-ufw.sh": "#!/bin/bash\n\necho \"=== Restaurar Snapshot Magalu Cloud ===\"\necho \"\"\n\necho \"Fazendo login...\"\nmgc auth login\n\necho \"\"\necho \"=== Selecione o Snapshot ===\"\necho \"\"\n\nmgc virtual-machine snapshots list -o table 2>/dev/null || mgc virtual-machine snapshots list\n\necho \"\"\nread -p \"ID do snapshot: \" SNAPSHOT_ID\n\necho \"\"\necho \"=== Selecione o Machine Type ===\"\necho \"\"\n\nmgc virtual-machine machine-types list -o table 2>/dev/null || mgc virtual-machine machine-types list\n\necho \"\"\nread -p \"Nome do machine-type: \" MACHINE_TYPE\n\necho \"\"\necho \"=== Selecione a VPC ===\"\necho \"\"\n\nmgc network vpcs list -o table 2>/dev/null || mgc network vpcs list\n\necho \"\"\nread -p \"Nome da VPC: \" VPC_NAME\n\necho \"\"\necho \"=== Selecione a Chave SSH ===\"\necho \"\"\n\nmgc profile ssh-keys list -o table 2>/dev/null || mgc profile ssh-keys list\n\necho \"\"\nread -p \"Nome da chave SSH: \" SSH_KEY\n\necho \"\"\nread -p \"Nome da nova instancia: \" INSTANCE_NAME\n\necho \"\"\nread -p \"Associar IP pubblico? (s/n): \" ASSIGN_PUBLIC_IP\n\nif [[ \"$ASSIGN_PUBLIC_IP\" =~ ^[Ss]$ ]]; then\n    PUBLIC_IP=\"true\"\nelse\n    PUBLIC_IP=\"false\"\nfi\n\necho \"\"\necho \"=== Criando user-data para desabilitar ufw ===\"\n\nUSER_DATA_SCRIPT=\"#!/bin/bash\nufw disable\"\n\nUSER_DATA_B64=$(echo \"$USER_DATA_SCRIPT\" | base64 -w 0)\n\necho \"\"\necho \"=== Restaurando snapshot ===\"\necho \"\"\n\nmgc virtual-machine snapshots restore \\\n  --id=\"$SNAPSHOT_ID\" \\\n  --name=\"$INSTANCE_NAME\" \\\n  --machine-type.name=\"$MACHINE_TYPE\" \\\n  --network.associate-public-ip=\"$PUBLIC_IP\" \\\n  --network.vpc.name=\"$VPC_NAME\" \\\n  --ssh-key-name=\"$SSH_KEY\" \\\n  --user-data=\"$USER_DATA_B64\"\n\necho \"\"\necho \"Restaura\u00e7\u00e3o concluida!\"", "vm_scripts/setup-api-debian.sh": "#!/bin/bash\n\nCONFIG_FILE=\"/var/www/.setup-api-config\"\nNGINX_MAIN_CONF=\"/etc/nginx/sites-available/main\"\n\nPG_ADMIN_USER=\"postgres\"\nPG_ADMIN_PASS=\"\"\n\ninit_postgres_credentials() {\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  ACESSSO POSTGRESQL\"\n    echo \"==============================================\"\n    \n    while [ -z \"$PG_ADMIN_USER\" ]; do\n        read -p \"Usu\u00e1rio PostgreSQL: \" PG_ADMIN_USER\n        if [ -z \"$PG_ADMIN_USER\" ]; then\n            echo \"Informe o usu\u00e1rio\"\n        fi\n    done\n    \n    while [ -z \"$PG_ADMIN_PASS\" ]; do\n        read -s -p \"Senha PostgreSQL: \" PG_ADMIN_PASS\n        if [ -z \"$PG_ADMIN_PASS\" ]; then\n            echo \"Informe a senha\"\n        fi\n    done\n    echo \"\"\n}\n\ninit_postgres_credentials\n\nsave_config() {\n    grep -q \"^$PROJECT_NAME|\" \"$CONFIG_FILE\" 2>/dev/null || echo \"$PROJECT_NAME|$DB_NAME|$DB_USER|$PORT|$LOCATION\" >> \"$CONFIG_FILE\"\n}\n\nupdate_config() {\n    local name=$1\n    local port=$2\n    local location=$3\n    if [ -f \"$CONFIG_FILE\" ]; then\n        if grep -q \"^$name|\" \"$CONFIG_FILE\"; then\n            sed -i \"s|^$name|.*|$name|$port|$location|\" \"$CONFIG_FILE\"\n        else\n            echo \"$name||$port|$location\" >> \"$CONFIG_FILE\"\n        fi\n    fi\n}\n\ncheck_port() {\n    local port=$1\n    if lsof -Pi :$port -sTCP:LISTEN -t >/dev/null 2>&1; then\n        echo \"Porta $port j\u00e1 est\u00e1 em uso\"\n        return 1\n    fi\n    return 0\n}\n\nkill_port() {\n    local port=$1\n    echo \"Verificando porta $port...\"\n    local pids=$(lsof -Pi :$port -t 2>/dev/null || true)\n    if [ -n \"$pids\" ]; then\n        echo \"Matando processos na porta $port: $pids\"\n        echo \"$pids\" | xargs -r sudo kill -9 2>/dev/null || true\n        sleep 1\n    fi\n}\n\ncleanup_pm2() {\n    local name=$1\n    echo \"Limpando PM2 para $name...\"\n    sudo pm2 stop \"$name\" 2>/dev/null || true\n    sudo pm2 delete \"$name\" 2>/dev/null || true\n}\n\nremove_location() {\n    local name=$1\n    if [ -f \"$NGINX_MAIN_CONF\" ]; then\n        echo \"Removendo location /$name do Nginx...\"\n        sudo sed -i \"/location \\/$name/,/}/d\" \"$NGINX_MAIN_CONF\"\n    fi\n}\n\ncleanup_database() {\n    local db_name=$1\n    local db_user=$2\n    echo \"Limpando banco de dados...\"\n    sudo -u postgres psql -c \"SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = '$db_name' AND pid <> pg_backend_pid();\" 2>/dev/null || true\n    sudo -u postgres psql -c \"DROP DATABASE IF EXISTS $db_name;\" 2>/dev/null || true\n    sudo -u postgres psql -c \"DROP USER IF EXISTS $db_user;\" 2>/dev/null || true\n}\n\nlist_projects() {\n    if [ -f \"$CONFIG_FILE\" ]; then\n        echo \"\"\n        echo \"Projetos existentes:\"\n        cat \"$CONFIG_FILE\" | while IFS='|' read -r name dbname dbuser port location; do\n            echo \"  - $name (porta: $port, path: /$location)\"\n        done\n    fi\n}\n\ngenerate_nginx_conf() {\n    local server_name=$1\n    shift\n    local locations=(\"$@\")\n    \n    local conf=\"server {\n    listen 80;\n    server_name $server_name;\n\"\n    for loc in \"${locations[@]}\"; do\n        IFS='|' read -r name port <<< \"$loc\"\n        conf+=\"\n    location /$name/ {\n        proxy_pass http://127.0.0.1:$port/;\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade \\$http_upgrade;\n        proxy_set_header Connection 'upgrade';\n        proxy_set_header Host \\$host;\n        proxy_set_header X-Real-IP \\$remote_addr;\n        proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for;\n        proxy_cache_bypass \\$http_upgrade;\n    }\n\"\n    done\n    conf+=\"\n}\"\n    echo \"$conf\"\n}\n\nrollback_project() {\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  REVERTENDO PROJETO\"\n    echo \"==============================================\"\n\n    list_projects\n\n    read -p \"Nome do projeto a remover: \" ROLLBACK_NAME\n\n    if [ -z \"$ROLLBACK_NAME\" ]; then\n        echo \"Nome n\u00e3o pode ser vazio\"\n        return 1\n    fi\n\n    PROJECT_DIR=\"/var/www/$ROLLBACK_NAME\"\n\n    echo \"\"\n    echo \"ATEN\u00c7\u00c3O: Isso ir\u00e1 remover:\"\n    echo \"  - Diret\u00f3rio: $PROJECT_DIR\"\n    echo \"  - Banco de dados PostgreSQL\"\n    echo \"  - Location Nginx: /$ROLLBACK_NAME/\"\n    echo \"  - Processo PM2\"\n    echo \"\"\n    read -p \"Confirmar? (sim/n\u00e3o): \" CONFIRM\n    if [ \"$CONFIRM\" != \"sim\" ]; then\n        echo \"Cancelado\"\n        return 0\n    fi\n\n    DB_NAME=\"${ROLLBACK_NAME}_db\"\n    DB_USER=\"${ROLLBACK_NAME}_user\"\n    PORT=$(grep \"^PORT=\" \"$PROJECT_DIR/.env\" 2>/dev/null | cut -d= -f2 || echo \"3000\")\n\n    echo \"\"\n    echo \"1. Parando PM2...\"\n    cleanup_pm2 \"$ROLLBACK_NAME\"\n\n    echo \"2. Removendo location Nginx...\"\n    remove_location \"$ROLLBACK_NAME\"\n\n    echo \"3. Liberando porta $PORT...\"\n    kill_port \"$PORT\"\n\n    echo \"4. Removendo banco de dados...\"\n    cleanup_database \"$DB_NAME\" \"$DB_USER\"\n\n    echo \"5. Removendo diret\u00f3rio...\"\n    sudo rm -rf \"$PROJECT_DIR\"\n\n    echo \"6. Atualizando config...\"\n    if [ -f \"$CONFIG_FILE\" ]; then\n        grep -v \"^$ROLLBACK_NAME|\" \"$CONFIG_FILE\" > \"${CONFIG_FILE}.tmp\" && mv \"${CONFIG_FILE}.tmp\" \"$CONFIG_FILE\"\n    fi\n\n    echo \"\"\n    echo \"=== Projeto $ROLLBACK_NAME removido com sucesso! ===\"\n}\n\ncreate_backup() {\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CRIAR BACKUP\"\n    echo \"==============================================\"\n\n    read -p \"Nome do projeto: \" BACKUP_NAME\n\n    PROJECT_DIR=\"/var/www/$BACKUP_NAME\"\n    if [ ! -d \"$PROJECT_DIR\" ]; then\n        echo \"Projeto n\u00e3o encontrado: $PROJECT_DIR\"\n        return 1\n    fi\n\n    BACKUP_FILE=\"/tmp/${BACKUP_NAME}_backup_$(date +%Y%m%d_%H%M%S).tar.gz\"\n\n    echo \"Criando backup de $PROJECT_DIR...\"\n    sudo tar -czf \"$BACKUP_FILE\" -C \"$(dirname \"$PROJECT_DIR\")\" \"$(basename \"$PROJECT_DIR\")\"\n\n    if [ -f \"$PROJECT_DIR/.env\" ]; then\n        echo \"Backup criado: $BACKUP_FILE\"\n        ls -lh \"$BACKUP_FILE\"\n    else\n        echo \"Erro ao criar backup\"\n        rm -f \"$BACKUP_FILE\"\n    fi\n}\n\ninstall_base() {\n    echo \"\"\n    echo \"--- INSTALA\u00c7\u00c3O BASE ---\"\n\n    echo \"1. Atualizando pacotes...\"\n    sudo apt update && sudo apt upgrade -y\n\n    echo \"2. Instalando Node.js 20...\"\n    if ! command -v node &> /dev/null; then\n        curl -fsSL https://deb.nodesource.com/setup_20.x | sudo -E bash -\n        sudo apt install -y nodejs\n    fi\n\n    echo \"3. Instalando PostgreSQL...\"\n    if ! command -v psql &> /dev/null; then\n        sudo apt install -y postgresql postgresql-contrib\n    fi\n\n    echo \"4. Instalando Nginx e PM2...\"\n    if ! command -v nginx &> /dev/null; then\n        sudo apt install -y nginx\n    fi\n    if ! command -v pm2 &> /dev/null; then\n        sudo npm install -g pm2\n    fi\n\n    echo \"5. Verificando instala\u00e7\u00f5es...\"\n    node -v\n    nginx -v\n    psql --version\n    pm2 --version\n\n    echo \"\"\n    echo \"Base instalada com sucesso!\"\n}\n\ncreate_project() {\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CRIAR NOVO PROJETO\"\n    echo \"==============================================\"\n\n    read -p \"Nome do projeto (ex: crebortoli): \" PROJECT_NAME\n    read -p \"Dom\u00ednio/IP principal (ex: 201.54.22.122): \" SERVER_NAME\n    SERVER_NAME=\"${SERVER_NAME:-201.54.22.122}\"\n    read -p \"Porta (Enter para auto-detectar): \" PORT\n\n    if [ -z \"$PORT\" ]; then\n        PORT=3001\n        while ! check_port \"$PORT\"; do\n            PORT=$((PORT + 1))\n        done\n    else\n        if ! check_port \"$PORT\"; then\n            echo \"\"\n            echo \"ERRO: Porta $PORT j\u00e1 est\u00e1 em uso!\"\n            read -p \"Deseja limpar a porta e continuar? (sim/n\u00e3o): \" CLEAN_PORT\n            if [ \"$CLEAN_PORT\" == \"sim\" ]; then\n                kill_port \"$PORT\"\n            else\n                echo \"Cancelado\"\n                return 1\n            fi\n        fi\n    fi\n\n    LOCATION=\"$PROJECT_NAME\"\n    PROJECT_DIR=\"/var/www/$PROJECT_NAME\"\n\n    if [ -d \"$PROJECT_DIR\" ]; then\n        echo \"\"\n        echo \"Projeto j\u00e1 existe em $PROJECT_DIR\"\n        read -p \"Deseja remover e recriar? (sim/n\u00e3o): \" RECREATE\n        if [ \"$RECREATE\" == \"sim\" ]; then\n            DB_NAME=\"${PROJECT_NAME}_db\"\n            DB_USER=\"${PROJECT_NAME}_user\"\n            cleanup_pm2 \"$PROJECT_NAME\"\n            remove_location \"$PROJECT_NAME\"\n            kill_port \"$PORT\"\n            cleanup_database \"$DB_NAME\" \"$DB_USER\"\n            sudo rm -rf \"$PROJECT_DIR\"\n        else\n            echo \"Cancelado\"\n            return 0\n        fi\n    else\n        echo \"\"\n        echo \"--- Configura\u00e7\u00e3o do Banco de Dados ---\"\n        read -p \"Nome do banco de dados [${PROJECT_NAME}_db]: \" DB_NAME\n        DB_NAME=\"${DB_NAME:-${PROJECT_NAME}_db}\"\n\n        read -p \"Usu\u00e1rio do banco [${PROJECT_NAME}_user]: \" DB_USER\n        DB_USER=\"${DB_USER:-${PROJECT_NAME}_user}\"\n\n        while [ -z \"$DB_PASS\" ]; do\n            read -s -p \"Senha do banco: \" DB_PASS\n            echo \"\"\n            if [ -z \"$DB_PASS\" ]; then\n                echo \"Senha n\u00e3o pode ser vazia\"\n            fi\n        done\n    fi\n\n    read -p \"Tabelas (Enter para agendamentos,servicos,clientes,contatos): \" TABLES_INPUT\n    TABLES=\"${TABLES_INPUT:-agendamentos,servicos,clientes,contatos}\"\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CRIANDO BANCO DE DADOS\"\n    echo \"==============================================\"\n\n    sudo -u postgres psql -c \"CREATE USER $DB_USER WITH PASSWORD '$DB_PASS';\" 2>/dev/null || echo \"Usu\u00e1rio j\u00e1 existe\"\n    sudo -u postgres psql -c \"CREATE DATABASE $DB_NAME OWNER $DB_USER;\" 2>/dev/null || echo \"Banco j\u00e1 existe\"\n    sudo -u postgres psql -c \"GRANT ALL PRIVILEGES ON DATABASE $DB_NAME TO $DB_USER;\"\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CRIANDO PROJETO\"\n    echo \"==============================================\"\n\n    sudo mkdir -p \"$PROJECT_DIR/src\"\n    sudo mkdir -p \"$PROJECT_DIR/public\"\n\n    sudo tee \"$PROJECT_DIR/package.json\" > /dev/null <<EOF\n{\n  \"name\": \"$PROJECT_NAME\",\n  \"version\": \"1.0.0\",\n  \"main\": \"src/server.js\",\n  \"scripts\": {\n    \"start\": \"node src/server.js\",\n    \"dev\": \"node --watch src/server.js\"\n  },\n  \"dependencies\": {\n    \"express\": \"^4.18.0\",\n    \"dotenv\": \"^16.0.0\",\n    \"pg\": \"^8.11.0\",\n    \"cors\": \"^2.8.5\"\n  },\n  \"engines\": {\n    \"node\": \">=18.0.0\"\n  }\n}\nEOF\n\n    sudo tee \"$PROJECT_DIR/.env\" > /dev/null <<EOF\nPORT=$PORT\nNODE_ENV=production\nDB_HOST=localhost\nDB_PORT=5432\nDB_NAME=$DB_NAME\nDB_USER=$DB_USER\nDB_PASS=$DB_PASS\nEOF\n\n    sudo tee \"$PROJECT_DIR/src/server.js\" > /dev/null <<SERVEREOF\nconst express = require('express');\nconst { Pool } = require('pg');\nconst cors = require('cors');\nrequire('dotenv').config();\n\nconst app = express();\nconst PORT = process.env.PORT || 3000;\n\nconst pool = new Pool({\n    host: process.env.DB_HOST || 'localhost',\n    port: process.env.DB_PORT || 5432,\n    database: process.env.DB_NAME,\n    user: process.env.DB_USER,\n    password: process.env.DB_PASS\n});\n\npool.on('error', (err) => console.error('DB Error:', err));\n\napp.use(cors());\napp.use(express.json());\napp.use(express.urlencoded({ extended: true }));\n\napp.get('/', (req, res) => {\n    res.json({ \n        message: 'API Running', \n        status: 'OK',\n        project: process.env.npm_package_name || 'api',\n        timestamp: new Date().toISOString()\n    });\n});\n\napp.get('/health', async (req, res) => {\n    try {\n        await pool.query('SELECT 1');\n        res.json({ status: 'healthy', database: 'connected', timestamp: new Date().toISOString() });\n    } catch (err) {\n        res.json({ status: 'unhealthy', database: 'disconnected', error: err.message });\n    }\n});\n\napp.get('/api/tables', async (req, res) => {\n    try {\n        const result = await pool.query(\\`\n            SELECT table_name FROM information_schema.tables \n            WHERE table_schema = 'public' AND table_type = 'BASE TABLE'\n            ORDER BY table_name;\n        \\`);\n        res.json({ tables: result.rows.map(r => r.table_name) });\n    } catch (err) {\n        res.status(500).json({ error: err.message });\n    }\n});\n\napp.get('/api/tables/:tableName', async (req, res) => {\n    const { tableName } = req.params;\n    try {\n        const result = await pool.query(\\`SELECT * FROM \"\\${tableName}\" LIMIT 100;\\`);\n        res.json({ table: tableName, data: result.rows });\n    } catch (err) {\n        res.status(500).json({ error: err.message });\n    }\n});\n\napp.post('/api/tables/:tableName', async (req, res) => {\n    const { tableName } = req.params;\n    const data = req.body;\n    try {\n        const keys = Object.keys(data).map(k => '\"${k}\"').join(', ');\n        const values = Object.keys(data).map((_, i) => \\`$\\${i + 1}\\`).join(', ');\n        const result = await pool.query(\\`INSERT INTO \"\\${tableName}\" (\\${keys}) VALUES (\\${values}) RETURNING *;\\`, Object.values(data));\n        res.json({ success: true, data: result.rows[0] });\n    } catch (err) {\n        res.status(500).json({ error: err.message });\n    }\n});\n\napp.put('/api/tables/:tableName/:id', async (req, res) => {\n    const { tableName, id } = req.params;\n    const data = req.body;\n    try {\n        const keys = Object.keys(data).map((k, i) => \\`\"\\${k}\" = $\\${i + 1}\\`).join(', ');\n        const result = await pool.query(\\`UPDATE \"\\${tableName}\" SET \\${keys} WHERE id = $\\${Object.keys(data).length + 1} RETURNING *;\\`, [...Object.values(data), id]);\n        res.json({ success: true, data: result.rows[0] });\n    } catch (err) {\n        res.status(500).json({ error: err.message });\n    }\n});\n\napp.delete('/api/tables/:tableName/:id', async (req, res) => {\n    const { tableName, id } = req.params;\n    try {\n        await pool.query(\\`DELETE FROM \"\\${tableName}\" WHERE id = $1;\\`, [id]);\n        res.json({ success: true });\n    } catch (err) {\n        res.status(500).json({ error: err.message });\n    }\n});\n\napp.listen(PORT, '0.0.0.0', () => {\n    console.log(\\`Server running on port \\${PORT}\\`);\n});\nSERVEREOF\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CRIANDO TABELAS PADR\u00c3O\"\n    echo \"==============================================\"\n\n    IFS=',' read -ra TABLE_ARRAY <<< \"$TABLES\"\n    for table in \"${TABLE_ARRAY[@]}\"; do\n        table=$(echo \"$table\" | xargs)\n        if [ -n \"$table\" ]; then\n            echo \"Criando tabela: $table\"\n            sudo -u postgres psql -d \"$DB_NAME\" -c \"\n                CREATE TABLE IF NOT EXISTS \\\"$table\\\" (\n                    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n                    created_at TIMESTAMP DEFAULT NOW(),\n                    updated_at TIMESTAMP DEFAULT NOW()\n                );\n            \" 2>/dev/null || echo \"Tabela $table j\u00e1 existe\"\n        fi\n    done\n\n    cd \"$PROJECT_DIR\"\n    sudo npm install\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CONFIGURANDO PM2\"\n    echo \"==============================================\"\n\n    cleanup_pm2 \"$PROJECT_NAME\"\n    sudo pm2 start \"$PROJECT_DIR/src/server.js\" --name \"$PROJECT_NAME\"\n    sudo pm2 save\n\n    SYSTEMD_SERVICE=$(sudo pm2 startup | tail -1)\n    if [ -n \"$SYSTEMD_SERVICE\" ]; then\n        echo \"$SYSTEMD_SERVICE\" | sudo bash 2>/dev/null || true\n    fi\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  CONFIGURANDO NGINX (MULTI-LOCATION)\"\n    echo \"==============================================\"\n\n    local location_block=\"\n    location /$LOCATION/ {\n        proxy_pass http://127.0.0.1:$PORT/;\n        proxy_http_version 1.1;\n        proxy_set_header Upgrade \\$http_upgrade;\n        proxy_set_header Connection 'upgrade';\n        proxy_set_header Host \\$host;\n        proxy_set_header X-Real-IP \\$remote_addr;\n        proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for;\n        proxy_cache_bypass \\$http_upgrade;\n    }\n\"\n\n    if [ -f \"$NGINX_MAIN_CONF\" ]; then\n        echo \"Adicionando location /$LOCATION/ ao config existente...\"\n        if ! grep -q \"location /$LOCATION/\" \"$NGINX_MAIN_CONF\"; then\n            sudo sed -i \"s|server {|server {\\n$location_block|\" \"$NGINX_MAIN_CONF\"\n        fi\n    else\n        echo \"Criando novo config Nginx...\"\n        sudo tee \"$NGINX_MAIN_CONF\" > /dev/null <<EOF\nserver {\n    listen 80;\n    server_name $SERVER_NAME;\n$location_block\n}\nEOF\n    fi\n\n    sudo ln -sf \"$NGINX_MAIN_CONF\" /etc/nginx/sites-enabled/main 2>/dev/null || true\n    sudo nginx -t && sudo systemctl reload nginx\n\n    save_config\n\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  RESUMO DO PROJETO\"\n    echo \"==============================================\"\n    echo \"\"\n    echo \"Projeto: $PROJECT_NAME\"\n    echo \"Diret\u00f3rio: $PROJECT_DIR\"\n    echo \"Porta: $PORT\"\n    echo \"Location: /$LOCATION/\"\n    echo \"Banco: $DB_NAME\"\n    echo \"Usu\u00e1rio: $DB_USER\"\n    echo \"Tabelas: $TABLES\"\n    echo \"\"\n    echo \"URL: http://$SERVER_NAME/$LOCATION/\"\n    echo \"\"\n    echo \"=== Projeto criado com sucesso! ===\"\n}\n\nshow_menu() {\n    echo \"\"\n    echo \"==============================================\"\n    echo \"  Setup API Multi-Projeto (Nginx Locations)\"\n    echo \"==============================================\"\n    echo \"\"\n    echo \"Escolha uma op\u00e7\u00e3o:\"\n    echo \"  1 - Instalar base (Node, PostgreSQL, Nginx, PM2)\"\n    echo \"  2 - Criar novo projeto\"\n    echo \"  3 - Listar projetos\"\n    echo \"  4 - Reverter/remover projeto\"\n    echo \"  5 - Criar backup\"\n    echo \"  6 - Sair\"\n    echo \"\"\n    read -p \"Op\u00e7\u00e3o: \" OPTION\n\n    case $OPTION in\n        1) install_base ;;\n        2) create_project ;;\n        3) list_projects ;;\n        4) rollback_project ;;\n        5) create_backup ;;\n        6) echo \"Saindo...\"; exit 0 ;;\n        *) echo \"Op\u00e7\u00e3o inv\u00e1lida\" ;;\n    esac\n}\n\nif [ \"$1\" == \"install\" ]; then\n    install_base\nelif [ \"$1\" == \"create\" ]; then\n    create_project\nelif [ \"$1\" == \"list\" ]; then\n    list_projects\nelif [ \"$1\" == \"rollback\" ]; then\n    rollback_project\nelif [ \"$1\" == \"backup\" ]; then\n    create_backup\nelse\n    show_menu\nfi"};
